[13799] = { ["id"] = 13799, ["name"] = "Where Are My Keys?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3518, ["storyline"] = { 13799 }, ["series"] = { 13800 }, ["description"] = "I can't find my keys -- I suspect my evil twin is at fault. \"Take care\" of him for me, <name>.", ["objectivesText"] = "Dr. Fingers wants you to kill his evil clone, Evil Fingers , and retrieve his keys.", ["rewardGold"] = 33000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3518 } }, ["questType"] = "standard" },
