[13945] = { ["id"] = 13945, ["name"] = "Resident Danger", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 475, 476, 483, 486, 487, 488, 489, 918, 919, 922, 923, 930, 931, 932, 933, 935, 937, 997, 2438, 2459, 2499, 2518, 2541, 2561, 7383, 13945, 13946, 14005, 14039 }, ["description"] = "The Gnarlpine aggression is limiting our options. None of our kind are eager to bring blade and arrow against creatures that were once our friends, but I grow fearful that they are going to set their sights on Dolanaar soon. The biggest concern to me are the furbolg in Ban'ethil Hollow and Ban'ethil Barrow Dens. I need you to travel to the west, make your way into the Barrow Den, and kill as many of the Gnarlpine as you can. We probably won't have many more chances to limit their strength - be swift.", ["objectivesText"] = "Kill 20 Gnarlpine Furbolg in and around Ban'ethil Barrow Den.", ["rewardGold"] = 561800, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2081, ["x"] = 0.556, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 2081, ["x"] = 0.556, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 568, ["name"] = "Teldrassil", ["orderIndex"] = 6, ["flags"] = 0 } } },
[13946] = { ["id"] = 13946, ["name"] = "Nature's Reprisal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 475, 476, 483, 486, 487, 488, 489, 918, 919, 922, 923, 930, 931, 932, 933, 935, 937, 997, 2438, 2459, 2499, 2518, 2541, 2561, 7383, 13945, 13946, 14005, 14039 }, ["description"] = "I'm glad you were willing to atone for your mistake - it speaks a great deal about your character. I have another task for you. I have gathered some ireroot seeds . They are somewhat like fel cones, but quite a bit more potent. Nature often responds very negatively to demons, and these ireroot seeds prompt a very concentrated form of that reprisal. To our north, in Fel Rock, there are grellkin that are far beyond redemption. Use the ireroot seeds to route them before they become a more serious threat.", ["objectivesText"] = "Use ireroot seeds to kill 12 grellkin in Fel Rock. Progress: Did you have any success in routing those grellkin for us?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 46716 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2083, ["x"] = 0.558, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 2083, ["x"] = 0.558, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 568, ["name"] = "Teldrassil", ["orderIndex"] = 12, ["flags"] = 0 } } },
[14005] = { ["id"] = 14005, ["name"] = "The Vengeance of Elune", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 475, 476, 483, 486, 487, 488, 489, 918, 919, 922, 923, 930, 931, 932, 933, 935, 937, 997, 2438, 2459, 2499, 2518, 2541, 2561, 7383, 13945, 13946, 14005, 14039 }, ["series"] = { 933, 935, 7383, 14039 }, ["description"] = "As Teldrassil purges itself of the corruption that has perverted its growth for all of these years, a malevolent growth has formed near the tree's edge, south of here. We have an opportunity to strike out and purge the source of the fel moss that has tainted the gnarlpine, the timberlings, and everything else. With the water that you've collected from the moonwells and the renewed strength of Teldrassil herself, I can grant you great power for a short while. Put an end to this corruption, <name>.", ["objectivesText"] = "Use the powers granted to you by Tarindrella to fight your way to the Heart of Corruption and destroy it. Progress: Did you find the source of the corruption?", ["rewardGold"] = 561800, ["rewardXP"] = 250, ["rewardItems"] = { 49448, 49449, 49546, 49562, 54873, 131821, 131822 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 1992, ["x"] = 0.425, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 1992, ["x"] = 0.425, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 568, ["name"] = "Teldrassil", ["orderIndex"] = 26, ["flags"] = 0 } } },
[14008] = { ["id"] = 14008, ["name"] = "Frost Nova", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["storyline"] = { 14008 }, ["description"] = "I'm Fizz Lighter , your personal trainer, <sir/ma'am>. I understand that you're interested in some new insight about being a <class>? Look. Just get better at what you already know, and you'll learn how to do more of what it is you do best. Helpful, right? So go, get some more experience, then when you learn how to do something new go ahead and try it out on one of the dummy's here.", ["objectivesText"] = "Reach level 3 to learn Frost Nova , then cast the spell 2 times at a Training Dummy. Progress: Whenever you're ready, sir.", ["rewardXP"] = 125, ["rewardItems"] = { 53365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4737 } }, ["questType"] = "standard" },
