[14039] = { ["id"] = 14039, ["name"] = "Home of the Kaldorei", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 475, 476, 483, 486, 487, 488, 489, 918, 919, 922, 923, 930, 931, 932, 933, 935, 937, 997, 2438, 2459, 2499, 2518, 2541, 2561, 7383, 13945, 13946, 14005, 14039 }, ["series"] = { 933, 935, 7383, 14005 }, ["description"] = "It has been an undeniable honor to have met you. You are a testament to the nobility of your race. Go now and finish this final task. Take the waters to Tyrande Whisperwind in Darnassus.", ["objectivesText"] = "Bring the Filled Vessel to Tyrande Whisperwind in Darnassus. Progress: How fare you, young one?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 5188 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 3515, ["x"] = 0.459333, ["y"] = 0.482667 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 7999, ["x"] = 0.430667, ["y"] = 0.779333 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.459333, ["y"] = 0.482667 }, ["mapCandidates"] = { ["npc"] = { 57, 89 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 568, ["name"] = "Teldrassil", ["orderIndex"] = 28, ["flags"] = 0 } } },
[14069] = { ["id"] = 14069, ["name"] = "Good Help is Hard to Find", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14071, 14075, 24488, 24502, 24503, 24520, 24567, 25473, 28349, 28414 }, ["description"] = "I've failed! I tried to meet our Kaja'Cola quotas, but you know troll slaves these days. Good help is hard to find! I think your personal touch is called for. Go show 'em what happens to slackers. If all else fails, a shock from the battery on your Goblin All-In-1-Der Belt should do the trick. Adjust their attitudes and the rest will fall in line. Kaja'Cola production must continue or the Trade Prince will have all of our heads!", ["objectivesText"] = "Adjust the attitudes of 8 Defiant Trolls . Progress: A good start, sir, but might I suggest that you may want to make an example of a few more?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.6102, ["y"] = 0.7574 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 2, ["flags"] = 0 } } },
[14070] = { ["id"] = 14070, ["name"] = "Do it Yourself", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "We need to send a message to several deadbeats. Of course, they're hiding out in Drudgetown, the scum. I know how you hate going into the slums, boss-<man/lady>, but what can we do? <Sassy rifles through some paperwork.> I have all of the names right here. Might I suggest a little 'personal visit'? A couple of strategic beatdowns will send a message to the other debtors AND your competition. <name> is not a goblin to be trifled with!", ["objectivesText"] = "Beat down Bruno Flameretardant , Frankie Gearslipper , Jack the Hammer , and Sudsy Magee .", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 54296, 54297, 62189, 62190, 62191, 65855, 65856, 65857, 121419, 121420, 121421, 121422, 131857, 132942, 132944, 132945, 132946, 181645, 181647, 181649, 184305, 184772, 184773, 184774, 184775, 184776, 210469, 237812 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 11, ["flags"] = 0 } } },
[14071] = { ["id"] = 14071, ["name"] = "Rolling with my Homies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14075, 24488, 24502, 24503, 24520, 24567, 25473, 28349, 28414 }, ["description"] = "<name>, you're about to host the corporate party to end all corporate parties. My research says that if you're seen having a good time at the party, your promotion quotient will skyrocket and explode! So, with that in mind, might I suggest that you take your new company hot rod out for a spin? Go pick up your friends. Just remember me on the way up when it all comes together and you're the new Trade <Prince/Princess>, okay?", ["objectivesText"] = "Drive the Hot Rod around and pickup your friends: Ace , Gobber , and Izzy . Progress: The party's almost ready. How was your trip to town?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 46856, 54298, 54299, 54300, 131858 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.76775 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 6, ["flags"] = 0 } } },
[14075] = { ["id"] = 14075, ["name"] = "Trouble in the Mines", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 24488, 24502, 24503, 24520, 24567, 25473, 28349, 28414 }, ["description"] = "We've got trouble down in the Kaja'mine again, boss. The tunneling worms have returned and they're literally eating away at the Kajaro Trading Company's profits! Kaja'mite mining is down, which is negatively impacting our production of Kaja'Cola! I tried calling the exterminator, but he's fled with the last payment we made to him. Do you think you could head into the three mines and take care of it? I'd help but I still haven't attended the cartel-mandated fighter training seminar.", ["objectivesText"] = "Slay 6 Tunneling Worms . Progress: I don't know, boss. I'm still getting reports of worms eating all of the kaja'mite in the mines. You should head back down there and take care of them.", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 54292, 54293, 131856 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.6102, ["y"] = 0.7574 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 1, ["flags"] = 0 } } },
[14109] = { ["id"] = 14109, ["name"] = "The New You", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 26712 }, ["description"] = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there. Well, happy shopping. Swindle Street has some of the best bargains anywhere!", ["objectivesText"] = "Buy some Shiny Bling from Gappy Silvertooth, a Hip New Outfit from Szabo, and some Cool Shades from Missa Spekkies on Swindle Street. Progress: Do you have it all, <name>? I can't wait to see it on you! You bought the good stuff, right?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 47044, 47045, 47046, 47047, 116062, 139506, 139730, 180633, 181295, 187635, 188957, 189178, 189457, 209912, 209913, 209914, 237812 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 35120, ["x"] = 0.298667, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 35053, ["x"] = 0.4948, ["y"] = 0.6404 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.298667, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 10, ["flags"] = 0 } } },
[14110] = { ["id"] = 14110, ["name"] = "The New You", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 26711 }, ["description"] = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there. Well, happy shopping. Swindle Street has some of the best bargains anywhere!", ["objectivesText"] = "Buy some Shiny Bling from Gappy Silvertooth, a Hip New Outfit from Szabo, and some Cool Shades from Missa Spekkies on Swindle Street. Progress: Do you have it all? I can't wait to see it on you! Mmm hmm!", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 47044, 47045, 47046, 47047, 116062, 139506, 139730, 180633, 181295, 187635, 188957, 189178, 189457, 209912, 209913, 209914, 237812 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 35120, ["x"] = 0.298667, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 35054, ["x"] = 0.4948, ["y"] = 0.6388 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.298667, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 9, ["flags"] = 0 } } },
[14113] = { ["id"] = 14113, ["name"] = "Life of the Party", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14115, 14116, 14120, 14153 }, ["description"] = "Oh my gosh, babe! Everyone is here! Who cares about some stupid dragon? We setup the party around the pool. Sounds like they're having a great time. You are going to look so good! Why don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to slip into something even more amazing!", ["objectivesText"] = "Put on your Awesome Party Ensemble (Cool Shades, Hip New Outfit, and Shiny Bling) and then head over to the party at the KTC Headquarters pool to entertain 10 Kezan Partygoers . Progress: How's the party going? You look amazing! So dashing and handsome, sir!", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 35053, ["x"] = 0.4948, ["y"] = 0.6404 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.6404 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 18, ["flags"] = 0 } } },
[14115] = { ["id"] = 14115, ["name"] = "Pirate Party Crashers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14113, 14116, 14120, 14153 }, ["description"] = "Oh my gosh! Pirates! <name>, there are Southsea pirates crashing your party! You have to get in there and do something about this or your career, and any chance of you being the next Trade <Prince/Princess>, is going to be ruined!", ["objectivesText"] = "Kill 12 Pirate Party Crashers in order to save your career. Progress: Was that all of them? I know that I saw a lot rushing in!", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 54302, 54303 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 20, ["flags"] = 0 } } },
[14116] = { ["id"] = 14116, ["name"] = "The Uninvited Guest", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14113, 14115, 14120, 14153 }, ["description"] = "While you were dealing with the pirates, I noticed the Trade Prince slip upstairs. He's up on the balcony at the top of the stairs. <name>, I think he's the one that sent the pirates. <Sassy cringes.> You'd better get up there A.S.A.P.! You wouldn't want to keep him waiting.", ["objectivesText"] = "Speak with Trade Prince Gallywix upstairs at the KTC Headquarters main building on Kezan .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 35222, ["x"] = 0.4232, ["y"] = 0.5148 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 21, ["flags"] = 0 } } },
[14120] = { ["id"] = 14120, ["name"] = "A Bazillion Macaroons?!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14113, 14115, 14116, 14153 }, ["description"] = "You're an extremely ambitious young goblin, <name>. Maybe a little too ambitious for your own good. I see a lot of myself in you when I was your age. I have a proposition. You might have noticed that Mount Kajaro is exploding thanks to your dragon. Everyone on Kezan is going to die! But, if you bring me a bazillion macaroons before my yacht leaves the island, I'll make sure that you're one of the lucky few to escape. If you want to live, you better hurry and figure out how to get me my moolah!", ["objectivesText"] = "Speak with Sassy Hardwrench at KTC Headquarters on Kezan .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 35222, ["x"] = 0.4232, ["y"] = 0.5148 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.4232, ["y"] = 0.5148 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 22, ["flags"] = 0 } } },
[14121] = { ["id"] = 14121, ["name"] = "Robbing Hoods", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "We're all going to die!!! <You slap Megs to calm her down.> Sorry about that, <Mr./Ms.> <name>. Okay, we need to find a way to get a lot of moolah quickly. There are reports of the Trade Prince sending hired looters into the streets. You could take the hot rod out there and run them down, snatching the loot that they've illegally stolen. There wouldn't be anything wrong with that, right?", ["objectivesText"] = "Use your Hot Rod to run over 12 Hired Looters, collecting 12 Stolen Loots in the process. Progress: Were you able to steal a whole bunch of stolen loot ?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 47530 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.76775 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 24, ["flags"] = 0 } } },
[14122] = { ["id"] = 14122, ["name"] = "The Great Bank Heist", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "All of your assets have been frozen and the First Bank of Kezan is out of business! You need an awful lot of moolah, boss. I think you're going to have to go break your own money out of the bank! The different widgets in your Goblin All-In-1-Der belt should be enough to crack the vault. I just hope that you've been saving for a rainy day like I always told you to do. You might have noticed... it's raining hot liquid magma!!!", ["objectivesText"] = "Crack the vault at the First Bank of Kezan to retrieve your Personal Riches . Progress: Did you get it? Did you crack the safe and get your personal riches out of the bank?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 46858, 54304, 54305, 54306, 56148, 131859 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 23, ["flags"] = 0 } } },
[14123] = { ["id"] = 14123, ["name"] = "Waltz Right In", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "There's only one way we're going to get a bazillion macaroons: stealing from the rich! That slime, the Trade Prince, has stolen all kinds of antiques and expensive art. It's time to take them back and give them to the needy... mainly us! Hobart left behind a cap he was working on. It's a disguise that'll make you look like one of Gallywix's mooks. All you have to do is waltz right in to his Villa to the west and 'procure' the items. Just watch out for his pigs who can smell through the disguise!", ["objectivesText"] = "Obtain Maldy's Falcon , The Goblin Lisa , and The Ultimate Bomb . Progress: You got the goods, boss?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 48937, 48939, 48941 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34693, ["x"] = 0.589385, ["y"] = 0.756769 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34693, ["x"] = 0.589385, ["y"] = 0.756769 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.589385, ["y"] = 0.756769 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 25, ["flags"] = 0 } } },
[14124] = { ["id"] = 14124, ["name"] = "Liberate the Kaja'mite", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "<Sir/Ma'am>, we need tons of moolah to pay the Trade Prince and get off Kezan ! Well, tons of it is just waiting for the taking down there in the Kaja'mine! These are the last known deposits of kaja'mite anywhere. This is the raw stuff that made us the genius tinkerers and alchemists we are today. If that's not worth a bazillion macaroons, I don't know what is! Take some of my kablooey bombs and blowup the deposits. Then, pick up the chunks. Just watch out for the rebellious trolls!", ["objectivesText"] = "Collect 12 Kaja'mite Chunks . Progress: How much Kaja'mite do you have?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 48766, 48768 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.6102, ["y"] = 0.7574 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 26, ["flags"] = 0 } } },
[14125] = { ["id"] = 14125, ["name"] = "447", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "We're close, but we still don't have enough macaroons. But, I've got a plan: we're going to collect on the headquarters insurance policy! Hope you don't mind, but I filled the place with the leftover fireworks from your party. All you have to do is go in there and sabotage things. Might I suggest the faulty generator, the leaky stove , and the flammable bed ? Then, come back outside and use the control panel to send in the gasbot . It's a foolproof plan!", ["objectivesText"] = "Overload the Defective Generator , Activate the Leaky Stove , Drop a Cigar on the Flammable Bed , and use the Gasbot to set KTC Headquarters ablaze!", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 54307, 54308, 54309, 131860 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 37602, ["x"] = 0.5955, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 27, ["flags"] = 0 } } },
[14126] = { ["id"] = 14126, ["name"] = "Life Savings", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "We've got all of the moolah that we need. There's only one thing left to do now, boss: get you to the Trade Prince's yacht. It's about to leave port! We're gonna have to hurry. Hop in, 'cause I'm driving!", ["objectivesText"] = "Hand over your Life Savings to Trade Prince Gallywix aboard the Trade Prince's Yacht on Kezan . Progress: Oh, <name>, it's you. What an unexpected surprise.", ["rewardXP"] = 250, ["rewardItems"] = { 49866 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 35222, ["x"] = 0.4232, ["y"] = 0.5148 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 28, ["flags"] = 0 } } },
[14153] = { ["id"] = 14153, ["name"] = "Life of the Party", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14113, 14115, 14116, 14120 }, ["description"] = "Oh wow, baby! Everyone is here! Who cares about some stupid dragon? We setup the party around the pool. Sounds like they're having a great time already. You are going to look so fine! Why don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to grab my stuff.", ["objectivesText"] = "Put on your Awesome Party Ensemble (Cool Shades, Hip New Outfit, and Shiny Bling) and then head over to the party at the KTC Headquarters pool to entertain 10 Kezan Partygoers .", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 21154, 22278, 22280, 44803, 44916, 50160, 52489, 74282, 74283 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 35054, ["x"] = 0.4948, ["y"] = 0.6388 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.6388 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 19, ["flags"] = 0 } } },
[14231] = { ["id"] = 14231, ["name"] = "Useless quest record", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 14231 }, ["rewardItems"] = { 49082 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[14245] = { ["id"] = 14245, ["name"] = "It's a Town-In-A-Box", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4720, ["mapID"] = 174, ["storyline"] = { 14245 }, ["series"] = { 14031, 14233, 14234, 14235, 14236, 14237, 14238, 14240, 14241, 14242, 14243, 14244, 14303, 14326, 14445 }, ["description"] = "The trade prince had an entire town-in-a-box in the ship's hold! I managed to recover it while you were out saving all of our skins. Do you want to do the honors? All you have to do is climb to the top of that huge pile of explosives and push the plunger, and whamo kablamo, instant town!", ["objectivesText"] = "Climb to the top of the mountain of explosives and use the Town-In-A-Box Plunger.", ["rewardGold"] = 53500, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 174, ["npcID"] = 36470, ["x"] = 0.445, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 174, ["npcID"] = 36471, ["x"] = 0.4555, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 174, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 174 }, ["zone"] = { 4720 } }, ["questType"] = "standard" },
[14279] = { ["id"] = 14279, ["name"] = "Learning the Word", ["level"] = 2, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4755, ["storyline"] = { 14279 }, ["series"] = { 14154, 14157, 14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14280, 14281, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291, 26129, 28850 }, ["description"] = "You have much to learn, <name>. And I've much to teach you. These are perilous times, however, and I fear that you may need to learn much on your own Have no fear, <brother/sister>. The Light will guide us through this. Go, get more experience, and learn a new skill. Use it against the bloodfang worgen nearby.", ["objectivesText"] = "Reach level 3 to learn Shadow Word: Pain . Use it 2 times on a bloodfang worgen. Progress: You are learning swiftly, my dear.", ["rewardGold"] = 50, ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4755 } }, ["questType"] = "standard" },
[14281] = { ["id"] = 14281, ["name"] = "Frost Nova", ["level"] = 2, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4755, ["storyline"] = { 14281 }, ["series"] = { 14154, 14157, 14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291, 26129, 28850 }, ["description"] = "The path ahead is difficult, <name>. We must devote the entirety of our mental power to the task at hand. As you begin to grow in power, new pathways to the arcane will begin to materialize in your mind. You'll begin to develop spells you did not know before. Go, get more experience, and then use what you learn against the Bloodfang Worgen.", ["objectivesText"] = "Reach level 3 to learn Frost Nova . Use it against a Bloodfang Worgen. Progress: I always knew you were a quick study!", ["rewardXP"] = 85, ["rewardItems"] = { 53365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4755 } }, ["questType"] = "standard" },
[14283] = { ["id"] = 14283, ["name"] = "Moonfire", ["level"] = 2, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4755, ["storyline"] = { 14283 }, ["series"] = { 14154, 14157, 14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14281, 14285, 14286, 14287, 14288, 14289, 14290, 14291, 26129, 28850 }, ["description"] = "We were driven to the edge of extinction once before, <name>. But we druids, keepers of the old ways, saved our people from famine. When we cut ourselves off from the outside world and our crops failed, it was our order who called upon the earth's blessings and restored the harvest. Just as our powers restored the crops, your growth in power will develop your connection to our ancient arts. Go, develop your powers, and use what you learn against the Bloodfang Worgen.", ["objectivesText"] = "Reach level 3 to learn Moonfire , then use it against a Bloodfang Worgen. Progress: The earth speaks to us, <name>. It will not abandon us even in these perilous times.", ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4755 } }, ["questType"] = "standard" },
[14446] = { ["id"] = 14446, ["name"] = "Cataclysm!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 14446 }, ["description"] = "Hear my words, <class>! The winds of change have gathered into a violent storm that sweeps across Azeroth. Have you the courage to face the true cause of our plight? Muster your resolve, <race>, and pray for the strength and fortune to see you through the trials that await. An unexpected ally has issued a call for all that would hear. Peer into the Waters of Farseeing and behold the fate of the world!", ["objectivesText"] = "Nambria wants you to peer into the Waters of Farseeing.", ["rewardGold"] = 549600, ["rewardXP"] = 515, ["rewardItems"] = { 89125, 156689 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[14449] = { ["id"] = 14449, ["name"] = "The First Step", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14452, 14458, 24852 }, ["description"] = "What you see here is the work of the quilboar, young one. Year after year they have encroached on our village. The great cataclysm finally drove them from their dens to spread like locusts across the land, and now you see the result; my own mother, dead from their savagery. Today, you are of age. Today, you will take up your weapon and fight for the tribe, and avenge the Greatmother. Follow the path to the east, and find my son, Grull. He will lead you in our strike against the quilboar.", ["objectivesText"] = "Follow the path East out of Camp Narache and find Grull Hawkwind .", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 262510 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2981, ["x"] = 0.452, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2980, ["x"] = 0.488, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 0, ["flags"] = 0 } } },
[14452] = { ["id"] = 14452, ["name"] = "Rite of Strength", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14449, 14458, 24852 }, ["description"] = "Behold, <name>. The very presence of the Bristleback is a blight. Nothing is left in their wake but corpses and barren land. Camp Narache could become what we see here in but a few days, unless we stand and fight. This will be your Rite of Strength; the first ceremony of a tauren brave. Go into the heart of the thornsnarl and kill Bristleback quilboar, then return to me.", ["objectivesText"] = "Kill 6 Bristleback Invaders . Progress: Get in there, <name>! We won't let any past. I want you in the midst of them, scattering them left and right!", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57199, 57216, 57231, 131868 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2980, ["x"] = 0.488, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2980, ["x"] = 0.488, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 1, ["flags"] = 0 } } },
[14455] = { ["id"] = 14455, ["name"] = "Stop the Thorncallers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["description"] = "Knowing the ways of your prey is another aspect of the hunt. In the lands they come from, quilboar live in the shade and protection of huge thorned roots. When they move, their shamans seed and grow new roots for them to live in. These thorns mar the land and choke out other life, turning the earth around them barren. Go to the south and stop these thorncallers before they have a chance to continue, <name>.", ["objectivesText"] = "Kill 7 Bristleback Thorncallers .", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57200, 57217, 57232, 131870 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 4, ["flags"] = 0 } } },
[14456] = { ["id"] = 14456, ["name"] = "Rite of Courage", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["description"] = "One of the first lessons you should learn, <name>, is to never underestimate your prey. While we were distracted by the attack on Camp Narache , more of the Bristleback swept in unnoticed and stole a cache of our rifles. You can see them to the south now, filling the air with lead. This is your Rite of Courage: brave the hail of gunfire, hunt the Bristleback gun thieves, and bring back our rifles.", ["objectivesText"] = "Recover 7 Stolen Rifles from Bristleback Gun Thieves. Progress: How many have you brought me, initiate?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 49535, 57201, 57218, 57224, 131871 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 5, ["flags"] = 0 } } },
[14458] = { ["id"] = 14458, ["name"] = "Go to Adana", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14449, 14452, 24852 }, ["description"] = "We've struck a great blow against the quilboar here. I will stay here, and hold the line, but you need to move on. Seek Adana Thunderhorn ; she has taken a few braves to the southwest to root out the rest of the Bristleback.", ["objectivesText"] = "Go to Adana Thunderhorn to the Southwest.", ["rewardGold"] = 30, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2980, ["x"] = 0.488, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 3, ["flags"] = 0 } } },
[14459] = { ["id"] = 14459, ["name"] = "The Battleboars", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14460, 14461, 23733, 24215, 24861 }, ["description"] = "There are more threats to be dealt with here. The Bristleback are taming wild boars to be used against us. These armored battleboars have been abused beyond hope of recovery; they must be put down, for our safety and their peace. Go to the pens to the south and slay them, <name>. Return to me afterwards.", ["objectivesText"] = "Kill 10 Armored Battleboars .", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 49539, 57202, 57219, 131869 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 6, ["flags"] = 0 } } },
[14460] = { ["id"] = 14460, ["name"] = "Rite of Honor", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14459, 14461, 23733, 24215, 24861 }, ["description"] = "Chief Squealer Thornmantle leads these quilboar. It was he that set upon Greatmother Hawkwind and took her life, leading the attack on Camp Narache . He fled and hid afterwards, but we've found him. He lurks to the west within his foul den of thorns, fending off any braves we send in after him. You've proven yourself as a brave defender of our people, <name>. Kill Thornmantle and bring his mane back to Chief Hawkwind , in honor of our Greatmother!", ["objectivesText"] = "Kill Chief Squealer Thornmantle. Progress: Have you completed your trials, young one?", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 50473, 57203, 57220, 57792, 131872 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2981, ["x"] = 0.452, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 8, ["flags"] = 0 } } },
[14461] = { ["id"] = 14461, ["name"] = "Feed of Evil", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14459, 14460, 23733, 24215, 24861 }, ["description"] = "We must do more than simply hunt boars here. The eyesore that has been left upon the land must be purged. To give them a wild thirst for blood, the battleboars are force-fed raw flesh. Take this torch, and use it to burn the troughs of meat and gore to cinders.", ["objectivesText"] = "Use Adana's Torch to set fire to all 3 Troughs in the Battleboar Pens. Progress: Have all the troughs been burned?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 49539 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36694, ["x"] = 0.462, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 7, ["flags"] = 0 } } },
[14481] = { ["id"] = 14481, ["name"] = "Into The Abyss", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 14481 }, ["series"] = { 14482, 24432, 25281, 25405, 27724, 28825, 28826, 28827 }, ["description"] = "The Horde and Alliance are locked in battle with one another in the seas to the west. Below them, a great host of enemies prepares to carry out a plan that could be the undoing of us all. I am sending you to speak with the admiral of the alliance forces. Share with him the vision you have seen. Convince him to focus his attention on the true threat below, before it grows too late... To gain audience with the admiral, you must first enlist with the recruiter at the harbor.", ["objectivesText"] = "Nambria wants you to speak to Recruiter Burns at Stormwind Harbor.", ["rewardGold"] = 7400, ["rewardXP"] = 25, ["rewardItems"] = { 53053, 54345, 54639, 55186 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[14491] = { ["id"] = 14491, ["name"] = "The Restless Earth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 14438 }, ["description"] = "Until recently, a group of dwarves intruded on our lands to the west, carving the earth apart senselessly to search for treasure. When the very earth itself tore apart, the spirits of the land they had abused rose up and took their revenge. The agitated earth spirits still roam the former dig site, <name>. We must offer them appeasement. Take this drum with you to the west and play to the spirits. The rhythm may calm their fury and confusion.", ["objectivesText"] = "Use the Drums of the Soothed Earth to calm 6 Agitated Earth Spirits.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 49647, 57207, 57223, 57233 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36644, ["x"] = 0.476, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36644, ["x"] = 0.476, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 1, ["flags"] = 0 } } },
[20440] = { ["id"] = 20440, ["name"] = "Poison Water", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["description"] = "Our sacred wells have been tainted, and I will need your help to fix this. To cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual. First we will create a cleansing totem for the Winterhoof Water Well. To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons. They are to the southwest. Return to me with the paws and talons, <name>.", ["objectivesText"] = "Collect 6 Prairie Wolf Paws and 4 Plainstrider Talons . Progress: Do you have the paws and talons, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 200, ["rewardItems"] = { 4758, 4759, 243335 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 6, ["flags"] = 0 } } },
[20441] = { ["id"] = 20441, ["name"] = "Rite of Vision", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 24440, 24441, 24456, 24457, 24523, 24524, 24540, 24550, 44498 }, ["description"] = "Again, be sure you are ready to leave Bloodhoof Village behind, <name>. The next step on your journey will take you far from here. Your path continues to lead onward, across the fields of Mulgore , the eyes of the Earth Mother on you at all times. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, your eyes will be opened, and the spirits will guide you.", ["objectivesText"] = "Consume the Water of Vision in front of the tribal fire in Bloodhoof Village.", ["rewardXP"] = 150, ["rewardItems"] = { 49651, 57206, 57222, 131363 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 3054, ["x"] = 0.478, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 10, ["flags"] = 0 } } },
[23733] = { ["id"] = 23733, ["name"] = "Rites of the Earthmother", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14459, 14460, 14461, 24215, 24861 }, ["description"] = "Today, you have undertaken a rite of passage far more difficult than we ask of most of our youths. Be proud. Now, it is time for you to continue on your journey. To the west, beyond our burial ground, you will find a path winding up the mesa. Follow it to the top, and speak with Dyami Windsoar . Walk with the Earth Mother, friend. You will always be welcome here.", ["objectivesText"] = "Speak to Dyami Windsoar atop Fargaze Mesa.", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2981, ["x"] = 0.452, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36803, ["x"] = 0.412, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 10, ["flags"] = 0 } } },
[24215] = { ["id"] = 24215, ["name"] = "Rite of the Winds", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14459, 14460, 14461, 23733, 24861 }, ["description"] = "Look, <name>. The rolling plains of Mulgore stretch before you: our home, the cradle of the Earth Mother. Here she provides us with all we could ever need, a peaceful and verdant land. This is what you will fight to protect. Your journey will take you far beyond her sheltering arms, to the farthest and cruelest regions of this world, and beyond. Below us is Bloodhoof Village. The first step on your true path begins now. Drink deep of the Water of Vision , and let the spirits guide you onward.", ["objectivesText"] = "Drink the Water of Vision . Provided item:", ["rewardXP"] = 150, ["rewardItems"] = { 49652 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36803, ["x"] = 0.412, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36644, ["x"] = 0.476, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 11, ["flags"] = 0 } } },
[24440] = { ["id"] = 24440, ["name"] = "Winterhoof Cleansing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24441, 24456, 24457, 24523, 24524, 24540, 24550, 44498 }, ["description"] = "I have crafted the totem to cleanse the Winterhoof Water Well. Now, you must take it to the well and perform a cleansing ritual. The well is to the southeast, but be warned: whoever did this may still be there, laying in wait. This may prove very dangerous, <name>. Be careful...but do not let the defilers of our well escape.", ["objectivesText"] = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", ["rewardXP"] = 200, ["rewardItems"] = { 5411, 57205, 57221 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 7, ["flags"] = 0 } } },
[24456] = { ["id"] = 24456, ["name"] = "Thunderhorn Cleansing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24441, 24457, 24523, 24524, 24540, 24550, 44498 }, ["description"] = "The Grimtotem are a tribe that believe all of Kalimdor should belong to the tauren alone. Their hate and anger led to a corrupting thirst for power. Magatha, their leader, poisoned our High Chieftain, Cairne Bloodhoof, and attempted to take Thunder Bluff for herself; she was defeated, and the Grimtotem exiled. Now they seek to ruin Mulgore itself as they are driven out. Quickly, <name>, you must go to the Thunderhorn Water Well in the north and perform the ritual!", ["objectivesText"] = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well.", ["rewardXP"] = 200, ["rewardItems"] = { 5415, 57210, 57226, 57235, 131366 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 9, ["flags"] = 0 } } },
[24457] = { ["id"] = 24457, ["name"] = "Rite of Vision", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 24457 }, ["series"] = { 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 44498 }, ["description"] = "I cannot thank you enough for cleansing my tribe's well, <name>, and for fighting the savage Grimtotem to do it. But there is more to be done, and it is time for your journey to lead you beyond Bloodhoof Village. Zarlman Two-Moons stands by the fire in the north end of the village. Go speak with him and learn of the next ritual you must undertake.", ["objectivesText"] = "Speak with Zarlman Two-Moons in Bloodhoof Village.", ["rewardXP"] = 25, ["rewardItems"] = { 57206, 57222, 131363 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 3054, ["x"] = 0.478, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard" },
[24459] = { ["id"] = 24459, ["name"] = "Morin Cloudstalker", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 24459 }, ["series"] = { 749, 751 }, ["description"] = "You may have heard of the Venture Company. They are a goblin \"cartel\", something like a tribe. While one of these cartels has joined us in the Horde, the Venture Company is loyal only to greed. These greedy goblins and their workers have tried to exploit the resources of Mulgore before, to little success. One of our outrunners, Morin Cloudstalker , has gone to check the remains of one of the goblin caravans. If you wish to help him, follow the road out of the village to the east.", ["objectivesText"] = "Find Morin Cloudstalker to the east of Bloodhoof Village.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36644, ["x"] = 0.476, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2988, ["x"] = 0.57, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard" },
[24469] = { ["id"] = 24469, ["name"] = "Hold the Line!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24470, 24473 }, ["description"] = "Hey, you there! Ye're a stout-looking <class>. Lend us a hand? It looks like today's big earthquake shook a bunch o' those barbarous troggs out of the ground, and they're sure steamed about something. My men are doing what they can to hold them off, but we could use a hand. Do yer part - head just south of here and help dig me mountaineers outta trouble. We've got to hold the line!", ["objectivesText"] = "Slay 6 Rockjaw Invaders . Progress: How many of 'em did ya get?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 54983, 54984, 66922, 66923, 66926, 131895, 142450, 237812 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 37081, ["x"] = 0.368, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 37081, ["x"] = 0.368, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 0, ["flags"] = 0 } } },
[24470] = { ["id"] = 24470, ["name"] = "Give 'em What-For", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24469, 24473 }, ["description"] = "Alright, <name>, listen up. I know a thing or two about troggs, and one of those things is that the biggest, strongest troggs get the most respect. The brutes value strength over anything else. Ye see those great big troggs sitting back behind the front lines? They're the closest they have to what ye'd call a leader. Go take out a few, and show 'em what it means to mess with the Sons of Ironforge!", ["objectivesText"] = "Kill 3 Rockjaw Goons . Progress: Well, what're ye waitin' for, <class>?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 66928, 66929, 66930, 131896 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 37081, ["x"] = 0.368, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 37081, ["x"] = 0.368, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 1, ["flags"] = 0 } } },
[24471] = { ["id"] = 24471, ["name"] = "Aid for the Wounded", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["description"] = "<name>, listen! Unlike Joren, I've no need for yer blade, but I do need someone with a steady hand and a bit o' courage. Our mountaineers are trained to protect the village from the odd wolf attack... not an all-out trogg invasion! Many of our best have succumbed to wounds and exhaustion, and I need yer help bandaging them up. Here, take my first aid kit and assist as many as ye can.", ["objectivesText"] = "Use Sten's First Aid Kit on 4 Wounded Coldridge Mountaineers. Progress: Thanks for yer help, <name>.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 49743, 198048, 200454, 204075, 204732, 204733, 204745, 204762, 204764, 204765, 204766, 204770, 204772, 204773, 204775, 204778, 204779, 204780, 204785, 204786, 204898, 204901 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 658, ["x"] = 0.366, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 658, ["x"] = 0.366, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 2, ["flags"] = 0 } } },
[24473] = { ["id"] = 24473, ["name"] = "Lockdown in Anvilmar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24469, 24470 }, ["description"] = "We appreciate yer help out here, but there may be a place where they need ye even more. Due to the trogg attacks - not to mention that massive earthquake we just had - we're putting all civilians on lockdown inside Anvilmar, just up the hill to the northwest. Go an' talk to me wife, Jona, inside Anvilmar. I'm certain she's in need of an able-bodied <man/lass> such as yerself.", ["objectivesText"] = "Speak with Jona Ironstock in Anvilmar.", ["rewardGold"] = 20, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 37081, ["x"] = 0.368, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 3, ["flags"] = 0 } } },
[24474] = { ["id"] = 24474, ["name"] = "First Things First: We're Gonna Need Some Beer", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 427, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24475 }, ["description"] = "I don't know how ANYONE expects to get any work done around here if we don't have any ale! Our beer level here in Anvilmar is dangerously low. Lucky for us, we've stowed some backup kegs for just such an occasion. West of Anvilmar, along the valley's northern border, ye'll find kegs of Stormhammer Stout and Theramore Pale Ale. Just to the east of here, ye'll find a stash of Gnomenbrau. That's me personal favorite.", ["objectivesText"] = "Obtain a Cask of Stormhammer Stout , a Cask of Theramore Pale Ale , and a Cask of Gnomenbrau . Progress: The ale, darling, the ale!", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 49744, 49745, 49746 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 4, ["flags"] = 0 } } },
[24475] = { ["id"] = 24475, ["name"] = "All the Other Stuff", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 427, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24474 }, ["description"] = "If we're going to be on lockdown for any extended period o' time, we're gonna need some food, and some blankets to keep the wee ones warm. Would ye mind headin' outside and gatherin' up some supplies? Ye'll find that a few o' the small boars actually have some healthy-sized haunches... good for eatin'. We'll also need some pelts from the young wolves. Ye'll find animals almost anywhere ye go in Coldridge.", ["objectivesText"] = "Obtain 3 Boar Haunches and 4 Ragged Wolf Hides . Progress: The people are gettin' restless. D'ye have the supplies yet?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 49747, 49748 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 5, ["flags"] = 0 } } },
[24477] = { ["id"] = 24477, ["name"] = "Dwarven Artifacts", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 427, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24486 }, ["description"] = "<name>, my <boy/beautiful flower>! Are you into archaeology? We've an exciting opportunity right outside our front door. All the shaking from today's seismic event has knocked a number of artifacts loose from the soil around our encampment. Survey along the valley's northern border, and you should find all sorts of treasures. Bring some back to me, and perhaps we can study them together. Right, then! Off you go!", ["objectivesText"] = "Obtain 5 Forgotten Dwarven Artifacts . Progress: Yes?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 49749 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 6, ["flags"] = 0 } } },
[24486] = { ["id"] = 24486, ["name"] = "Make Hay While the Sun Shines", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 427, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24477 }, ["description"] = "The trogg village to the southwest suffered similar damage to ours. One would assume, logically, that there would be some trogg artifacts sticking out of the ground, too! Unfortunately, it looks like most of the artifacts have already been scooped up by trogg scavengers. Please, go see if you can find some way to get them back. Believe it or not, knowledge about troggs may eventually lead to further knowledge about the mighty dwarves!", ["objectivesText"] = "Obtain 5 Priceless Rockjaw Artifacts from Rockjaw Scavengers. Progress: Did you manage to pry any artifacts from the troggs?", ["rewardGold"] = 200, ["rewardXP"] = 200, ["rewardItems"] = { 49751, 57530, 57531, 57532, 131890 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 7, ["flags"] = 0 } } },
[24487] = { ["id"] = 24487, ["name"] = "Whitebeard Needs Ye", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 182 }, ["description"] = "Ye've done us a great service here, but I'm afraid I've gotta send ye off elsewhere. Grelin Whitebeard , a good friend of mine, has put in word that he may need some reinforcements near the troll camps to the southwest. Follow the road westward, ye should find him soon enough. Be well, <name>. Troggs may be a pain, but trolls are a whole other type of trouble.", ["objectivesText"] = "Report to Grelin Whitebeard 's camp in Coldridge Valley .", ["rewardGold"] = 35, ["rewardXP"] = 25, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 786, ["x"] = 0.32, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 8, ["flags"] = 0 } } },
[24488] = { ["id"] = 24488, ["name"] = "The Replacements", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24502, 24503, 24520, 24567, 25473, 28349, 28414 }, ["description"] = "My guys are all on the injured roster! Our shredders are all kaput! The ref is about to call the game! It's down to the wire and I need you, <name>!!! Let's get one of these shredders in working condition. There are replacement parts all over Bilgewater Port. Any green-blooded Kezanian will gladly let you have them if there's a chance that the Buccaneers will win. We'll show those no-good Steamwheedle Sharks how to play footbomb!", ["objectivesText"] = "Collect 6 Replacement Parts . Progress: We're counting on you, <name>!", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 49752 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.579333 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 13, ["flags"] = 0 } } },
[24489] = { ["id"] = 24489, ["name"] = "Trolling for Information", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["description"] = "I'm notoriously bad at reading troll facial expressions. That being said, these trolls don't look angry to me. They seem to be confused... maybe a little frightened. Something happened that we're not seeing here, <name>. I say we do some investigation before we just kill every troll in sight. There are three troll camps in the area: one to the southeast, one to the southwest, and one due west. Each camp has a soothsayer... see if you can get close enough to listen to what they're saying.", ["objectivesText"] = "Stand near a Frostmane Soothsayer in each of the Frostmane camps and listen to what they have to say. Progress: I can't even begin to imagine what would make the trolls act like this.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 1354, ["x"] = 0.32, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 1354, ["x"] = 0.32, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 10, ["flags"] = 0 } } },
[24490] = { ["id"] = 24490, ["name"] = "A Trip to Ironforge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 218 }, ["description"] = "The presence of a fire elemental here in Coldridge is no small matter. That earthquake did more than just upset a bunch of troggs... it changed the world enough to tear a gash into the elemental plane. We should submit a report to Ironforge. You wouldn't be willing to take a trip, would ya? Don't worry, I've a feeling that you'll do just fine. Talk to Hands Springsprocket by the tunnel on the eastern edge of the valley. He'll point you in the right direction.", ["objectivesText"] = "Report to Hands Springsprocket in Coldridge Valley .", ["rewardGold"] = 80, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 786, ["x"] = 0.32, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 6782, ["x"] = 0.408, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 13, ["flags"] = 0 } } },
[24491] = { ["id"] = 24491, ["name"] = "Follow that Gyro-Copter!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24492 }, ["description"] = "D-d-did you see that? How the whole cave just crumbled like that? I guess it's good that you got here when you did, and not a minute earlier. While this development makes my job of monitoring the cave entrance much easier, I imagine it makes it a lot harder for you to get to Kharanos. Hey wait, I've got an idea! The Gnomeregan Airmen have a flight path not far from here. I'll send up a signal, and they should be here to help. I imagine they'll land back over at Anvilmar.", ["objectivesText"] = "Report to Milo Geartwinge near Anvilmar.", ["rewardGold"] = 80, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 6782, ["x"] = 0.408, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 37113, ["x"] = 0.374667, ["y"] = 0.705333 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 14, ["flags"] = 0 } } },
[24492] = { ["id"] = 24492, ["name"] = "Pack Your Bags", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["series"] = { 24491 }, ["description"] = "The weight limit on my gyro is such that I only have enough room for one <race>. Looks like you're in luck, <name>! That dwarf woman Jona told me that most of your personal belongings have been moved inside Anvilmar. Please gather what you'll need, finish up any affairs that remain, and return to me when you're prepared for takeoff.", ["objectivesText"] = "Obtain a Coldridge Beer Flagon , a Ragged Wolf-Hide Cloak , and some Leftover Boar Meat . Progress: Are you absolutely certain you've taken care of everything? You won't have time to turn back.", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["rewardItems"] = { 49754, 49755, 49756, 57540, 57541 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 37113, ["x"] = 0.374667, ["y"] = 0.705333 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 37113, ["x"] = 0.374667, ["y"] = 0.705333 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.374667, ["y"] = 0.705333 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 427, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 15, ["flags"] = 0 } } },
[24493] = { ["id"] = 24493, ["name"] = "Don't Forget About Us", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["mapID"] = 27, ["storyline"] = { 182, 218, 3361, 24469, 24470, 24471, 24473, 24474, 24475, 24477, 24486, 24487, 24489, 24490, 24491, 24492, 24493 }, ["description"] = "You're leaving? Make sure you stock up before you head out. More importantly, please speak to Tharek Blackstone once you arrive in Kharanos. Tell him what has happened here in Coldridge, and that we could use some assistance. Hopefully he'll be able to arrange something for us.", ["objectivesText"] = "Report to Tharek Blackstone in Kharanos.", ["rewardGold"] = 100, ["rewardXP"] = 25, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 1872, ["x"] = 0.532, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6176 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["questLines"] = { { ["id"] = 5395, ["name"] = "Coldridge Valley", ["orderIndex"] = 16, ["flags"] = 1 } } },
[24502] = { ["id"] = 24502, ["name"] = "Necessary Roughness", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24488, 24503, 24520, 24567, 25473, 28349, 28414 }, ["description"] = "We're down to our last shredder. While no one was looking, I loaded it up with, shall we say, modified footbombs. Kid, I need you to get in that shredder and give 'em heck!", ["objectivesText"] = "Get into the Bilgewater Buccaneer and then throw the Footbomb at 8 Steamwheedle Sharks .", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.579333 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 14, ["flags"] = 0 } } },
[24503] = { ["id"] = 24503, ["name"] = "Fourth and Goal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24488, 24502, 24520, 24567, 25473, 28349, 28414 }, ["description"] = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal. Now, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal! I've modified the footbomb to give you the extra power that you'll need. Make me proud!", ["objectivesText"] = "Score the winning goal by kicking the Footbomb through the smokestacks behind the opposing goal.", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 54294, 54295 }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.579333 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 15, ["flags"] = 0 } } },
[24520] = { ["id"] = 24520, ["name"] = "Give Sassy the News", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24488, 24502, 24503, 24567, 25473, 28349, 28414 }, ["description"] = "I'd celebrate with you, <name>, but it feels like that dragon did a number on ol' Mount Kajaro. I... uh... I think I'm gonna grab my stuff and get on the first ship leaving the island! Anyways, you should probably head back to headquarters and let Sassy know that you won the footbomb title for us. I'm sure she'll also want to know about the dragon and Mount Kajaro. Good luck!", ["objectivesText"] = "Speak with Sassy Hardwrench at KTC Headquarters on Kezan .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.579333 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 17, ["flags"] = 0 } } },
[24524] = { ["id"] = 24524, ["name"] = "Wildmane Cleansing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24441, 24456, 24457, 24523, 24540, 24550, 44498 }, ["description"] = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young <name>. The Wildmane Totem is made, and your last task lies ahead. The Wildmane Water Well lies north of Thunder Bluff. Perform the ritual! Heal the land of the Grimtotem's poisons! Let clean water flow once again!", ["objectivesText"] = "Use the Wildmane Cleansing Totem at the Wildmane Water Well.", ["rewardXP"] = 250, ["rewardItems"] = { 5416, 57213, 57229, 57238, 57240, 131373 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 19, ["flags"] = 0 } } },
[24533] = { ["id"] = 24533, ["name"] = "Words of Power", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["storyline"] = { 24533 }, ["description"] = "Now, if ya DO want to become somethin' special, ye'll need to talk to me. A priest is nothin' without his spells. And how do you learn new spells? Ya go and get more experience. So go out, get stronger, and then come show me what ya learn.", ["objectivesText"] = "Reach level 3 to learn Shadow Word: Pain , then cast it 5 times on training dummies.", ["rewardGold"] = 309800, ["rewardXP"] = 100, ["rewardItems"] = { 177665 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6176 } }, ["questType"] = "standard" },
[24540] = { ["id"] = 24540, ["name"] = "War Dance", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24441, 24456, 24457, 24523, 24524, 24550, 44498 }, ["description"] = "Some see our people as gentle giants, or noble savages. They have never seen us fight against our own kind...against betrayers from within. The Grimtotem were offered mercy in exile, and they have scarred their own home to spite us. They will no longer be tolerated in Mulgore . I've already sent our warriors ahead to drive them out through Stonetalon Pass, to the north. You have fought bravely against the Grimtotem, <name>; I ask that you join the battle again. Go, and help deal this final blow.", ["objectivesText"] = "Defeat Orno Grimtotem at Stonetalon Pass. Progress: I do not plan on sitting idly in Thunder Bluff while our warriors risk their lives for our home, <name>. We shall meet on the battlefield. Strike out ahead of me; I will leave soon.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 57214, 57230, 57239, 57241, 57793, 156986 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.568667, ["y"] = 0.477 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 21, ["flags"] = 0 } } },
[24550] = { ["id"] = 24550, ["name"] = "Journey into Thunder Bluff", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24441, 24456, 24457, 24523, 24524, 24540, 44498 }, ["description"] = "The wells are cleansed, and Mulgore 's waters run sweet and clear once more. You've saved us...but you've also uncovered grim happenings. The actions of the Grimtotem must be made known. It is time for you to enter Thunder Bluff, our great city atop the mesa. Go to our leader, Baine Bloodhoof , son of Cairne. He must hear of this.", ["objectivesText"] = "Speak with Baine Bloodhoof in Thunder Bluff.", ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 7, 88 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 20, ["flags"] = 0 } } },
[24567] = { ["id"] = 24567, ["name"] = "Report for Tryouts", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24488, 24502, 24503, 24520, 25473, 28349, 28414 }, ["description"] = "<name>, Coach Crosscheck is looking for you. He's the leader of our fearless footbomb team, the Bilgewater Buccaneers. He says that the division title against the Steamwheedle Sharks is on the line and that you're the only one that can bring it home for us! Head west into town. You can't miss Kajaro Field. A footbomb star. This is going to be great for your image!", ["objectivesText"] = "Speak with Coach Crosscheck at Kajaro Field on Kezan .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.76775 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 12, ["flags"] = 0 } } },
[24607] = { ["id"] = 24607, ["name"] = "The Rise of the Darkspear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24639, 24641, 24642, 24643 }, ["description"] = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here. Vol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream. No, dis time we not fleein'. Dis time, we are fightin' for a home dat will last. It's time to begin ya trainin', <name>. Speak with Nortet to the east.", ["objectivesText"] = "Meet with Nortet in the Darkspear Training Grounds.", ["rewardGold"] = 40, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 37951, ["x"] = 0.624, ["y"] = 0.844 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.844 }, ["mapCandidates"] = { ["npc"] = { 1, 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 0, ["flags"] = 0 } } },
[24622] = { ["id"] = 24622, ["name"] = "A Troll's Truest Companion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24623, 24626, 25064 }, ["description"] = "If ya lookin' for something ta do, we need some more raptors moved over to da pens. If ya head over to da island south of here, you can be meetin' with our caretakers and dey can set ya up. Dey might appreciate a hand too. Got ta be spreadin' da love, ya know?", ["objectivesText"] = "Speak to Kijara on Bloodtalon Shore.", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 50018, 52283 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38005, ["x"] = 0.672, ["y"] = 0.88 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 37969, ["x"] = 0.634, ["y"] = 0.952 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.88 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 46, ["flags"] = 0 } } },
[24623] = { ["id"] = 24623, ["name"] = "Saving the Young", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24622, 24626, 25064 }, ["description"] = "I actually have somethin' really important dat I could use help with, if ya be willin', mon. Our hatchlins' are bein' stolen by someone on da next island. At first I thought dey were just runnin' away or that nature be claimin' dem, but we are missin' more than a dozen of da little guys now. Please head to Zalazane's Fall to da northwest and point da little hatchlins back dis way. Poor tings.", ["objectivesText"] = "Use the Bloodtalon Whistle to rescue 12 Lost Bloodtalon Hatchlings . Progress: Poor little tings.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 50018, 52283 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 37969, ["x"] = 0.634, ["y"] = 0.952 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 37969, ["x"] = 0.634, ["y"] = 0.952 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.952 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 47, ["flags"] = 0 } } },
[24624] = { ["id"] = 24624, ["name"] = "Mercy for the Lost", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["description"] = "The fiend who stole our raptors has been corruptin' dem with some kind of magic. Now dat dey've grown with dis corruption inside of them, I fear dere's little we can be doin' to save dem outside grantin' them da peace of death. Go ta Zalazane's Fall, northwest of here, an' see da task done. I hope ya can stomach dae work. I don't tink I could bring myself ta do da deed, even knowin' that it be needed.", ["objectivesText"] = "Kill 8 Corrupted Bloodtalon Raptors.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 50018, 52283 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 37987, ["x"] = 0.634, ["y"] = 0.952 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 37987, ["x"] = 0.634, ["y"] = 0.952 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.952 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 48, ["flags"] = 0 } } },
[24626] = { ["id"] = 24626, ["name"] = "Young and Vicious", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24622, 24623, 25064 }, ["description"] = "Ya be a good one, <name>. Moraya was askin' for new raptors ta train. We shouldn't keep her waitin' any longa! I have a few other recruits bringin' some over as well, but I have a special one dat I've been promisin' Moraya for a while. Swiftclaw be one of our fastest and bravest young raptors yet, but he can be a bit unruly. I'll lend ya da lasso, I just need ya to catch him somewhere on da island here and steer him over to da pens on da main isle. I doubt he'll be makin' it easy on ya though.", ["objectivesText"] = "Capture Swiftclaw and bring him back to the pens near Darkspear Hold. Progress: Did ya come back wit one of the raptors I sent ya for?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 50018, 50053, 52283, 52877, 52882, 131825 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 37969, ["x"] = 0.634, ["y"] = 0.952 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38005, ["x"] = 0.672, ["y"] = 0.88 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.952 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 50, ["flags"] = 0 } } },
[24639] = { ["id"] = 24639, ["name"] = "The Basics: Hitting Things", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24607, 24641, 24642, 24643 }, ["description"] = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around. Go thrash dose tiki targets . Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", ["objectivesText"] = "Destroy 6 Tiki Targets . Progress: Strength isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", ["rewardGold"] = 2000, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.521333, ["y"] = 0.531667 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 9, ["flags"] = 0 } } },
[24641] = { ["id"] = 24641, ["name"] = "A Rough Start", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24607, 24639, 24642, 24643 }, ["description"] = "Lets put dose skills ta use. I'll start ya off easy, mon. There be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight. Dey're all over the island. Bring me some cat pelts.", ["objectivesText"] = "Retrieve 6 Wildmane Cat Pelts . Progress: I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 50222 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.521333, ["y"] = 0.531667 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 18, ["flags"] = 0 } } },
[24642] = { ["id"] = 24642, ["name"] = "Proving Pit", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24607, 24639, 24641, 24643 }, ["description"] = "Ya done quite well for ya'self, <class>. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer. l put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", ["objectivesText"] = "Speak to a Darkspear Jailor , then enter the proving pit and kill a Captive Spitescale Scout . Progress: All trolls gotta prove demselves before we let them move past da training grounds.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 52870, 52872, 52873, 52874, 52875, 52876, 52889, 85574 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.521333, ["y"] = 0.531667 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 27, ["flags"] = 0 } } },
[24643] = { ["id"] = 24643, ["name"] = "More Than Expected", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24607, 24639, 24641, 24642 }, ["description"] = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more. Head down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", ["objectivesText"] = "Report to Vol'jin at Darkspear Hold.", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 38037, ["x"] = 0.521333, ["y"] = 0.531667 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38966, ["x"] = 0.688, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.521333, ["y"] = 0.531667 }, ["mapCandidates"] = { ["npc"] = { 1, 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 36, ["flags"] = 0 } } },
[24750] = { ["id"] = 24750, ["name"] = "The Rise of the Darkspear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24750, 24751, 24753, 24754, 24755, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24751, 24753, 24754, 24755 }, ["description"] = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here. Vol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream. No, dis time we not fleein'. Dis time, we are fightin' for a home dat will last. It's time to begin ya trainin', <name>. Speak with Soratha to the east.", ["objectivesText"] = "Meet with Soratha in the Darkspear Training Grounds.", ["rewardGold"] = 40, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 37951, ["x"] = 0.624, ["y"] = 0.844 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 38246, ["x"] = 0.590857, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.844 }, ["mapCandidates"] = { ["npc"] = { 1, 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 1, ["flags"] = 0 } } },
