[24753] = { ["id"] = 24753, ["name"] = "A Rough Start", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24750, 24751, 24753, 24754, 24755, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24750, 24751, 24754, 24755 }, ["description"] = "Lets put dose skills ta use. I'll start ya off easy, mon. There be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight. Dey're all over the island. Bring me some cat pelts.", ["objectivesText"] = "Retrieve 6 Wildmane Cat Pelts . Progress: I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 50222 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 38246, ["x"] = 0.590857, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 38246, ["x"] = 0.590857, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.590857, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 19, ["flags"] = 0 } } },
