[24768] = { ["id"] = 24768, ["name"] = "Proving Pit", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 6, 8 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24764, 24765, 24767, 24768, 24769, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24764, 24765, 24767, 24769 }, ["description"] = "Ya done quite well for ya'self, <class>. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer. l put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", ["objectivesText"] = "Speak to a Darkspear Jailor , then enter the proving pit and kill a Captive Spitescale Scout . Progress: All trolls gotta prove demselves before we let them move past da training grounds.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 52870, 52872, 52873, 52874, 52875, 52876, 52889, 85574 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 38243, ["x"] = 0.576, ["y"] = 0.5276 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 38243, ["x"] = 0.576, ["y"] = 0.5276 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.5276 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 30, ["flags"] = 0 } } },
[24769] = { ["id"] = 24769, ["name"] = "More Than Expected", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 6, 8 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24764, 24765, 24767, 24768, 24769, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24764, 24765, 24767, 24768 }, ["description"] = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more. Head down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", ["objectivesText"] = "Report to Vol'jin at Darkspear Hold.", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 38243, ["x"] = 0.576, ["y"] = 0.5276 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38966, ["x"] = 0.688, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.5276 }, ["mapCandidates"] = { ["npc"] = { 1, 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 39, ["flags"] = 0 } } },
