[24782] = { ["id"] = 24782, ["name"] = "The Rise of the Darkspear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24783, 24785, 24786, 24787 }, ["description"] = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here. Vol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream. No, dis time we not fleein'. Dis time, we are fightin' for a home dat will last. It's time to begin ya trainin', <name>. Speak with Tunari to the east.", ["objectivesText"] = "Meet with Tunari in the Darkspear Training Grounds.", ["rewardGold"] = 40, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 37951, ["x"] = 0.624, ["y"] = 0.844 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.844 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 6, ["flags"] = 0 } } },
[24783] = { ["id"] = 24783, ["name"] = "The Basics: Hitting Things", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24782, 24785, 24786, 24787 }, ["description"] = "Alright, mon. We start simple. I need ta know dat you know the basics of the holy arts. Go thrash dose tiki targets . Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", ["objectivesText"] = "Destroy 6 Tiki Targets .", ["rewardGold"] = 2000, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.833 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 13, ["flags"] = 0 } } },
[24784] = { ["id"] = 24784, ["name"] = "Learnin' tha Word", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["storyline"] = { 24784 }, ["series"] = { 24782, 24783, 24785, 24786, 24787 }, ["description"] = "As ya get more skill out there in tha' world, you'll start to discovah' new powahs. Why dontcha go out an' go get yaself stronger, and come back when ya learn sometin' new. You can show me what ya learn.", ["objectivesText"] = "Reach level 3 to learn Shadow Word: Pain . Use it 5 times on 5 Tiki training dummies.", ["rewardGold"] = 40, ["rewardXP"] = 190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard" },
[24785] = { ["id"] = 24785, ["name"] = "A Rough Start", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24782, 24783, 24786, 24787 }, ["description"] = "Lets put dose skills ta use. I'll start ya off easy, mon. There be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight. Dey're all over the island. Bring me some cat pelts.", ["objectivesText"] = "Retrieve 6 Wildmane Cat Pelts . Progress: I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 50222 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.833 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 24, ["flags"] = 0 } } },
[24786] = { ["id"] = 24786, ["name"] = "Proving Pit", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24782, 24783, 24785, 24787 }, ["description"] = "Ya done quite well for ya'self, <class>. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer. l put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", ["objectivesText"] = "Speak to a Darkspear Jailor , then enter the proving pit and kill a Captive Spitescale Scout .", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 52870, 52872, 52873, 52874, 52875, 52876, 52889, 85574 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.833 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 33, ["flags"] = 0 } } },
[24787] = { ["id"] = 24787, ["name"] = "More Than Expected", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24782, 24783, 24785, 24786 }, ["description"] = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more. Head down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", ["objectivesText"] = "Report to Vol'jin at Darkspear Hold.", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38245, ["x"] = 0.675, ["y"] = 0.833 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38966, ["x"] = 0.688, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.833 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 42, ["flags"] = 0 } } },
[24812] = { ["id"] = 24812, ["name"] = "No More Mercy", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24813, 24814 }, ["description"] = "Da naga have committed great atrocities on our people. Da time ta show dem mercy has long passed. Enter da cave and kill any naga you find dere. Every naga dead dis day is one less naga ta take us unawares later on. I trust ya will be thorough.", ["objectivesText"] = "Kill 12 Spitescale Naga.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 52065, 52878, 52883, 52886, 131827 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38442, ["x"] = 0.678, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38442, ["x"] = 0.678, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 53, ["flags"] = 0 } } },
[24813] = { ["id"] = 24813, ["name"] = "Territorial Fetish", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24812, 24814 }, ["description"] = "Dis is no casual counter-attack. We be fully intendin' ta slaughter every last naga here and do anything we can ta ensure that dey will have no desire ta return. I want ya ta place dese fetishes on any Spitescale banner ya be findin' inside their cave. It should prove a clear statement of what we think of their presence here. More dan dat, da magic in dese fetishes will be weakenin' any Spitescale dat approach, which should make dem second guess stayin' on our isle.", ["objectivesText"] = "Place 8 Territorial Fetishes on Spitescale flags.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 52065 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38442, ["x"] = 0.678, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38442, ["x"] = 0.678, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 54, ["flags"] = 0 } } },
[24814] = { ["id"] = 24814, ["name"] = "An Ancient Enemy", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24812, 24813 }, ["description"] = "Da Sea Witch is here, on top of dis very isle. We've been waitin' a long time for dis chance at revenge and ya will be havin' da privilege of seein' it through. Meet with Vol'jin , up da ramp to da northeast. Let him know when you are ready ta join da battle.", ["objectivesText"] = "Speak with Vol'jin in Spitescale Cove and aid him in killing Zar'jira , the Sea Witch. Progress: I did not think we'd be afforded da opportunity to fight her again. She was foolish to be returnin'.", ["rewardGold"] = 6000, ["rewardXP"] = 300, ["rewardItems"] = { 52065, 52879, 52884, 52887, 60260, 131828 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38442, ["x"] = 0.678, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38966, ["x"] = 0.688, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 55, ["flags"] = 0 } } },
[24852] = { ["id"] = 24852, ["name"] = "Our Tribe, Imprisoned", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14449, 14452, 14458 }, ["description"] = "Despite their size, the Bristleback greatly outnumber us. A pack ambush can easily overwhelm even the largest tauren. Many new initiates have taken up arms to defend our home. Some have given their lives, but others have been captured alive. Please, find their cages and free them. The battle should keep the quilboar distracted.", ["objectivesText"] = "Open 4 Quilboar Cages . Progress: Not enough have returned, <name>. Return and free more of our people. Be brave!", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57198, 57215, 131867 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2980, ["x"] = 0.488, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2980, ["x"] = 0.488, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 2, ["flags"] = 0 } } },
[24861] = { ["id"] = 24861, ["name"] = "Last Rites, First Rites", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6452, ["mapID"] = 7, ["storyline"] = { 14449, 14452, 14455, 14456, 14458, 14459, 14460, 14461, 23733, 24215, 24852, 24861 }, ["series"] = { 14459, 14460, 14461, 23733, 24215 }, ["description"] = "The camp is safe, and the quilboar driven off, all thanks to you, young one. You have my personal thanks for what you have done for my mother, my son, and for all of us. It is now time to put Greatmother Hawkwind to rest. Lay the final offering at her feet, <name>, and we will say our goodbyes.", ["objectivesText"] = "Use the Ceremonial Offering at Greatmother Hawkwind's grave. Progress: Do not be shy, <name>. I am honored to have you lay the final offering.", ["rewardXP"] = 100, ["rewardItems"] = { 50465 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2981, ["x"] = 0.452, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2981, ["x"] = 0.452, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 5407, ["name"] = "Red Cloud Mesa", ["orderIndex"] = 9, ["flags"] = 0 } } },
[24959] = { ["id"] = 24959, ["name"] = "Fresh out of the Grave", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "<name>! Rise, <name>! Welcome back to the realm of the living. With the blessing and power of the Dark Lady, I have freed you from death's grip. You are no slave, <name>. You are free to follow whatever path you choose from here. If you choose to serve the Dark Lady Sylvanas, I recommend you speak with Undertaker Mordo . You will find him behind me, in the graveyard.", ["objectivesText"] = "Report to Undertaker Mordo at the Deathknell Graves in Tirisfal Glades.", ["rewardGold"] = 200, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 49044, ["x"] = 0.294, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1568, ["x"] = 0.3, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 0, ["flags"] = 0 } } },
[24960] = { ["id"] = 24960, ["name"] = "The Wakening", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "King, peasant, or <class>... I don't care WHAT you were before. I just need somebody with a working tongue. Being raised from the dead is strenuous. Not everyone copes with it as well as you did. In particular, there are three newly-raised undead who are having trouble coping right now. I want you to find them and talk to them. It might be that they just need someone that they can relate with. You'll find them here in the graveyard.", ["objectivesText"] = "Speak with Marshal Redpath , Lilian Voss , and Valdred Moray . Progress: No dilly-dallying now. You're among the Forsaken now, and we hold ours to a higher standard.", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["rewardItems"] = { 9599, 54868, 60240, 131210, 211279 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 2307, ["x"] = 0.306, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 2307, ["x"] = 0.306, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 4, ["flags"] = 0 } } },
[24961] = { ["id"] = 24961, ["name"] = "The Truth of the Grave", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "Earlier on, I saw a young Forsaken woman running towards the old inn. She was screaming for her life, pleading to be taken back home. Not all of us are as resolute as others, <name>. Even so, we must accept our fate as undead if we are to rise up against those that would put us down. Take my hand mirror and show it to the young woman. She needs to see what she really is, and join us in our cause. Besides... we can use all the bodies that we can get.", ["objectivesText"] = "Find Lilian Voss inside the large inn in Deathknell . Then speak with her to show her Elreth's Hand Mirror . Progress: Have you spoken with her yet? She needs to be shown the truth.", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["rewardItems"] = { 52050 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1661, ["x"] = 0.308, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1661, ["x"] = 0.308, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 10, ["flags"] = 0 } } },
[24970] = { ["id"] = 24970, ["name"] = "No Better Than the Zombies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "While you were inside that cave, your big friend Darnell came by with some alarming news. Since the val'kyr arrived, we've seen more and more undead that chose not to join our forces under the banner of the Dark Lady. They've been gathering at a small camp here in the valley, and now they've organized forces. They plan to attack Deathknell , <class>. Darnell is just down the road, to the east. Be careful, <name>. While those undead aren't completely brainless, they're still not quite right in the head.", ["objectivesText"] = "Report to Darnell at Deathknell in Tirisfal Glades.", ["rewardGold"] = 55, ["rewardXP"] = 25, ["rewardItems"] = { 159, 3267, 3268, 3269, 5779 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1570, ["x"] = 0.328, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 49425, ["x"] = 0.356, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 14, ["flags"] = 0 } } },
[24971] = { ["id"] = 24971, ["name"] = "Assault on the Rotbrain Encampment", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "While you were taking care of matters for Executor Arren, I went off on an assignment of my own. Shadow Priest Sarvis asked me to peek in on the Rotbrain camp. There's a reason why they're called Rotbrains. Their leader goes by the name of Marshal Redpath , and he's an absolute beast. Look, <name>... the attack is starting. You're better in combat than I am. Get in there and help out! When you're done, meet up with Shadow Priest Sarvis in the chapel. Good luck, <name>.", ["objectivesText"] = "Kill Marshal Redpath and 8 Rotbrain undead.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 3276, 3277 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 49425, ["x"] = 0.356, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1569, ["x"] = 0.308, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 15, ["flags"] = 0 } } },
[24972] = { ["id"] = 24972, ["name"] = "Vital Intelligence", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "<Sarvis produces a piece of paper from within his robes.> These will need to be taken to my field agent, Deathguard Simmer . This information contains the whereabouts of the last few holdouts from the Scarlet Crusade. We will destroy these crusaders, once and for all. And I have a feeling you'll be instrumental in that effort, <name>. Take the road north out of Deathknell . Soon after entering Tirisfal proper, you'll see a large manse. Simmer's inside.", ["objectivesText"] = "Deliver the Scarlet Crusade Documents to Deathguard Simmer at Calston Estate in Tirisfal Glades. Progress: Yes, what do you want?", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["rewardItems"] = { 2885 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1569, ["x"] = 0.308, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1519, ["x"] = 0.446, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 16, ["flags"] = 0 } } },
[24973] = { ["id"] = 24973, ["name"] = "Night Web's Hollow", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce in Lordaeron, even in the height of the Alliance's power so many years ago. There is a gold mine to the west that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little. Get up there and see what you can do for us, <name>.", ["objectivesText"] = "Kill 8 Young Night Web Spiders and 5 Night Web Spiders . Progress: Be wary of the spiders' venom, <name>. If you feel a sharp burning, you may want to have it looked at.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 3270, 3272, 3273, 57139, 131387 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1570, ["x"] = 0.328, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1570, ["x"] = 0.328, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 13, ["flags"] = 0 } } },
[24974] = { ["id"] = 24974, ["name"] = "Ever So Lonely", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "You work hard your whole life, and what do you get? Killed by a plague. Then you work even harder in undeath, and what do you get? Money, yes, and a small estate with a few pesky hangers-on, but happiness? Not so much. I'm lonely in my old age, <name>. I need a companion. Use this leash on one of the murlocs at the Whispering Shore to the northwest. You'll have to weaken it first before it can be leashed. Then bring it back to me.", ["objectivesText"] = "Use the Murloc Leash on a Vile Fin murloc at the Whispering Shore, then return it to Sedrick Calston at Calston Estate. Progress: Oh, the pain of loneliness is too much to bear!", ["rewardGold"] = 232300, ["rewardXP"] = 150, ["rewardItems"] = { 2505, 4358, 6714, 52059, 120968, 137663 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 38925, ["x"] = 0.446, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 38925, ["x"] = 0.446, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 0, ["flags"] = 0 } } },
[24975] = { ["id"] = 24975, ["name"] = "Fields of Grief", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24976, 24977 }, ["description"] = "What have we here? You look like a fledgling <class>. If you hope to prove yourself to the Dark Lady, you need to learn the ways of the Forsaken. To the west you'll find a farm. Humans infest the land like mold on a rotting corpse. And worse yet, the Scarlet Crusade patrols nearby from their tower. Teach those scum a lesson and steal 10 of their precious pumpkins. Once you have 10, bring them back to me.", ["objectivesText"] = "Steal 10 pumpkins from the Solliden Farmstead in Tirisfal Glades . Progress: Were you able to gather 10 pumpkins yet, <name>?", ["rewardGold"] = 105000, ["rewardXP"] = 150, ["rewardItems"] = { 2846 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1518, ["x"] = 0.446, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1518, ["x"] = 0.446, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 1, ["flags"] = 0 } } },
[24976] = { ["id"] = 24976, ["name"] = "Variety is the Spice of Death", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24975, 24977 }, ["description"] = "These pumpkins have a purpose, <class>. They'll be the delivery mechanism for my latest batch of plague, which should be a particularly painful and virulent concoction. However, the plague requires a few rare ingredients. We'll need Marrowpetals , which grow at the bottom of Stillwater Pond, just to the east of here. We'll also need Xavren's thorn , which grows on rocky cliffs to the northwest. Finally, we need some briny sea cucumbers , found in the surf off of Whispering Shore.", ["objectivesText"] = "Obtain 4 Marrowpetals , 4 Xavren's Thorns , and 8 Briny Sea Cucumbers . Progress: I've got a feeling this will be my best batch yet, good <class>.", ["rewardGold"] = 309800, ["rewardXP"] = 150, ["rewardItems"] = { 52066, 52067, 52068, 57147, 57148, 57790, 131388 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1518, ["x"] = 0.446, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1518, ["x"] = 0.446, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 2, ["flags"] = 0 } } },
[24977] = { ["id"] = 24977, ["name"] = "Johaan's Experiment", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24975, 24976 }, ["description"] = "Harmless pumpkins, right? Or so it would seem. If we are to defeat the Scourge advances from the North and the human infestation from the South we need to start realizing the full potential of our gift of undeath. With a little ingenuity a simple pumpkin becomes an agent for our Dark Lady. This pumpkin, laced with my latest formula, will prove to be quite a treat. Yet another Scarlet Zealot has been captured and is being kept outside, by the gazebo. Take this pumpkin to the fool.", ["objectivesText"] = "Take the Laced Pumpkin to the Captured Scarlet Zealot at the gazebo at Calston Estate. Progress: Stay away, foul and unholy creature! May the Light protect me! The Scarlet Crusade shall rid Azeroth of your... ...oh wait. Is that food for me? I am so hungry...", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 3035 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1518, ["x"] = 0.446, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1931, ["x"] = 0.445, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 4, ["flags"] = 0 } } },
[24978] = { ["id"] = 24978, ["name"] = "Reaping the Reapers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24980 }, ["description"] = "Humans are notoriously fickle creatures. The farmers to the west are no exception. Sure, they may be plowing their fields peacefully now, but tomorrow, they may be raising their scythes against us. The Alliance looms close by in Gilneas, and the power of Stormwind looms to the south... any of these could recruit these tillers and use them as a wedge against us. I want them dead. See to it that it's done.", ["objectivesText"] = "Kill 10 Tirisfal Farmers or Tirisfal Farmhands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 57145, 57146, 133700, 156938 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1519, ["x"] = 0.446, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1519, ["x"] = 0.446, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 5, ["flags"] = 0 } } },
[24979] = { ["id"] = 24979, ["name"] = "A Scarlet Letter", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "Lieutenant Gebler: How curious that you would decide to take a prisoner... an undead one at that. What were you thinking? Do you think that, just because of the prisoner's former status, that she would be above the edicts of the Scarlet Crusade? This is most troubling, Gebler. I would remind you that there are penalties for such behavior. I command you to execute the prisoner at once. She is no longer one of us.", ["objectivesText"] = "Find the prisoner in Scarlet Palisade. Progress: A letter? What does it say?", ["rewardGold"] = 232300, ["rewardXP"] = 100, ["rewardItems"] = { 52079 }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1519, ["x"] = 0.446, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 6, ["flags"] = 0 } }, ["startItems"] = { 52079 } },
[24980] = { ["id"] = 24980, ["name"] = "The Scarlet Palisade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24978 }, ["description"] = "We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave. Prove to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slaying 10 warriors of the Scarlet Crusade.", ["objectivesText"] = "Kill 10 Scarlet Warriors .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 52079 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1519, ["x"] = 0.446, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1519, ["x"] = 0.446, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 7, ["flags"] = 0 } } },
[24981] = { ["id"] = 24981, ["name"] = "A Thorn in our Side", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "Information we've received from Executor Arren in Deathknell contain all the details we need to wipe the human infestation from the lands. According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill. Kill 3 of his zealots and 3 of his missionaries. And while you're there, see if you can dig up any other information about what they're up to.", ["objectivesText"] = "Kill 3 Scarlet Zealots and 3 Scarlet Missionaries , and obtain the Scarlet Epistle. Progress: We shall herd the Scarlet Crusade like cattle to their demise.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 52077 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1515, ["x"] = 0.605, ["y"] = 0.519 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1515, ["x"] = 0.605, ["y"] = 0.519 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.519 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 9, ["flags"] = 0 } } },
[24982] = { ["id"] = 24982, ["name"] = "The New Forsaken", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24982 }, ["series"] = { 24983 }, ["description"] = "Speaking frankly, the Forsaken of yesteryear were a sniveling, pathetic group. We huddled together in decrepit old human buildings, hiding from the Scourge, cowering from the Alliance, and groveling at the foot of the Horde. Look before you now, and see the product of the new Forsaken. We have made our mark here on Azeroth, and that mark will grow. Our dominion will soon blanket the world! You want my advice? Speak with Magistrate Sevren in Brill, down this road. He runs that town.", ["objectivesText"] = "Report to Magistrate Sevren at Brill in Tirisfal Glades .", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1496, ["x"] = 0.525, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1499, ["x"] = 0.61, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[24983] = { ["id"] = 24983, ["name"] = "Forsaken Duties", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24982 }, ["description"] = "I need a fresh report from our Deathguard waystation to the east. I must know if more Scourge forces have slipped past The Bulwark and into Tirisfal. Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here! Travel south along the road, then east at the fork to the waystation. Speak with Deathguard Linnea . She has the information I need.", ["objectivesText"] = "Speak with Deathguard Linnea at Death's Watch Waystation in Tirisfal Glades .", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1499, ["x"] = 0.61, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1495, ["x"] = 0.654, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 10, ["flags"] = 0 } } },
[24988] = { ["id"] = 24988, ["name"] = "The Chill of Death", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "It's so cold, now. The Plague of Undeath crawls through my veins like an icy serpent. The mindless state will be upon me soon. But no doomed destiny will prevent me from serving our Dark Lady. When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army. Now my hands shake from the chill. If you would bring me five duskbat pelts , I could sew myself a blanket. Help me, <name>, so that I can continue to serve the cause.", ["objectivesText"] = "Obtain five Duskbat Pelts . Progress: Do you have five duskbat pelts yet, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 100, ["rewardItems"] = { 2876, 57151, 57152, 57153, 131389 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1521, ["x"] = 0.652, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1521, ["x"] = 0.652, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 11, ["flags"] = 0 } } },
[24989] = { ["id"] = 24989, ["name"] = "Return to the Magistrate", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "You should return to Magistrate Sevren with the information I gave you. He'll want it as soon as possible, so be swift.", ["objectivesText"] = "Return to Magistrate Sevren in Brill.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1495, ["x"] = 0.654, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1499, ["x"] = 0.61, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 12, ["flags"] = 0 } } },
[24990] = { ["id"] = 24990, ["name"] = "Darkhound Pounding", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24996 }, ["description"] = "Lady Sylvanas has called upon the Royal Apothecary Society. She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring our enemies - living and dead - to ruin. My studies show that the blood of beasts might prove to be the key. Here, fill these vials with darkhound blood so I can test my theory.", ["objectivesText"] = "Collect 5 Vials of Darkhound Blood . Progress: Have you collected the darkhound blood yet, <name>? Time is fleeting!", ["rewardGold"] = 169800, ["rewardXP"] = 100, ["rewardItems"] = { 2858, 3382 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10665, ["x"] = 0.6, ["y"] = 0.528667 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 10665, ["x"] = 0.6, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.528667 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 13, ["flags"] = 0 } } },
[24991] = { ["id"] = 24991, ["name"] = "Garren's Haunt", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24991 }, ["description"] = "As you're probably already realizing, the Royal Apothecary Society is a widespread organization. We take our plague-alchemy seriously. It is our belief that the more agents we have performing experiments, the sooner we will realize our objective. One of our agents performs his work at a small encampment to the north of here. His name is Jerrod, and he could use an apprentice of your... stature.", ["objectivesText"] = "Report to Apothecary Jerrod at Garren's Haunt in Tirisfal Glades .", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10665, ["x"] = 0.6, ["y"] = 0.528667 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 38977, ["x"] = 0.615, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.528667 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[24992] = { ["id"] = 24992, ["name"] = "Escaped From Gilneas", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24993 }, ["description"] = "As far as you know, a worgen rogue roaming in Tirisfal is a new development. This is something that Executor Zygand would certainly be interested in.", ["objectivesText"] = "Report the worgen's presence to Executor Zygand at Brill in Tirisfal Glades .", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["rewardItems"] = { 97919, 137663 }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1515, ["x"] = 0.605, ["y"] = 0.519 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.519 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 15, ["flags"] = 0 } } },
[24994] = { ["id"] = 24994, ["name"] = "Doom Weed", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24995 }, ["description"] = "My envoy just delivered me a bushel of gloom weed. Gloom weed! I don't need gloom weed, I need doom weed ! You can see the predicament that I'm in, <name>. I'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward. It is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.", ["objectivesText"] = "Collect 10 Doom Weed . Progress: <The apothecary mutters to himself.> They brought me gloom weed? GLOOM WEED?!", ["rewardGold"] = 105000, ["rewardXP"] = 150, ["rewardItems"] = { 13702 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 38977, ["x"] = 0.615, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 38977, ["x"] = 0.615, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 17, ["flags"] = 0 } } },
[24995] = { ["id"] = 24995, ["name"] = "Off the Scales", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24994 }, ["description"] = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated. I will need several scales from murlocs in the vicinity. You will find the creatures ambling brainlessly along the coast to the north.", ["objectivesText"] = "Obtain 5 Vile Fin Scales . Progress: <name>, were you able to obtain those scales from the murlocs?", ["rewardGold"] = 169800, ["rewardXP"] = 150, ["rewardItems"] = { 2859, 3434, 57149, 57150 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 38977, ["x"] = 0.615, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 38977, ["x"] = 0.615, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 18, ["flags"] = 0 } } },
[24996] = { ["id"] = 24996, ["name"] = "Holland's Experiment", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24990 }, ["description"] = "I am to understand that another one of those foolish Dwarven Mountaineers has just been captured. The deathguard has him stored here in this building, and they've assigned one of their own to persuade him not to escape. Why don't you go see how the Captured Mountaineer enjoys this special drink I made for him? It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", ["objectivesText"] = "Bring Holland's Special Drink to the Captured Mountaineer . Progress: Why if I had my trusted rifle you'd be as good as dead, <class>. Just wait until the Steam Tank Brigade arrives to rescue me!", ["rewardGold"] = 280900, ["rewardXP"] = 100, ["rewardItems"] = { 3460, 57143, 57144, 131390 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10665, ["x"] = 0.6, ["y"] = 0.528667 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 2211, ["x"] = 0.6, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.528667 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 14, ["flags"] = 0 } } },
[24997] = { ["id"] = 24997, ["name"] = "Graverobbers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24998 }, ["description"] = "The mass graves within the forest to the west of us were made to accommodate the... impressive... number of deaths Tirisfal suffered when the plague first came. The bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide gnolls to gather the corpses and use them to bolster their armies. This cannot be allowed! Your task is twofold: slay the Rot Hides at the mass grave and Garren's Haunt, and gather from them the embalming ichor that gives them life.", ["objectivesText"] = "Kill Rot Hide Graverobbers and Rot Hide Mongrels , and obtain 6 flasks of Embalming Ichor . Progress: Is your task complete? Have you destroyed those dog-things and drained them of their ichor?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 2834, 3439, 6063 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 38978, ["x"] = 0.615, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 38978, ["x"] = 0.615, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 19, ["flags"] = 0 } } },
[24998] = { ["id"] = 24998, ["name"] = "Maggot Eye", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 24997 }, ["description"] = "Maggot Eye is a foul beast, even by gnoll standards. He leads a band of renegade gnolls through the land, tearing up the glades and stealing whatever corpses he can find along the way. Those are our corpses! We had plans for those! Maggot Eye resides just up the path from us. Show him no mercy. Mercy is for the weak.", ["objectivesText"] = "Kill Maggot Eye and obtain his paw. Progress: Yes?", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 3635, 57158, 57159, 57160, 131392, 228445, 228446, 228447, 228448 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 38978, ["x"] = 0.615, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 38978, ["x"] = 0.615, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 20, ["flags"] = 0 } } },
[24999] = { ["id"] = 24999, ["name"] = "Planting the Seed of Fear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "It seems that Jerrod has you hunting the murlocs to the north. That's good... we can use their parts for our poisons. I get a little worried sometimes, though... The Vile Fin spawning grounds are not far off Tirisfal's northern coast, so you'll probably notice several tadpoles among the adults on the shore. If these impressionable young murlocs were to seek revenge against us... that could ruin us. Go chase them, and show them that the Forsaken and the Horde are not to be trifled with.", ["objectivesText"] = "Chase 12 Vile Fin Tadpoles until they pass out in fear.", ["rewardGold"] = 169800, ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 38978, ["x"] = 0.615, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 38978, ["x"] = 0.615, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 21, ["flags"] = 0 } } },
[25003] = { ["id"] = 25003, ["name"] = "The Family Crypt", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25031 }, ["description"] = "The strongest point in the mills is the Agamand Family Crypt. With necromancy, Captain Dargol has raised the ancestors of the Agamands and plans to use them against us. This cannot pass, and you must stop it. Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.", ["objectivesText"] = "Kill 5 Wailing Ancestors and 5 Rotting Ancestors . Progress: Time is not a luxury we have, <name>. With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", ["rewardGold"] = 309800, ["rewardXP"] = 150, ["rewardItems"] = { 57161, 57162, 57163, 131393 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 22, ["flags"] = 0 } } },
[25004] = { ["id"] = 25004, ["name"] = "The Mills Overrun", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "The Scourge are trying to form a base here at the Agamand Mills. If they do, then they can stage further attacks within Tirisfal. The orders have been given. The Scourge in the Mills must be destroyed. Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.", ["objectivesText"] = "Gather 5 Notched Ribs and 3 Blackened Skulls . Progress: Our battles with the Scourge wage on, <name>. Do your part and throw those cursed, mindless <race> back into the Plaguelands!", ["rewardGold"] = 619600, ["rewardXP"] = 150, ["rewardItems"] = { 3162, 3163 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 23, ["flags"] = 0 } } },
[25005] = { ["id"] = 25005, ["name"] = "Speak with Sevren", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25006, 25007, 25009, 25010, 25011, 25012, 25046, 26964, 26965, 28568 }, ["description"] = "I have destroyed the remains you've given me, <name>. That is, all remains except for these... Devlin Agamand was weak and sharp-tongued in life, and was among the first to succumb to the plague. He existed as a slave of the Scourge for a long time, longer than most. As such, he may possess knowledge that would be of value to us. Bring his remains to Magistrate Sevren , and tell him what I've told you. He'll know what to do.", ["objectivesText"] = "Speak with Magistrate Sevren at Brill in Tirisfal Glades . Progress: The fetor of Scourge hangs about you, <name>. What is it you seek?", ["rewardGold"] = 42450, ["rewardXP"] = 25, ["rewardItems"] = { 2831 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1499, ["x"] = 0.61, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 25, ["flags"] = 0 } } },
[25006] = { ["id"] = 25006, ["name"] = "The Grasp Weakens", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25005, 25007, 25009, 25010, 25011, 25012, 25046, 26964, 26965, 28568 }, ["description"] = "While the Frozen Throne lies dormant, the grasp that the Lich King once held over the Scourge grows ever-weaker. His grip on a weakling like Devlin Agamand should be weak enough that we can remove it entirely. Speak with Shadow Priestess Malia in the manor on the east side of town. She will assist you in the procedure.", ["objectivesText"] = "Speak with Shadow Priestess Malia in Brill and participate in the extraction of Devlin Agamand. Progress: What did you find out?", ["rewardGold"] = 561800, ["rewardXP"] = 200, ["rewardItems"] = { 2831, 2839, 57164, 57165, 131394 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1499, ["x"] = 0.61, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1499, ["x"] = 0.61, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 26, ["flags"] = 0 } } },
[25007] = { ["id"] = 25007, ["name"] = "East... Always to the East", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25005, 25006, 25009, 25010, 25011, 25012, 25046, 26964, 26965, 28568 }, ["description"] = "You've done much for us here, <name>, but <men/women> of your caliber are needed elsewhere. To the east lies the Bulwark: a fortified barricade against the ravages of the Plaguelands. The Bulwark protects us from Scourge invasions, and has allowed us enough sanctity to build up our forces here in Tirisfal Glades . Go, speak with High Executor Derrington . He is an ally, and will doubtless appreciate whatever aid you can give him.", ["objectivesText"] = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades .", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1499, ["x"] = 0.61, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 10837, ["x"] = 0.549, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 28, ["flags"] = 0 } } },
[25009] = { ["id"] = 25009, ["name"] = "At War With The Scarlet Crusade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25005, 25006, 25007, 25010, 25011, 25012, 25046, 26964, 26965, 28568 }, ["description"] = "Though the strength of the Scarlet Crusade wanes, we are still at war. The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon. Kill 3 of his zealots and 4 of his friars. It should prove to be a devastating blow to the Crusade!", ["objectivesText"] = "Slay 3 Scarlet Zealots and 4 Scarlet Friars .", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10837, ["x"] = 0.549, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 10837, ["x"] = 0.549, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 22, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 31, ["flags"] = 0 } } },
[25010] = { ["id"] = 25010, ["name"] = "A Deadly New Ally", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25005, 25006, 25007, 25009, 25011, 25012, 25046, 26964, 26965, 28568 }, ["description"] = "Shortly before you arrived at the Bulwark, I was approached by the most unusual young undead woman. She swore enmity against the Scarlet Crusade, so I sent her to work on our enemies to the north. You say you saw some dead crusaders earlier? Those were probably her work. Go check up on her, and see if she can use any assistance in her vendetta against the Crusade... though I wouldn't be surprised if she's already killed them all.", ["objectivesText"] = "Look for your new ally at the Scarlet Encampment in Tirisfal Glades .", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10837, ["x"] = 0.549, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 13158, ["x"] = 0.874667, ["y"] = 0.433333 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 32, ["flags"] = 0 } } },
[25011] = { ["id"] = 25011, ["name"] = "To Bigger and Better Things", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25005, 25006, 25007, 25009, 25010, 25012, 25046, 26964, 26965, 28568 }, ["description"] = "There isn't much more glory for you here on the Bulwark, <name>. You've done enough already. There may, however, be further adventures waiting in Silverpine Forest. Speak with my bat man, Timothy Cunningham . He'll give you a ride to Brill, free of charge.", ["objectivesText"] = "Speak with Timothy Cunningham at the Bulwark in Tirisfal Glades .", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10837, ["x"] = 0.549, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 37915, ["x"] = 0.835, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 34, ["flags"] = 0 } } },
[25012] = { ["id"] = 25012, ["name"] = "Take to the Skies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25005, 25006, 25007, 25009, 25010, 25011, 25046, 26964, 26965, 28568 }, ["description"] = "If you're headed back to Brill, you'll want to stop by Executor Zygand on your way out. I hear there's some excitement going on in Silverpine Forest, to the south. He'll know more than I do. Speak with me again when you're ready to head out.", ["objectivesText"] = "Speak with Executor Zygand at Brill in Tirisfal Glades .", ["rewardGold"] = 210675, ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 37915, ["x"] = 0.835, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1515, ["x"] = 0.605, ["y"] = 0.519 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.835, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 35, ["flags"] = 0 } } },
[25013] = { ["id"] = 25013, ["name"] = "A Little Oomph", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25056 }, ["description"] = "<Dithers samples his latest concoction.> Hmm... this isn't quite there. It needs something to give it a little more zing. I've got it! The spiders to the north have a potent venom that'll do the trick. See if you can extract some for me, <name>?", ["objectivesText"] = "Obtain 4 samples of Vicious Night Web Spider Venom . Progress: Do you have some venom from a Vicious Night Web Spider yet, <name>? It's the final component I need in order to test my experiment.", ["rewardGold"] = 280900, ["rewardXP"] = 150, ["rewardItems"] = { 2872, 57166, 57167, 57168 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 11057, ["x"] = 0.549, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 11057, ["x"] = 0.549, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 30, ["flags"] = 0 } } },
[25023] = { ["id"] = 25023, ["name"] = "Old Friends", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4720, ["mapID"] = 174, ["storyline"] = { 25023 }, ["series"] = { 24925, 24929, 24937, 24940, 24942, 24952, 24954, 24958, 25024 }, ["description"] = "Alright then, grab onto the ladder. We gotta get outa here! We'll make a flyby of the town, and then I'm gonna get you to some old friends!", ["objectivesText"] = "Speak with Thrall at the Warchief's Lookout on the Lost Isles .", ["rewardGold"] = 309800, ["rewardXP"] = 25, ["rewardItems"] = { 121594, 121595, 121596, 121597, 129986, 129994, 130002, 130013, 237812 }, ["ends"] = { { ["mapID"] = 174, ["npcID"] = 38935, ["x"] = 0.394, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 174, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 174 }, ["zone"] = { 4720 } }, ["questType"] = "standard" },
[25029] = { ["id"] = 25029, ["name"] = "Deaths in the Family", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "The Agamand family was the most prosperous family in Tirisfal Glades . I used to work their mills...before the plague. When the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend. We were fools, but at least we were loyal fools. The Agamands, in their pride, doomed us to undeath. And now they are minions of the Scourge! Serve the Forsaken by defeating the Agamands who fell to the plague. Serve me by bringing me their remains.", ["objectivesText"] = "Obtain Gregor's Remains , Nissa's Remains , Thurman's Remains , and Devlin's Remains . Progress: Do you have the remains of the Agamands? Are those cursed beasts finally destroyed?", ["rewardGold"] = 7150, ["rewardXP"] = 200, ["rewardItems"] = { 2828, 2829, 2830, 2831, 3440, 3446 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 24, ["flags"] = 0 } } },
[25030] = { ["id"] = 25030, ["name"] = "The Haunted Mills", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "You sense a malign presence coming from within the skull of the beast. Coleman Farthing may be interested in seeing this.", ["objectivesText"] = "Bring Dargol's Skull to Coleman Farthing at the Agamand Mills. Progress: Well well... what do we have here?", ["rewardGold"] = 210000, ["rewardXP"] = 200, ["rewardItems"] = { 3082 }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 27, ["flags"] = 0 } }, ["startItems"] = { 3082 } },
[25031] = { ["id"] = 25031, ["name"] = "Head for the Mills", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 25031 }, ["series"] = { 25003 }, ["description"] = "The Agamand Mills, to the west, have been lost to the Scourge. The Agamand family has been slain, and the entire residence has been claimed by the Scourge. This is probably the largest Scourge outpost in Tirisfal, <name>. If you think you're enough of a <class>, head up there and speak with Coleman Farthing . He's been doing his best to take the land back, and he'll need help. Just follow this road, it'll take you right to him.", ["objectivesText"] = "Report to Coleman Farthing at Agamand Mills in Tirisfal Glades .", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 38977, ["x"] = 0.615, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1500, ["x"] = 0.545, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[25035] = { ["id"] = 25035, ["name"] = "Breaking the Line", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["description"] = "Vol'jin be callin' for an all out attack on da naga that have taken over our northern isle. Many of our men were already engaged with their forces near da bridge, but several of us are breakin' through their lines ta assault their isle itself. Speak to Jornun right 'ere to secure a ride to da isle. Once there, seek out Morakki , da Captain of da Watch. He will be tellin' ya how ya can aid in da battle.", ["objectivesText"] = "Speak to Jornun to secure a ride to Spitescale Cove and then seek out Morakki .", ["rewardGold"] = 500, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38440, ["x"] = 0.678, ["y"] = 0.89 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38442, ["x"] = 0.678, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.89 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 52, ["flags"] = 0 } } },
[25037] = { ["id"] = 25037, ["name"] = "Crab Fishin'", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["description"] = "Perhaps me agin' body is just growin' too picky after all dese years, but boar meat just ain't goin' down easy no more. More for da new recruits I be thinkin'. We just set out some crab traps, but if ya be willin' ta help an impatient old troll, I'd love ta have some fresh crawler meat right now. Dey're all around da island, but da best spot ta be huntin' them is off da eastern coast.", ["objectivesText"] = "Kill Pygmy Surf Crawlers and collect 5 Fresh Crawler Meat . Progress: Da sea be offerin' few boons as delicious as fresh crawler meat .", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 52080 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39007, ["x"] = 0.684, ["y"] = 0.876 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39007, ["x"] = 0.684, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.876 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 51, ["flags"] = 0 } } },
[25038] = { ["id"] = 25038, ["name"] = "Gordo's Task", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed . Many weeds around here and near road. When you have gloom weed you take to Master Holland in Brill.", ["objectivesText"] = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in Brill. Progress: Where's that useless abomination? Either you have what I need or you'd best get out there and find it.", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["rewardItems"] = { 12737 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10666, ["x"] = 0.444, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 10665, ["x"] = 0.6, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 3, ["flags"] = 0 } } },
[25046] = { ["id"] = 25046, ["name"] = "A Daughter's Embrace", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25005, 25006, 25007, 25009, 25010, 25011, 25012, 26964, 26965, 28568 }, ["description"] = "The whisper continues: <\"My name is Lilian Voss. Before I died, I was a member of the Scarlet Crusade. My father, High Priest Voss, raised me to be a weapon against the plagued. I studied stealth, sorcery, martial arts, anything to make myself stronger. I gave up my childhood for him.\"> <\"Then, as fate would have it, I died and returned as... this. My father instantly forgot me and, when I returned, ordered me executed.\"> <\"Come. We will speak with him now, in his tower to the northwest.\">", ["objectivesText"] = "Bring Lilian Voss to her father in the tower at Crusader's Run.", ["rewardGold"] = 561800, ["rewardXP"] = 250, ["rewardItems"] = { 57169, 57170, 57171, 57791 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 13158, ["x"] = 0.874667, ["y"] = 0.433333 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 10837, ["x"] = 0.549, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.874667, ["y"] = 0.433333 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 33, ["flags"] = 0 } } },
[25047] = { ["id"] = 25047, ["name"] = "Broken Panther Figurine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5095, ["storyline"] = { 25047 }, ["description"] = "This badly broken figurine was discarded by its last owner. However, with the right materials and your skill in jewelcrafting, it could be completely restored.", ["objectivesText"] = "Repair the broken figurine using your skill and materials.", ["rewardXP"] = 1415, ["rewardItems"] = { 9719, 52186, 52194, 52197, 52199, 54849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5095 } }, ["questType"] = "standard", ["startItems"] = { 52197 } },
[25056] = { ["id"] = 25056, ["name"] = "Grisly Grizzlies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["series"] = { 25013 }, ["description"] = "Have you seen the plagued bruins that wander to the west of here? Those hides... so hideous, so diseased, so... perfect! Fetch me 5 of them. I've got an idea for an anti-Scourge poison that's guaranteed to succeed!", ["objectivesText"] = "Obtain 5 Plagued Bruin Hides . Progress: Let's see... do you have enough hides?", ["rewardGold"] = 105000, ["rewardXP"] = 150, ["rewardItems"] = { 52270 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 11057, ["x"] = 0.549, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 11057, ["x"] = 0.549, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 29, ["flags"] = 0 } } },
[25064] = { ["id"] = 25064, ["name"] = "Moraya", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 24622, 24623, 24626 }, ["description"] = "Moraya has been lookin' for some help with tha raptors. Ya should talk to her on the other side of Darkspear Hold when ya get a chance.", ["objectivesText"] = "Speak with Moraya .", ["rewardGold"] = 200, ["rewardXP"] = 25, ["rewardItems"] = { 50018, 52283 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38966, ["x"] = 0.688, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38005, ["x"] = 0.672, ["y"] = 0.88 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 45, ["flags"] = 0 } } },
[25073] = { ["id"] = 25073, ["name"] = "Sen'jin Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6, 8, 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 24607, 24622, 24623, 24624, 24625, 24626, 24639, 24641, 24642, 24643, 24750, 24751, 24753, 24754, 24755, 24758, 24759, 24761, 24762, 24763, 24764, 24765, 24767, 24768, 24769, 24770, 24771, 24773, 24774, 24775, 24776, 24777, 24779, 24780, 24781, 24782, 24783, 24785, 24786, 24787, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["description"] = "You've be doin' quite well for one so young. I've no doubts you'll be makin' quite da name for yarself. Go now, northwest, across da shallows ta Sen'jin Village. Dere you'll be meetin' Master Gadrin . He'll likely have a task or two for ya before ya truly make ya way out into the Durotar wilds. Please remember, <name>, we may disagree wit' the young Hellscream at times, but his intentions are noble, and it be very important that we remain united as one Horde. Make da Darkspear proud.", ["objectivesText"] = "Report to Master Gadrin in Sen'jin Village.", ["rewardGold"] = 200, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 38966, ["x"] = 0.688, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3188, ["x"] = 0.559, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 56, ["flags"] = 0 } } },
[25089] = { ["id"] = 25089, ["name"] = "Beyond the Graves", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "Darnell tells me that the two of you have already met. That's good, because I'm sending you both into Deathknell . Your work is done here. Speak with Deathguard Saltain in Deathknell , to the north. He will tell you more of what you must know.", ["objectivesText"] = "Speak with Deathguard Saltain at Deathknell in Tirisfal Glades.", ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 2307, ["x"] = 0.306, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1740, ["x"] = 0.316, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 5, ["flags"] = 0 } } },
[25090] = { ["id"] = 25090, ["name"] = "A Putrid Task", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24974, 24975, 24976, 24977, 24978, 24979, 24980, 24981, 24983, 24988, 24989, 24990, 24992, 24993, 24994, 24995, 24996, 24997, 24998, 24999, 25003, 25004, 25005, 25006, 25007, 25009, 25010, 25011, 25012, 25013, 25029, 25030, 25038, 25046, 25056, 25090 }, ["description"] = "Scourge have trickled into Tirisfal Glades and have infested this area. I need someone to beat back the rotting dead and ravaged corpses that have taken this small farm. Scatter their bones and bring back their putrid claws . The Deathguards will reward you.", ["objectivesText"] = "Bring 7 Putrid Claws to Deathguard Dillinger in Cold Hearth Manor. Progress: Have you completed the task with which I have charged you? Do you have those putrid claws ?", ["rewardGold"] = 232300, ["rewardXP"] = 150, ["rewardItems"] = { 2855 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1496, ["x"] = 0.525, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1496, ["x"] = 0.525, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 8, ["flags"] = 0 } } },
[25105] = { ["id"] = 25105, ["name"] = "Nibbler! No!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 25105 }, ["description"] = "Lila's pet Nibbler got into my workshop again! I was making a bracelet, to be delivered today. The work was almost done, except for the gems. I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight! The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings. I need to get replacement gems fast; the courier is coming in tonight. Help!", ["objectivesText"] = "Cut three Solid Zephyrites and give them to Isabel Jones in Stormwind City. Progress: Have you brought the solid zephyrites I need?", ["rewardXP"] = 4115, ["rewardItems"] = { 46038, 52086, 52178 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.539333, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[25126] = { ["id"] = 25126, ["name"] = "Cutting Teeth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["series"] = { 25127, 25152, 25172 }, ["description"] = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead. I believe you'll be of more use to us slaughtering the boars you'll find in the farms to the north and northeast of here.", ["objectivesText"] = "Slaughter 6 Mottled Boars . Progress: I hope you haven't returned to try and convince me that you have completed your task, <name>? No, of course not. I would think better of you.", ["rewardGold"] = 110, ["rewardXP"] = 250, ["rewardItems"] = { 31446, 31447, 31448, 53359, 53360, 53378, 131849, 157549 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 1, ["flags"] = 0 } } },
[25127] = { ["id"] = 25127, ["name"] = "Sting of the Scorpid", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["series"] = { 25126, 25152, 25172 }, ["description"] = "I must send you back into the fields again, <class>. You will find large numbers of scorpids northwest of here. Bring me eight of their tails. The antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you... But I'm sure you won't be needing any of that, will you?", ["objectivesText"] = "Obtain 8 Scorpid Worker Tails . Progress: The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 4862, 53362, 53380, 53394, 131853 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 4, ["flags"] = 0 } } },
[25128] = { ["id"] = 25128, ["name"] = "Hana'zua", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25128 }, ["series"] = { 25129, 25130 }, ["description"] = "Hey mon, take a knee and hear me out. We got a problem. A good friend of mine, Hana'zua , has gone out into the valley and he hasn't returned. Last I seen, he was headin' north, where the scorpids hunt. Maybe you go take a look for him? The spirits be tellin' me that he's not well.", ["objectivesText"] = "Find Hana'zua in the Valley of Trials .", ["rewardGold"] = 500, ["rewardXP"] = 50, ["rewardItems"] = { 4905 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 5887, ["x"] = 0.424, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3287, ["x"] = 0.406, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard" },
[25129] = { ["id"] = 25129, ["name"] = "Sarkoth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 25129 }, ["series"] = { 25128, 25130 }, ["description"] = "<class>! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg. I wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", ["objectivesText"] = "Kill Sarkoth and bring his claw back to Hana'zua . Progress: Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right. At least I wish to die knowing that my last enemy in life lays dead.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 4905 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3287, ["x"] = 0.406, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3287, ["x"] = 0.406, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[25130] = { ["id"] = 25130, ["name"] = "Back to the Den", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25130 }, ["series"] = { 25128, 25129 }, ["description"] = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to our settlement unassisted. Please, <name>, return and tell Gornek of my situation. Perhaps he can help me.", ["objectivesText"] = "Bring the news of Hana'zua 's plight to Gornek in the Valley of Trials .", ["rewardGold"] = 500, ["rewardXP"] = 50, ["rewardItems"] = { 4905, 53354, 53370, 53371, 60241, 131851 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3287, ["x"] = 0.406, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard" },
[25131] = { ["id"] = 25131, ["name"] = "Vile Familiars", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["series"] = { 25132, 25133, 25167, 25168, 25171 }, ["description"] = "I trust the Valley of Trials will teach you much, young <class>. I was sent to the Valley to guide you, but I have discovered a growing taint here... One of the Burning Blade - a foul, demon-worshipping cult - has made camp here in the Valley of Trials . He skulks in a cave to the north, and his vile familiars have spilled from its mouth to cause havoc. As your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", ["objectivesText"] = "Kill 8 Vile Familiars . Progress: To prove yourself against the Burning Blade, you must first defeat these vile familiars . Return to me when you have done this.", ["rewardGold"] = 4000, ["rewardXP"] = 300, ["rewardItems"] = { 4859, 53395, 53396, 53397, 131403 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3145, ["x"] = 0.434, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3145, ["x"] = 0.434, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 6, ["flags"] = 0 } } },
[25132] = { ["id"] = 25132, ["name"] = "Burning Blade Medallion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["series"] = { 25131, 25133, 25167, 25168, 25171 }, ["description"] = "Through my divinations, I see that an item of power--a medallion--hides deep within the Burning Blade Coven, guarded by beasts and black magic. We must have it. For too long these demon-worshippers have defiled our homelands. Cleanse the coven of its demonic taint by slaying the fel beasts and their leader. Return with this medallion as proof of your deed. Go, <name>. You will find the coven in a cave to the north.", ["objectivesText"] = "Slay 5 Felstalkers and obtain the Burning Blade Medallion . Progress: Is your task complete, <name>?", ["rewardGold"] = 6000, ["rewardXP"] = 300, ["rewardItems"] = { 118, 4859, 53361, 53367, 53379, 131850 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3145, ["x"] = 0.434, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3145, ["x"] = 0.434, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 7, ["flags"] = 0 } } },
[25133] = { ["id"] = 25133, ["name"] = "Report to Sen'jin Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["series"] = { 25131, 25132, 25167, 25168, 25171 }, ["description"] = "Your trials against the Burning Blade are finished... here in the Valley. But I want you to report your findings. Go to the troll village of Sen'jin and seek out Master Gadrin . Sen'jin Village is east out of the valley, then right at the fork. Tell Gadrin of the Burning Blade, and that they have reached the Valley of Trials . Discover from him if they have yet reached Sen'jin. Go, <name>, and be swift. I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", ["objectivesText"] = "Speak with Master Gadrin in Sen'jin Village.", ["rewardGold"] = 100, ["rewardXP"] = 100, ["rewardItems"] = { 4859 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3145, ["x"] = 0.434, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3188, ["x"] = 0.559, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 9, ["flags"] = 0 } } },
[25135] = { ["id"] = 25135, ["name"] = "Thazz'ril's Pick", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["description"] = "<name>, you are a dependable <race>. Can I count on you for another task? Some time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind. When I later returned to retrieve it I found the cave was filled with vicious beasts! Will you go into the cave, the Burning Blade Coven, and get my pick? I left it in a chamber with waterfalls. My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", ["objectivesText"] = "Bring Thazz'ril's Pick to Foreman Thazz'ril . Progress: Have you entered the Burning Blade Coven, <name>? Did you find my pick?", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 16114, 16332 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 11378, ["x"] = 0.434, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 11378, ["x"] = 0.434, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 8, ["flags"] = 0 } } },
[25136] = { ["id"] = 25136, ["name"] = "Galgar's Cactus Apple Surprise", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["description"] = "It sure gets hot out here in the Valley of Trials . < Galgar wipes his brow.> If only I had some cactus apples , I could make my famous cactus apple surprise ! Nothing cools you off faster than a piece of that delicious treat. I'll tell you what, <name>. If you bring me six cactus apples , I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", ["objectivesText"] = "Obtain 6 Cactus Apples . Progress: Have you finished collecting cactus apples ?", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 11583, 11584, 202401 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 9796, ["x"] = 0.428, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 9796, ["x"] = 0.428, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 3, ["flags"] = 0 } } },
[25145] = { ["id"] = 25145, ["name"] = "Corruption", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["requiredRaces"] = { 2 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["storyline"] = { 25145 }, ["series"] = { 3090 }, ["description"] = "It is my duty to train you, and I intend to do just that. As you become more powerful, you will begin to hear the fel voices revealing new spells to you. Go, get more experience, learn a new spell, and then practice your new spell against one of the training dummies around here.", ["objectivesText"] = "Reach level 3 to learn Corruption . Locate a Training Dummy and practice casting Corruption 5 times. Progress: Once you have learned Immolate, then we can test your abilities.", ["rewardGold"] = 125, ["rewardXP"] = 125, ["rewardItems"] = { 961, 5392, 5393, 5398, 5399, 5586, 10544, 11190, 15103, 25913, 25914, 25915, 52595, 52621, 52633, 53363, 56679, 56680, 56681, 56682, 65822, 65823, 65824 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6451 } }, ["questType"] = "standard" },
[25149] = { ["id"] = 25149, ["name"] = "Frost Nova", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 2 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["storyline"] = { 25149 }, ["series"] = { 25138 }, ["description"] = "Alright, here's the easy part. All you have to do to deepen your connection to the arcane is to get more experience and grow your power. You'll begin to find that you can cast new spells. You'll see. Go try it, and show me what you learn.", ["objectivesText"] = "Reach level 3 to learn Frost Nova . Locate a Training Dummy and practice using Frost Nova 2 times.", ["rewardXP"] = 125, ["rewardItems"] = { 53365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6451 } }, ["questType"] = "standard" },
[25152] = { ["id"] = 25152, ["name"] = "Your Place In The World", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["series"] = { 25126, 25127, 25172 }, ["description"] = "Finally, you are of age, <name>... of age to battle in the name of the Horde. To conquer for the glory of the Warchief. Yes... < Kaltunk looks you over.> You will do nicely. No doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous. < Kaltunk laughs.> Report to Gornek , he should be able to assign a task better suited to a young <class>. You will find him seated at the fire behind me.", ["objectivesText"] = "Speak with Gornek .", ["rewardXP"] = 100, ["rewardItems"] = { 4862 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 10176, ["x"] = 0.432, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 0, ["flags"] = 0 } } },
[25154] = { ["id"] = 25154, ["name"] = "A Present for Lila", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 25154 }, ["description"] = "I'm trying to impress this trade ship captain Lila. I've been working on a necklace to match her lovely purple hair, but the gems have gone missing! They were there when I was showing them off to my good friend Curver last evening. We were drinking moonshine and I blacked out - when I woke up the gems were gone! They must have been darn good thieves, because Curver didn't see anything. Her ship is coming in tonight, and I really need three nightstones to get her present done. Help me out here!", ["objectivesText"] = "Cut three Timeless Nightstones and give them to Isabel Jones in Stormwind City. Progress: Have you brought me the nightstones?", ["rewardXP"] = 4115, ["rewardItems"] = { 52098 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.539333, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[25155] = { ["id"] = 25155, ["name"] = "Ogrezonians in the Mood", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 25155 }, ["description"] = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia. I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island. My work must go on, though, and we need those gems. I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", ["objectivesText"] = "Cut three Jagged Jaspers and give them to Isabel Jones in Stormwind City. Progress: Have you brought me the gems I need?", ["rewardXP"] = 4115, ["rewardItems"] = { 52121, 52182, 53038 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.539333, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[25156] = { ["id"] = 25156, ["name"] = "Elemental Goo", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 25156 }, ["description"] = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method. I simply glue on the gems with Barnsworth Elemental Glue! The professor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do. Can you go get me some?", ["objectivesText"] = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Isabel Jones in Stormwind City. Progress: Did you bring me the elemental goo ?", ["rewardXP"] = 4115, ["rewardItems"] = { 52328, 52506 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.539333, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[25157] = { ["id"] = 25157, ["name"] = "The Latest Fashion!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 25157 }, ["description"] = "Professor Barnsworth has been working on this new stardust - what with the fashion in Stormwind this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage! The Jewelcrafter's Association, however, won't let us market it until we've completed some humanoid testing - something about tinkering with magical dust being dangerous or some such nonsense. Well, I suppose we need to humor them. Take this bag and test out Stardust No. 2 on some humanoid subjects.", ["objectivesText"] = "Test Stardust No. 2 on 10 \"humanoid subjects\".", ["rewardXP"] = 4115, ["rewardItems"] = { 52180, 52490, 52507, 59507 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 50480, ["x"] = 0.539333, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.539333, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[25158] = { ["id"] = 25158, ["name"] = "Nibbler! No!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 25158 }, ["description"] = "Lila's pet Nibbler got into my workshop again! I was making a bracelet, to be delivered today. The work was almost done, except for the gems. I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight! The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings. I need to get replacement gems fast; the courier is coming in tonight. Help!", ["objectivesText"] = "Cut three Solid Zephyrites and give them to Marith Lazuria in Orgrimmar. Progress: Have you brought me those solid zephyrites I need?", ["rewardXP"] = 4115, ["rewardItems"] = { 52086 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.724667, ["y"] = 0.344667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[25159] = { ["id"] = 25159, ["name"] = "The Latest Fashion!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 25159 }, ["description"] = "Dr. Vernstrom has been working on this new stardust - what with the fashion in Orgrimmar this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage! The Jewelcrafter's Association, however, won't let us market it until we've completed some \"live testing\" - something about tinkering with magical dust being dangerous or some such nonsense. Well, I suppose we need to humor them. Take this bag and test out Stardust No. 2 on humanoid subjects.", ["objectivesText"] = "Test Stardust No. 2 on 10 \"humanoid subjects\".", ["rewardXP"] = 4115, ["rewardItems"] = { 52507 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.724667, ["y"] = 0.344667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[25160] = { ["id"] = 25160, ["name"] = "A Present for Lila", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 25160 }, ["description"] = "I'm trying to impress this trade ship captain Lila. I've been working on a necklace to match her lovely purple hair, but the gems have gone missing! They were there when I was showing them off to my good friend Bonder last evening. We were drinking moonshine and I blacked out - when I woke up the gems were gone! They must have been darn good thieves, because Bonder didn't see anything. Her ship is coming in tonight, and I really need three nightstones to get her present done. Help me out here!", ["objectivesText"] = "Cut three Timeless Nightstones and give them to Marith Lazuria in Orgrimmar. Progress: Have you brought me the nightstones?", ["rewardXP"] = 4115, ["rewardItems"] = { 52098, 52180 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.724667, ["y"] = 0.344667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
