[25162] = { ["id"] = 25162, ["name"] = "Elemental Goo", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 25162 }, ["description"] = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method. I simply glue on the gems with Vernstrom Elemental Glue! The doctor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do. Can you go get me some?", ["objectivesText"] = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Marith Lazuria in Orgrimmar. Progress: Did you bring me the elemental goo ?", ["rewardXP"] = 4115, ["rewardItems"] = { 52326, 52372, 52446, 52506 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 50482, ["x"] = 0.724667, ["y"] = 0.344667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.724667, ["y"] = 0.344667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[25165] = { ["id"] = 25165, ["name"] = "Never Trust a Big Barb and a Smile", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25170 }, ["description"] = "Next, we gonna get some poison from the scorpions that be runnin' around here. But don't you worry, Bom'bay 's not gonna let you get hurt! Bom'bay 's got a big totem that you gonna stick in the ground when the scorpion strikes. The totem gonna suck up all the poison, and you gonna walk away still breathing. Sound good?", ["objectivesText"] = "Obtain 6 samples of Scorpid Venom by placing the Poison Extraction Totem near a Clattering Scorpid. Progress: You got the jujus, ya?", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 2773, 52505, 120968 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 10578, ["x"] = 0.558, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 10578, ["x"] = 0.558, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[25167] = { ["id"] = 25167, ["name"] = "Breaking the Chain", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25131, 25132, 25133, 25168, 25171 }, ["description"] = "Aw man, this ain't good. Not one bit, mon. Thrall's off to sea, Vol'jin's taking care of business in Echo Isles, and old Master Gadrin is left behind to take care of Sen'jin. And then what happens? Those humans come outta Northwatch Hold and set up camp in our backyard! Lucky for us, they just got here, and they're still setting up their base. You can help out old Gadrin by destroying those big supply crates they carry, and by killing the laborers carryin' them. You'll find'm to the southwest.", ["objectivesText"] = "Destroy 3 Northwatch Supply Crates and kill 10 Northwatch Lugs . Progress: We gotta get rid of these humans, <class>.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3188, ["x"] = 0.559, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3188, ["x"] = 0.559, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.559, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[25168] = { ["id"] = 25168, ["name"] = "Purge the Valley", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25131, 25132, 25133, 25167, 25171 }, ["description"] = "Northwatch is a highly-defended stronghold southwest of here, across the harbor. It's a strategically-located stronghold that the Horde still struggles to overtake. We don't need the humans setting up another Northwatch here in Durotar . Sweep through the valley to the west and slay these humans, <name>. Let them know the power and the fury of Sen'jin.", ["objectivesText"] = "Defeat 12 Northwatch troops in Northwatch Foothold.", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 53388, 53389 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3188, ["x"] = 0.559, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3188, ["x"] = 0.559, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.559, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[25169] = { ["id"] = 25169, ["name"] = "The War of Northwatch Aggression", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "These humans in the west, they don't just wanna camp out in Durotar , mon. They got bigger plans, and those plans involve takin' our home and leavin' our skulls on pikes. Well I'm not havin' it. Nope! Not Lar! I've got family here in Sen'jin, and I'll be damned if I let one of those brutes put my Tai'tasi's head on a stick! They've got their plans written down in there, mon. Big scrolls, real important-lookin'. We gonna burn those scrolls before they burn us.", ["objectivesText"] = "Destroy the 3 sets of Attack Plans held within Northwatch Foothold. Progress: Destroy those humans, <name>.", ["rewardGold"] = 619600, ["rewardXP"] = 200, ["rewardItems"] = { 53364, 53391 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3140, ["x"] = 0.555, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3140, ["x"] = 0.555, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 4, ["flags"] = 0 } } },
[25170] = { ["id"] = 25170, ["name"] = "Cleaning Up the Coastline", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25165 }, ["description"] = "Heya mon! Bom'bay be workin' on some new mojo. You wanna try a piece of it? Well, before ya do, Bom'bay 's gonna need ya to pick up some jujus. First, Bom'bay needs ya to get some o' the goop from the crabs down by the water. Let me see your hands! < Bom'bay examines your hands closely.> Bom'bay gonna need 5 handfuls. Go on now!", ["objectivesText"] = "Obtain 5 handfuls of Crawler Mucus . Progress: You bring the jujus, I show you my mojo.", ["rewardGold"] = 55, ["rewardXP"] = 150, ["rewardItems"] = { 4888, 52505 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 10578, ["x"] = 0.558, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 10578, ["x"] = 0.558, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[25171] = { ["id"] = 25171, ["name"] = "Riding On", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25131, 25132, 25133, 25167, 25168 }, ["description"] = "We gotta pass the word on to Razor Hill. These humans may be defeated today, but tomorrow they'll come again, and when they do, we'll need help from the orcs. Speak with Jhash, outside the gates of Sen'jin. He'll give you a ride to Razor Hill. His wolves know the path well.", ["objectivesText"] = "Speak to Raider Jhash to get a ride to Razor Hill. Once there, speak with Gar'thok .", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 79802, 85429, 85430, 87399, 109584, 192761, 192762, 211279 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3188, ["x"] = 0.559, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.559, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 5, ["flags"] = 0 } } },
[25172] = { ["id"] = 25172, ["name"] = "Invaders in Our Home", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6451, ["mapID"] = 1, ["storyline"] = { 25126, 25127, 25131, 25132, 25133, 25135, 25136, 25152, 25172, 37446 }, ["series"] = { 25126, 25127, 25152 }, ["description"] = "You're not just another grunt - you seem to be a serious <class>. Good, because that's exactly what I need. Try not to let the word out, since I don't want to cause a panic... but there have been reports of more humans nearby. This is an egregious betrayal of the peace that we negotiated with that miserable Jaina Proudmoore! We can't allow humans here in Durotar, and especially not here in the Valley. You will find them to the south. Slay them quickly, before their numbers increase any more.", ["objectivesText"] = "Slay 7 Northwatch Scouts . Progress: Quickly, <name>. Dispatch of these humans in our valley.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 4862, 53355, 53373, 53386, 131855 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3143, ["x"] = 0.432, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 1227, ["name"] = "Valley of Trials", ["orderIndex"] = 2, ["flags"] = 0 } } },
[25173] = { ["id"] = 25173, ["name"] = "From Bad to Worse", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25177 }, ["description"] = "Tiragarde Keep lies to the southeast of here, on Durotar 's eastern shore. You probably passed it on your trip from Sen'jin Village. This castle has been a thorn in my side for too long. Humans from Kul Tiras lived in the castle for years, thwarting my every attempt to crush them. When the cataclysm hit us, the shore was wiped out, along with the castle and all the humans. However, these upstarts from Northwatch have moved in to take their place! < Gar'Thok roars in aggravation.>", ["objectivesText"] = "Kill 6 Northwatch Marines , 6 Northwatch Sharpshooters , and Lieutenant Palliter in Tiragarde Keep.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 53375, 53383, 53392, 131405, 156970 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.519, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 6, ["flags"] = 0 } } },
[25176] = { ["id"] = 25176, ["name"] = "Exploiting the Situation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25178, 25187, 25188, 25227 }, ["description"] = "<Hey there, handsome! I've had my eye on those big, beefy biceps ever since you stepped into town./What're you looking at> ugly? I've seen you walking around Razor Hill, trying to steal MY men from me!; Listen, I've got something for you to do. I hear Gar'Thok's got you headed over to Tiragarde. While you're there, think you could find some abandoned Kul Tiras knicknacks? <Thanks sweetie!/Don't ask why> just get to it!;", ["objectivesText"] = "Obtain 6 pieces of Kul Tiras Treasure . Progress: <Gail purrs disarmingly at you.>", ["rewardGold"] = 169800, ["rewardXP"] = 150, ["rewardItems"] = { 52558 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39423, ["x"] = 0.53, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39423, ["x"] = 0.53, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 7, ["flags"] = 0 } } },
[25177] = { ["id"] = 25177, ["name"] = "Storming the Beaches", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25173 }, ["description"] = "Now that those humans are out of our hair for a bit, we can move on to more pressing matters. The cataclysm utterly decimated Durotar 's eastern coast. You saw the wreckage that it made of Tiragarde. The devastation was even worse on the coast to the east of here. After the first wave, the beach was overtaken by angry elementals that came from the sea. I sent grunts to take care of it, but the onslaught was too much. I'm guessing you'll have a little more luck than they did. Beware the tides!", ["objectivesText"] = "Kill 11 Foaming Sea Elementals .", ["rewardGold"] = 210000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.519, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 8, ["flags"] = 0 } } },
[25178] = { ["id"] = 25178, ["name"] = "Shipwreck Searching", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25176, 25187, 25188, 25227 }, ["description"] = "<Hey handsome, welcome back! You wouldn't mind running another errand, would you? I'd be EVER so grateful.../You! Stop right there> you tramp! I'm not finished with you yet.; I hear you're headed off to the shore east of here. The beach is filled with crashed ships, and those ships have gnomish tools in them... tools that I can use. <See you soon, beefcake!/Get cracking> missy!;", ["objectivesText"] = "Obtain 4 sets of Gnomish Tools . Progress: Has my knight in shining armor returned?", ["rewardGold"] = 315900, ["rewardXP"] = 150, ["rewardItems"] = { 4863 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39423, ["x"] = 0.53, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39423, ["x"] = 0.53, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 9, ["flags"] = 0 } } },
[25179] = { ["id"] = 25179, ["name"] = "Loss Reduction", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "You've got to help us. The elementals... they're stronger than they look, and they come in waves. They took us completely by surprise, and we were overcome. Many of my fellow grunts lay dying on the beach. If you could save them... I would be grateful, as would Gar'Thok back in Razor Hill.", ["objectivesText"] = "Rescue 4 Injured Razor Hill Grunts .", ["rewardGold"] = 241020, ["rewardXP"] = 200, ["rewardItems"] = { 53384 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.519, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 32, ["flags"] = 0 } } },
[25187] = { ["id"] = 25187, ["name"] = "Lost in the Floods", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25176, 25178, 25188, 25227 }, ["description"] = "The recent cataclysmic events have done more than wash a few boats onto our shore, <class>. The Southfury River has overflowed, and Durotar 's entire western basin is now flooded. There are still people out there. I've been searching for a while, but haven't been able to find anything. Would you mind using my telescope and taking a look for yourself?", ["objectivesText"] = "Use Thonk's Spyglass to search for survivors in Southfury Watershed. Progress: What have you seen?", ["rewardGold"] = 78750, ["rewardXP"] = 150, ["rewardItems"] = { 52514 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39323, ["x"] = 0.495, ["y"] = 0.401 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39323, ["x"] = 0.495, ["y"] = 0.401 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.401 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 10, ["flags"] = 0 } } },
[25188] = { ["id"] = 25188, ["name"] = "Watershed Patrol", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25176, 25178, 25187, 25227 }, ["description"] = "My post is here on the tower, <name>, and I cannot leave it. I need someone to go out there and help the people who are still trapped in the river's overflow. Can I count on you?", ["objectivesText"] = "Search the Southfury Watershed and help the people you saw in the spyglass.", ["rewardGold"] = 619600, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39323, ["x"] = 0.495, ["y"] = 0.401 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39323, ["x"] = 0.495, ["y"] = 0.401 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.401 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 11, ["flags"] = 0 } } },
[25190] = { ["id"] = 25190, ["name"] = "Raggaran's Rage", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25192 }, ["description"] = "The quilboar are a stain on the land that not even the river can wash away. They told me to evacuate, but I told them that my job was not yet done. Hrrrraaagh! I hate quilboar so much! Will you help me kill them?", ["objectivesText"] = "Kill 4 Razormane Quilboar and 4 Razormane Scouts . Progress: I hate quilboar!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39326, ["x"] = 0.426, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39326, ["x"] = 0.426, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 15, ["flags"] = 0 } } },
[25192] = { ["id"] = 25192, ["name"] = "Raggaran's Fury", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25190 }, ["description"] = "I will not rest until they're defeated! Slay them all! < Raggaran catches his breath.> Their stinking lairs are to the north, or to the southwest!", ["objectivesText"] = "Kill 5 Razormane Dustrunners and 5 Razormane Battleguards . Progress: Quilboar! Kill them!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 53381, 53382, 131408, 156969 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39326, ["x"] = 0.426, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39326, ["x"] = 0.426, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 16, ["flags"] = 0 } } },
[25193] = { ["id"] = 25193, ["name"] = "Lost But Not Forgotten", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "Today marks the anniversary of my son Kron's passing. As long as I refused to admit it, I recognize now: Kron is not returning from his crocolisk hunt. I've been working on a project... something that will memorialize Kron's passion for the hunt. It's a crocolisk-tooth necklace... rows and rows of teeth, suitable to be worn by only the bravest young orc. I will place it on his grave. Kron was brave, but he was not strong, like you. Will you bring me the teeth for my necklace?", ["objectivesText"] = "Obtain 250 Crocolisk Teeth. Progress: Kron will be remembered.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 52514, 53372, 53377, 53393, 60242, 60615, 131409 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3193, ["x"] = 0.434, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3193, ["x"] = 0.434, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 12, ["flags"] = 0 } } },
[25194] = { ["id"] = 25194, ["name"] = "Unbidden Visitors", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25195 }, ["description"] = "Don' worry, Zen'Taji 's not in any trouble. He just been studyin' what happens when the river overflows. Ya see the big tall birds that stand on the riverbank? Zen'Taji thinks they're in trouble. The earthquake and the flood pushed the plainstriders over to this side of the water, but they can't fly back, and they're too scared to swim. They'll die if they stay here. Zen'Taji doesn't like violence, but maybe YOU can attack them and scare them over to the other side. Yes?", ["objectivesText"] = "Attack 3 Wayward Plainstriders until they flee toward the Barrens. Progress: Just beat on 'em, mon. Trust Zen'Taji , they will run. It is no big thing.", ["rewardGold"] = 280900, ["rewardXP"] = 100, ["rewardItems"] = { 1416, 4358, 4945, 6714, 8956, 46725, 97919, 128632, 133597, 137663 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39324, ["x"] = 0.474, ["y"] = 0.403333 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39324, ["x"] = 0.474, ["y"] = 0.403333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.403333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 13, ["flags"] = 0 } } },
[25195] = { ["id"] = 25195, ["name"] = "That's the End of That Raptor", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25194 }, ["description"] = "Many creatures died when the water came rushin' into the valley. The raptors, however, thrived. They're clever predators, and they've been living off the misfortune of the other creatures. One of the raptors is particularly cruel. He's killing the little animals and letting them rot in the water without even eating them! He goes by the name of Screamslash , and if we're not careful, he could seriously disrupt the balance of nature. Travel north, slay him, and give his body back to nature.", ["objectivesText"] = "Slay the raptor called Screamslash . Progress: The raptor has always been a quick adapter.", ["rewardGold"] = 561800, ["rewardXP"] = 250, ["rewardItems"] = { 53398 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39324, ["x"] = 0.474, ["y"] = 0.403333 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39324, ["x"] = 0.474, ["y"] = 0.403333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.403333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 14, ["flags"] = 0 } } },
[25196] = { ["id"] = 25196, ["name"] = "The Dranosh'ar Blockade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25232, 25260, 25261, 25262 }, ["description"] = "You should head north from here, <name>. Speak with Gor the Enforcer at the Dranosh'ar Blockade. He's been placed in charge of securing shipping lanes for Orgrimmar, and Skull Rock sits right next to his precious dock. I'm certain he'll be interested in picking up where we left off.", ["objectivesText"] = "Report to Gor the Enforcer at the Dranosh'ar Blockade in Durotar .", ["rewardGold"] = 70225, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3142, ["x"] = 0.522, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 18, ["flags"] = 0 } } },
[25205] = { ["id"] = 25205, ["name"] = "The Wolf and The Kodo", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "My \"associate\" here has some plans for you that I don't agree with. His actions are hasty, uncontrolled, and irresponsible, and you may end up paying for them with your life. Before you work with Gor, first listen to the tale that I have to tell. It's a moralistic story - a fable - but I believe its lesson will prove valuable. Speak to me when you are ready.", ["objectivesText"] = "Hear the moral of Shin Stonepillar 's story. Progress: Pay close attention to the meaning behind my words, child.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39380, ["x"] = 0.448, ["y"] = 0.148 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39380, ["x"] = 0.448, ["y"] = 0.148 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 25, ["flags"] = 0 } } },
[25206] = { ["id"] = 25206, ["name"] = "Ignoring the Warnings", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "Ignore the shaman, soldier. Certain powers-that-be within the Horde demand that I keep him with me, but I assure you, that Thrall-loving farseer truly sees no farther than the borders of this hut. Elementals war against one another to the west of here. I normally wouldn't mind, but I need that land clear to secure a broader shipping route to and from the Barrens. The elementals are normally quite strong, but they are weakened by their attacks against one another. Use this knowledge to destroy them.", ["objectivesText"] = "Destroy 12 Warring Elementals. You may slay either Furious Earthguards or Teeming Waterguards . Progress: Elementals? Pfuh! No match for the power of the Horde.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 53368, 53374, 131410 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 26, ["flags"] = 0 } } },
[25227] = { ["id"] = 25227, ["name"] = "Thonk", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 25227 }, ["series"] = { 25176, 25178, 25187, 25188 }, ["description"] = "<Oh, sweetie, I just remembered!/Sorry if I've been mean to you. Sometimes I get a little jealous when other women come into town> as I'm a little insecure about my appearance.; My VERY good friend Thonk works in the guard tower on that cliff, just to the northwest of Razor Hill. He said something about a river overflowing, lots of work to be done, and so on. I wasn't really paying attention... I was staring into those deep brown eyes of his. <What, we can't see other people?/Thanks.>", ["objectivesText"] = "Report to Thonk on the guard tower northwest of Razor Hill.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39423, ["x"] = 0.53, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39323, ["x"] = 0.495, ["y"] = 0.401 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[25232] = { ["id"] = 25232, ["name"] = "The Burning Blade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25196, 25260, 25261, 25262 }, ["description"] = "I've been sent to investigate the presence of more Burning Blade agents here in Durotar . To the northeast, you'll find a cave where the organization trains their new recruits. I'm interested in what exactly they are teaching these neophytes. I only tell you this because you seem to be looking for work. If you're interested in a little coin, sack the cave and return with their spellscrolls. The cave is somewhat hidden: exit Razor Hill from the east, and follow the canyon's eastern ridge.", ["objectivesText"] = "Obtain 6 Burning Blade Spellscrolls from members of the Burning Blade in Dustwind Cave. Progress: The scrolls, <name>, the scrolls!", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 118, 52564, 53361, 53367, 53379, 120313, 131850 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3142, ["x"] = 0.522, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3142, ["x"] = 0.522, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 17, ["flags"] = 0 } } },
[25236] = { ["id"] = 25236, ["name"] = "Thunder Down Under", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "Our army needs water, and luckily the elements gave us plenty of that when the cataclysm hit. The water that filled up the canyon to the southwest should do the trick. Unfortunately, the corpses of thunder lizards still sit at the bottom of the canyon, and their electrical discharges are a bit too dangerous. I've got grunts that can lift them out of the water, but we need someone agile enough to attach the other end of the rope. Are you my <man/woman>, <name>?", ["objectivesText"] = "Attach a Mageweave Tether to 8 Drowned Thunder Lizards in Thunder Ridge.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 52574 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 376, ["name"] = "Durotar Test", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 27, ["flags"] = 0 } } },
[25256] = { ["id"] = 25256, ["name"] = "Sent for Help", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "You, <race>, stop a minute. My boss Spiketooth sent me to look for help and supplies. You don't appear to be a merchant, but you can probably still help him out. He's just to the southeast of here, next to the crashed cart. Oh, and tell him I sent you... I want to make sure that he knows I'm not just slacking off over here.", ["objectivesText"] = "Report to Spiketooth at Deadeye Shore in Durotar .", ["rewardGold"] = 200, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39604, ["x"] = 0.562, ["y"] = 0.202 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39590, ["x"] = 0.588, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 28, ["flags"] = 0 } } },
[25257] = { ["id"] = 25257, ["name"] = "Ghislania", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "I own a couple gladiators that I put into competitions around Kalimdor. You can see most of them chained up around here... we were lucky to rein these ones in after the cart broke down. Ghislania , that naga over there... she's lost her last three fights. She could use a tune-up, or maybe just a little bit of thrashing. Go challenge her, I'll bet even YOU are stronger than she is.", ["objectivesText"] = "Defeat Ghislania in combat.", ["rewardGold"] = 232300, ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39590, ["x"] = 0.588, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39590, ["x"] = 0.588, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 29, ["flags"] = 0 } } },
[25258] = { ["id"] = 25258, ["name"] = "Griswold Hanniston", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "Griswold, chained up over there on the cliffs, is my newest gladiator. We found him just south of here, sniffing around with Northwatch soldiers. I had my men nab him up, and now he works for me. He looks tough enough, but he hasn't really been battle-tested yet. Go pick a fight with him so I can see if he's worth keeping around.", ["objectivesText"] = "Defeat Griswold Hanniston in combat.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39590, ["x"] = 0.588, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39590, ["x"] = 0.588, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 30, ["flags"] = 0 } } },
[25259] = { ["id"] = 25259, ["name"] = "Gaur Icehorn", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["description"] = "I wouldn't normally keep a taunka as a captive, due to their close relationship with the Horde... but this one is a traitor, and a criminal to boot. Exiled by his own tribe, he canoed down to Azshara and was found stealing supplies from Valormok. He would have been put to the axe had I not been standing by, wallet in hand. Gaur is my winningest gladiator, <class>. I'll bet you a fist full of silver that you can't beat him.", ["objectivesText"] = "Defeat Gaur Icehorn in combat.", ["rewardGold"] = 803374, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39590, ["x"] = 0.588, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39590, ["x"] = 0.588, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 31, ["flags"] = 0 } } },
[25260] = { ["id"] = 25260, ["name"] = "Fizzled", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25196, 25232, 25261, 25262 }, ["description"] = "The flood to the southwest wiped out one of the few Burning Blade camps that still pockmark Durotar . This one was led by a goblin named Fizzle Darkclaw, and believe me, we're better off without him. Darkclaw, however, did possess an orb that the Horde is interested in procuring. Who knows why... I leave that to the warlocks. All I know is that I need that orb.", ["objectivesText"] = "Obtain Fizzle's Orb from Fizzle Darkclaw in Thunder Ridge. Progress: Run into any trouble on the way?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 52580, 53366, 53369, 131413 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 19, ["flags"] = 0 } } },
[25261] = { ["id"] = 25261, ["name"] = "Margoz", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25196, 25232, 25260, 25262 }, ["description"] = "One of our more useful shaman, Margoz , knows more of the Burning Blade's corruption. He speaks of a cave called Skull Rock in the mountains, just outside Orgrimmar, that shelters a large band of Burning Blade cultists. Before you go to Skull Rock, speak with Margoz . He is wise and his council is valued. He is camped to the southeast, between the coast and Drygulch Ravine. Follow his advice, but whatever Margoz says, <name>, I still want you to crush those cultists!", ["objectivesText"] = "Speak with Margoz .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 39379, ["x"] = 0.45, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3208, ["x"] = 0.564, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 20, ["flags"] = 0 } } },
[25262] = { ["id"] = 25262, ["name"] = "Skull Rock", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25196, 25232, 25260, 25261 }, ["description"] = "<name>. The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock. Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars . By wearing these collars, I believe the cultists attune themselves to demonic power. But to confirm this, I must have a collection of the collars to study. Go to Skull Rock and gather Searing Collars from the cultists you find there. Bring them to me, and I will uncover their secrets.", ["objectivesText"] = "Gather 6 Searing Collars from the cultists in Skull Rock. Progress: Have you yet entered Skull Rock, <name>? Do you have the Searing Collars ?", ["rewardXP"] = 200, ["rewardItems"] = { 4871, 53358, 53387, 53390, 131414 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3208, ["x"] = 0.564, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3208, ["x"] = 0.564, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 21, ["flags"] = 0 } } },
[25263] = { ["id"] = 25263, ["name"] = "Arnak Fireblade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 834, 835, 25165, 25167, 25168, 25169, 25170, 25171, 25173, 25176, 25177, 25178, 25179, 25187, 25188, 25190, 25192, 25193, 25194, 25195, 25196, 25205, 25206, 25232, 25236, 25256, 25257, 25258, 25259, 25260, 25261, 25262, 25263 }, ["series"] = { 25264 }, ["description"] = "The Searing Collars you brought me are powerful demonic implements. Divining their origin is, I'm afraid, beyond my skills as a shaman. We will need a warlock to study them. Take a searing collar to Arnak Fireblade . Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign. Be that true or false, we may need his aid against the demonic cult in Durotar . You may find Arnak in Orgrimmar in the Cleft of Shadow.", ["objectivesText"] = "Bring an Example Collar to Arnak Fireblade in Orgrimmar. Progress: My most humble greetings, <class>. How might I help my <race> brother today?", ["rewardXP"] = 25, ["rewardItems"] = { 6658 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3208, ["x"] = 0.564, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 86, ["questLines"] = { { ["id"] = 563, ["name"] = "Durotar", ["orderIndex"] = 22, ["flags"] = 0 } } },
[25264] = { ["id"] = 25264, ["name"] = "Ak'Zeloth", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 10, ["storyline"] = { 25264 }, ["series"] = { 25263 }, ["description"] = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society. The collar you brought me confirms my fears. It belongs to the Burning Blade. Your role in this tale is nearly complete, <name>. Go to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth . Pass on to him this information.", ["objectivesText"] = "Speak with Ak'Zeloth at Far Watch Post in the Northern Barrens .", ["rewardXP"] = 95, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3521, ["x"] = 0.678, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[25266] = { ["id"] = 25266, ["name"] = "Warchief's Emissary", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 174, ["storyline"] = { 25266 }, ["series"] = { 25243, 25244, 25251, 25265, 25267 }, ["description"] = "The goblins and the Horde have accomplished too much together to part ways now, <class>. I intend for the Bilgewater Cartel to become part of the Horde. I have something that I want you to deliver to the new warchief. Give this package to my Darkspear friend on the dock at Bladefist Bay in Durotar . She will help you to get into Orgrimmar safely. Speak with Sassy Hardwrench on the ship when you are ready to set sail. Until we meet again. Aka'Magosh, a blessing on you and yours, <name>!", ["objectivesText"] = "Deliver the Sealed Package to the Darkspear Loyalist on the docks at Bladefist Bay in Durotar . Progress: What possible business could you have in Orgrimmar, <race>?", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 52582 }, ["starts"] = { { ["mapID"] = 174, ["npcID"] = 38935, ["x"] = 0.394, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 39609, ["x"] = 0.672667, ["y"] = 0.356667 }, { ["mapID"] = 1, ["npcID"] = 86884, ["x"] = 0.576, ["y"] = 0.096 } }, ["coords"] = { ["mapID"] = 174, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 1, 174 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[25279] = { ["id"] = 25279, ["name"] = "The Shrine Reclaimed", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25279 }, ["series"] = { 25277 }, ["description"] = "Yes, <name>. I am Goldrinn, the one called \"Lo'Gosh\" in your tongue. Your persistence in the face of fear has unbound me from twilight's grasp. My shrine has been purified, and my worshippers have returned to their rightful place at my right paw. Return to Takrik and continue your work here in Hyjal. I will have need of you again soon.", ["objectivesText"] = "Return to Takrik Ragehowl at the reclaimed Shrine of Goldrinn in Hyjal.", ["rewardGold"] = 280900, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39432, ["x"] = 0.29, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25280] = { ["id"] = 25280, ["name"] = "The Shrine Reclaimed", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25280 }, ["series"] = { 25278 }, ["description"] = "Yes <name>, I am Goldrinn. Your persistence in the face of fear has unbound me from twilight's grasp. My shrine has been purified, and my worshippers have returned to their rightful place at my right paw. Return to Ian and continue your work here in Hyjal. I will have need of you again soon.", ["objectivesText"] = "Return to Ian Duran at the reclaimed Shrine of Goldrinn in Hyjal.", ["rewardGold"] = 280900, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39433, ["x"] = 0.291, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.291, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25316] = { ["id"] = 25316, ["name"] = "As Hyjal Burns", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 25316 }, ["series"] = { 25317, 25319, 27721, 27726, 49855 }, ["description"] = "<name>! We've heard much about you and your previous accomplishments. It is good that you've come here just as Azeroth finds itself in a time of great need. Deathwing's minions are attacking Hyjal and seek to bring the destructive Ragnaros back into our world. Aronus will take you to join Malfurion's forces in Hyjal. Lend them what help you can.", ["objectivesText"] = "Fly to Hyjal using Aronus and speak to Ysera once you're there.", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 39865, ["x"] = 0.454667, ["y"] = 0.447333 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 40289, ["x"] = 0.62, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.447333 }, ["mapCandidates"] = { ["npc"] = { 80, 198 }, ["zone"] = { 493 } }, ["questType"] = "standard" },
[25354] = { ["id"] = 25354, ["name"] = "Sweeping the Shelf", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25354 }, ["description"] = "The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive. Something sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients! Fly up to the Lightning Ledge and demolish the Twilight's Hammer there. Crush them, <name>, slay their creations and hurl their bodies from the mountainside!", ["objectivesText"] = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 57366, 57367, 57368, 57369, 57370, 57371, 57372, 57373 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39432, ["x"] = 0.29, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39432, ["x"] = 0.29, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25370] = { ["id"] = 25370, ["name"] = "Inciting the Elements", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25370 }, ["series"] = { 25574 }, ["description"] = "This is no mere natural occurrence, <name>. There must be a twilight presence behind our lines that we haven't accounted for. It's possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight. Seek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy's illusions. Feed them the juniper berries that grow nearby to gain their trust.", ["objectivesText"] = "Feed Juniper Berries to the Faerie Dragons and slay 4 Twilight Inciters . Progress: Back already, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 53009, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40278, ["x"] = 0.64, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 40278, ["x"] = 0.64, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25443] = { ["id"] = 25443, ["name"] = "The Name Never Spoken", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25404, 25408, 25411, 25412, 25428 }, ["description"] = "Did my drought work? You spoke with one of them? Then you know what to do. The name of their elemental master is written on three firestones scattered throughout the Inferno. Examine each of these stones and we will have the name we need. Hurry! Your precious forest burns!", ["objectivesText"] = "Assemble the true name by examining the three Firestones in the Inferno.", ["rewardXP"] = 4115, ["rewardItems"] = { 30632 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.413, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 46, ["flags"] = 0 } } },
[25460] = { ["id"] = 25460, ["name"] = "The Earth Rises", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25460 }, ["description"] = "The effects of the Twilight's Hammer attack can be felt even here, this close to the world tree. As our forests burn, the very earth turns against us in a crazed frenzy. We can't allow the elementals to go unchecked. Go and help our men take care of them.", ["objectivesText"] = "Slay 8 Scalding Rock Elementals .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 57281, 57282, 57283, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39925, ["x"] = 0.64, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39925, ["x"] = 0.64, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25475] = { ["id"] = 25475, ["name"] = "Find OOX-22/FE!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 25475 }, ["series"] = { 351, 485, 648, 836, 3721, 25476 }, ["description"] = "You have uncovered some sort of strange, egg-shaped device made from metal. Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption! A voice from inside the robotic egg crackles to life. \"My name's Oglethorpe Obnoticus, and my homing robot has crashed! I will reward you for its recovery; please take this beacon to the robot!\" \"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", ["objectivesText"] = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale. Progress: You appear to have uncovered the wreckage of... a robotic chicken? The voice from within the egg crackles to life again: \"Yes, excellent work! This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs. Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", ["rewardXP"] = 2090, ["rewardItems"] = { 8623, 8704, 8705, 10398 }, ["ends"] = { { ["mapID"] = 69, ["npcID"] = 7807, ["x"] = 0.550889, ["y"] = 0.540889 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.550889, ["y"] = 0.540889 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "standard", ["startItems"] = { 8705 } },
[25476] = { ["id"] = 25476, ["name"] = "Rescue OOX-22/FE!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 25476 }, ["series"] = { 351, 485, 648, 836, 3721, 25475 }, ["description"] = "The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure. It has built-in cloaking, but I need time on my end to make it operational again. Escort the robot from its current location to, let's say, the main road! That should be a perfect place, and long enough, to get things online!\" \"Escort it safely and then come talk to me in Booty Bay! Oglethorpe Obnoticus - out!\"", ["objectivesText"] = "Escort OOX-22/FE to safety, then report to Oglethorpe Obnoticus in Booty Bay.", ["rewardXP"] = 4180, ["rewardItems"] = { 8623, 8704, 8705, 9647, 9648, 10398 }, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 7807, ["x"] = 0.550889, ["y"] = 0.540889 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 7406, ["x"] = 0.43, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.550889, ["y"] = 0.540889 }, ["mapCandidates"] = { ["npc"] = { 69, 210 }, ["zone"] = { 357 } }, ["questType"] = "standard" },
[25556] = { ["id"] = 25556, ["name"] = "Into Zul'Farrak", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 25556 }, ["series"] = { 25021, 25025, 25026, 25032, 27068 }, ["description"] = "That foul traitor...I should've known better than to trust his kind. My hunt for Sul'thraze has blinded me. Forgive me, <name>. Mazoga has fled inside of Zul'Farrak , the heart of the Sandfury civilization. If you truly seek the sword, you must pursue him. Do not go alone; the entirety of the Sandfury tribe lies in wait behind those walls, and they will not welcome you. I will stay here. My search for the blade must end. Should you find it, keep it; I must give up before I am consumed.", ["objectivesText"] = "Find Mazoga within Zul'Farrak .", ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 7804, ["x"] = 0.424, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Nightborne" },
[25561] = { ["id"] = 25561, ["name"] = "Circle the Wagons... er, Boats", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 25486, 25488, 25504, 25515, 25517, 25524, 25532, 25542, 25561, 25585, 25588, 25590, 25609, 25627, 25660, 25661, 25672, 25704, 25744, 25756, 25762, 25774, 25778, 25790, 25796, 25798, 25813, 25825, 25835, 25869, 25871, 25873, 27275, 27310, 27312, 27314, 27316, 27318, 27320, 27323, 27325, 27327, 27329, 27357, 28031, 28045, 28047, 28048, 28051, 28085, 28086, 28087, 28088, 28098, 28124, 28125, 28127, 28136, 28139, 28140, 28142, 28143, 28157, 28158, 28159, 28160 }, ["series"] = { 25479, 25481, 25486, 25488, 25504, 25515, 25532, 25542, 25585, 28503 }, ["description"] = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge! <name>, you need to go back to Mazzer Stripscrew and get on your boat. Use the cannon to sink them before it's too late!", ["objectivesText"] = "Sink 15 Southsea Rowboats .", ["rewardGold"] = 169800, ["rewardXP"] = 2090, ["rewardItems"] = { 55121, 63550, 63551, 63552, 63553, 63554, 63555, 63556, 63557, 131434, 131435 }, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 40475, ["x"] = 0.765, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 40475, ["x"] = 0.765, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["db2QuestSortName"] = "Proving Grounds", ["questLines"] = { { ["id"] = 521, ["name"] = "Thousand Needles", ["orderIndex"] = 16, ["flags"] = 0 } } },
