[25574] = { ["id"] = 25574, ["name"] = "Flames from Above", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25574 }, ["series"] = { 25370 }, ["description"] = "We've identified the general direction where the infiltrators have been coming from, thanks to your work. Now we just need to shut down their camp and put an end to their operations this side of Nordrassil. Take this horn. It will signal one of our emerald drakes to swoop down and give these Twilight cultists a taste of the flames they so madly worship.", ["objectivesText"] = "Seek the Twilight Encampment north of Nordrassil and use Tholo's Horn . Progress: Is it done yet, <name>?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 55122, 57294, 57295, 57296, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40278, ["x"] = 0.64, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 40278, ["x"] = 0.64, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25630] = { ["id"] = 25630, ["name"] = "The Fires of Mount Hyjal", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25630 }, ["series"] = { 25381 }, ["description"] = "Do you see it, <name>? From the ridge southwest of here... plumes of black smoke curling into the sky. Mount Hyjal is burning. If the fires have raced this far up the mountain, surely they threaten the Grove of Aessina and all of our forces there. Can you investigate? Speak with Laina Nightsky near the Grove of Aessina. Last I heard, she was fighting off the assault.", ["objectivesText"] = "Speak with Laina Nightsky near the Grove of Aessina in Hyjal.", ["rewardXP"] = 515, ["rewardItems"] = { 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39434, ["x"] = 0.282, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39927, ["x"] = 0.386, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25665] = { ["id"] = 25665, ["name"] = "A Plea From Beyond", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25665 }, ["series"] = { 25663, 25664, 25985, 27874 }, ["description"] = "<You can't make sense of the spirit's urgent plea, but maybe Choluna can decipher what's going on here.> <Speak with Choluna back inside the shrine!>", ["objectivesText"] = "Return to Choluna inside of the Shrine of Aviana in Mount Hyjal .", ["rewardXP"] = 515, ["rewardItems"] = { 65661, 65662 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41005, ["x"] = 0.444, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25667] = { ["id"] = 25667, ["name"] = "Culling the Wendigos", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "The wendigos in the Grizzled Den to the southwest of town have long been a thorn in our side. They're never quite strong enough to threaten Kharanos directly, yet they prey on travelers, mountaineer patrols, and supply convoys. I'm going to be withdrawing my observers from the Grizzled Den because I need them on the troll front. Would you help my men finish culling the wendigo population? Without strength of numbers, they won't be able to attack us.", ["objectivesText"] = "Kill 10 Wendigos in the Grizzled Den. You may kill Wendigos or Young Wendigos .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 4, ["flags"] = 0 } } },
[25668] = { ["id"] = 25668, ["name"] = "Pilfered Supplies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "With the Frostmanes making trouble to our east, the wendigos have sensed our weakness and grown bolder in their raids. Only one of the four most recent supply wagons has made it here safely. The wendigos made off with the rest, stashing it in the Grizzled Den, a cave southwest of town. If you're willing to go down there and recover the stolen supplies, you would have the gratitude of all the townspeople and the mountaineers defending Kharanos.", ["objectivesText"] = "Retrieve 6 Pilfered Supplies from the Grizzled Den. Progress: Did you find any of the missing supplies?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 55151, 57550, 57551, 131436 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 40951, ["x"] = 0.536, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 40951, ["x"] = 0.536, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 3, ["flags"] = 0 } } },
[25724] = { ["id"] = 25724, ["name"] = "Frostmane Aggression", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "The cataclysm has thrown the balance of power in Dun Morogh into question, <name>. Without warning, a wave of troggs emerged from the caves near Gnomeregan and overran the Frostmane trolls. The trolls have been migrating east ever since. There has always been a Frostmane presence up on Shimmer Ridge, to the northwest, but with the migration, the trolls now surround us. We can't allow the trolls to use this position to their advantage. While my men hold the line in the east, strike against Shimmer Ridge.", ["objectivesText"] = "Kill 5 Frostmane Seers and 7 Frostmane Snowstriders on Shimmer Ridge.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 2676, 2900 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 2, ["flags"] = 0 } } },
[25771] = { ["id"] = 25771, ["name"] = "One Draenei's Junk...", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4, ["mapID"] = 17, ["storyline"] = { 25771 }, ["description"] = "A shard of glimmering rock sits before you. You sense that this item would be of value to someone within the Blasted Lands .", ["objectivesText"] = "Return the Imperfect Draenethyst Fragment to Kum'isha the Collector in Blasted Lands . Progress: Well? Draenethyst?", ["rewardItems"] = { 10593, 12122 }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 7363, ["x"] = 0.486667, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.486667, ["y"] = 0.317333 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 4 } }, ["questType"] = "standard", ["startItems"] = { 10593 } },
[25792] = { ["id"] = 25792, ["name"] = "Pushing Forward", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "Most of the mountaineers and steam tanks in Dun Morogh are battling along the Frostmane Front, which is approaching us from the southeast. We can barely hold the trolls back, let alone advance into their village and take on their leader. They've blocked our path of approach with mysterious totems that choke mountaineers who come in range, leaving the victims helpless against their enemies. This stone is inscribed with a rune of fire ; it should be able to destroy the totems and free our mountaineers.", ["objectivesText"] = "Use the Rune of Fire to destroy 4 Constriction Totems in the Frostmane Front. Progress: Was the rune able to destroy the totems? Were we too late?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 1010, 1011, 10547, 56009, 156940 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 7, ["flags"] = 0 } } },
[25838] = { ["id"] = 25838, ["name"] = "Help from Steelgrill's Depot", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25839 }, ["description"] = "With your help, we've managed to push toward Frostmane Retreat. Our forces will soon be in position to dwindle down the Frostmane trolls' reserves, leaving their village open to attack. That's where the Gnomeregan covert ops team comes in. Their technicians have figured out a way to deploy operatives behind enemy lines without alerting the Frostmanes to our presence. Head to Steelgrill's Depot, just northeast of town, and speak with Delber Cranktoggle . He'll tell you more about it.", ["objectivesText"] = "Speak to Delber Cranktoggle at Steelgrill's Depot.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41363, ["x"] = 0.568, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 8, ["flags"] = 0 } } },
[25839] = { ["id"] = 25839, ["name"] = "The Ultrasafe Personnel Launcher", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25838 }, ["description"] = "The cataclysm has brought our enemies closer to home, so the chief of Gnomeregan covert operations asked me to build a device to dispatch personnel quickly and quietly to any corner of Dun Morogh . Behold, the ultrasafe personnel launcher! With a jolt of electricity and the benefit of a VLD parachute system, uh, that's 'very late deployment' for you laymen, this baby'll get you to the front in no time. Just hop aboard and prepare for flight! Slamp Wobblecog will be waiting for you in the drop zone.", ["objectivesText"] = "Use the Ultrasafe Personnel Launcher to deploy to Frostmane Retreat.", ["rewardGold"] = 210675, ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41363, ["x"] = 0.568, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41298, ["x"] = 0.625333, ["y"] = 0.535333 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 9, ["flags"] = 0 } } },
[25840] = { ["id"] = 25840, ["name"] = "Eliminate the Resistance", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "The Frostmane chieftain died in the initial trogg onslaught, but they've been led by a well-respected warrior ever since. Battok the Berserker was the one who organized the Frostmane retreat, the construction of the new village, and the strikes against Kharanos and the mountaineers. If we remove Battok, the Frostmanes' organization should crumble, leaving the mountaineers free to pick off the survivors. Battok will be in the village, just east of here.", ["objectivesText"] = "Slay Battok the Berserker and 5 Frostmane Warriors in Frostmane Retreat.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 57554, 57555, 131448 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41298, ["x"] = 0.625333, ["y"] = 0.535333 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41298, ["x"] = 0.625333, ["y"] = 0.535333 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.625333, ["y"] = 0.535333 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 11, ["flags"] = 0 } } },
[25841] = { ["id"] = 25841, ["name"] = "Strike From Above", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25882 }, ["description"] = "Delber's technicians have been up day and night helping us prepare for this strike. Aside from building and tuning the personnel launcher, his men have prepared the covert operations air wing for a strike on Frostmane Retreat. They'll be waiting for a signal to begin their strikes. Take this flare with you, and set it off near the cluster of buildings at the northern end of the village, and the buildings at the southern end of the village. The flying machines will make a quick strike at each site.", ["objectivesText"] = "Use the Signal Flare to call in airstrikes at the northern and southern ends of Frostmane Retreat.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 56048 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41298, ["x"] = 0.625333, ["y"] = 0.535333 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41298, ["x"] = 0.625333, ["y"] = 0.535333 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.625333, ["y"] = 0.535333 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 12, ["flags"] = 0 } } },
[25882] = { ["id"] = 25882, ["name"] = "A Hand at the Ranch", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 25882 }, ["series"] = { 25841 }, ["description"] = "Captain Tharran asked me to pass along his thanks for your help and congratulations on a successful mission. He and his men are cleaning up the last of the trolls and tending to the wounded. He also wanted me to ask you to check out reports about troll raids on the Amberstill Ranch to the north. Ask for Sergeant Flinthammer when you arrive.", ["objectivesText"] = "Speak with Sergeant Flinthammer at Amberstill Ranch.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41298, ["x"] = 0.625333, ["y"] = 0.535333 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41578, ["x"] = 0.704, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.625333, ["y"] = 0.535333 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[25886] = { ["id"] = 25886, ["name"] = "Pressing the Advantage", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25886 }, ["series"] = { 25881 }, ["description"] = "It looks like most of the Twilight's Hammer has fallen back to regroup for another assault. Their most dedicated are staying behind to hold the line. This is our chance to whittle away at their leadership. Range out along the Scorched Plain and crush the Twilight Field Captains . We'll remove them from the equation!", ["objectivesText"] = "Slay 4 Twilight Field Captains .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41492, ["x"] = 0.572, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41492, ["x"] = 0.572, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25905] = { ["id"] = 25905, ["name"] = "Rams on the Lam", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "The rams we raise and train here at Amberstill ranch have long been the mounts of choice for Dun Morogh 's mountaineers. Aye, there're a few here, but not enough to guard my family and all the animals. A few brave Frostmane raiders have taken to stealing our rams under the cover of night, taking them south into the Tundrid Hills. Would you be willing to help return them? You'll need to get fairly close to them and give a sharp whistle to get their attention. Their training will take over from there.", ["objectivesText"] = "Recover 6 Stolen Rams from the Tundrid Hills by using /whistle.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 1261, ["x"] = 0.705, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 1261, ["x"] = 0.705, ["y"] = 0.489 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 15, ["flags"] = 0 } } },
[25932] = { ["id"] = 25932, ["name"] = "It's Raid Night Every Night", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "The reports I'm sending Captain Tharran can't really convey the amount of trouble the Frostmanes have created for us. Your assault on the village has started to relieve some of the pressure. The raids are still frequent, but the trolls don't have the numbers they once did. Even so, my men are tired and their morale is flagging. Would you help us keep watch for the Frostmane raiders? They could turn up at any time.", ["objectivesText"] = "Help Sergeant Flinthammer and his mountaineers defend Amberstill Ranch from Frostmane Raiders. Progress: We're glad to have your help, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 57556, 57558, 57559, 131458 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41578, ["x"] = 0.704, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41578, ["x"] = 0.704, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 13, ["flags"] = 0 } } },
[25933] = { ["id"] = 25933, ["name"] = "Help for the Quarry", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "Thank you again for all your help here, <name>. I have a cousin who used to work in the mines beneath the Gol'Bolar Quarry, but he hasn't been able to work since troggs flooded into the mines and took control. The quarry and its camp are just to the southeast of the ranch. Would you be willing to check in with the foreman there and see if there's anything to be done?", ["objectivesText"] = "Speak to Foreman Stonebrow at the Gol'Bolar Quarry.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41578, ["x"] = 0.704, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 1254, ["x"] = 0.762, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 16, ["flags"] = 0 } } },
[25937] = { ["id"] = 25937, ["name"] = "Priceless Treasures", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "Mining wasn't the only thing going on in the quarry, you know. I led a team of Explorers' League excavators recovering priceless ancient artifacts. I managed to escape, but my colleagues were much deeper in the mine and didn't survive the initial trogg attack. They took great pride in their work and they risked their lives to learn more of our history. If you're going into the mines, take this pick with you and see if you can find anything in the digs the prospectors started.", ["objectivesText"] = "Recover 8 Frozen Artifacts from inside the Gol'Bolar Quarry Mine. Progress: Were you able to find any artifacts down there?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 56225, 56226, 57549, 57571, 57572, 57574, 131459 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 50631, ["x"] = 0.762, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 50631, ["x"] = 0.762, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 19, ["flags"] = 0 } } },
[25940] = { ["id"] = 25940, ["name"] = "Last Stand at Whistling Grove", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25940 }, ["series"] = { 25382, 25462, 25490, 25491 }, ["description"] = "We might have a chance to beat these flames back thanks to your work in the Inferno. Still, more wildlife is threatened. Keeper Taldros ran north through the flames, to Whistling Grove. See if you can help him!", ["objectivesText"] = "Report to Keeper Taldros at Whistling Grove in Mount Hyjal .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39927, ["x"] = 0.386, ["y"] = 0.476 }, { ["mapID"] = 198, ["npcID"] = 39928, ["x"] = 0.19, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39932, ["x"] = 0.135, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25951] = { ["id"] = 25951, ["name"] = "Final Judgment", ["level"] = 81, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 25951 }, ["series"] = { 25860 }, ["description"] = "Get to the bridge on the east, quickly. Lady Naz'jar and the Fathom-Lord should be there with whatever forces remain. Follow our Lady's direction, as always. Hold the bridge until we can complete the ritual. Once our allies arrive, the Kvaldir will be doomed.", ["objectivesText"] = "Hold the bridge on Quel'Dormir Terrace until Lady Sira'kess ' allies arrive. This task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision. Progress: Stand with us, Battlemaiden. We shall not fall this day.", ["rewardXP"] = 41550, ["rewardItems"] = { 55171 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5144 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 205, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 144, ["flags"] = 0 } } },
[25978] = { ["id"] = 25978, ["name"] = "Entombed in Ice", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "Khurgorn tells me the cataclysm upset the balance of the elements all over the world. Helm's Bed Lake, to the south, used to be beautiful and tranquil, but it is now overrun with agitated water elementals. When they started to leave the confines of the lake, I sent my troops in to keep them busy, but most have been frozen in blocks of ice. If we can break them free, they have a good chance of recovering. I cannot spare the men for a second expedition out onto the lake. Would you be willing to try?", ["objectivesText"] = "Break open six Icy Tombs to free the Frozen Mountaineers trapped inside at Helm's Bed Lake. Progress: Were you able to help any of the mountaineers?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41786, ["x"] = 0.828, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41786, ["x"] = 0.828, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 21, ["flags"] = 0 } } },
[25979] = { ["id"] = 25979, ["name"] = "Dealing with the Surge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "The elements are in turmoil, <class>. The cataclysm stirred up the long-dormant water spirits of Helm's Bed Lake, just to the south. They're angry, confused, and unwilling to hear my pleas. I have tried everything I know to calm them, to persuade them to stop lashing out and attacking the sergeant's mountaineers. It pains me to say this, but no other options remain -- we must kill the elementals.", ["objectivesText"] = "Kill 6 Helm's Bed Surgers at Helm's Bed Lake.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41804, ["x"] = 0.825, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41804, ["x"] = 0.825, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 20, ["flags"] = 0 } } },
[25983] = { ["id"] = 25983, ["name"] = "Promontory Point", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25983 }, ["series"] = { 25981, 25987 }, ["description"] = "We need to get this information up to Captain Taylor on Promontory Point! He's out there to the northwest with Erunak Stonespeaker and the Earthen Ring.", ["objectivesText"] = "Speak with Captain Taylor on Promontory Point in Vashj'ir.", ["rewardXP"] = 515, ["rewardItems"] = { 56571, 57102 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41666, ["x"] = 0.418667, ["y"] = 0.704667 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41598, ["x"] = 0.492, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.704667 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[25984] = { ["id"] = 25984, ["name"] = "Promontory Point", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25984 }, ["series"] = { 25982, 25988, 26071 }, ["description"] = "<name>, I need you to get this information to Legionnaire Nazgrim on Promontory Point. He's up there to the northwest with Erunak Stonespeaker and those Earthen Ring people.", ["objectivesText"] = "Speak with Legionnaire Nazgrim on Promontory Point in Vashj'ir.", ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41669, ["x"] = 0.515, ["y"] = 0.607 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41636, ["x"] = 0.485333, ["y"] = 0.530667 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.607 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[25985] = { ["id"] = 25985, ["name"] = "Wings Over Mount Hyjal", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25985 }, ["series"] = { 25663, 25664, 25665, 27874 }, ["description"] = "<name>, is it true you're going to try to commune with the ancients? Southwest of here is the Shrine of Aviana, the matron of all flying creatures. It's the home of my favorite instructor, Choluna . I've never encountered one who was so deeply in touch with the spirits of this world. You could learn a lot from her! The recent attacks have isolated the shrine. But it's easily accessible from the air - look for the second biggest tree on Hyjal. Good luck!", ["objectivesText"] = "Locate Choluna at the Shrine of Aviana in Mount Hyjal .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41005, ["x"] = 0.444, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41005, ["x"] = 0.444, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25986] = { ["id"] = 25986, ["name"] = "Trouble at the Lake", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 25986 }, ["description"] = "You've been a great help in securing the mines and rescuing the trapped miners. The Senate will be heartened to hear that you and Captain Tharran's mountaineers have made progress in securing Dun Morogh . What worries me is that I haven't seen any reports from Sergeant Bahrum and his detachment. They were sent east, along the road toward Helm's Bed Lake, and ordered to set up a small outpost. Would you go to Bahrum's Post and check in on the sergeant?", ["objectivesText"] = "Speak with Sergeant Bahrum at Bahrum's Post.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 1977, ["x"] = 0.758, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41786, ["x"] = 0.828, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[25997] = { ["id"] = 25997, ["name"] = "Dark Iron Scheming", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25998, 26078, 26085, 26094, 26102, 26112 }, ["description"] = "A cadre of Dark Iron spies have taken over Ironband's Compound to the south, beyond Helm's Bed Lake. The mountaineers are normally able to keep them from getting into Dun Morogh , but everything is in disarray right now. The Dark Iron dwarves would be fools if they didn't take advantage of the chaos. We have to find out what they're planning and stop them before they do any damage. Will you see if you can discover what they're doing down at Ironband's Compound?", ["objectivesText"] = "Kill 5 Dark Iron Spies and capture the Dark Iron Attack Plans from Captain Beld at Ironband's Compound. Progress: What are the Dark Irons up to?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 56264, 57575, 57576, 57578, 131462 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41786, ["x"] = 0.828, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41786, ["x"] = 0.828, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 22, ["flags"] = 0 } } },
[25998] = { ["id"] = 25998, ["name"] = "Get to the Airfield", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25997, 26078, 26085, 26094, 26102, 26112 }, ["description"] = "According to the plans you captured, the Dark Irons are planning a large-scale attack on the Ironforge Airfield! The council has moved most of our forces down into Dun Morogh to deal with the instability brought by the cataclysm, leaving our defenses weakened at the airfield. We need a way to get you to the airfield quickly. Take the road back west toward Gol'Bolar Quarry and find Mathel Rustwrench. He should have a flying machine you can use. Go!", ["objectivesText"] = "Board Mathel's Flying Machine at the Gol'Bolar Quarry.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41786, ["x"] = 0.828, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 23, ["flags"] = 0 } } },
[26078] = { ["id"] = 26078, ["name"] = "Extinguish the Fires", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25997, 25998, 26085, 26094, 26102, 26112 }, ["description"] = "The Dark Iron attack took us by surprise. Their saboteurs managed to damage most of our aircraft, steam tanks, and supplies. We were only able to get a few of our bombers airborne. Every technician, recruit, and guard I can spare is scrambling to get the others repaired and flight-ready. Our infantry can only hold out for so long. Take this equipment and help extinguish the burning bombers.", ["objectivesText"] = "Using the Firefighting Equipment, extinguish 6 fires at the Ironforge Airfield. Progress: We need to hurry and get those bombers airborne!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 56803, 98132 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 24, ["flags"] = 0 } } },
[26085] = { ["id"] = 26085, ["name"] = "Rallying the Defenders", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25997, 25998, 26078, 26094, 26102, 26112 }, ["description"] = "While our engineers work on getting the bombers ready to fly again, our guards and mountaineers continue to fight the invaders. They've been out there since the incursion began, without so much as a chance to catch some sleep or have a meal. Ironforge's defenders are among the best on Azeroth, but even they have limits. Take these banners and plant them in banks of loose snow. Remind the men what they are fighting for and help keep their morale high.", ["objectivesText"] = "Plant 8 Ironforge Banners in mounds of Loose Snow throughout the Ironforge Airfield. Progress: We must do what little we can to keep the defenders' spirits high.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 45018, 56809 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 25, ["flags"] = 0 } } },
[26094] = { ["id"] = 26094, ["name"] = "Striking Back", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25997, 25998, 26078, 26085, 26102, 26112 }, ["description"] = "My chief engineer tells me that he's managed to get one of the bombers repaired and airworthy. Take these bombs with you, and look for the repaired bomber at the start of the runway. Once you're airborne, use the bombs to do as much damage to the attacking Dark Iron dwarves as you can. I've heard rumors that they're preparing to deploy a new kind of war golem. Keep your eyes peeled for those golems and make them your highest priority targets.", ["objectivesText"] = "Board the Repaired Bomber and use the Iron Hammer Bomb to kill 30 Dark Iron attackers. You may kill any of the Dark Iron dwarves or their allies at the Ironforge Airfield. Progress: At last, we finally have a chance to hurt the Dark Iron attackers.", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 56814 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 26, ["flags"] = 0 } } },
[26102] = { ["id"] = 26102, ["name"] = "Grimaxe's Demise", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25997, 25998, 26078, 26085, 26094, 26112 }, ["description"] = "With you leading the way, we've finally broken the momentum of the Dark Iron attack. General Grimaxe , the Dark Iron leader, is attempting to rally his troops from the center of their lines on the frozen lake to the south. He stands atop one of their new dark iron golems, shouting orders to his men. If he succeeds in rallying them, they may still be able to overpower us. You must prevent that, <name>. Destroy the golem guarding him, then kill General Grimaxe himself. He is the key to our victory.", ["objectivesText"] = "Kill General Grimaxe at the Ironforge Airfield. Progress: If we can defeat General Grimaxe , the Dark Iron forces won't be able to regroup.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 57579, 57580, 57581, 57582, 131483, 131484 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 27, ["flags"] = 0 } } },
[26105] = { ["id"] = 26105, ["name"] = "Claim Korthun's End", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 26105 }, ["description"] = "The Horde has spies in this area? Darkbreak Cove is nearby, and inside lies the Pincer X2! The Horde must not be allowed anywhere nearby! Someone in Darkbreak Cove will want to hear of this... after you finish slaying some more of these dirty Horde spies.", ["objectivesText"] = "Kill 7 Hellscream Seadogs in Korthun's End.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 56571, 57102 }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41665, ["x"] = 0.418667, ["y"] = 0.704667 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.704667 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[26112] = { ["id"] = 26112, ["name"] = "Demanding Answers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["series"] = { 25997, 25998, 26078, 26085, 26094, 26102 }, ["description"] = "So just how did all those Dark Iron warriors end up here, on the doorstep of Ironforge, on the verge of invading our city? Does not 'Empress' Moira, a member of our esteemed Council of Three Hammers, rule the Dark Iron? This cannot have happened without her knowledge and consent. This was no ragtag band of rebel dwarves, but a well-organized and fully equipped invasion force. I have prepared a report on the battle for the airfield. Take it to Ironforge, to the High Seat and confront her!", ["objectivesText"] = "Take Stonebreaker's Report to Moira Thaurissan in Ironforge's High Seat. Progress: What is the meaning of this intrusion?", ["rewardGold"] = 339600, ["rewardXP"] = 250, ["rewardItems"] = { 56823 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 41853, ["x"] = 0.782, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 42129, ["x"] = 0.3956, ["y"] = 0.5628 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 27, 87 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 28, ["flags"] = 0 } } },
[26118] = { ["id"] = 26118, ["name"] = "Seize the Ambassador", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "The ambassador's betrayal will long haunt me. You must arrest him before he can do further harm, or worse, before he can escape and start planning the next attack. Ironforge is not safe with Ambassador Slaghammer free inside the city. Take these manacles and go to the Dark Iron embassy. It's just to the north of the High Seat, around the rim of the Great Forge. Arrest Ambassador Slaghammer and return with him.", ["objectivesText"] = "Go to the Dark Iron Embassy and use the Sturdy Manacles to arrest Ambassador Slaghammer. Progress: We must stop the ambassador before he causes more harm.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 56837, 57583, 57584, 57585, 133692 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 42129, ["x"] = 0.3956, ["y"] = 0.5628 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 42129, ["x"] = 0.3956, ["y"] = 0.5628 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.3956, ["y"] = 0.5628 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 29, ["flags"] = 0 } } },
[26121] = { ["id"] = 26121, ["name"] = "Claim Korthun's End", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 26121 }, ["description"] = "You are seeink spies up above? This is not good... not good at all, comrade. Return to Korthun's End and destroy them, my friend.", ["objectivesText"] = "Kill 7 Hellscream Seadogs in Korthun's End.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41662, ["x"] = 0.409333, ["y"] = 0.704667 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41665, ["x"] = 0.418667, ["y"] = 0.704667 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.409333, ["y"] = 0.704667 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[26124] = { ["id"] = 26124, ["name"] = "Secure Seabrush", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 26124 }, ["description"] = "The Alliance has spies in this area? Tenebrous Cavern is nearby, and inside lies the Horde's new submarine, the Verne! The Alliance must not be allowed anywhere nearby! Someone in the cavern will want to hear of this incursion... after you finish slaying some more of these scheming Alliance spies.", ["objectivesText"] = "Kill 7 Alliance Sea-Scouts in Seabrush.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41668, ["x"] = 0.515333, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.515333, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[26125] = { ["id"] = 26125, ["name"] = "Secure Seabrush", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 26125 }, ["description"] = "You saw spies up above? This is not good... I won't have it. Return to Seabrush and get rid of them before they start trickling into our hideout.", ["objectivesText"] = "Kill 7 Alliance Sea-Scouts in Seabrush.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41663, ["x"] = 0.514667, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41668, ["x"] = 0.515333, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.514667, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[26150] = { ["id"] = 26150, ["name"] = "A Visit With Maybell", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 26150 }, ["series"] = { 106, 107, 111, 112 }, ["description"] = "You seem like the helpful type, <name>. How about doing an old man a favor? The last time I was over at the Maclure Vineyards I overheard Maybell crying in her cottage. Would you be so kind as to go check up on her? I'm a little worried.", ["objectivesText"] = "Speak to Maybell Maclure at the Maclure Vineyards in Elwynn Forest .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 253, ["x"] = 0.432, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 251, ["x"] = 0.43, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[26152] = { ["id"] = 26152, ["name"] = "WANTED: James Clark", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 11, 35, 37, 40, 45, 46, 47, 52, 59, 60, 62, 71, 76, 83, 84, 85, 86, 87, 88, 106, 107, 111, 112, 114, 123, 147, 176, 5545, 26152, 37112 }, ["description"] = "By decree of the Stormwind Army, a bounty has been placed on the head of James Clark. Clark is wanted for robbery, burglary, arson, and murder. He is also a suspect in the kidnapping and disappearance of the Brackwell's prized pig, Princess. James Clark was last seen heading towards Eastvale Logging Camp. Bring James Clark to justice and report to Marshal Patterson at Eastvale Logging Camp.", ["objectivesText"] = "Kill James Clark and take James Clark's Head . Progress: Turning in a bounty?", ["rewardXP"] = 200, ["rewardItems"] = { 57122 }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 42256, ["x"] = 0.818, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.818, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 566, ["name"] = "Elwynn Forest", ["orderIndex"] = 18, ["flags"] = 0 } } },
[26153] = { ["id"] = 26153, ["name"] = "Penny's Pumpkin Pancakes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26153 }, ["description"] = "My daughter Penny loves pumpkin pancakes but we have had a shortage of pumpkins here in Elwynn from the frostbite last season. I have heard of a new pumpkin patch north of Stormwind that might be ripe for the picking now though. Head out and harvest a few of those ripe pumpkins for me and let's see what we can do.", ["objectivesText"] = "Obtain 6 Stormwind Pumpkins . Deliver them to Robby Flay in Stormwind City. Progress: Have you finished collecting the pumpkins?", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 57137 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5052, ["y"] = 0.7192 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26177] = { ["id"] = 26177, ["name"] = "Feeling Crabby?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26177 }, ["description"] = "Fresh crab legs have always been one of the King's favorite foods. We have had good luck catching fresh crabs in the canals over the past few weeks. Do you think you can lend me a hand and catch a few of them for me? Be sure to catch them alive, they are no good to me dead, the King requires the freshest catch we can muster.", ["objectivesText"] = "Catch 6 Canal Crabs . Deliver them to Robby Flay in Stormwind City. Progress: You must have fast hands! I can't believe you caught all those crabs so quickly!", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 7052, 19979, 43389, 50398, 57175, 85500 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5052, ["y"] = 0.7192 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26178] = { ["id"] = 26178, ["name"] = "Planning for the Future", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 26178 }, ["description"] = "We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain. The Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance. If Elder Ko'nani hasn't asked you already, he will ask you to deal with them. While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.", ["objectivesText"] = "Collect 12 Snowfall Glade Pups . Deliver them to Trapper Mau'i at Moa'ki Harbor.", ["rewardGold"] = 50000, ["rewardXP"] = 200, ["rewardItems"] = { 35692 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[26179] = { ["id"] = 26179, ["name"] = "The Venture Co.", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["description"] = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore . Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background. Greedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", ["objectivesText"] = "Kill 7 Venture Co. Workers for Morin Cloudstalker at Bloodhoof Village. Progress: The Venture Co. was refused mining rights here in Mulgore , but it would seem that they do not take no for an answer. We tauren are not ones to mince words, however, and we have other ways of getting our message across.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 61071, 61072, 61073, 61103, 61104, 61105, 131521, 131598, 156990, 156991, 166846, 166970, 166971, 232448, 232449, 232450, 232451, 232452, 232453, 234746, 235264, 235265, 235661, 237133, 238251, 246697 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2988, ["x"] = 0.57, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2988, ["x"] = 0.57, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 13, ["flags"] = 0 } } },
[26180] = { ["id"] = 26180, ["name"] = "Supervisor Fizsprocket", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["description"] = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands. The depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", ["objectivesText"] = "Kill Supervisor Fizsprocket and collect Fizsprocket's Clipboard . Progress: I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.", ["rewardGold"] = 561800, ["rewardXP"] = 250, ["rewardItems"] = { 4819, 57208, 57242, 131493 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2988, ["x"] = 0.57, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2988, ["x"] = 0.57, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 14, ["flags"] = 0 } } },
[26183] = { ["id"] = 26183, ["name"] = "The King's Cider", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26183 }, ["description"] = "I am forever in debt to our King for all that he has done for us. One thing I can do for him is make his favorite drink! Lucky for us, the ingredients we need to make this wonderful drink are located right here in Stormwind City. Apple trees can be found in every district of Stormwind. These trees are too tall to pick the fruit from, but lucky for us the apples have fallen to the ground and are easy to retrieve.", ["objectivesText"] = "Obtain 12 Juicy Apples . Deliver the fruit to Robby Flay in Stormwind City. Progress: Were you able to find enough Juicy Apples ?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 57197 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5052, ["y"] = 0.7192 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26188] = { ["id"] = 26188, ["name"] = "Mazzranache", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["description"] = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite. As fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I have gathered all the parts of the remedy I need to cure myself... except a flatland cougar femur . I grow weaker by the moment... please, help me.", ["objectivesText"] = "Bring a Flatland Cougar Femur to Maur Raincaller at Bloodhoof Village. Progress: My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn't be able to handle a beast my grandfather was unable to defeat... Do you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 4805, 57209, 57234, 66616, 131494 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 3055, ["x"] = 0.471, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 3055, ["x"] = 0.471, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 4, ["flags"] = 0 } } },
[26190] = { ["id"] = 26190, ["name"] = "A Fisherman's Feast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26190 }, ["description"] = "If there is one meal I know the King likes, it's fresh catfish. Catfish are easy to prepare but hard to catch. That's where you come in! We have a good population of Gigantic Catfish here in the waters of Stormwind but the competition to catch them is intense to say the least. I need you to figure out a way to \"acquire\" some of these fine catfish for our King. You will find fisherman at the small canal docks around town. You should be able to figure out the rest of the plan on your own.", ["objectivesText"] = "Obtain 5 Gigantic Catfish . Deliver the fish to Robby Flay in Stormwind City. Progress: Were you able to steal the fish?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 57245, 58503 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5052, ["y"] = 0.7192 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26192] = { ["id"] = 26192, ["name"] = "Orphans Like Cookies Too!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26192 }, ["description"] = "The orphans of Stormwind are often forgotten, but not today my friend. The king has requested a special batch of cookies be baked and sent immediately over to the orphanage. I was almost finished with the final batch when I ran out of confectioners' sugar . Can you run out and get some more for me? You should be able to find it at any of the general stores or inns inside of Stormwind.", ["objectivesText"] = "Obtain 4 sacks of Confectioners' Sugar . Deliver the sugar to Robby Flay in Stormwind City. Progress: Were you able to find the Confectioner's Sugar?", ["rewardGold"] = 319000, ["rewardXP"] = 1415, ["rewardItems"] = { 57246 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 42288, ["x"] = 0.5052, ["y"] = 0.7192 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5052, ["y"] = 0.7192 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26197] = { ["id"] = 26197, ["name"] = "The Future of Gnomeregan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. <class>s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque has assembled a team of trainers to help you learn your arts. Bipsi Frostflinger will help oversee your training and adjustment to life on the surface. She's waiting for you outside the tall building to the northeast.", ["objectivesText"] = "Meet with Bipsi Frostflinger in New Tinkertown .", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 134123 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42396, ["x"] = 0.339, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42331, ["x"] = 0.344, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 6, ["flags"] = 0 } } },
[26199] = { ["id"] = 26199, ["name"] = "The Future of Gnomeregan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26199, 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26422, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26197, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. <class>s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts. \"Doc\" Cogspin will help oversee your training and adjustment to life on the surface. She's waiting for you near the cluster of buildings to the north.", ["objectivesText"] = "Meet with \"Doc\" Cogspin in New Tinkertown .", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 134123 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42396, ["x"] = 0.339, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 469, ["npcID"] = 42323, ["x"] = 0.395, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 7, ["flags"] = 0 } } },
[26202] = { ["id"] = 26202, ["name"] = "The Future of Gnomeregan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26202, 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26424, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26197, 26199, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. We're going to need all the help we can get to reclaim our home and rid ourselves of the troggs and irradiated gnomes. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your, uh, \"arts\". Alamar Grimm has taken up residence in the building just west of this one. He possesses powers similar to yours and can help you get adjusted.", ["objectivesText"] = "Meet with Alamar Grimm in New Tinkertown .", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 134123 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42396, ["x"] = 0.339, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 469, ["npcID"] = 460, ["x"] = 0.376, ["y"] = 0.3785 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 8, ["flags"] = 0 } } },
[26203] = { ["id"] = 26203, ["name"] = "The Future of Gnomeregan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26203, 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26197, 26199, 26202, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. <class>s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts. Drill Sergeant Steamcrank will help oversee your training and adjustment to life on the surface. He's waiting for you on the small practice field across the road.", ["objectivesText"] = "Meet with Drill Sergeant Steamcrank in New Tinkertown .", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 134123 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42396, ["x"] = 0.339, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 469, ["npcID"] = 42324, ["x"] = 0.405, ["y"] = 0.3545 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 9, ["flags"] = 0 } } },
[26205] = { ["id"] = 26205, ["name"] = "A Job for the Multi-Bot", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26197, 26199, 26202, 26203, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "If the multi-bot works, it will help us do all kinds of jobs that are unpleasant or dangerous for us gnomes! After Thermaplugg detonated his irradiator at the end of Operation: Gnomeregan, toxic clouds and ooze began bubbling up at the old airfield south of town. If we don't get it under control, the contamination could spread to the rest of our lands. Take the multi-bot with you, and bring it close to the geysers in the green pools at the Toxic Airfield. Your bot should spring into action!", ["objectivesText"] = "Use the GS-9x Multi-Bot to clean up 5 Toxic Geysers at the Toxic Airfield. When you get close enough to a geyser, your GS-9x Multi-Bot will automatically begin its task.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42553, ["x"] = 0.342, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42553, ["x"] = 0.342, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 23, ["flags"] = 0 } } },
[26206] = { ["id"] = 26206, ["name"] = "The Future of Gnomeregan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26423, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. <class>s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts. Kelsey Steelspark , a key member of Gnomeregan Covert Ops, will help oversee your training and adjustment to life on the surface. She should be in the council tent to the northwest.", ["objectivesText"] = "Meet with Kelsey Steelspark in New Tinkertown .", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 134123 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42396, ["x"] = 0.339, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42366, ["x"] = 0.334, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 10, ["flags"] = 0 } } },
[26208] = { ["id"] = 26208, ["name"] = "The Fight Continues", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredRaces"] = { 7, 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "The dwarves of Ironforge kindly took us in when the trogg invasion and radiation forced us to leave Gnomeregan for the first time. But even the kindness of friends can't quell the longing for home. I sent out a call for brave gnomes and other members of the Alliance to help us regain control of Gnomeregan and defeat the usurper Thermaplugg once and for all. We weren't able to achieve everything Operation: Gnomeregan set out to do, but Thermaplugg is on the run and we're closer to home than ever.", ["objectivesText"] = "Watch the holo-table in front of High Tinker Mekkatorque to learn about Operation: Gnomeregan. Progress: Thermaplugg's defeat is a certainty, but that irradiator has bought him time to regroup.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 20, ["flags"] = 0 } } },
[26220] = { ["id"] = 26220, ["name"] = "Everything Is Better with Bacon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 85, ["storyline"] = { 26220 }, ["description"] = "Feeding a hungry orc army is never an easy task. Luckily for us, we have a good supply of mature swine meat from the pig farms and surrounding areas south of Orgrimmar. Do me a favor and slaughter some of those pigs for their delicious belly meat. I will slice it up and make bacon for the troops' breakfast.", ["objectivesText"] = "Slaughter Mature Swine south of Orgrimmar and bring me back 6 of their Swine Bellies . I will be waiting for you here in The Drag. Progress: Have you finished slaughtering the swine?", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 29292, 30632, 57758 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5476, ["y"] = 0.5028 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[26222] = { ["id"] = 26222, ["name"] = "Scrounging for Parts", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "There's just too much to do around here, and too few gnomes on their feet to help! The high tinker has asked me to start converting some of our old bots and parts from Operation: Gnomeregan. I hope to have a new line of multi-bots ready for a field test soon! I don't suppose you'd have some time to help, do you? There are all kinds of parts scattered around. Pick up anything you find and bring it back to me. You never know what could turn out to be useful!", ["objectivesText"] = "Bring 7 Spare Parts to Engineer Grindspark in New Tinkertown . Progress: Did you get those parts?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57764 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42553, ["x"] = 0.342, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42553, ["x"] = 0.342, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 22, ["flags"] = 0 } } },
[26226] = { ["id"] = 26226, ["name"] = "Crawfish Creole", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26226 }, ["description"] = "There are a number of small lakes scattered around Orgrimmar. These lakes fill up with crawfish every year. That's where you come in, <name>. I need you to catch some of those delicious crustaceans and return to me when you are done. Assuming your catch is successful, our Horde army will feast tonight.", ["objectivesText"] = "Catch 10 Muddy Crawfish in Orgrimmar. Deliver the crustaceans to Marogg when you are done. Progress: Were you able to dig up some crayfish?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 43001, 57765 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5476, ["y"] = 0.5028 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26227] = { ["id"] = 26227, ["name"] = "Careful, This Fruit Bites Back", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26227 }, ["description"] = "Sometimes the troops want something sweet to eat. I don't always give them what they want but this time, I am going to make an exception. I am sure you have seen the local cactus that grows here in Orgrimmar. These cactus produce a tasty treat called prickly pear fruit . The trouble is the fruit are covered in spines! Watch your hands and bring me back a handful of that fruit.", ["objectivesText"] = "Retrieve 8 pieces of Prickly Pear Fruit . Deliver the fruit to Marogg in Orgrimmar. Progress: Were you able to find enough fruit?", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 10036, 23836, 54451, 57766 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5476, ["y"] = 0.5028 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26233] = { ["id"] = 26233, ["name"] = "Stealing From Our Own", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26233 }, ["description"] = "As you know, <name>, Garrosh has relegated the trolls of Orgrimmar to the western outskirts of the city. Fortunately, that means that we have easy access to their supplies. I am working on a large batch of jambalaya for the infantry and I need as much rice as possible. Lucky for us, the trolls keep it stored in barrels near their structures. Retrieve these barrels of Darkspear rice for me and I should be able to finish up.", ["objectivesText"] = "Retrieve 6 Barrels of Darkspear Rice . Deliver the rice to Marogg in Orgrimmar. Progress: Were you able to acquire the rice?", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 57877 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5476, ["y"] = 0.5028 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26234] = { ["id"] = 26234, ["name"] = "Stealing From Our Own", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26234 }, ["description"] = "As you know, <name>, Garrosh has relegated the goblins of Orgrimmar to the western outskirts of the city. Fortunately, that means that we have easy access to their supplies. I am working on a large batch of jambalaya for the infantry and I need as much rice as possible. Lucky for us, the goblins keep it stored in barrels near their structures. Retrieve these barrels of Kezan rice for me and I should be able to finish up.", ["objectivesText"] = "Retrieve 6 Barrels of Kezan Rice . Deliver the rice to Marogg in Orgrimmar. Progress: Were you able to acquire the rice?", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 57878 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5476, ["y"] = 0.5028 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26235] = { ["id"] = 26235, ["name"] = "Even Thieves Get Hungry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26235 }, ["description"] = "We have had a problem with thieves stealing our infantry rations here in Orgrimmar for the last couple of weeks. I recently received some intelligence of where these crimes are taking place. Anywhere you see piles of crates and supplies, there are likely to be thieves nearby. I need you to hunt these thieves down and recover the stolen rations. Return to me when you are done.", ["objectivesText"] = "Recover 3 Horde Infantry Rations . Deliver them to Marogg in Orgrimmar. Progress: Were you able to recover the rations?", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 57879 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 42506, ["x"] = 0.5476, ["y"] = 0.5028 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5476, ["y"] = 0.5028 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26264] = { ["id"] = 26264, ["name"] = "What's Left Behind", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredRaces"] = { 7, 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["description"] = "Most of us have seen the sickly and deranged gnomes suffering from exposure to the poisons and radiation of Gnomeregan. Eventually, they will devolve further, until they become mindless, but mostly harmless, puddles of toxic sludge. My research suggests that we may even be able to restore them from this state. Go to the Toxic Airfield to the south, subdue the toxic sludge I told you about, and bring back the possessions of the gnomes they once were.", ["objectivesText"] = "Retrieve 6 Recovered Possessions from Toxic Sludges at the Toxic Airfield. Progress: Were you able to recover the belongings of any of the irradiated gnomes?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57987, 59039, 59040, 59041, 59042, 59043 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42611, ["x"] = 0.338, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42611, ["x"] = 0.338, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 24, ["flags"] = 0 } } },
[26265] = { ["id"] = 26265, ["name"] = "Dealing with the Fallout", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredRaces"] = { 7, 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["description"] = "Tock Sprysprocket has some crazy theory about these toxic sludges being the last remnants of gnomes, so my men have orders not to engage them for now. However, the Toxic Airfield, just south of us, is teeming with living contamination . They are elementals composed of contaminated water and other toxic materials. Left unchecked, they'll overrun the town. Will you help us dispose of them?", ["objectivesText"] = "Destroy 6 Living Contaminations at the Toxic Airfield. Progress: Were you able to clear away any of the contamination?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 59038, 59039, 59040, 59041, 59042, 59043, 59053 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42630, ["x"] = 0.334, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42630, ["x"] = 0.334, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 25, ["flags"] = 0 } } },
[26272] = { ["id"] = 26272, ["name"] = "The Rise of the Darkspear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 26273, 26275, 26276, 26277 }, ["description"] = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here. Vol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream. No, dis time we not fleein'. Dis time, we are fightin' for a home dat will last. It's time to begin ya trainin', <name>. Speak with Voldreka to the east.", ["objectivesText"] = "Meet with Voldreka in the Darkspear Training Grounds.", ["rewardGold"] = 1500, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 37951, ["x"] = 0.624, ["y"] = 0.844 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.844 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 7, ["flags"] = 0 } } },
[26273] = { ["id"] = 26273, ["name"] = "The Basics: Hitting Things", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 26272, 26275, 26276, 26277 }, ["description"] = "Alright, mon. We start simple. I need ta know dat you know the basics of the dark arts. Go thrash dose tiki targets . Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", ["objectivesText"] = "Destroy 6 Tiki Targets . Progress: Power stems from dis world and worlds you've not yet seen. Masterin' da power of one ain't gonna be enough ta make it outside of dese trainin' grounds - you gonna need to be pullin ya power from all of dem.", ["rewardGold"] = 2000, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.649, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 15, ["flags"] = 0 } } },
[26275] = { ["id"] = 26275, ["name"] = "A Rough Start", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 26272, 26273, 26276, 26277 }, ["description"] = "Lets put dose skills ta use. I'll start ya off easy, mon. There be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight. Dey're all over the island. Bring me some cat pelts.", ["objectivesText"] = "Retrieve 6 Wildmane Cat Pelts . Progress: I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 50222 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.649, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 25, ["flags"] = 0 } } },
[26276] = { ["id"] = 26276, ["name"] = "Proving Pit", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 26272, 26273, 26275, 26277 }, ["description"] = "Ya done quite well for ya'self, <class>. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer. l put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", ["objectivesText"] = "Speak to a Darkspear Jailor , then enter the proving pit and kill a Captive Spitescale Scout . Progress: All trolls gotta prove demselves before we let them move past da training grounds.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 52870, 52872, 52873, 52874, 52875, 52876, 52889, 85574 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.649, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 34, ["flags"] = 0 } } },
[26277] = { ["id"] = 26277, ["name"] = "More Than Expected", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6453, ["mapID"] = 1, ["storyline"] = { 24622, 24623, 24624, 24625, 24626, 24812, 24813, 24814, 25035, 25037, 25064, 25073, 26272, 26273, 26275, 26276, 26277, 31158, 31159, 31160, 31161, 31163 }, ["series"] = { 26272, 26273, 26275, 26276 }, ["description"] = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more. Head down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", ["objectivesText"] = "Report to Vol'jin at Darkspear Hold.", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 42618, ["x"] = 0.649, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 38966, ["x"] = 0.688, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.649, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 43, ["flags"] = 0 } } },
[26284] = { ["id"] = 26284, ["name"] = "Missing in Action", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26285, 26318, 26329, 26331 }, ["description"] = "Fer a job like this, I normally bring me whole crew o' demolitionists. With some help in settin' up th' powder, th' charges, and th' rest o' th' gear, the job gets done a lot faster. Those blasted troggs have me men caged all around Frostmane Hold. Now I'm 'ere all alone without th' personnel I need to finish th' job. You look like a capable <class>, though. Would you find th' demolitionists th' troggs captured and break them out o' their cages?", ["objectivesText"] = "Free 6 Captured Demolitionists from their cages around Frostmane Hold. Progress: Were you able to free any o' me men?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 27, ["flags"] = 0 } } },
[26285] = { ["id"] = 26285, ["name"] = "Get Me Explosives Back!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26284, 26318, 26329, 26331 }, ["description"] = "It's gonna take a lot of powder ta collapse those caves. I don't know whether th' damnable troggs understood that when they stole me supplies and kidnapped me demolitionists! But th' outcome's th' same. Ain't gonna be able ta blow nothin' up until I've got that powder back. Go south to Frostmane Hold and kill any o' those troggs you find. Any one o' 'em could be carryin' me kegs o' powder.", ["objectivesText"] = "Recover 7 Stolen Powder Kegs from Rockjaw Bonepickers or Rockjaw Marauders at Frostmane Hold. Progress: Well, did you recover me missing supplies?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 58202 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 28, ["flags"] = 0 } } },
[26316] = { ["id"] = 26316, ["name"] = "What's Keeping Kharmarn?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["description"] = "The cataclysm tore open deep caves beneath Frostmane Hold and troggs flooded out of their warrens. They succeeded in displacing the trolls who used to live there and they stand to drive us out if we do not act. High Tinker Mekkatorque hired the renowned demolitionist, Kharmarn Palegrip , to close the caves and stem the trogg advance. We've received no word about whether he was able to stop the troggs. Would you look for him at his camp near Frostmane Hold, to the south beyond the Toxic Airfield?", ["objectivesText"] = "Find Kharmarn Palegrip at his camp in Frostmane Hold.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42489, ["x"] = 0.334, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 26, ["flags"] = 0 } } },
[26318] = { ["id"] = 26318, ["name"] = "Finishin' the Job", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26284, 26285, 26329, 26331 }, ["description"] = "My team has finished settin' up th' powder kegs and th' detonator at the bottom o' th' cave in th' western part of Frostmane Hold. All you need to do is venture down there and activate th' detonator to explode the powder and collapse those tunnels. That'll stop th' flow of troggs from th' deep parts of th' earth. Mekkatorque'll have an easier time of dealin' with the remainin' troggs if you can take out their leader, who calls 'imself Boss Bruggor . Good luck, <name>.", ["objectivesText"] = "At the bottom of the cave in Frostmane Hold, kill Boss Bruggor and activate the Detonator to detonate the trogg tunnels. Progress: Well, is th' job done?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 59044, 59045, 59046, 131512 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 29, ["flags"] = 0 } } },
[26325] = { ["id"] = 26325, ["name"] = "A Nose for This Sort of Thing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386 }, ["series"] = { 26330, 26332 }, ["description"] = "<The skull speaks to you.> I live? No, I do not... but I can. That raptor you have is wise to have found my skull among what must have been so many. In life, I was strong, powerful, a lord among trolls. With your help, I can be a lord once more. The Bloodscalps at Zuuldaia hoard magical fetishes that can help me return. They hide these artifacts under the sand. Use your hatchling to find these artifacts, <name>... then throw them in the pot.", ["objectivesText"] = "Use your Lashtail Hatchling to sniff out 8 Zuuldaian Fetishes . Progress: <The large troll skull bubbles to the surface.> How many did you find?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 58165, 58171 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 31, ["flags"] = 0 } } },
[26329] = { ["id"] = 26329, ["name"] = "One More Thing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26284, 26285, 26318, 26331 }, ["description"] = "Well, it's time to start packin' up and movin' on to the next job. There's always somethin' else to blow up out there. Somewhere, there's a mountain needs movin' or a gorge that needs carvin', and I'll be there to do it. I don't suppose you'd do me one more favor? Would you take this report back to High Tinker Mekkatorque in New Tinkertown ? He needs to know that th' troggs won't be botherin' his people again anytime soon.", ["objectivesText"] = "Bring Kharmarn's Report to High Tinker Mekkatorque in New Tinkertown . Progress: Welcome back, <name>.", ["rewardGold"] = 200, ["rewardXP"] = 25, ["rewardItems"] = { 58178, 237812 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42708, ["x"] = 0.33, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 30, ["flags"] = 0 } } },
[26331] = { ["id"] = 26331, ["name"] = "Crushcog's Minions", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredRaces"] = { 7, 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26284, 26285, 26318, 26329 }, ["description"] = "Our old enemy, Thermaplugg, is doing his best to keep us from rebuilding and finishing our reclamation of Gnomeregan. He's sent one of his most loyal henchmen, Razlo Crushcog, and a force of irradiated gnomes to harry us. They've taken over an old arsenal up the road to the north, and Crushcog's technicians are repairing those weapons. We have to stop them before they're able to get those mechano-tanks back online. Go to Crushcog's Arsenal and eliminate as many of the technicians as you can.", ["objectivesText"] = "Kill 8 of Crushcog's Minions at Crushcog's Arsenal. You may kill Irradiated Technicians or Crushcog's Battle Suits.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 31, ["flags"] = 0 } } },
[26333] = { ["id"] = 26333, ["name"] = "No Tanks!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["description"] = "We've lost more than a couple scouts trying to find out what exactly Razlo Crushcog plans to do with all those mechano-tanks his irradiated technicians are repairing. We can't afford to take it slowly anymore. We must act before Crushcog turns his followers and his weapons on us. This techno-grenade packs enough explosive power to destroy the mechano-tanks and deny Crushcog their use. Take it north with you along the road to Crushcog's Arsenal and take out those tanks!", ["objectivesText"] = "Use the Techno-Grenade to destroy 5 Repaired Mechano-Tanks at Crushcog's Arsenal. Progress: Have you managed to take out any of those mechano-tanks Crushcog's men are working on?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 58200, 59047, 59048, 59049, 131514, 184156 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42491, ["x"] = 0.334, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42491, ["x"] = 0.334, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 32, ["flags"] = 0 } } },
[26339] = { ["id"] = 26339, ["name"] = "Staging in Brewnall", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26342, 26364 }, ["description"] = "While High Tinker Mekkatorque, his military advisors, and I finalize the plans for the attack on Razlo Crushcog, I've sent my assistant ahead to Brewnall Village to begin preparations. To get to Brewnall Village, follow the road southeast out of town. Once you arrive, find Jarvi Shadowstep and see if he needs any help. Our dwarven cousins have dispatched a cadre of mountaineers from Ironforge to join us in the fight against Crushcog.", ["objectivesText"] = "Speak with Jarvi Shadowstep at Brewnall Village.", ["rewardGold"] = 200, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42366, ["x"] = 0.334, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42353, ["x"] = 0.374, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 33, ["flags"] = 0 } } },
[26342] = { ["id"] = 26342, ["name"] = "Paint it Black", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26339, 26364 }, ["description"] = "We have reliable intelligence that Razlo Crushcog has taken up a defensive position on the island in the middle of frozen Iceflow Lake. To make matters worse, he's surrounded himself with a network of sentry-bots that will detect any possible attackers. If we're to take on Crushcog, we'll need to take out those sentries. This device launches a dark, sticky paint that will coat the optical sensors of Crushcog's sentry-bots. Use it to take out his early warning system.", ["objectivesText"] = "Use the Paintinator to blind 5 of Crushcog's Sentry-Bots. Progress: Were you able to blind Crushcog's sentries?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 44800, 45693, 58203, 63809, 63810, 63811 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42353, ["x"] = 0.374, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42353, ["x"] = 0.374, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 34, ["flags"] = 0 } } },
[26364] = { ["id"] = 26364, ["name"] = "Down with Crushcog!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26339, 26342 }, ["description"] = "Our cousins, the dwarves of Ironforge, have agreed to help us in the battle against Razlo Crushcog. Mountaineer Stonegrind is a veteran who knows Dun Morogh well. He and High Tinker Mekkatorque stand ready on a small snow-covered island in Iceflow Lake to the north. Meet up with them there and let the high tinker know when you are ready to face the traitor Crushcog. Take this orbital targeting device and use it during the battle. It will help guide the high tinker's special weapons.", ["objectivesText"] = "Defeat Razlo Crushcog. Speak to High Tinker Mekkatorque at Iceflow Lake when you are ready to begin the battle. Progress: Did you face Crushcog? What happened?", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 58253, 59050, 59051, 59052, 131516 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42353, ["x"] = 0.374, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42353, ["x"] = 0.374, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 35, ["flags"] = 0 } } },
[26373] = { ["id"] = 26373, ["name"] = "On to Kharanos", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["description"] = "Some of the mountaineers under Stonegrind's command were telling me about the situation out at Kharanos. When the troggs took over Frostmane Hold, it sounds like the surviving trolls fled westward, deep into the heart of the dwarven homeland. Now, they threaten the dwarven town of Kharanos. It sounds like they're going to need all the help they can get. You should go to Kharanos and introduce yourself to Captain Tharran . Just follow the road east out of Brewnall and keep going until you see the town.", ["objectivesText"] = "Speak with Captain Tharran in Kharanos.", ["rewardGold"] = 10500, ["rewardXP"] = 25, ["rewardItems"] = { 159, 4540 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42353, ["x"] = 0.374, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 40950, ["x"] = 0.536, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 36, ["flags"] = 0 } } },
[26380] = { ["id"] = 26380, ["name"] = "Bound for Kharanos", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 26380 }, ["description"] = "I was supposed to be bringing these casks of ale to the inn in Kharanos. They contain a mysterious new ale produced by an upstart brewery based in Brewnall Village. As I was leaving town, I was attacked by a Frostmane troll raiding party. It's going to take me days to repair the wagon! I don't suppose you'd be willing to do me a favor, will you? These big kegs aren't going anywhere, but I have some smaller sample casks . Would you bring them to Kharanos for me? Just follow the road to the southeast.", ["objectivesText"] = "Bring the Sample Casks to Innkeeper Belm at the Thunderbrew Distillery in Kharanos. Progress: Welcome, visitor. Have you come to the inn to rest, or do you need a new hearthstone?", ["rewardGold"] = 10500, ["rewardXP"] = 25, ["rewardItems"] = { 159, 4540, 58271 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42933, ["x"] = 0.498, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 1247, ["x"] = 0.544, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[26389] = { ["id"] = 26389, ["name"] = "Blackrock Invasion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "The orcs have begun burning down the forest, <name>! They have taken over the vineyard to the east and are planning their final assault against us! They must be stopped! Head east, across the river, and kill the rampaging Blackrock orcs. Collect their weapons as proof of their demise and return to me. You're our only hope, <name>!", ["objectivesText"] = "Recover 8 Blackrock Orc Weapons . Progress: Have you killed the rampaging orc hordes?", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 58361 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 45, ["flags"] = 0 } } },
[26390] = { ["id"] = 26390, ["name"] = "Ending the Invasion!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "The rampaging orc horde is led by a savage beast known as Kurtok the Slayer ! Kurtok is responsible for the recent invasion and must be killed if we are to have peace in the valley. Venture back east, across the river and through the vineyard, and look for the passage leading into the mountains. Kurtok will be there, preparing for another assault. Kill him and return to me.", ["objectivesText"] = "Kill Kurtok the Slayer . Progress: Have you found Kurtok?", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 5579, 5580, 57393, 85575, 133699, 248621 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 47, ["flags"] = 0 } } },
[26391] = { ["id"] = 26391, ["name"] = "Extinguishing Hope", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["description"] = "Times like these make me long for when the Defias were still around. The cataclysm has opened a pathway from the Burning Steppes and now Blackrock orcs pour into Northshire Valley! They have taken over my vineyard and are burning it to the ground! TO THE GROUND! Please, <name>, that vineyard is all I have. Take my fire extinguisher and extinguish the flames at the vineyard. There still might be hope for that land!", ["objectivesText"] = "Use Milly's Extinguisher to put out 8 Vineyard Fires. Progress: Have you put out the fires?", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 11475, 57247, 58362 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 9296, ["x"] = 0.48, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 9296, ["x"] = 0.48, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 46, ["flags"] = 0 } } },
[26396] = { ["id"] = 26396, ["name"] = "Return to Argus", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26396 }, ["series"] = { 26393, 26394, 26395 }, ["description"] = "The gryphon master in Goldshire is Bartlett. If you've spoken to him before, then you can take one of my gryphons to him. That's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there. You've already been to Bartlett, so just speak with me again when you're ready to take a gryphon to Goldshire. Once there, you can deliver Osric's Crate to Smith Argus .", ["objectivesText"] = "Buy a gryphon ride to Goldshire from the gryphon master Dungar Longdrink , then take Osric's Crate to Smith Argus at Goldshire. Progress: You're back from Stormwind? Did Osric send the armor?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 16115 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 352, ["x"] = 0.618, ["y"] = 0.728667 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 514, ["x"] = 0.416, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.728667 }, ["mapCandidates"] = { ["npc"] = { 37, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26397] = { ["id"] = 26397, ["name"] = "Walk With The Earth Mother", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 88, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["description"] = "Much has changed outside of Mulgore, <name>. The world is torn, and our Horde allies have turned down dark paths. We must guide them. Even in the darkest hour, we will bravely hold our heads high, and honor the Earth Mother in all we do. You must go, <name>, and be this example. Go to Orgrimmar . Tell Saurfang how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow. Tal at the Skytower will send you on your way. Go in peace, and never forget your people.", ["objectivesText"] = "Take the Mark of Bloodhoof to High Overlord Saurfang , located in Grommash Hold in Orgrimmar . You may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin. Progress: What makes you seek the Warchief of the Horde, <race>?", ["rewardGold"] = 210675, ["rewardXP"] = 150, ["rewardItems"] = { 58366, 243335 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 14720, ["x"] = 0.485, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 39605, ["x"] = 0.4745, ["y"] = 0.5395 }, { ["mapID"] = 85, ["npcID"] = 86832, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.568667, ["y"] = 0.477 }, ["mapCandidates"] = { ["npc"] = { 85, 88 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 22, ["flags"] = 0 } } },
[26412] = { ["id"] = 26412, ["name"] = "The Mosh'Ogg Bounty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 26412 }, ["series"] = { 26399, 26400 }, ["description"] = "Say... have you heard about the ogres? I got a hot tip from some fella' named Mok'thardin that they're hiding some special, magical artifact in their cave. Skeezy knows better, though. I can smell money from a Mulgore mile away, and I'll bet that ogre doodad's worth a fortune. Here's a hint: I've seen them guarding a chest up in some ruins behind their mound. Care to fetch it for me?", ["objectivesText"] = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 58205 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[26414] = { ["id"] = 26414, ["name"] = "Hitting a Walleye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26414 }, ["description"] = "Sometimes, I fish for fun. Other times to relax, but sometimes I want a challenge. That's where the hardened walleye comes into the picture. This prized fish is not caught for us to eat, but for the challenge. You can find the walleye in Stormwind Lake just north of the city. Think you are up to the challenge?", ["objectivesText"] = "Catherine Leland in Stormwind City wants you to bring her 8 Hardened Walleye . Progress: Was the challenge too much for you?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 6256, 6289, 6308, 57245, 58503, 67414 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26416] = { ["id"] = 26416, ["name"] = "Well, Come to the Jungle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 26416 }, ["series"] = { 26278, 26417, 28688 }, ["description"] = "My commander has sent me to scout for potential recruits to assist in the defense of Grom'gol Base Camp in Northern Stranglethorn . Are you familiar with Stranglethorn? It's a long way away... across the Great Sea, on the southern tip of the Eastern Kingdoms. You fit the build he was looking for... interested in leaving Kalimdor for a while? If so, then go talk to my cohort Bort in Orgrimmar. He'll help you board the zeppelin. And tell him I said \"Woozle wozzle.\" He'll know what it means.", ["objectivesText"] = "Report to Bort in Orgrimmar.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 43063, ["x"] = 0.498667, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 43062, ["x"] = 0.526727, ["y"] = 0.553273 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.498667, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 63, 85 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[26420] = { ["id"] = 26420, ["name"] = "Diggin' For Worms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26420 }, ["description"] = "Hey there, Angler! Arnold here tells me that you have been looking for a new fishing spot and I think I know just the place. North of Stormwind there is a great little spot called Olivia's Pond. The pond is stocked with crystal bass every year but they are hard to catch. They only bite on a very specific type of bait... overgrown earthworms . If you search the shore around the pond, you should find plenty of worms to use as bait.", ["objectivesText"] = "Find an Overgrown Earthworm near Olivia's Pond and use it as bait to catch a Crystal Bass . Crystal Bass can be found in Olivia's Pond, north of Stormwind. Progress: Did the bait work?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 6256, 58787, 58788, 67414 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26421] = { ["id"] = 26421, ["name"] = "Meet the High Tinker", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor. Mekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", ["objectivesText"] = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42331, ["x"] = 0.344, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 13, ["flags"] = 0 } } },
