[26424] = { ["id"] = 26424, ["name"] = "Meet the High Tinker", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 26202, 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26424, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26425, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor. Mekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", ["objectivesText"] = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 469, ["npcID"] = 460, ["x"] = 0.376, ["y"] = 0.3785 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 469, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.3785 }, ["mapCandidates"] = { ["npc"] = { 27, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 16, ["flags"] = 0 } } },
[26425] = { ["id"] = 26425, ["name"] = "Meet the High Tinker", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 26203, 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26566, 31135, 31137, 41217, 41218 }, ["description"] = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor. Mekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", ["objectivesText"] = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 469, ["npcID"] = 42324, ["x"] = 0.405, ["y"] = 0.3545 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 469, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.3545 }, ["mapCandidates"] = { ["npc"] = { 27, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 17, ["flags"] = 0 } } },
[26433] = { ["id"] = 26433, ["name"] = "The Holy Water of Clarity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 26433 }, ["description"] = "Skeezy said you'd be coming. Let's identify this... thing. To start out, I'm going to need you to obtain The Holy Water of Clarity . The nagas to our southeast maintain a hallowed shrine that dispenses a water so clean, so fresh, and so mouthwateringly pure, that when the imbiber quaffs but a mouthful of the sacred stuff, their mind is cleansed and their best path made clear. Sounds good, doesn't it? Obtain it from the Nek'mani Wellspring at the peak of the naga camp. Good luck!", ["objectivesText"] = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn . Progress: <Flem's ears perk up as you approach.> The Holy Water of Clarity ? Is it here!?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 58811 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 43096, ["x"] = 0.336, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 43096, ["x"] = 0.336, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[26442] = { ["id"] = 26442, ["name"] = "Rock Lobster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26442 }, ["description"] = "If I could choose my last meal, it would definitely be fresh lobster tail. Something about that tasty crustacean is just irresistible! We recently started trapping lobsters here in Stormwind. Would you mind heading out and checking the traps for me? One more thing, watch out for the sharks. They can be vicious down there.", ["objectivesText"] = "Collect 6 Rock Lobsters from the cages below the docks in Stormwind Harbor. Watch out for sharks! Progress: Looks like you were able to avoid the sharks. Were there any lobsters in the traps?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 58809, 67414 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26451] = { ["id"] = 26451, ["name"] = "Gurubashi Challenge: Free-For-All Arena Combat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 26451 }, ["description"] = "The arena is a place of battle unlike any other. Inside, you have no friends. Alliances that do form are fleeting, as your allies can turn on you in the blink of an eye. Horde vs. Alliance, Alliance vs. Alliance, Horde vs. Horde... anything goes. Take this battle standard, <race>, and place it down on the arena floor. Defeat the summoned combatant, then return to me. Stay on your toes, <race>. Anything goes inside the Gurubashi Arena.", ["objectivesText"] = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger. Progress: Why don't you get a little bit more blood on your armor before you speak with me again?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 58860 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 43099, ["x"] = 0.462, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 43099, ["x"] = 0.462, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "pvp" },
[26452] = { ["id"] = 26452, ["name"] = "Gurubashi Challenge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 26452 }, ["description"] = "You've returned, <race>. That means you've felt the call of the arena once more. Very well. Take this battle standard, <race>, and place it down on the arena floor. Defeat the summoned combatant, then return to me. Stay on your toes, <race>. Anything goes inside the Gurubashi Arena.", ["objectivesText"] = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger. Progress: Why don't you get a little bit more blood on your armor before you speak with me again?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 60387 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 43099, ["x"] = 0.462, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 43099, ["x"] = 0.462, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "pvp" },
[26488] = { ["id"] = 26488, ["name"] = "Big Gulp", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26488 }, ["description"] = "Arnold and I used to relax down at the moat in the Valley of Heroes. One day, I lost my locket in the lake and I have never been able to find it. Rumor has it that huge royal monkfish live in that moat and that they eat anything! I know it's a long shot, but do you think you could catch a few monkfish and look for my locket? Please let me know right away if you find it, it's very precious to me.", ["objectivesText"] = "Fish up a Royal Monkfish from the moat in the Valley of Heroes district of Stormwind. Once you catch a monkfish, fillet it and check if it swallowed the locket. Progress: Were you able to find my locket?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 6256, 6289, 6532, 44983, 57191, 58856, 58864, 58865, 67405, 67414 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26536] = { ["id"] = 26536, ["name"] = "Thunder Falls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26536 }, ["description"] = "Arnold and I have been fishing in and around Stormwind for years now. That's the kind of time it takes to find a good fishing spot. One of my favorites is called Thunder Falls. It's just south of Stormwind in Elwynn Forest. Best part about Thunder Falls is the violet perch . I have never seen them anywhere else, only up there at the falls. It's a bit of hike for me and Arnold to get out there these days though, do you think you could head up there and fetch some of those perch for us?", ["objectivesText"] = "Catch 4 Violet Perch from Thunder Falls, south of Stormwind. Return to Catherine Leland with your catch once you are done. Progress: Were you able to find the falls?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 58899, 67414 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5494, ["x"] = 0.4365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[26543] = { ["id"] = 26543, ["name"] = "Clammy Hands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26543 }, ["description"] = "Nothing tastes like fresh monstrous clam meat , <name>. I have been so busy with work these past few weeks that I have not been able to make it out to the local clam spawning grounds. Think you could run down there and gather some of those tasty treats for me? The clams can be found near the shoreline on the eastern coast of Durotar. Should be plenty right around the Orgrimmar docks.", ["objectivesText"] = "Collect 10 Monstrous Clam Meat from the clams near the eastern shoreline, just south of Orgrimmar. Return to Razgar once you are done. Progress: Were you able to find the clams?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 58934, 67414 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.585667, ["y"] = 0.495667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26556] = { ["id"] = 26556, ["name"] = "No Dumping Allowed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26556 }, ["description"] = "Ever since those goblins took up refuge in Orgrimmar, they have been dumping all of their waste in our water supply. I have no idea what effect this is having on our local fishing supply, but I don't think it's good. I have heard reports of a new mutated fish species spawning in that toxic pool near their camp. A few specimens would really help me figure out what exactly is going on. Can you help me out?", ["objectivesText"] = "Fish up 6 Toxic Puddlefish and return them to Razgar in the Valley of Honor once you are done. Progress: Were you able to fish up a few specimens?", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 6529, 30632, 58945, 67414 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.585667, ["y"] = 0.495667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26557] = { ["id"] = 26557, ["name"] = "A Staggering Effort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26557 }, ["description"] = "I've fished sandy carp in Orgrimmar's local waters for years now. Recently, I have noticed my bait is not working as well as it used to. I suspect it has something to do with all the tauren that moved into the Valley of Wisdom. I spoke with one of their local fisherman and it just turns out their appetite has changed. They are biting on stag eyes these days. You should be able to find plenty of stags north of Orgrimmar, just outside the northern gate.", ["objectivesText"] = "Slaughter a Stag north of Orgrimmar and use its eye as bait to catch a Sandy Carp in the Valley of Wisdom. Return to Razgar in the Valley of Honor once you are done. Progress: Did the eye work as bait?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 33820, 58946, 58949, 67414 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.585667, ["y"] = 0.495667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26566] = { ["id"] = 26566, ["name"] = "A Triumph of Gnomish Ingenuity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 31135, 31137, 41217, 41218 }, ["description"] = "We will need all the weapons, inventions, and soldiers we can get in order to defeat Razlo Crushcog and his followers. Over to the northeast, you'll find Engineer Grindspark , one of a new generation of brilliant gnomish minds. Why, he hasn't had an explosion in over three prototypes! But enough bragging. Engineer Grindspark is working on a bot that he says will help clean up the toxic airfield. You should introduce yourself to him and see if he needs any help testing it.", ["objectivesText"] = "Speak with Engineer Grindspark in New Tinkertown .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42553, ["x"] = 0.342, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 21, ["flags"] = 0 } } },
[26572] = { ["id"] = 26572, ["name"] = "A Golden Opportunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26572 }, ["description"] = "You heard of the golden stonefish , <name>? The thing with these fish is that they can't be caught by normal means. They have jaws so strong that they snap right through any hooks or lures you try to use on 'em. You can find a number of them in Thunder Ridge, south of Orgrimmar. That ridge used to be full of thunder lizards, but they all drowned in the flood. Take my knife, swim down there and cut off their tails. You should be able to use the tail to zap any stonefish you find.", ["objectivesText"] = "Use Razgar's Fillet Knife to cut off a Drowned Thunder lizard Tail in Thunder Ridge, south of Orgrimmar. Once you have the tail, use it near a Golden Stonefish to kill it. Return to Razgar in the Valley of Honor once you are done. Progress: How did it go down there? Any luck with the tails and the stonefish?", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 19979, 58955, 58958, 58960, 67414 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.585667, ["y"] = 0.495667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26588] = { ["id"] = 26588, ["name"] = "A Furious Catch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26588 }, ["description"] = "Are you up for a challenge, <name>? Good, I was hoping you would be. The Southfury River flows just west of Orgrimmar and your challenge can be found within its mighty flow. We are looking for a giant furious pike . This esteemed fish used to be prevalent in these areas but ever since the floods hit, the big ones have been much harder to find. Head out to the river and let's see just how good of an angler you really are.", ["objectivesText"] = "Catch a Giant Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar's western gate. Return to Razgar in the Valley of Honor once you are done. Progress: Were you able to catch a giant pike?", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 58951, 67414 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 43239, ["x"] = 0.585667, ["y"] = 0.495667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.585667, ["y"] = 0.495667 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26596] = { ["id"] = 26596, ["name"] = "The Call of Kalimdor", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 26596 }, ["series"] = { 26702, 27210, 27211, 28552 }, ["description"] = "I've been sent by the good people of Theramore to find loyal members of the Alliance who are willing to help Lady Jaina with some problems in Dustwallow. You weren't really here working for the goblins, were you? The path back to Dustwallow will take you through Ratchet. Wait on the end of this pier for the next boat. Once you get to Ratchet, speak with Gazlowe . He'll point you in the right direction from there. Ugh, I think I stepped on a fish! And it flopped!", ["objectivesText"] = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 48808, ["x"] = 0.405, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3391, ["x"] = 0.509, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 10, 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[26598] = { ["id"] = 26598, ["name"] = "The Heart of Mokk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 26598 }, ["objectivesText"] = "Progress: Witch Doctor Unbagwa know what Mokk the Savage like. Yes, yes! Me speak with spirits and make he come, I do. But other gorilla-beast like spirit talkin' too. You protect Witch Doctor Unbagwa and I make he come to you. Witch Doctor Unbagwa want something first. You bring a Gorilla Fang and me start spirit talking!", ["rewardItems"] = { 2799, 4097 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 1449, ["x"] = 0.54, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 1449, ["x"] = 0.54, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[26696] = { ["id"] = 26696, ["name"] = "The Call of Kalimdor", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 26696 }, ["series"] = { 26682, 26701, 28554 }, ["description"] = "Say, you haven't seen a fish about this long? Short fins? Responds to the name Steve? He's blue? Never mind, I'll keep looking. Actually... there was another reason I came here to Booty Bay. Boss Krog, over in Dustwallow, is looking for new blood. Someone to help us Stonemaul from getting overrun. You look strong enough. Wait on the edge of the pier for the next ship, then ride to Ratchet. Gazlowe should be able to help you from there. Steve? Steve!", ["objectivesText"] = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 48797, ["x"] = 0.393, ["y"] = 0.690333 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3391, ["x"] = 0.509, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.393, ["y"] = 0.690333 }, ["mapCandidates"] = { ["npc"] = { 10, 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[26709] = { ["id"] = 26709, ["name"] = "The Stone Throne", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26709 }, ["description"] = "I am returning to my throne. I've no desire to see any more of these Earthen Ring, but you remain welcome here, <race>. If you wish to help us rebuild our realm, perhaps we can help you in return. All things in time.", ["objectivesText"] = "Seek out Therazane at Therazane 's Throne.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43792, ["x"] = 0.496, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[26711] = { ["id"] = 26711, ["name"] = "Off to the Bank", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14110 }, ["description"] = "Yo, baby. Wassup? You ready for the party? No?! You know I love you, so I don't know how to say this, but check it... I think you need to swing into town to buy a new outfit for the party. Don't look at me like that... you want to look gooood, right? Don't you want to look super fine for me? I am your contractually-obligated boyfriend after all! Swing by the bank first and pull out plenty of macaroons. You don't want to buy any of that cheap stuff!", ["objectivesText"] = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan .", ["rewardXP"] = 50, ["rewardItems"] = { 47044 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 35054, ["x"] = 0.4948, ["y"] = 0.6388 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 35120, ["x"] = 0.298667, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.6388 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 7, ["flags"] = 0 } } },
[26712] = { ["id"] = 26712, ["name"] = "Off to the Bank", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14109 }, ["description"] = "Hi, babe. Are you ready for the party? No?! You know I love you, right? I think you need to swing into town and buy a new outfit for the party. Don't look at me like that... you want to look your best? Don't you want to look good for me? I am your contractually-obligated girlfriend after all! Make sure you swing by the bank first and pull out plenty of macaroons. Don't buy any of that cheap stuff!", ["objectivesText"] = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan .", ["rewardXP"] = 50, ["rewardItems"] = { 47044 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 35053, ["x"] = 0.4948, ["y"] = 0.6404 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 35120, ["x"] = 0.298667, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.6404 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 8, ["flags"] = 0 } } },
[26783] = { ["id"] = 26783, ["name"] = "The Mosh'Ogg Bounty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 26783 }, ["description"] = "There's been some activity up north, at the rebel camp. I just heard from a soldier named Nimetz that a <race> <class> up there found the key to what's been driving them so crazy. That wasn't you, was it? Anyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast. I've heard that the ogres are guarding a chest up in some ruins behind their mound. I suspect it may be related. Care to fetch it for me?", ["objectivesText"] = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound. Progress: Why is it that the OGRES always find the priceless artifacts?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 58205, 58490 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 44018, ["x"] = 0.589, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 44018, ["x"] = 0.589, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.589, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[26799] = { ["id"] = 26799, ["name"] = "Those That Couldn't Be Saved", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "The val'kyr raise hundreds of corpses every day. Agatha raised you just a few moments ago. Not all are as lucky as you, however. Some maintain their free will, but live in constant fear and confusion. They usually run off into the woods, cowering at their own reflections. Others lose their minds completely, shambling about aimlessly. They often turn to violence, and must be destroyed. This is your task, <name>. Destroy them, our former brothers and sisters though they might be.", ["objectivesText"] = "Kill 6 Mindless Zombies . Progress: You will not go far in this new life if you are unable to kill even the weakest, most brainless creatures, <name>. Do not return until you have success to report.", ["rewardGold"] = 285, ["rewardXP"] = 250, ["rewardItems"] = { 3275, 11847 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1568, ["x"] = 0.3, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1568, ["x"] = 0.3, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 2, ["flags"] = 0 } } },
[26800] = { ["id"] = 26800, ["name"] = "Recruitment", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "We've been shipping in dead bodies from Silverpine, Hillsbrad... hell, anywhere we can get them from. We can't, however, afford to ignore the bodies which are sitting right on our front doorstep. The last vestiges of the Scarlet Crusade roam here in Tirisfal Glades. While we've managed to push them from Deathknell , several of their bodies litter the buildings to the north and the east. Go find them... and bring that Darnell fellow with you. He looks strong enough to carry a few corpses.", ["objectivesText"] = "Search Deathknell and the vicinity for 6 Scarlet Corpses , then point at them so Darnell can pick them up. Progress: Have you managed to scavenge up some corpses?", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 11848, 11849, 11850, 237812 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1740, ["x"] = 0.316, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1740, ["x"] = 0.316, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 6, ["flags"] = 0 } } },
[26801] = { ["id"] = 26801, ["name"] = "Scourge on our Perimeter", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26802, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "If you're going to be an asset to the Forsaken, you need to learn how to fight. And there's no better target than the Scourge minions that continue to pester us. The wretched ghouls and Rattlecage skeletons that roam the north and to the east are former troopers of the fallen Scourge. They should prove to be an even match for a fledgling <class> like you. Do not tarry - when you are done, speak to me again.", ["objectivesText"] = "Kill 8 undead outside of Deathknell . You may kill either Wretched Ghouls or Rattlecage Skeletons . Progress: Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village. Let's hope you will fare better than them, yes?", ["rewardGold"] = 2000, ["rewardXP"] = 250, ["rewardItems"] = { 3274, 11851, 11852, 131923 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1569, ["x"] = 0.308, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1569, ["x"] = 0.308, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 8, ["flags"] = 0 } } },
[26802] = { ["id"] = 26802, ["name"] = "The Damned", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 28608, 28651, 28652, 28653, 28672 }, ["description"] = "First of all, look at your armor. You're a mess, <class>. If you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. If you can gather some paws and wings from the wolves and bats nearby, maybe I'll find some armor for you. You'll find the creatures to the north and to the west of here.", ["objectivesText"] = "Obtain 4 Scavenger Paws and 4 Duskbat Wings . Progress: Do try your best to keep yourself unharmed until I get you some armor.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 2173, 3264, 3265, 6060, 37957, 37999, 38042, 38103, 131605, 237812 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1570, ["x"] = 0.328, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1570, ["x"] = 0.328, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 12, ["flags"] = 0 } } },
[26803] = { ["id"] = 26803, ["name"] = "Missing Reports", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26803 }, ["series"] = { 26804, 26806, 26807 }, ["description"] = "Saurfang is wise, and his intentions are good. In time, he will grow to see your people as a valuable ally. I am awaiting reports about recent Alliance activity in Durotar, but they haven't arrived yet. Would you be willing to visit Razor Hill and ask him for the reports in person? The easiest way to get there is by wind rider. Doras , Orgrimmar 's wind rider master will let you use one of his wind riders for a small fee. Look for him on the rise north of the Valley of Strength.", ["objectivesText"] = "Talk to Orgrimmar 's wind rider master, Doras .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3144, ["x"] = 0.49, ["y"] = 0.721333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3310, ["x"] = 0.512, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.721333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26804] = { ["id"] = 26804, ["name"] = "Flight to Razor Hill", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 26804 }, ["series"] = { 26803, 26806, 26807 }, ["description"] = "When you're ready to take the wind rider down to Razor Hill, simply speak with me again. When you get there, waste no time in finding Gar'Thok . He's the one responsible for preparing reports on recent Alliance activity in Durotar.", ["objectivesText"] = "Speak to Doras to purchase a wind rider ride to Razor Hill. Once you arrive, speak with Gar'Thok .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3310, ["x"] = 0.512, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[26806] = { ["id"] = 26806, ["name"] = "Reports to Orgrimmar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 26806 }, ["series"] = { 26803, 26804, 26807 }, ["description"] = "Eitrigg will have to be happy with the part of the report that I've finished. Tell him to expect more in the future. < Gar'Thok hands you a stack of roughly folded papers.> This should cover the most important details of the increase in Alliance forces working out of Northwatch. Please apologize to Eitrigg for me and let him know that we've had our hands full here, trying to keep Razor Hill secure and supplied. When you're ready to return to Orgrimmar , simply speak to Burok and hire a wind rider.", ["objectivesText"] = "Take Gar'Thok's Reports to Burok at Razor Hill. Progress: Are you ready to return to Orgrimmar ?", ["rewardXP"] = 25, ["rewardItems"] = { 60370 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3139, ["x"] = 0.519, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 41140, ["x"] = 0.53, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.519, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[26807] = { ["id"] = 26807, ["name"] = "Return to Eitrigg", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 26807 }, ["series"] = { 26803, 26804, 26806 }, ["description"] = "Since you've already spoken to Doras, you'll be able to hire a wind rider to take you right back to Orgrimmar . Each time you arrive in a new town, be sure to speak with the town's flight master. After that, you'll be able to use the flight master's services to travel quickly. Speak to me again when you're ready to purchase a return flight to Orgrimmar . Bring those reports to Eitrigg in the Valley of Strength once you've landed.", ["objectivesText"] = "Speak with Burok and purchase a flight back to Orgrimmar . Once in Orgrimmar , bring Gar'Thok's Reports to Eitrigg in the Valley of Strength. Progress: Did you bring those reports?", ["rewardGold"] = 232300, ["rewardXP"] = 150, ["rewardItems"] = { 60370 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 41140, ["x"] = 0.53, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3144, ["x"] = 0.49, ["y"] = 0.721333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[26870] = { ["id"] = 26870, ["name"] = "Cleansing the Caverns", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 718, ["storyline"] = { 26870 }, ["description"] = "Naralex had a noble goal. Our great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong. Naralex's trusted allies, the Druids of the Fang, turned on him! They seek not to heal the Barrens, but to dominate it. <name>, before we can awaken Naralex and restore balance to this vital place, you need to eradicate the Fanglords. Their influence has sunk too deeply.", ["objectivesText"] = "Ebru in the Wailing Caverns wants you to kill the Fanglords Cobrahn, Anacondra, Pythas, and Serpentis. Progress: Are the Fanglords dead? Muyoh cannot awaken Naralex until they are!", ["rewardGold"] = 48350, ["rewardXP"] = 1145, ["rewardItems"] = { 65911, 65937, 65961, 65985, 66003, 131615, 131616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 718 } }, ["questType"] = "dungeon" },
[26872] = { ["id"] = 26872, ["name"] = "Deviate Hides", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 718, ["storyline"] = { 26872 }, ["description"] = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns . These deviate creatures have strange, otherworldly properties. Their very existence causes great pain to the earth. I believe that slaying them will greatly aid our work in healing the caverns. If you feel up to the task, slay as many as you can and bring me their hides as proof of their demise.", ["objectivesText"] = "Nalpak wants 10 Deviate Hides . Progress: How many of the beasts have you slain?", ["rewardGold"] = 280900, ["rewardXP"] = 1145, ["rewardItems"] = { 6443, 9603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 718 } }, ["questType"] = "dungeon" },
[26873] = { ["id"] = 26873, ["name"] = "Preemptive Methods", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 718, ["storyline"] = { 26873 }, ["description"] = "There is an herb in these caverns that holds untold power, <name>. Perhaps you wish to help me collect it? It is a rare flower called Serpentbloom . I believe that in greater quantities it has the potential to prevent nightmares like Naralex's from ever occuring. Unfortunately, Serpentbloom can only be found in the darkest recesses of this place.", ["objectivesText"] = "Nalpak wants you to collect 5 Serpentbloom . Progress: I am eager to see if you can gather enough Serpentbloom .", ["rewardGold"] = 280900, ["rewardXP"] = 1145, ["rewardItems"] = { 5339 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 718 } }, ["questType"] = "dungeon" },
[26897] = { ["id"] = 26897, ["name"] = "Blackfathom Deeps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 26897 }, ["description"] = "Although our position is exposed, we are safe compared to our friends inside Blackfathom Deeps ! They stand mere feet away from the most deadly Twilight's Hammer forces in the area. Speak with Sentinel Aluwyn and give them the aid they desperately need!", ["objectivesText"] = "Speak with Sentinel Aluwyn .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 3845, ["x"] = 0.182, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.182, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "dungeon" },
[26901] = { ["id"] = 26901, ["name"] = "Going, Going, Guano!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 491, ["storyline"] = { 26901 }, ["description"] = "The bats native to Razorfen Kraul produce a very peculiar natural substance. Their guano's stench seems to send the Quilboar into a murderous frenzy - and this place reeks of it! I need you to find the bat cave, and bring me a suitable sample. If we can reverse the effects and produce an antidote, we may be able to save the Quilboar.", ["objectivesText"] = "Extract 1 pile of Kraul Guano . Progress: Ah, I see you have returned. Were you able to procure any Kraul Guano ?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 5801 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 491 } }, ["questType"] = "dungeon" },
[26904] = { ["id"] = 26904, ["name"] = "Corruption", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6176, ["storyline"] = { 26904 }, ["description"] = "Few people, especially among our allies, truly understand the nature of the power we wield. They shun us for pursuing knowledge that they are too weak to use properly. As you become more powerful, you will begin to discover new spells, further magnifying your power. Go, get more experience, then return once you've learned a new spell. We'll see if you have it in you to truly master the dark arts.", ["objectivesText"] = "Reach level 3 to learn Corruption , then cast it 5 times on a Training Dummy near the entrance to Anvilmar.", ["rewardGold"] = 25, ["rewardXP"] = 125, ["rewardItems"] = { 961, 5392, 5393, 5398, 5399, 5586, 10544, 11190, 15103, 25913, 25914, 25915, 52595, 52621, 52633, 53363, 56679, 56680, 56681, 56682, 65822, 65823, 65824 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6176 } }, ["questType"] = "standard" },
[26905] = { ["id"] = 26905, ["name"] = "Agamaggan's Charge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 491, ["storyline"] = { 26905 }, ["series"] = { 26906 }, ["description"] = "Listen closely, mortal. The Quilboar are my children. My blood runs deep in these lands. Charlga Razorflank has steered my children into darkness, driven into insanity by the Scourge. Slay her, <name>. Slay her and open my childrens' eyes. Give the Quilboar the chance to return to their noble roots. Let them once more earn my blessing. Bring me her heart!!!", ["objectivesText"] = "Take Charlga Razorflank's heart . Progress: <The Spirit of Agamaggan stares at you patiently.>", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 5793, 65918, 65944, 65968, 65991, 66007, 131617 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 491 } }, ["questType"] = "dungeon" },
[26906] = { ["id"] = 26906, ["name"] = "Agamaggan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 491, ["storyline"] = { 26906 }, ["series"] = { 26905 }, ["description"] = "I sense a being of immense power within these twisted thorns, <name>. The entire area has come alive at its presence. It must be the Spirit of Agamaggan ! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently. All the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients. If there's any being that could steer the Quilboar towards their noble roots, it would be him. You must seek him out.", ["objectivesText"] = "Talk to the Spirit of Agamaggan .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 65918, 65944, 65968, 65991, 66007, 131617 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 491 } }, ["questType"] = "dungeon" },
[26907] = { ["id"] = 26907, ["name"] = "Take Them Down!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 491, ["storyline"] = { 26907 }, ["description"] = "In order to maintain the relative safety in the Southern Barrens, we must put a stop to the current leadership of the Razorfen tribe. Although Charlga Razorflank commands her people through powerful mysticism, her true power is in the strength of the elders around her. Slay them. Hunt down Bonetusk, the pack leader. Stop Roogug , the overseer of Geomancers. Crush Ramtusk, the quilboar Warlord. Return to me when the deed is done.", ["objectivesText"] = "Kill Hunter Bonetusk , Roogug , and Warlord Ramtusk .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 491 } }, ["questType"] = "dungeon" },
[26908] = { ["id"] = 26908, ["name"] = "Feeling Thorny", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4709, ["mapID"] = 199, ["storyline"] = { 26908 }, ["description"] = "Mankrik's furor over his dead wife raises further concerns, <class>. The quilboar in Razorfen Kraul are far more ruthless and full of hatred than Mankrik could ever imagine. You should travel south there and speak with my old friend Auld Stonespire . He works to put an end to their rampage before the land suffers more in its already weak condition.", ["objectivesText"] = "Speak to Auld Stonespire .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 199, ["npcID"] = 37812, ["x"] = 0.45, ["y"] = 0.854 } }, ["coords"] = { ["mapID"] = 199, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.854 }, ["mapCandidates"] = { ["npc"] = { 199 }, ["zone"] = { 4709 } }, ["questType"] = "dungeon" },
[26914] = { ["id"] = 26914, ["name"] = "Corruption", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["requiredRaces"] = { 1 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["storyline"] = { 26914 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31140, 31141, 31142, 31143 }, ["description"] = "We must take care in how we speak around the abbey and its environs, but don't let that deter you from the path of power. As you become more powerful, you will begin to hear the fel voices, granting you their power in the dark arts. Go, get more experience and learn a new spell. Once you have, practice it on the training dummies.", ["objectivesText"] = "Reach level 3 to learn the Corruption ability, then practice casting Corruption 5 times on a Training Dummy south of the entrance to Northshire Abbey. Progress: Well, did you give it a try?", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 961, 5392, 5393, 5398, 5399, 5586, 10544, 11190, 15103, 25913, 25914, 25915, 52595, 52621, 52633, 53363, 56679, 56680, 56681, 56682, 65822, 65823, 65824 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard" },
[26919] = { ["id"] = 26919, ["name"] = "Learning the Word", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["storyline"] = { 26919 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31140, 31141, 31142, 31143 }, ["description"] = "One of your responsibilities as a priest is caring for the wounded. Another is to go out into the world and be more... proactive about defending them. As you do so, you'll grow in power and learn all sorts of new things. Why don't you go out, get more experience, and then return to demonstrate what you've learned?", ["objectivesText"] = "Reach level 3 to learn Shadow Word: Pain , then use it 5 times on training dummies near Northshire Abbey. Progress: Well, what have you learned?", ["rewardGold"] = 50, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard" },
[26939] = { ["id"] = 26939, ["name"] = "The G-Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 721, ["storyline"] = { 26939 }, ["series"] = { 26941, 26942, 26943, 26944, 50337, 50338 }, ["description"] = "How did you get in here? Oh, it doesn't matter. I'm Murd Doc of the G-Team. We're the best there is, and we're here to retake Gnomeregan ! When nobody else could help him, the High Tinker found and hired us. But we simply can't do this alone! You're an honorary G-Team Commando now, <name>. Take this parachute, jump down straight ahead into the Hall of Gears, and kill the Viscous Fallout . After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", ["objectivesText"] = "Kill the Viscous Fallout . Progress: What're you doing out in the open like that, fool? Get down!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 60680, 65913, 65939, 65963, 65987, 66004, 131624, 131625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 721 } }, ["questType"] = "dungeon" },
[26941] = { ["id"] = 26941, ["name"] = "The G-Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 721, ["storyline"] = { 26941 }, ["series"] = { 26939, 26942, 26943, 26944, 50337, 50338 }, ["description"] = "That Murd Doc is crazy, <class>. Never, ever, let you find yourself in an aircraft with that gnome. Stealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000 . The Electrocutioner is in charge of the aircraft... ...and I hate aircraft. I'm not getting in any sort of aircraft! Use this parachute to drop down afterwards and speak with Commando Face for your next job.", ["objectivesText"] = "Kill the Electrocutioner 6000 . Progress: Woah! How did you see me!?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 60680, 65913, 65939, 65963, 65987, 66004, 131624, 131625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 721 } }, ["questType"] = "dungeon" },
[26942] = { ["id"] = 26942, ["name"] = "The G-Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 721, ["storyline"] = { 26942 }, ["series"] = { 26939, 26941, 26943, 26944, 50337, 50338 }, ["description"] = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable. You are, though, so let's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg . Our leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work. Probably.", ["objectivesText"] = "Kill Mekgineer Thermaplugg .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 65913, 65939, 65963, 65987, 66004, 131624, 131625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 721 } }, ["questType"] = "dungeon" },
[26943] = { ["id"] = 26943, ["name"] = "Home Sweet Gnome", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 26943 }, ["series"] = { 26939, 26941, 26942, 26944, 50337, 50338 }, ["description"] = "I used t' have quite the home back in Ironforge. That is, I did until I was booted out to make way for the gnomes. They couldn't stop a bunch of troggs with all them gizmos and machines! An' I have to pay for their weakness? No, sir. No longer. Go to Gnomeregan and talk to Commando Murd Doc . Sure, he's a gnome, but his crew, S.A.F.E. I think they call 'em, are going to take Gnomeregan back. Go! I want my house back!", ["objectivesText"] = "Speak to Murd Doc .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 86570 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 2789, ["x"] = 0.402, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "dungeon" },
[26944] = { ["id"] = 26944, ["name"] = "Exploring Gnomeregan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 26944 }, ["series"] = { 26939, 26941, 26942, 26943, 50337, 50338 }, ["description"] = "The gnomish capital, Gnomeregan , hasn't been under their control for some time now. I know what it feels like to lose a home. Please, venture inside Gnomeregan and speak to Commando Murd Doc , a member of S.A.F.E. If there's anything at all that you can do to help them take their home, I urge you to do so. There are dark secrets in those halls.", ["objectivesText"] = "Speak to Murd Doc .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 86570 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 44018, ["x"] = 0.589, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.589, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "dungeon" },
[26952] = { ["id"] = 26952, ["name"] = "The Menders' Stead", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 26952 }, ["series"] = { 26935, 26999, 27000, 27001, 27002, 27175, 27233 }, ["description"] = "I don't like the looks of what the Forsaken are doing here at the Bulwark. Bombs, cauldrons, needless bloodshed... none of these embody that which the Argent Crusade stands for. Furthermore, I don't like the fact that they employ mercenaries like yourself. Nothing against you personally, <class>. It's just that you could be doing so much more for yourself. If you're interested in healing the plaguelands, rather than re-plaguing them, then report to Field Agent Kaartish at the Menders' Stead to the east.", ["objectivesText"] = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 10839, ["x"] = 0.832, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 44454, ["x"] = 0.492, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.832, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 18, 22 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[26970] = { ["id"] = 26970, ["name"] = "Learning the Word", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6456, ["storyline"] = { 26970 }, ["series"] = { 9291 }, ["description"] = "As a priest, one of your most important duties is to use the Light's power to aid the wounded. Another is to use your power offensively, to protect them. As you grow more experienced, you will begin to uncover new abilities that you can use in your charge. Go, gain more experience, and then demonstrate the abilities you have learned to me.", ["objectivesText"] = "Reach level 3 to learn Shadow Word: Pain , then use it 5 times on target dummies near the crash site. Progress: Have you seen to the wounds of the crash survivors?", ["rewardGold"] = 50, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6456 } }, ["questType"] = "standard" },
[27004] = { ["id"] = 27004, ["name"] = "The Twilight Plot", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27004 }, ["series"] = { 27003, 27005, 27040, 27041, 27058, 27059, 27952, 27953, 28292, 28293, 28295, 28296, 28557, 28558 }, ["description"] = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest. One of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, <name>. Keep searching the cultists until you find them.", ["objectivesText"] = "Collect the Masters' Gate Plans . Progress: Those plans are the key to everything.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60745 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44799, ["x"] = 0.474, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44799, ["x"] = 0.474, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27005] = { ["id"] = 27005, ["name"] = "The Twilight Plot", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27005 }, ["series"] = { 27003, 27004, 27040, 27041, 27058, 27059, 27952, 27953, 28292, 28293, 28295, 28296, 28557, 28558 }, ["description"] = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest. One of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, <name>. Kill cultists at the Masters' Gate until you find them.", ["objectivesText"] = "Collect the Masters' Gate Plans . Progress: Those plans are the key to everything.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60745 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44823, ["x"] = 0.512, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44823, ["x"] = 0.512, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27006] = { ["id"] = 27006, ["name"] = "Fly Over", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27006 }, ["series"] = { 27042 }, ["description"] = "I tried ta fly o'er the terrace an have a look fer myself, but those toastie eatin' pansies kept shootin' at me, an I couldn't get near. Ya look like ya might be handy with the reins. Why don' ya take yer flyin' beastie up there ta the southwest and see what all the fuss is about?", ["objectivesText"] = "Investigate the central area in the back of the Masters' Gate. Progress: What'd ya see? What are those cheese lovers up ta?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44802, ["x"] = 0.474, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44802, ["x"] = 0.474, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27008] = { ["id"] = 27008, ["name"] = "Fly Over", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27008 }, ["series"] = { 27043 }, ["description"] = "I'm quite adept at riding my flying carpet. Unfortunately, when I tried to investigate what the cultists had uncovered up at the Masters' Gate, they nearly shot me down. You look as if you might be skilled with the flying reins as well. Would you mind flying up there to the southwest to see what they've unearthed?", ["objectivesText"] = "Investigate the central area in the back of the Masters' Gate.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44818, ["x"] = 0.512, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44818, ["x"] = 0.512, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27040] = { ["id"] = 27040, ["name"] = "Decryption Made Easy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27040 }, ["series"] = { 27003, 27004, 27005, 27041, 27058, 27059, 27952, 27953, 28292, 28293, 28295, 28296, 28557, 28558 }, ["description"] = "We don't have the tools to decipher these encrypted plans . The Twilight's Hammer do, though. Would you be a sweetie and take the plans back up there to run them through their one-time decryption engines ?", ["objectivesText"] = "Decrypt 6 plans.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60758 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44799, ["x"] = 0.474, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27041] = { ["id"] = 27041, ["name"] = "Decryption Made Easy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27041 }, ["series"] = { 27003, 27004, 27005, 27040, 27058, 27059, 27952, 27953, 28292, 28293, 28295, 28296, 28557, 28558 }, ["description"] = "We don't have the tools to decipher these encrypted plans . The Twilight's Hammer do, though. Would you take the plans back up there and run them through their one-time decryption engines ?", ["objectivesText"] = "Decrypt 6 plans.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60758 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44823, ["x"] = 0.512, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27042] = { ["id"] = 27042, ["name"] = "Fight Fire and Water and Air with...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27042 }, ["series"] = { 27006 }, ["description"] = "Did ye hear the blatherin' idiot while ye were up there? That's none other than Haethen Kaul , their leader. The man's gone daft with power. He's pullin' it straight from them bound elementals, makin' him nigh invincible. The only thing I can think of to get ye into proper shape fer a fight with him is fer ye to first kill all o' them elementals, gettin' their wards. That should protect ye from Haethen's spells. Well, most o' them anyway.", ["objectivesText"] = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 5462, 61442, 61443, 61444, 61445, 61446, 61447 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44802, ["x"] = 0.474, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44802, ["x"] = 0.474, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27043] = { ["id"] = 27043, ["name"] = "Fight Fire and Water and Air with...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27043 }, ["series"] = { 27008 }, ["description"] = "Did you hear the man going on with his incessant yelling while you were up there? That's Haethen Kaul , their leader. It's a well known fact that he's gone insane from the power he's drawing from their bound elementals. Unfortunately, it makes him nigh invincible. If you're to fight him, you'll first have to kill each of the elementals, gaining their wards in the process. That should protect you from Haethen's magic. Well, most of it anyway.", ["objectivesText"] = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 5462, 30632, 61442, 61443, 61444, 61445, 61446, 61447 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44818, ["x"] = 0.512, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44818, ["x"] = 0.512, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27046] = { ["id"] = 27046, ["name"] = "Fear of Boring", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27046 }, ["description"] = "The gyreworms infest the rock, eating away at it until our home will one day collapse. For every one that is killed, twice as many burst forth to follow, but we must carry on the fight. They must be extinguished. Go to the Crumbling Depths and slaughter any worms that you can find.", ["objectivesText"] = "Kill 10 gyreworms . Progress: Your flesh is well suited for the task. It does not corrode from their attacks as our rockskin does.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27049] = { ["id"] = 27049, ["name"] = "Soft Rock", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27049 }, ["description"] = "The corruption of the Crimson Expanse has not subsided. Destroy the Fungal Behemoths that shower their filth upon our realm. If they continue to rise, we will continue to destroy them.", ["objectivesText"] = "Kill 8 Fungal Behemoths .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43804, ["x"] = 0.58, ["y"] = 0.132 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43804, ["x"] = 0.58, ["y"] = 0.132 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.132 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27050] = { ["id"] = 27050, ["name"] = "Fungal Fury", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27050 }, ["description"] = "Something upon the Crimson Expanse continues to spur disgusting growths upon the rock. New fungi are rising, and they need to be crushed before they can spread.", ["objectivesText"] = "Destroy 10 of the newly sprouted mushrooms in the Crimson Expanse.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 18660, 30632 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43804, ["x"] = 0.58, ["y"] = 0.132 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43804, ["x"] = 0.58, ["y"] = 0.132 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.132 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27058] = { ["id"] = 27058, ["name"] = "The Wrong Sequence", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27058 }, ["series"] = { 27003, 27004, 27005, 27040, 27041, 27059, 27952, 27953, 28292, 28293, 28295, 28296, 28557, 28558 }, ["description"] = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do. Punch in the wrong activation sequence and destroy it. Hmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", ["objectivesText"] = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 61436, 61438, 61439, 61441 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44799, ["x"] = 0.474, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44799, ["x"] = 0.474, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27059] = { ["id"] = 27059, ["name"] = "The Wrong Sequence", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27059 }, ["series"] = { 27003, 27004, 27005, 27040, 27041, 27058, 27952, 27953, 28292, 28293, 28295, 28296, 28557, 28558 }, ["description"] = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do. Punch in the wrong activation sequence and destroy it. Hmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", ["objectivesText"] = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 61436, 61438, 61439, 61441 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44823, ["x"] = 0.512, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44823, ["x"] = 0.512, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27062] = { ["id"] = 27062, ["name"] = "Looming Threat", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 722, ["mapID"] = 64, ["storyline"] = { 27062 }, ["description"] = "The Quilboar in Razorfen Downs seem to have allied with the Scourge. This is dark news for us, <class>. We have dire enough problems dealing with these Grimtotem, we won't be able to handle an attack by the Scourge. Venture into Razorfen Downs , east of here, and see if you can find anyone that may be able to help you stop them before they decide to attack here.", ["objectivesText"] = "Find help in Razorfen Downs .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 39895, ["x"] = 0.513, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.513, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 722 } }, ["questType"] = "dungeon" },
[27063] = { ["id"] = 27063, ["name"] = "Looming Threat", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 722, ["mapID"] = 69, ["storyline"] = { 27063 }, ["description"] = "The Scourge are a direct affront to nature. They have managed to corrupt the Quilboar in Razorfen Downs and now threaten to spread further into Thousand Needles and eventually, I fear, west into Feralas. You must go there and do anything you can to confine them. Perhaps you can find someone in the area to help you? The winds whisper of a powerful presence in the area.", ["objectivesText"] = "Find help in Razorfen Downs .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 40032, ["x"] = 0.506, ["y"] = 0.17 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 722 } }, ["questType"] = "dungeon" },
[27066] = { ["id"] = 27066, ["name"] = "Learning the Word", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6452, ["storyline"] = { 27066 }, ["series"] = { 27014 }, ["description"] = "As you become more skilled, your skills will expand, and you will gain access to many new powers. Go - get some experience out there, and come back to me when you've learned something new. You can demonstrate on the training dummies nearby.", ["objectivesText"] = "Reach level 3 to learn Shadow Word: Pain . Practice using it 5 times on Training Dummies in Camp Narache.", ["rewardGold"] = 50, ["rewardXP"] = 125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6452 } }, ["questType"] = "standard" },
[27067] = { ["id"] = 27067, ["name"] = "Moonfire", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6452, ["storyline"] = { 27067 }, ["series"] = { 3094 }, ["description"] = "As you develop your skills, druid, you will begin to feel your connection to the Earthmother deepening. You will begin to understand new secrets of nature, and learn to cast new spells. Go now, get more experience, and return to me when you've learned a new spell. Demonstrate what you've learned.", ["objectivesText"] = "Reach level 3 to learn Moonfire . Practice using it on a Training Dummy in Camp Narache. Progress: Have you seen to the injured of the wounded?", ["rewardXP"] = 125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6452 } }, ["questType"] = "standard" },
[27068] = { ["id"] = 27068, ["name"] = "Chief Ukorz Sandscalp", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1176, ["storyline"] = { 27068 }, ["series"] = { 25021, 25025, 25026, 25032, 25556 }, ["description"] = "Take a good look, mon. Dis is how it goes, betrayal after betrayal. I backstab you for the sword, and den Chief Ukorz go and backstab me even better for it. That's life, yah! Or was... Now, I know you don't got no love for Mazoga. But I know you goin' in der anyway. Kill him for me, mon. Spill more blood on the sand, an' give Chief Ukorz Sandscalp what every one of de Sandfury deserves...a gory death. Maybe I leave some of my belongin's without a curse before passin' on if you do, yah?", ["objectivesText"] = "Kill Chief Ukorz Sandscalp .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 65930, 65955, 65979 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1176 } }, ["questType"] = "dungeon" },
[27070] = { ["id"] = 27070, ["name"] = "A Fool's Errand", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1176, ["storyline"] = { 27070 }, ["description"] = "I heard that a troll in here, Hydromancer Velratha I think she was called, has come into the possession of a very rare, beautiful, and powerful piece of jewelry called the Tiara of the Deep . She uses it to control the powerful demigod Gahz'rilla, whose very scales are said to crackle with energy. Do you know what all of that means, <race>? I need it! Kill Velratha, take the Tiara of the Deep , and kill Gahz'rilla for one of his scales. Bring them all back to me pronto! I'll reward you handsomely.", ["objectivesText"] = "Obtain the Tiara of the Deep and Gahzrilla's Electrified Scale. Progress: Do you have what I need?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 8707, 9234, 65929, 65954, 65978, 65999 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1176 } }, ["questType"] = "dungeon" },
[27071] = { ["id"] = 27071, ["name"] = "Wrath of the Sandfury", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1176, ["storyline"] = { 27071 }, ["description"] = "De Sandfury are a resilient tribe. Dey have survived sandstorms an' years an' years of other tings long covered by da sands. It would be foolish to assume that the only forces here are da trolls. We been tamin' da scarabs, breedin' da sul'lithuz, an' raisin' our dead to keep on fightin' for all eternity as zombies. Ruuzlu , da right hand of Chief Ukorz Sandscalp, be plannin' to use dem to retake Tanaris for de Sandfury empire. You best be killin' da trolls in charge of dis if you want to live, mon.", ["objectivesText"] = "Kill Theka the Martyr , Witch Doctor Zum'rah , Antu'sul , and Ruuzlu . Progress: If dey ain't dead yet, you can't guarantee your own life, <race>.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1176 } }, ["questType"] = "dungeon" },
[27076] = { ["id"] = 27076, ["name"] = "Breaking and Entering", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1176, ["storyline"] = { 27076 }, ["description"] = "A good buddy of mine, Weegli Blastfuse, joined up with Sergeant Bly and his group of outcasts to invade Zul'farrak and claim the legendary Sul'thraze as their prize. Of course, they underestimated the Sandfury tribe and now they're all trapped awaiting execution to please their demigod, Gahz'rilla! If you free him, he'll help you blast your way to Ukorz's private chamber where he keeps at least part of the blade. Kill his captors, Nekrum Gutchewer and Shadowpriest Sezz'ziz as revenge...I'll repay ya.", ["objectivesText"] = "Free Weegli Blastfuse and kill Nekrum Gutchewer and Shadowpriest Sezz'ziz . Progress: Are Nekrum and Sezz'ziz dead? If they are, I know Weegli will be here any minute now.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1176 } }, ["questType"] = "dungeon" },
[27100] = { ["id"] = 27100, ["name"] = "Twilight Research", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27100 }, ["series"] = { 27101, 27102 }, ["description"] = "The book you found appears to detail some form of research carried out by a member of the Twilight's Hammer. It deals with the oozes in some way, but there are multiple pages missing. Perhaps if you found additional notes you might be able to make sense of it.", ["objectivesText"] = "Obtain 4 Twilight Research Notes from Mercurial Oozes in the Upper Silvermarsh. Progress: <You scroll through the notes, trying to put them in order.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60814, 60816 }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43397, ["x"] = 0.495333, ["y"] = 0.523333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["startItems"] = { 60816 } },
[27101] = { ["id"] = 27101, ["name"] = "Maziel's Revelation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27101 }, ["series"] = { 27100, 27102 }, ["description"] = "The notes continue Maziel's rambling research into the properties of quicksilver and mercurial oozes. He appears to have made a major discovery. He mentions hiding his journal in the Lower Silvermarsh to the southwest.", ["objectivesText"] = "Find Maziel's Journal at the Lower Silvermarsh in Deepholm .", ["rewardXP"] = 3085, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43397, ["x"] = 0.495333, ["y"] = 0.523333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27102] = { ["id"] = 27102, ["name"] = "Maziel's Ascendancy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27102 }, ["series"] = { 27100, 27101 }, ["description"] = "Maziel's journal chronicles a ritual of ascendancy that would transfigure his body to one of pure quicksilver. The ritual would take place in the cave near the Lower Silvermarsh, where Maziel would feed upon the mercurial oozes until achieving full strength. Perhaps it is not too late to put an end to his madness.", ["objectivesText"] = "Slay Maziel inside the Silverlight Cave in Deepholm .", ["rewardXP"] = 5145, ["rewardItems"] = { 61481, 61482, 61483 }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43397, ["x"] = 0.495333, ["y"] = 0.523333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27103] = { ["id"] = 27103, ["name"] = "Shards of the Felvine", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27103 }, ["description"] = "The satyr Alzzin the Wildshaper has exerted his corrupt dominion over this part of Eldre'Thalas. The Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin. It may be the key to purify this ancient place. When the great satyr falls, capture whatever essence of the Felvine you can. Seal it in this Reliquary of Purity , and bring it to me. Good luck, and Cenarius' speed.", ["objectivesText"] = "Use the Reliquary of Purity to capture a Felvine Shard . Progress: With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch. Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.", ["rewardGold"] = 58650, ["rewardXP"] = 4180, ["rewardItems"] = { 18501, 18539, 18540 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27104] = { ["id"] = 27104, ["name"] = "Alzzin the Wildshaper", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27104 }, ["description"] = "The monster responsible for the ruin you see before you is called Alzzin the Wildshaper . To reach him, however, you will need to also slay Zevrim Thornhoof , the satyr who currently holds the still noble ancient Old Ironbark in his grasp. Once Ironbark is free, he will help you make an entrance into Alzzin's domain. Enter and slay him without mercy, for there is no other way.", ["objectivesText"] = "Kill Zevrim Thornhoof and Alzzin the Wildshaper . Progress: Time is running short, <race>. I trust you will not fail.", ["rewardGold"] = 309800, ["rewardXP"] = 4180, ["rewardItems"] = { 65922, 65948, 65972, 65993 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27105] = { ["id"] = 27105, ["name"] = "An Unwelcome Guest", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27105 }, ["description"] = "You will find that Dire Maul is filled with many nature and arcane elementals. Somehow, a water elemental has found its way into this area. Please gather its essence and take it to me. I am curious as to how one of their kind got here, and what sort of agenda it may have against the natural elements of Eldre'Thalas.", ["objectivesText"] = "Collect the Hydrospawn Essence . Progress: Do you carry the essence, or did the task prove too difficult?", ["rewardGold"] = 280900, ["rewardXP"] = 4180, ["rewardItems"] = { 2562, 18299 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27107] = { ["id"] = 27107, ["name"] = "Pusillin The Thief", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27107 }, ["description"] = "Me take quick nap earlier and stupid fast imp take book! Dagg'thol need book to follow orders and Master need book to conquer! Gah! You <race> help me get book from imp, and I give you shiny something. Go, imp right there to da left! KILL!!!", ["objectivesText"] = "Convince Pusillin to give up the Book of Incantations . Progress: <race> has book?", ["rewardGold"] = 105000, ["rewardXP"] = 4180, ["rewardItems"] = { 18249, 18261 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27108] = { ["id"] = 27108, ["name"] = "Lethtendris's Web", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27108 }, ["description"] = "Blood Elf Lethtendris has web to catch magic here. She use for herself, but Master want to use for good of whole world! You help get web from stupid elf and not only will Dagg'thol reward you, you see how Master use it way better!", ["objectivesText"] = "Obtain Lethtendris's Web. Progress: <name>, you have stupid elf's web?", ["rewardGold"] = 105000, ["rewardXP"] = 4180, ["rewardItems"] = { 18426 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27109] = { ["id"] = 27109, ["name"] = "The Warped Defender", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27109 }, ["description"] = "The Ironbark and Warpwood were once the mighty protectors of Eldre'Thalas. Look at how they have fallen! Ultimately, their fate lies at the hands of myself and my fellow Highborne. We were reckless with our power, <race>. But you, you can right the wrongs here! Venture forth and put Tendris Warpwood to rest. He was the mightiest and last defender of this area, and deserves spiritual release. Be wary, for if you do not dispose of the Ironbark Protectors prior to engaging Tendris, he will call them to assist.", ["objectivesText"] = "Kill Tendris Warpwood .", ["rewardGold"] = 280900, ["rewardXP"] = 4180, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27110] = { ["id"] = 27110, ["name"] = "The Madness Within", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27110 }, ["description"] = "This madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the five pylons to lower the force field. When this is done, destroy Immol'thar . With the Prince's power greatly reduced from the demon's demise, attack and end him as well. Lay the spirits of this city to rest, adventurer, and make the Prince pay for his wrongdoings.", ["objectivesText"] = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar . Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest. Progress: Be wary, adventurer. The Prince is... persuasive.", ["rewardGold"] = 105000, ["rewardXP"] = 4180, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27111] = { ["id"] = 27111, ["name"] = "The Treasure of the Shen'dralar", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27111 }, ["description"] = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.", ["objectivesText"] = "Return to the Athenaeum and find the Treasure of the Shen'dralar . Claim your reward!", ["rewardGold"] = 842700, ["rewardXP"] = 260, ["rewardItems"] = { 65924, 65949, 65973, 65994 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27112] = { ["id"] = 27112, ["name"] = "The Cursed Remains", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27112 }, ["description"] = "There are remaining beings here that pose a direct threat to us ever reclaiming this sacred city. Magister Kalendris and Illyana Ravenoak are both extremely dangerous and need to be disposed of as quickly as possible. Exercise caution, for with there being so few remaining feeding off of Immol'thar's energies, they are likely to be stronger than they first appear.", ["objectivesText"] = "Kill Magister Kalendris and Illyana Ravenoak.", ["rewardGold"] = 105000, ["rewardXP"] = 4180, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27113] = { ["id"] = 27113, ["name"] = "The Shen'dralar Ancient", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27113 }, ["description"] = "Some beings here have miraculously managed to remain free of the darkness that runs so rampant. On the second story of the Court of the Highborne rests a Shen'dralar Ancient . Seek it out, it may hold a wealth of wisdom, perhaps even the secret to freeing Eldre'Thalas.", ["objectivesText"] = "Speak to the Shen'dralar Ancient .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27114] = { ["id"] = 27114, ["name"] = "The Gordok Taste Test", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27114 }, ["rewardItems"] = { 18269, 18284 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27119] = { ["id"] = 27119, ["name"] = "The Gordok Ogre Suit", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27119 }, ["description"] = "If you're going to fight the king of the Gordok then you're going to need to get by Captain Kromcrush. Now, you can get by him by killing him, sure. You might actually want to leave him alive. How, you ask? I think I know! An ogre suit! I'll make you one if you bring me an Ogre Tannin from upstairs. I'm not going anywhere like this...", ["objectivesText"] = "Bring an Ogre Tannin to Knot Thimblejack . Progress: Just get me that Ogre Tannin , and I'll whip you up an ogre suit that will fool Captain Kromcrush into thinking you're one of his men.", ["rewardXP"] = 1570, ["rewardItems"] = { 18240, 18250, 18258 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27120] = { ["id"] = 27120, ["name"] = "The Gordok Ogre Suit", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27120 }, ["objectivesText"] = "Progress: Need another suit, do ya? Well, I'm not going anywhere soon it seems - bring me another Ogre Tannin , and I'll make you another ogre suit.", ["rewardXP"] = 1570, ["rewardItems"] = { 18240, 18250, 18258 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27123] = { ["id"] = 27123, ["name"] = "Deepholm, Realm of Earth", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5416, ["mapID"] = 276, ["storyline"] = { 27123 }, ["series"] = { 26245, 26246, 26247, 27203, 27722, 27727 }, ["description"] = "I knew you'd heed our call, <name>. When Deathwing was first defeated by the other dragon aspects, he retreated to Deepholm , the realm of earth. Deathwing's return to our world left a rift open between Azeroth and Deepholm . If we don't mend the breach, this land will be torn asunder. We're doing our best to contain the damage on this side of the rift. Aggra will take you through the rift so you can help repair the damage from the other side. Get on her wyvern when you're ready.", ["objectivesText"] = "Jump on Aggra's Wyvern and fly into the breach at the Maelstrom. Once you're on the other side, speak to Maruut Stonebinder .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 276, ["npcID"] = 45042, ["x"] = 0.33, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43065, ["x"] = 0.495, ["y"] = 0.529 } }, ["coords"] = { ["mapID"] = 276, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 207, 276 }, ["zone"] = { 5416 } }, ["questType"] = "standard" },
[27124] = { ["id"] = 27124, ["name"] = "Unfinished Gordok Business", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27124 }, ["description"] = "Now you da king, so maybe you get prized Gordok artifact back from Guard Mol'dar ! Da king before you never listened, just like all da other kings since da old timey Gordok king! Artifact is called da Gauntlet of Gordok Might. Old timey stories say only da one true king da Gordok can get it back. You find it and it will become mighty gauntlet you wear forever! Yar, I show you!", ["objectivesText"] = "Speak to Guard Mol'dar in Dire Maul .", ["rewardXP"] = 4180, ["rewardItems"] = { 18240, 18258, 18266, 18269, 18284, 18366, 18367, 18368, 18369 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27125] = { ["id"] = 27125, ["name"] = "King of the Gordok", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27125 }, ["description"] = "In Gordok society, their king is simply their strongest warrior. If anyone, ogre or otherwise, kills the current king, they are automatically hailed as the new one. The new king receives tribute from any living guards, Stomper Kreeg, and Captain Kromcrush. Find and kill King Gordok while killing as few of their other leaders as possible, and not only will your reward be great, you will be able to use your power as king to halt the Gordok invasion without conflict!", ["objectivesText"] = "Kill King Gordok . Progress: I have faith that you will be able to complete the task set out before you.", ["rewardGold"] = 280900, ["rewardXP"] = 4180, ["rewardItems"] = { 65927, 65952, 65976, 65997, 66018, 66027, 66036, 66043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27128] = { ["id"] = 27128, ["name"] = "King of the Gordok", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2557, ["storyline"] = { 27128 }, ["description"] = "You kill Gordok leader, you new ogre king. If you king, then ogre leaders like Kromcrush and Kreeg that survive pay you big tribute and you stop Gordok invasion. If you do that, then me very happy ogre and we take Dire Maul FOR DA HORDE!!! Go, little <race>! Kill ugly Gordok ogre king and maybe dis be new Stonemaul Hold! Yar!", ["objectivesText"] = "Kill King Gordok . Progress: You new Gordok king?", ["rewardGold"] = 280900, ["rewardXP"] = 4180, ["rewardItems"] = { 65927, 65952, 65976, 65997, 66018, 66027, 66036, 66043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2557 } }, ["questType"] = "dungeon" },
[27129] = { ["id"] = 27129, ["name"] = "Saving Warpwood", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 27129 }, ["description"] = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood , still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own. Taking Dire Maul would be a major step in reclaiming Feralas for our people. You can find Dire Maul to the southeast of here.", ["objectivesText"] = "Speak to Furgus Warpwood .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 40032, ["x"] = 0.506, ["y"] = 0.17 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "dungeon" },
[27130] = { ["id"] = 27130, ["name"] = "Saving Warpwood", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 27130 }, ["description"] = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood , still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own before they set their sights on Camp Mojache. Perhaps we can even enlist his aid afterward to ensure we maintain our presence in Feralas with enemies on so many sides.", ["objectivesText"] = "Speak to Furgus Warpwood .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 7875, ["x"] = 0.748, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "dungeon" },
[27131] = { ["id"] = 27131, ["name"] = "The Highborne", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 27131 }, ["description"] = "Estulan , a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of the Highborne, it is an effort I must support for the good of Feralas. May the wind carry your spirit there with great swiftness. You will find Dire Maul to the southeast.", ["objectivesText"] = "Speak to Estulan .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["rewardItems"] = { 67160, 67177, 67194, 87399, 130903 }, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 40032, ["x"] = 0.506, ["y"] = 0.17 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "dungeon" },
[27132] = { ["id"] = 27132, ["name"] = "The Highborne", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 27132 }, ["description"] = "Estulan , a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of his kind, it is an effort I must support for our own good. Please hurry, we need every foothold in Feralas that we can get. You will find Dire Maul to the west.", ["objectivesText"] = "Speak to Estulan .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["rewardItems"] = { 67160, 67177, 67194, 87399, 130903 }, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 7875, ["x"] = 0.748, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "dungeon" },
[27133] = { ["id"] = 27133, ["name"] = "Eyes in the Sky", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 27133 }, ["description"] = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul . I requested a druid of the talon to go there and scout it out. If he still lives, speak with him and he will act as your commander to stop the Gordok before they decide to attack. That's an order, <class>.", ["objectivesText"] = "Speak to the Druid of the Talon .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 3936, ["x"] = 0.46, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "dungeon" },
[27134] = { ["id"] = 27134, ["name"] = "Ogre in the Field", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 27134 }, ["description"] = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul . If we eradicate them and take Dire Maul for the Horde, we will possess a heavily fortified seat of power in this region with numerous artifacts to sweeten the deal. I sent in a small army of Stonemaul Ogres inside earlier - if any have survived, speak with them and finish the job. That's an order, <class>.", ["objectivesText"] = "Speak to the Stonemaul Ogre .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 39656, ["x"] = 0.518, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "dungeon" },
[27139] = { ["id"] = 27139, ["name"] = "Hobart Needs You", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4720, ["mapID"] = 174, ["storyline"] = { 27139 }, ["series"] = { 24671 }, ["description"] = "Heya, boss, Hobart Grapplehammer 's wants to speak with you. He says it's a matter of some urgency.", ["objectivesText"] = "Speak with Hobart Grapplehammer at the Town-In-A-Box on the Lost Isles .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 174, ["npcID"] = 36471, ["x"] = 0.4555, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 174, ["npcID"] = 38120, ["x"] = 0.502, ["y"] = 0.383 } }, ["coords"] = { ["mapID"] = 174, ["source"] = "quest_giver", ["x"] = 0.4555, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 174 }, ["zone"] = { 4720 } }, ["questType"] = "standard" },
[27185] = { ["id"] = 27185, ["name"] = "Cutting the Competition", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27185 }, ["description"] = "Look, I'm not about t' play games with ye. The Scarlet Crusade's Crimson Hammersmith was nothin' worth mentionin' before, but now that they're Balnazzar's Risen, the damned dreadlord has taught him t' make all sorts of powerful demonic weaponry. It's simple. Find their blacksmithing plans and kill the Risen Hammersmith when he comes for 'em, so that we can make sure their army doesn't get their hands on demon armaments. They're powerful enough as it is!", ["objectivesText"] = "Kill the Risen Hammersmith . Progress: Are we back on top of the arms race?", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 12827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27187] = { ["id"] = 27187, ["name"] = "Do the World a Favor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5034, ["storyline"] = { 27187 }, ["description"] = "Hyenas, on their best day, are a nuisance. These foul specimens have a particularly nasty disposition, are riddled with all manner of disease, and are simply a blight on the face of dogdom. Do the world a favor and rid the deserts of Uldum of this mangy menace.", ["objectivesText"] = "Kill 12 Mangy Hyenas .", ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[27192] = { ["id"] = 27192, ["name"] = "The Great Ezra Grimm", ["level"] = 46, ["requiredLevel"] = 42, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27192 }, ["description"] = "Men as far as Kul Tiras spoke of the legendary Ezra Grimm's premium tobacco . It was a delicacy enjoyed by every single person of importance that visited Stratholme . King Terenas, Uther the Lightbringer, Highlord Fordring...yes, they all enjoyed Grimm's specialty. Sadly, Ezra stayed in his shop when Stratholme was invaded, swearing on his life that the Scourge would never touch his tobacco. Venture forth and see if even one bit remains here...it is worth its weight in gold, I assure you.", ["objectivesText"] = "Recover a box of Ezra Grimm's Premium Tobacco . Progress: Did you find any?", ["rewardGold"] = 26700, ["rewardXP"] = 4300, ["rewardItems"] = { 13171, 13172 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27200] = { ["id"] = 27200, ["name"] = "Siren's Song", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 27200 }, ["description"] = "She's still out there... Ophelia, the Siren of the Highlands! Her terrible song will lure you to the depths. I've vowed to stay behind and avenge my fallen crewmates, <class>. If you want to join me, just say the word. We'll lash ourselves to the mast, we will. We'll shut our eyes. We'll stuff our ears with wax. And when her beautiful illusion drops... we'll strike. Are you in?", ["objectivesText"] = "Slay Ophelia, the Siren of the Highlands.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 63903, 63904, 63905 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 45171, ["x"] = 0.76, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 45171, ["x"] = 0.76, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[27203] = { ["id"] = 27203, ["name"] = "The Maelstrom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 27203 }, ["series"] = { 26245, 26246, 26247, 27123, 27722, 27727 }, ["description"] = "Thank the spirits you're here, <name>. We're not sure how much longer we can maintain the rift in the Maelstrom. Our most powerful members, led by Thrall , are barely preventing the tear. Last I heard, our only hope was to go through the breach and attempt to stabilize it from the other side. I will conjure a portal. Take it and report to Thrall as soon as you can.", ["objectivesText"] = "Go through the Portal to the Maelstrom and speak to Thrall .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 152668, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 }, { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 276, ["npcID"] = 45042, ["x"] = 0.33, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 276 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27208] = { ["id"] = 27208, ["name"] = "The Dreadlord Balnazzar", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27208 }, ["description"] = "With the fall of the Scarlet Crusade, their disguised demon leader, Balnazzar , released the possessed body of Grand Crusader Dathrohan and went on a rampage, killing every remaining crusader here. He then used his necromantic power to raise them all as vile undead slaves. Balnazzar refers to his new army as the Risen. We cannot let him grow this army - they are extremely powerful and, unlike Arthas' Scourge, Balnazzar will not hold his forces back. Kill him while we still have a chance, <class>.", ["objectivesText"] = "Kill Balnazzar . Progress: The Light commands you.", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 65928, 65953, 65977, 65998 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27223] = { ["id"] = 27223, ["name"] = "Retribution", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27223 }, ["description"] = "Where Market Row meets Festival Lane, you will encounter The Unforgiven . If you slay the entirety of Crusaders' Square, you will coax out Timmy the Cruel . Both of these former champions committed heinous acts against innocents here in the name of gaining unholy power. You must destroy both of them and rid Stratholme of their foul presence. Take caution, for they were powerful fighters in life, and their new dark powers will only have made them even more deadly.", ["objectivesText"] = "Kill The Unforgiven and Timmy the Cruel . Progress: Show them no mercy.", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 30922, 30940, 30958, 30961, 120978, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27225] = { ["id"] = 27225, ["name"] = "A Summons from Signilda Hardforge", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 89, ["storyline"] = { 27225 }, ["series"] = { 27337 }, ["description"] = "Signilda Hardforge has sent word that she wishes to honor you for your mastery of arms and your dedication to the Alliance. Make your way to Stormwind, and speak with her at the Training Hall to the south of Old Town. I do not know what she has planned, but it sounds like she has been impressed with your rapid progress.", ["objectivesText"] = "Speak to Signilda Hardforge at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4087, ["x"] = 0.530571, ["y"] = 0.462571 }, { ["mapID"] = 103, ["npcID"] = 17120, ["x"] = 0.555, ["y"] = 0.819667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 914, ["x"] = 0.795, ["y"] = 0.693 }, { ["mapID"] = 84, ["npcID"] = 164939, ["x"] = 0.802, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.530571, ["y"] = 0.462571 }, ["mapCandidates"] = { ["npc"] = { 84, 89, 103 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27227] = { ["id"] = 27227, ["name"] = "Lord Aurius Rivendare", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27227 }, ["description"] = "This Chapel is the last Light amongst so much darkness. Ras Frostwhisper took his own life in the slaughterhouse, carving his face into a macabre smile in front of the Lich King, who raised him into the Lich that now haunts Scholomance. The ground where that atrocity occured is now Scourge holy ground, blessed by the Lich King with the very darkest magic. Lord Aurius Rivendare , new ruler of Stratholme , now guards it and continues his master's evil work. Slay him without pause.", ["objectivesText"] = "Kill Lord Aurius Rivendare . Progress: Don't waste our time. Every second spend chatting away is a second we aren't taking Stratholme back for the Light.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27228] = { ["id"] = 27228, ["name"] = "Man Against Abomination", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27228 }, ["description"] = "Deep within, you will find Ramstein the Gorger . I cannot bear to tell you the atrocities this monster has commited. Know only this - he deserves to feel the full wrath of countless lost souls, a wrath you will bring upon him. Have no mercy. Be unwavering in your fury.", ["objectivesText"] = "Slaughter Ramstein the Gorger .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27230] = { ["id"] = 27230, ["name"] = "Weapons for War", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27230 }, ["description"] = "The Scourge are adept at forging powerful armaments for their soldiers, making it difficult for our men to kill 'em! There are blacksmithing plans near the Baroness Anastari's ziggurat that their chief swordsmith plans to use for an extremely powerful weapon for Lord Aurius. We're going to prevent that weapon from being made and stop their regular arms flow with one blow! Go take the plans and kill the Black Guard Swordsmith when he comes to defend 'em, and it'll make our mission much easier.", ["objectivesText"] = "Kill the Black Guard Swordsmith . Progress: You need to kill their swordsmith! Go!", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon", ["startItems"] = { 60886 } },
[27233] = { ["id"] = 27233, ["name"] = "The Menders' Stead", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 27233 }, ["series"] = { 26935, 26952, 26999, 27000, 27001, 27002, 27175 }, ["description"] = "I can handle training from here. If you're looking for something else to do, I recommend heading up the road to the northwest. The Cenarion druids and Argent Crusade have a small camp set up there, at Dalson's old farm. Maybe they can keep you busy until we need your help again.", ["objectivesText"] = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 45165, ["x"] = 0.44, ["y"] = 0.719 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 44454, ["x"] = 0.492, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.719 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard" },
[27265] = { ["id"] = 27265, ["name"] = "Ezul'aan Calls", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 3, 11, 30 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 87, ["storyline"] = { 27265 }, ["series"] = { 27343 }, ["description"] = "Ezul'aan , one of the foremost paladins in the realm, has asked to speak with you personally. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress. You should make your way to Stormwind immediately and meet him at the Training Hall in the Old Town district.", ["objectivesText"] = "Speak to Ezul'aan at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5147, ["x"] = 0.233, ["y"] = 0.0535 }, { ["mapID"] = 103, ["npcID"] = 16761, ["x"] = 0.39, ["y"] = 0.841333 }, { ["mapID"] = 89, ["npcID"] = 35281, ["x"] = 0.435, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 928, ["x"] = 0.525, ["y"] = 0.452 }, { ["mapID"] = 84, ["npcID"] = 164952, ["x"] = 0.792, ["y"] = 0.698667 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.0535 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 89, 103 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27266] = { ["id"] = 27266, ["name"] = "Dalgrun Calls", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 89, ["storyline"] = { 27266 }, ["series"] = { 27344 }, ["description"] = "Dalgrun Steelpine oversees the training and coordination of hunters in the service of Stormwind. He has asked to speak to you personally. As soon as you are able, travel to Stormwind and meet with Dalgrun at the Training Hall in Old Town. I have no idea what he has planned, but it sounds like he has been impressed with your rapid progress.", ["objectivesText"] = "Speak to Dalgrun Steelpine in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4138, ["x"] = 0.434, ["y"] = 0.261333 }, { ["mapID"] = 87, ["npcID"] = 5115, ["x"] = 0.7095, ["y"] = 0.895 }, { ["mapID"] = 103, ["npcID"] = 17122, ["x"] = 0.4735, ["y"] = 0.879 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 44247, ["x"] = 0.640667, ["y"] = 0.598 }, { ["mapID"] = 84, ["npcID"] = 164960, ["x"] = 0.792, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.261333 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 89, 103 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27267] = { ["id"] = 27267, ["name"] = "Make Contact with SI:7", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 89, ["storyline"] = { 27267 }, ["series"] = { 27351 }, ["description"] = "It seems that the leaders of SI:7 have taken an interest in your progress and your service to the Alliance. Veruca Darkstream , a high ranking member of SI:7, has asked to speak with you. Veruca is awaiting your arrival at the Training Hall in Stormwind. I'm not sure what she wants with you, but it seemed important.", ["objectivesText"] = "Speak with Veruca Darkstream at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4214, ["x"] = 0.402, ["y"] = 0.394 }, { ["mapID"] = 87, ["npcID"] = 5165, ["x"] = 0.5148, ["y"] = 0.1504 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 918, ["x"] = 0.711714, ["y"] = 0.608 }, { ["mapID"] = 84, ["npcID"] = 13283, ["x"] = 0.644667, ["y"] = 0.518 }, { ["mapID"] = 84, ["npcID"] = 164946, ["x"] = 0.787333, ["y"] = 0.705333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.394 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 89 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27268] = { ["id"] = 27268, ["name"] = "Patrice Lancaster Sends Word", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 89, ["storyline"] = { 27268 }, ["series"] = { 27361 }, ["description"] = "I have an urgent message for you from Stormwind, <name>. It seems that Speak to Patrice Lancaster has asked to speak with you at the Training Hall in Stormwind's Old Town district. The messenger did not say what the matter concerned, but that you should travel to Stormwind with all haste.", ["objectivesText"] = "Speak to Patrice Lancaster at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 11401, ["x"] = 0.434667, ["y"] = 0.79 }, { ["mapID"] = 87, ["npcID"] = 11406, ["x"] = 0.253556, ["y"] = 0.078222 }, { ["mapID"] = 103, ["npcID"] = 16756, ["x"] = 0.388, ["y"] = 0.511333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 376, ["x"] = 0.495, ["y"] = 0.4455 }, { ["mapID"] = 84, ["npcID"] = 164949, ["x"] = 0.794, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.434667, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 89, 103 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27269] = { ["id"] = 27269, ["name"] = "The Temple of the Moon", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 27269 }, ["series"] = { 27362 }, ["description"] = "I have an urgent message for you from Darnassus. The message is from the High Priestess of Elune, Tyrande Whisperwind , herself! The messenger did not say what the matter concerned, but that you should travel to the Temple of the Moon in Darnassus and meet with the high priestess at once.", ["objectivesText"] = "Speak to Tyrande Whisperwind at the Temple of the Moon in Darnassus.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 11401, ["x"] = 0.434667, ["y"] = 0.79 }, { ["mapID"] = 87, ["npcID"] = 11406, ["x"] = 0.253556, ["y"] = 0.078222 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 7999, ["x"] = 0.430667, ["y"] = 0.779333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.434667, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 87, 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[27270] = { ["id"] = 27270, ["name"] = "An Audience with Mulric", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 7 }, ["requiredRaces"] = { 3, 11, 34 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 87, ["storyline"] = { 27270 }, ["series"] = { 27353 }, ["description"] = "I have an urgent message for you from Stormwind, <name>. It seems Mulric Boldrock has asked to speak with you the next time you're in the city. The messenger gave no explanation for the shaman's invitation, but you should travel to Stormwind and find Mulric Boldrock at the Training Hall to the south of Old Town as soon as you can.", ["objectivesText"] = "Speak with Mulric Boldrock at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 23127, ["x"] = 0.552, ["y"] = 0.292 }, { ["mapID"] = 89, ["npcID"] = 52292, ["x"] = 0.4368, ["y"] = 0.7872 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 164945, ["x"] = 0.789, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[27271] = { ["id"] = 27271, ["name"] = "Frazzle's Request", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 87, ["storyline"] = { 27271 }, ["series"] = { 27354 }, ["description"] = "I just received a message from Stormwind, <name>. One of Stormwind's most renowned mages, Frazzle Frostfingers , has requested that you visit him at the Training Hall in Stormwind. The Training Hall is located in the Old Town district of Stormwind. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress.", ["objectivesText"] = "Speak with Frazzle Frostfingers at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5146, ["x"] = 0.2645, ["y"] = 0.062 }, { ["mapID"] = 103, ["npcID"] = 16749, ["x"] = 0.470571, ["y"] = 0.619429 }, { ["mapID"] = 89, ["npcID"] = 50690, ["x"] = 0.375, ["y"] = 0.800667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 331, ["x"] = 0.476, ["y"] = 0.89 }, { ["mapID"] = 84, ["npcID"] = 164955, ["x"] = 0.799, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.2645, ["y"] = 0.062 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 89, 103 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27272] = { ["id"] = 27272, ["name"] = "A Message From Evelyn Thorn", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 87, ["storyline"] = { 27272 }, ["series"] = { 27355 }, ["description"] = "It seems that the elders in our ranks have taken notice of your progress and dedication, <name>. Evelyn Thorn , one of the oldest and most respected members of our circle, has sent word that she wishes to speak with you. You should not take such an invitation lightly. Most only speak with her in the course of their lessons, but if she has asked to see you personally, it must be an important matter. Hurry back to Stormwind and look for her at the Training Hall to the south of the Old Town district.", ["objectivesText"] = "Speak with Evelyn Thorn at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5173, ["x"] = 0.502, ["y"] = 0.0725 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 461, ["x"] = 0.3945, ["y"] = 0.8485 }, { ["mapID"] = 84, ["npcID"] = 164942, ["x"] = 0.7945, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.0725 }, ["mapCandidates"] = { ["npc"] = { 84, 87 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27273] = { ["id"] = 27273, ["name"] = "An Invitation from Moonglade", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 4, 22, 32 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 89, ["storyline"] = { 27273 }, ["series"] = { 27356 }, ["description"] = "You just missed the messenger from Moonglade, <name>. He said little, except that he carried an urgent message from Loganaar , one of the honored trainers of the Cenarion Circle. Head to Moonglade as quickly as you can, <name>. The matter sounds important. Look for Loganaar in the village of Nighthaven.", ["objectivesText"] = "Speak to Loganaar at Nighthaven in Moonglade.", ["rewardXP"] = 145, ["rewardItems"] = { 65461, 65462 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4217, ["x"] = 0.404, ["y"] = 0.275333 }, { ["mapID"] = 84, ["npcID"] = 5504, ["x"] = 0.339, ["y"] = 0.547 }, { ["mapID"] = 97, ["npcID"] = 16721, ["x"] = 0.244, ["y"] = 0.544 }, { ["mapID"] = 84, ["npcID"] = 44395, ["x"] = 0.575, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 12042, ["x"] = 0.525, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.275333 }, ["mapCandidates"] = { ["npc"] = { 80, 84, 89, 97 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27274] = { ["id"] = 27274, ["name"] = "Patrice Lancaster Sends Word", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 27274 }, ["series"] = { 27363 }, ["description"] = "I have an urgent message for you from Stormwind, <name>. Patrice Lancaster has asked to meet with you in Stormwind. The message didn't say what the priest trainer wanted to discuss, but you should make your way to Stormwind as quickly as you can. Look for Patrice Lancaster at the Training Hall in the Old Town district of the city.", ["objectivesText"] = "Speak to Patrice Lancaster at the Training Hall in Stormwind.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 11406, ["x"] = 0.253556, ["y"] = 0.078222 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 45306, ["x"] = 0.6275, ["y"] = 0.3405 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.253556, ["y"] = 0.078222 }, ["mapCandidates"] = { ["npc"] = { 84, 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[27277] = { ["id"] = 27277, ["name"] = "An Audience with Feenix Arcshine", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 88, ["storyline"] = { 27277 }, ["series"] = { 27400 }, ["description"] = "I've received an urgent message from Orgrimmar for you, <name>. The renowned mage, Feenix Arcshine , wants you to meet with him in Orgrimmar. I'm not sure what this is about, but if I was you, I would travel to the capital as fast as possible and seek out Feenix Arcshine at The Barracks in the Valley of Honor.", ["objectivesText"] = "Speak with Feenix Arcshine at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3047, ["x"] = 0.225, ["y"] = 0.149667 }, { ["mapID"] = 90, ["npcID"] = 4566, ["x"] = 0.8148, ["y"] = 0.254 }, { ["mapID"] = 110, ["npcID"] = 16653, ["x"] = 0.5992, ["y"] = 0.2188 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 168626, ["x"] = 0.747, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.149667 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 90, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27278] = { ["id"] = 27278, ["name"] = "Tamanji's Call", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 88, ["storyline"] = { 27278 }, ["series"] = { 27395 }, ["description"] = "A courier from Orgrimmar just delivered a message for you. I'm to tell you that Tamanji , master of the hunters in Orgrimmar, has asked to meet with you. Travel quickly to Orgrimmar and present yourself to Tamanji at The Barracks in the Valley of Honor.", ["objectivesText"] = "Speak with Tamanji at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3039, ["x"] = 0.5745, ["y"] = 0.8895 }, { ["mapID"] = 110, ["npcID"] = 16674, ["x"] = 0.795, ["y"] = 0.286 }, { ["mapID"] = 90, ["npcID"] = 39116, ["x"] = 0.493778, ["y"] = 0.295556 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3352, ["x"] = 0.554, ["y"] = 0.4384 }, { ["mapID"] = 85, ["npcID"] = 168551, ["x"] = 0.738, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.5745, ["y"] = 0.8895 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 90, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27279] = { ["id"] = 27279, ["name"] = "The Shattered Hand", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 90, ["storyline"] = { 27279 }, ["series"] = { 27396 }, ["description"] = "A messenger just arrived from Orgrimmar bearing a communication for you. Thega Graveblade , the senior rogue trainer in Orgrimmar, has sent for you. You must head to Orgrimmar immediately and meet with her at The Barracks in the Valley of Honor. When Thega Graveblade summons you, the prudent thing to do is obey. Do not keep her waiting, <name>.", ["objectivesText"] = "Speak with Thega Graveblade at The Barracks in Orgrimmar.", ["rewardGold"] = 561800, ["rewardXP"] = 145, ["rewardItems"] = { 29460, 65487 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4584, ["x"] = 0.8175, ["y"] = 0.66125 }, { ["mapID"] = 110, ["npcID"] = 16684, ["x"] = 0.741333, ["y"] = 0.461667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 168598, ["x"] = 0.752, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.8175, ["y"] = 0.66125 }, ["mapCandidates"] = { ["npc"] = { 85, 90, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27280] = { ["id"] = 27280, ["name"] = "The Riverspeaker Calls", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 110, ["storyline"] = { 27280 }, ["series"] = { 27397 }, ["description"] = "News travels upon the winds, young shaman. Your deeds have not gone unnoticed! It seems Hretar Riverspeaker wishes to discuss something with you. Make your way to Orgrimmar as quickly as you can and speak with him at The Barracks in the Valley of Honor. He will be among the others who offer training.", ["objectivesText"] = "Speak with Hretar Riverspeaker at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 16661, ["x"] = 0.7155, ["y"] = 0.564 }, { ["mapID"] = 88, ["npcID"] = 51639, ["x"] = 0.2508, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3344, ["x"] = 0.39, ["y"] = 0.475 }, { ["mapID"] = 85, ["npcID"] = 168628, ["x"] = 0.734, ["y"] = 0.4345 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.7155, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 110 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[27281] = { ["id"] = 27281, ["name"] = "Gormok Ogrefist", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 88, ["storyline"] = { 27281 }, ["series"] = { 27365 }, ["description"] = "I just received word that you are needed in Orgrimmar, <name>. Gormok Ogrefist , the honored trainer of warriors in the city, has sent for you. It would not be wise to ignore such a summons. Travel quickly to Orgrimmar and visit The Barracks in the Valley of Honor where Gormok awaits your arrival.", ["objectivesText"] = "Speak with Gormok Ogrefist at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3042, ["x"] = 0.573, ["y"] = 0.8885 }, { ["mapID"] = 90, ["npcID"] = 4593, ["x"] = 0.471667, ["y"] = 0.157333 }, { ["mapID"] = 110, ["npcID"] = 43009, ["x"] = 0.775111, ["y"] = 0.362889 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3353, ["x"] = 0.735, ["y"] = 0.455 }, { ["mapID"] = 85, ["npcID"] = 168596, ["x"] = 0.735, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.573, ["y"] = 0.8885 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 90, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27282] = { ["id"] = 27282, ["name"] = "Kazak's Behest", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 90, ["storyline"] = { 27282 }, ["series"] = { 27402 }, ["description"] = "<name>, I have received word that you are needed back in Orgrimmar. Kazak Darkscream , one of the senior warlock trainers, has something important that he wishes to discuss with you. It seems like the kind of thing that cannot wait. Make your way back to Orgrimmar and speak with him as soon as you can. You will find him at the Training Hall in the Valley of Honor.", ["objectivesText"] = "Speak with Kazak Darkscream at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4563, ["x"] = 0.8572, ["y"] = 0.1528 }, { ["mapID"] = 110, ["npcID"] = 16648, ["x"] = 0.683667, ["y"] = 0.405 }, { ["mapID"] = 88, ["npcID"] = 43881, ["x"] = 0.254667, ["y"] = 0.146667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 168623, ["x"] = 0.745, ["y"] = 0.471 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.8572, ["y"] = 0.1528 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 90, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27283] = { ["id"] = 27283, ["name"] = "A Journey to Moonglade", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 88, ["storyline"] = { 27283 }, ["series"] = { 27404 }, ["description"] = "As you have heard, Moonglade is the home of the Cenarion Circle, the brotherhood of druids. All who dwell there do so in the peace of Cenarius. It is in that spirit that the trainer Loganaar has extended an invitation to visit him in Moonglade. You will find him in the village of Nighthaven.", ["objectivesText"] = "Speak with Loganaar in Nighthaven.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3034, ["x"] = 0.7076, ["y"] = 0.2692 }, { ["mapID"] = 85, ["npcID"] = 44726, ["x"] = 0.449, ["y"] = 0.515 }, { ["mapID"] = 85, ["npcID"] = 44978, ["x"] = 0.3472, ["y"] = 0.6772 }, { ["mapID"] = 90, ["npcID"] = 52319, ["x"] = 0.550857, ["y"] = 0.506571 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 12042, ["x"] = 0.525, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.7076, ["y"] = 0.2692 }, ["mapCandidates"] = { ["npc"] = { 80, 85, 88, 90 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27298] = { ["id"] = 27298, ["name"] = "Seek Out Avaros Dawnglaive", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 110, ["storyline"] = { 27298 }, ["series"] = { 27434 }, ["description"] = "Avaros Dawnglaive , a senior Blood Knight and advisor to the warchief, requires your presence in Orgrimmar. He has taken an interest in your training, <name>, and it is imperative that you speak with him immediately. The message I received didn't mention the reason he requested your visit, but you should set out for Orgrimmar right away. Avaros Dawnglaive can be found at The Barracks in the Valley of Honor.", ["objectivesText"] = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 16681, ["x"] = 0.85125, ["y"] = 0.3595 }, { ["mapID"] = 90, ["npcID"] = 20406, ["x"] = 0.575, ["y"] = 0.905 }, { ["mapID"] = 88, ["npcID"] = 43795, ["x"] = 0.632, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 23128, ["x"] = 0.491, ["y"] = 0.715 }, { ["mapID"] = 85, ["npcID"] = 168597, ["x"] = 0.733, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.85125, ["y"] = 0.3595 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 90, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27304] = { ["id"] = 27304, ["name"] = "Meet With Avaros Dawnglaive", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 6, 10 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 90, ["storyline"] = { 27304 }, ["series"] = { 27403 }, ["description"] = "Avaros Dawnglaive sends word from Orgrimmar -- he wishes to speak with you when you're in the city. I needn't remind you that Avaros is an honored member of our order and his requests should not be ignored. Next time you are in Orgrimmar, travel to The Barracks in the Valley of Honor and speak with him.", ["objectivesText"] = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 20406, ["x"] = 0.575, ["y"] = 0.905 }, { ["mapID"] = 88, ["npcID"] = 43795, ["x"] = 0.632, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 44725, ["x"] = 0.453333, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.905 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 90 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[27305] = { ["id"] = 27305, ["name"] = "Of Love and Family", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27305 }, ["description"] = "Inside the Scarlet Bastion is a painting of great personal value to Highlord Tirion Fordring. Search for a painting of our twin moons. Chip away at the paint until you uncover the master work, ' Of Love and Family .' May the Light guide your actions, and please handle the painting with the utmost care.", ["objectivesText"] = "Find ' Of Love and Family .' Progress: The painting, <name>. Do you have the painting?", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 14679 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27322] = { ["id"] = 27322, ["name"] = "Korok the Colossus", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 26965, 26989, 26992, 26995, 26998, 27039, 27045, 27056, 27065, 27069, 27073, 27082, 27088, 27093, 27094, 27096, 27097, 27098, 27099, 27180, 27181, 27193, 27194, 27195, 27226, 27231, 27232, 27290, 27322, 27333, 27342, 27345, 27349, 27350, 27364, 27401, 27405, 27406, 27423, 27438, 27472, 27474, 27475, 27476, 27478, 27484, 27512, 27513, 27518, 27542, 27547, 27548, 27550, 27577, 27580, 27594, 27601 }, ["description"] = "The monstrosity has fallen, granting a brief reprieve to the Forsaken soldiers on the front lines. Take Korok's second head and return it to Forward Commander Onslaught at Forsaken Forward Command.", ["objectivesText"] = "Take Korok's Second Head to Forward Commander Onslaught at Forsaken Forward Command in the Ruins of Gilneas . Progress: Korok is dead?", ["rewardXP"] = 1480, ["rewardItems"] = { 60956, 62866, 62867, 62868 }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 6389, ["x"] = 0.434667, ["y"] = 0.415333 }, { ["mapID"] = 217, ["npcID"] = 45315, ["x"] = 0.526667, ["y"] = 0.43 }, { ["mapID"] = 21, ["npcID"] = 45631, ["x"] = 0.516, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.434667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 130 } }, ["questType"] = "group", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 432, ["name"] = "Silverpine Forest", ["orderIndex"] = 31, ["flags"] = 0 } }, ["startItems"] = { 60956 } },
[27331] = { ["id"] = 27331, ["name"] = "Journey to Orgrimmar", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 27331 }, ["series"] = { 27435 }, ["description"] = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar. He asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", ["objectivesText"] = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3045, ["x"] = 0.2445, ["y"] = 0.221 }, { ["mapID"] = 90, ["npcID"] = 4606, ["x"] = 0.557111, ["y"] = 0.164444 }, { ["mapID"] = 110, ["npcID"] = 16658, ["x"] = 0.5532, ["y"] = 0.2832 }, { ["mapID"] = 88, ["npcID"] = 43870, ["x"] = 0.7545, ["y"] = 0.2845 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 44735, ["x"] = 0.455, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.2445, ["y"] = 0.221 }, ["mapCandidates"] = { ["npc"] = { 85, 88, 90, 110 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
