[27335] = { ["id"] = 27335, ["name"] = "Journey to Orgrimmar", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 90, ["storyline"] = { 27335 }, ["series"] = { 27439 }, ["description"] = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde , at The Barracks in Orgrimmar. He asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", ["objectivesText"] = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", ["rewardXP"] = 145, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4606, ["x"] = 0.557111, ["y"] = 0.164444 }, { ["mapID"] = 110, ["npcID"] = 16658, ["x"] = 0.5532, ["y"] = 0.2832 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 45337, ["x"] = 0.49, ["y"] = 0.713 }, { ["mapID"] = 85, ["npcID"] = 168621, ["x"] = 0.726, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.557111, ["y"] = 0.164444 }, ["mapCandidates"] = { ["npc"] = { 85, 90, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[27337] = { ["id"] = 27337, ["name"] = "A Fitting Weapon", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27337 }, ["series"] = { 27225 }, ["description"] = "From your earliest days, <name>, your trainers identified you as a natural talent. Your rapid progress and dedication have made you an example. In recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon. Legend has it that the cursed Shadowfang Keep in Silverpine Forest is home to a variety of materials that you will need. Travel there and find the lost Silverlaine family sword , a supply of moonsteel ingots , and sinew from ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60872, 60874, 60885, 65492, 65493, 65494, 65495 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 914, ["x"] = 0.795, ["y"] = 0.693 }, { ["mapID"] = 84, ["npcID"] = 164939, ["x"] = 0.802, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5511, ["x"] = 0.635, ["y"] = 0.370667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.693 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27343] = { ["id"] = 27343, ["name"] = "The Hand of the Light", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27343 }, ["series"] = { 27265 }, ["description"] = "I have been watching your progress, <name>, and I can only conclude that the Light shines brightly upon you. You are becoming an exemplary <class>. To honor your dedication, King Wrynn has commissioned the royal armorer to forge a special weapon. The materials to make your weapon are unique, and only found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots , and 5 Deathless Sinew . Progress: Do you have the materials for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60872, 60874, 60879, 65475, 65476, 65477 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 928, ["x"] = 0.525, ["y"] = 0.452 }, { ["mapID"] = 84, ["npcID"] = 164952, ["x"] = 0.792, ["y"] = 0.698667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5511, ["x"] = 0.635, ["y"] = 0.370667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27344] = { ["id"] = 27344, ["name"] = "A Well-Earned Reward", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27344 }, ["series"] = { 27266 }, ["description"] = "I am not the only one impressed by your progress <name>. Your mastery of bow and pet and your dedication to the Alliance have reached the ears of King Wrynn. In recognition of your service, the king has commissioned the royal bowyer to craft a special weapon. The cursed Shadowfang Keep in Silverpine Forest is home to the unique materials needed for your weapon. Travel there and obtain the scope from Lord Godfrey's gun, a supply of moontouched wood , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Godfrey's Crystal Scope from Lord Godfrey, 5 bundles of Moontouched Wood , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60874, 60877, 65465, 65466 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 44247, ["x"] = 0.640667, ["y"] = 0.598 }, { ["mapID"] = 84, ["npcID"] = 164960, ["x"] = 0.792, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1298, ["x"] = 0.585, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.640667, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27351] = { ["id"] = 27351, ["name"] = "A Royal Reward", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27351 }, ["series"] = { 27267 }, ["description"] = "SI:7 has been watching your progress with interest. You service to the Alliance is well-known and tales of your deeds have reached the king's ears. In recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon. The cursed Shadowfang Keep in Silverpine Forest is home to the exotic materials for your weapon. Travel there and recover Commander Springvale's sharpening stone , a supply of moonsteel ingots , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 58978, 60872, 60874, 60880, 65486 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 13283, ["x"] = 0.644667, ["y"] = 0.518 }, { ["mapID"] = 84, ["npcID"] = 51998, ["x"] = 0.795, ["y"] = 0.608 }, { ["mapID"] = 84, ["npcID"] = 164946, ["x"] = 0.787333, ["y"] = 0.705333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5511, ["x"] = 0.635, ["y"] = 0.370667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.644667, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27352] = { ["id"] = 27352, ["name"] = "Liquid Gold", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27352 }, ["description"] = "As the Scourge swept through Stratholme like a plague, the Knights of the Silver Hand manufactured holy water to use against the invaders. They stored it inside small crates along with other vital supplies, and distributed them throughout the city. Unfortunately, the citizens turned into Scourge reinforcements before the supplies could ever be used! These supply crates will prove extremely useful to our efforts. Bring me a vial of Stratholme Holy Water , we need to have it replicated in mass quantities.", ["objectivesText"] = "Find a vial of Stratholme Holy Water . Progress: Is that the vial of Stratholme Holy Water ? Wait, is that just regular water? Don't play games with ol' Stonebruiser!", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 13180 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27353] = { ["id"] = 27353, ["name"] = "Blessings of the Elements", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27353 }, ["series"] = { 27270 }, ["description"] = "Your talent has attracted much attention in shamanic circles, <name>. Word of your mastery of the elements and dedication to the Alliance has even reached the palace. In recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon. The materials for your weapon can only be found in Silverpine Forest's cursed Shadowfang Keep. Travel there and retrieve Lord Walden's talisman , the Book of Lost Souls , and the essence of the ghosts haunting the castle.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Walden's Talisman , the Book of Lost Souls , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 21242, 58097, 60873, 60875, 60881, 65488, 65489 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 164945, ["x"] = 0.789, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5511, ["x"] = 0.635, ["y"] = 0.370667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.789, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27354] = { ["id"] = 27354, ["name"] = "Mastering the Arcane", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27354 }, ["series"] = { 27271 }, ["description"] = "You have proven yourself a brilliant student and a dedicated servant of the Alliance. Word of your accomplishments has even reached the ears of the king. In recognition of your service, King Wrynn has commissioned the royal enchanter to create a special weapon. The materials required for your staff are found only in Silverpine Forest's cursed Shadowfang Keep. Travel there and find a lost heirloom of the Silverlaine family, a supply of moontouched wood , and the essence of the ghosts haunting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60878, 65467, 65468 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 331, ["x"] = 0.476, ["y"] = 0.89 }, { ["mapID"] = 84, ["npcID"] = 164955, ["x"] = 0.799, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1317, ["x"] = 0.53, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.89 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27355] = { ["id"] = 27355, ["name"] = "A Boon for the Powerful", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27355 }, ["series"] = { 27272 }, ["description"] = "The king is finally beginning to take note of our power and our value to the Alliance, thanks to your deeds. Perhaps they are beginning to accept our kind. King Wrynn has commissioned the royal enchanter to create a powerful weapon in recognition of your achievements. The materials you will need come from Silverpine Forest's Shadowfang Keep. Travel there and obtain the tenebrous orb held by Lord Godfrey, the Book of Lost Souls , and the essence of the ghosts haunting the castle.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60873, 60875, 60882, 65496 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 461, ["x"] = 0.3945, ["y"] = 0.8485 }, { ["mapID"] = 84, ["npcID"] = 164942, ["x"] = 0.7945, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1317, ["x"] = 0.53, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.3945, ["y"] = 0.8485 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27356] = { ["id"] = 27356, ["name"] = "The Circle's Future", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 4, 22, 32 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 27356 }, ["series"] = { 27273 }, ["description"] = "The Cenarion Circle is pleased with your progress, <name>. You are a credit to all druids and we look to you and your peers as the future of of our brotherhood. The circle has decided to honor you with the creation of unique staff. The rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your staff?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60874, 60876, 65461, 65462, 65463, 65464 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 12042, ["x"] = 0.525, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 12029, ["x"] = 0.532, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "dungeon" },
[27359] = { ["id"] = 27359, ["name"] = "Argent Reinforcements", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 2017, ["storyline"] = { 27359 }, ["description"] = "The Scourge have some sort of ward in place that's preventing me from opening a portal so that our reinforcements can help us take the city! It's like a neverending screaming inside of my head! Agh! I'm doing all I can to retain my sanity from that noise with this barrier. My best guess is that the banshees are maintaining the defense. If you could bring me some of their essences, I think I can use them to counteract the ward and get our boys in here!", ["objectivesText"] = "Obtain 4 Banshee Essences . Progress: Were you able to obtain the essences? Be careful, they're deadly spellcasters.", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 60975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2017 } }, ["questType"] = "dungeon" },
[27361] = { ["id"] = 27361, ["name"] = "Favored of the Light", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27361 }, ["series"] = { 27268 }, ["description"] = "The Light truly shines in you and your dedication to the Alliance, <name>. You serve as an example to your fellow priests and comrades in arms. In recognition of your deeds, King Wrynn has commissioned the royal enchanter to create a special staff. The materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and ghostly essence from the spirits haunting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65482 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 376, ["x"] = 0.495, ["y"] = 0.4455 }, { ["mapID"] = 84, ["npcID"] = 164949, ["x"] = 0.794, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1317, ["x"] = 0.53, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.4455 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27362] = { ["id"] = 27362, ["name"] = "Favored of Elune", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 27362 }, ["series"] = { 27269 }, ["description"] = "You are a true servant of Elune, an example to our people, and stalwart servant of the Alliance. The Temple of the Moon and the court of Stormwind wish to honor your achievements. We have commissioned the royal enchanter to create a staff for you. The materials for your staff can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and ghostly essence from the spirits haunting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65483 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 7999, ["x"] = 0.430667, ["y"] = 0.779333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1317, ["x"] = 0.53, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.430667, ["y"] = 0.779333 }, ["mapCandidates"] = { ["npc"] = { 84, 89 }, ["zone"] = { 1657 } }, ["questType"] = "dungeon" },
[27363] = { ["id"] = 27363, ["name"] = "A Budding Young Surgeon", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27363 }, ["series"] = { 27274 }, ["description"] = "You have shown yourself to be a capable priest and a credit to the people of Gnomeregan. The high tinker and the king of Stormwind wish to honor your contribution to the Alliance. They have commissioned the royal enchanter to create a special staff. The materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and ghostly essence from the spirits haunting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65480, 65482 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 45306, ["x"] = 0.6275, ["y"] = 0.3405 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1317, ["x"] = 0.53, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.6275, ["y"] = 0.3405 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[27365] = { ["id"] = 27365, ["name"] = "A Fitting Weapon", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27365 }, ["series"] = { 27281 }, ["description"] = "From your earliest days, your trainers always knew you would make your mark on the Horde. You have fought bravely and given our enemies reason to fear. As a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost Silverlaine family sword , a supply of moonsteel ingots , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 1292, 3191, 6323, 6641, 60872, 60874, 60885, 65492, 65493, 65494, 65495 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3353, ["x"] = 0.735, ["y"] = 0.455 }, { ["mapID"] = 85, ["npcID"] = 168596, ["x"] = 0.735, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3355, ["x"] = 0.596667, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27374] = { ["id"] = 27374, ["name"] = "The Maw of Madness", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 27374 }, ["series"] = { 27299, 27300, 27375, 27376, 27377, 27378, 27379, 27380, 27945 }, ["description"] = "I can't believe it, <name>. Me own son - me own flesh and blood! Throwing his lot in with those fiends from the Twilight's Hammer. Did you see what he became when he tried to destroy the wedding? Oh ... why? Why? It's that beast, <name>. The enormous mouth emerging from the earth to our west. \"The Maw of Madness!\" My son said it spoke to him, but I thought it was just nightmares. The Earthen Ring is trying to destroy it. Go to Earthcaller Torunscar , west of here, and see how you can help!", ["objectivesText"] = "Speak to Earthcaller Torunscar at the Ring of the Elements.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 63745 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 48367, ["x"] = 0.544, ["y"] = 0.168 }, { ["mapID"] = 241, ["npcID"] = 49374, ["x"] = 0.552, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 45332, ["x"] = 0.44, ["y"] = 0.105 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[27375] = { ["id"] = 27375, ["name"] = "The Weeping Wound", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 27375 }, ["series"] = { 27299, 27300, 27374, 27376, 27377, 27378, 27379, 27380, 27945 }, ["description"] = "A beast, <name>! I saw a beast. A great maw, an even greater hungering. They can't possibly know what they unleashed. It is here. Its terrible shapeless body is erupting right into the Highlands. I saw you in my vision, <name>. You struggle with the Earthen Ring to contain the beast. You will face the darkness. Go now, before the beast grows in power. Speak to Earthcaller Torunscar at the Circle of the Elements, northwest of here atop the ridge beyond the ruined Drakgor Encampment. Hurry!", ["objectivesText"] = "Speak with Earthcaller Torunscar at the Ring of the Elements.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 46324, ["x"] = 0.532, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 45332, ["x"] = 0.44, ["y"] = 0.105 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[27393] = { ["id"] = 27393, ["name"] = "The Call of the Blade", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 27393 }, ["series"] = { 25583 }, ["description"] = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me? I'm certain that there's something there.", ["objectivesText"] = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 54614, 55171, 62281 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 39881, ["x"] = 0.447667, ["y"] = 0.668333 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.447667, ["y"] = 0.668333 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 5144 } }, ["questType"] = "standard" },
