[27395] = { ["id"] = 27395, ["name"] = "A Marksman's Weapon", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27395 }, ["series"] = { 27278 }, ["description"] = "You have picked up the ways of the hunter quickly, <name>. Your skills have made you a credit to the Horde and an example to the younglings. As a reward for your progress and hard work, the warchief has commissioned his personal bowyer to create a unique weapon. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials we'll need. Travel there and retrieve the scope from Lord Godfrey's gun, a supply of moontouched wood , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Godfrey's Crystal Scope , 5 bundles of Moontouched Wood , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 42946, 60871, 60874, 60877, 65466 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3352, ["x"] = 0.554, ["y"] = 0.4384 }, { ["mapID"] = 85, ["npcID"] = 168551, ["x"] = 0.738, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3355, ["x"] = 0.596667, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.4384 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27396] = { ["id"] = 27396, ["name"] = "Blade of the Shattered Hand", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27396 }, ["series"] = { 27279 }, ["description"] = "Many members of the Shattered Hand do not survive their training, <name>. Not only have you survived, but you will soon become a feared blade of the Horde. As a reward for your progress, the warchief has commissioned his personal smith to forge a weapon. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover Commander Springvale's sharpening stone , a supply of moonsteel ingots , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60872, 60874, 60880, 65487 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168598, ["x"] = 0.752, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3355, ["x"] = 0.596667, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27397] = { ["id"] = 27397, ["name"] = "Hretar's Task", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27397 }, ["series"] = { 27280 }, ["description"] = "The elements and spirits speak to you with clear voices, <name>. You have become a powerful shaman and an example to others wishing to serve the Horde. Word has even reached the warchief, and he has commissioned his personal smith to forge a special weapon for you. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and obtain Lord Walden's talisman , the Book of Lost Souls , and essence from the ghosts haunting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Walden's Talisman from Lord Walden, the Book of Lost Souls , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60873, 60875, 60881, 65490, 65491 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3344, ["x"] = 0.39, ["y"] = 0.475 }, { ["mapID"] = 85, ["npcID"] = 168628, ["x"] = 0.734, ["y"] = 0.4345 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3355, ["x"] = 0.596667, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27398] = { ["id"] = 27398, ["name"] = "The Battle Is Won, The War Goes On", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 27398 }, ["description"] = "We've defeated the enemy's forces here, <name>. But Hyjal is not the only place where our foes are moving against us. I've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical. Speak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City for further instructions.", ["objectivesText"] = "Speak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City .", ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40772, ["x"] = 0.721, ["y"] = 0.743 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.721, ["y"] = 0.743 }, ["mapCandidates"] = { ["npc"] = { 84, 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[27399] = { ["id"] = 27399, ["name"] = "The Battle Is Won, The War Goes On", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 27399 }, ["description"] = "We've defeated the enemy's forces here, <name>. But Hyjal is not the only place where our foes are moving against us. I've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical. Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", ["objectivesText"] = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar .", ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40772, ["x"] = 0.721, ["y"] = 0.743 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.721, ["y"] = 0.743 }, ["mapCandidates"] = { ["npc"] = { 85, 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[27400] = { ["id"] = 27400, ["name"] = "Mastering the Arcane", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27400 }, ["series"] = { 27277 }, ["description"] = "All of your trainers agree, <name>, you show an amazing amount of talent for a journeyman. Even the warchief has heard of your rapid progress. As a reward for mastering your studies, the warchief has commissioned his master enchanter to create a staff for you. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find a magical heirloom of the Silverlaine family, a supply of moontouched wood , and the essence of the ghosts haunting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60878, 65467, 65468 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168626, ["x"] = 0.747, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3345, ["x"] = 0.42, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.747, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27402] = { ["id"] = 27402, ["name"] = "Token of Power", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27402 }, ["series"] = { 27282 }, ["description"] = "Your mastery of our ways continues to grow quickly, <name>, and I am far from the only one impressed by your progress. Even the warchief has taken note of your deeds. As a reward for your dedication, the warchief has commissioned his personal enchanter to craft a staff. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and retrieve the tenebrous orb held by Lord Godfrey, the Book of Lost Souls , and the essence of the ghosts haunting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 20536, 25233, 60873, 60875, 60882, 65497 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168623, ["x"] = 0.745, ["y"] = 0.471 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3345, ["x"] = 0.42, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.471 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27403] = { ["id"] = 27403, ["name"] = "A True Sunwalker", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 6, 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27403 }, ["series"] = { 27304 }, ["description"] = "I have watched your training, <name>. Yours is the path of an exemplary Sunwalker, a brave defender of the Horde and a follower of our ways. As a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60872, 60874, 60879, 65471, 65472, 65473, 65474 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 44725, ["x"] = 0.453333, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3355, ["x"] = 0.596667, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.453333, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27404] = { ["id"] = 27404, ["name"] = "The Circle's Future", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 27404 }, ["series"] = { 27283 }, ["description"] = "The Cenarion Circle is pleased with your progress, <name>. You are a credit to all druids and we look to you and your peers as the future of our brotherhood. The circle has decided to honor you with the creation of unique staff. The rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood , and sinew from the ghouls and geists infesting the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your staff?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60874, 60876, 65461, 65462, 65463, 65464 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 12042, ["x"] = 0.525, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 12029, ["x"] = 0.532, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "dungeon" },
[27434] = { ["id"] = 27434, ["name"] = "The Adept's Path", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27434 }, ["series"] = { 27298 }, ["description"] = "Your time as an apprentice has come to an end, <name>. You are ready to advance to the rank of adept, to become a full blood knight in service to Silvermoon. To honor your accomplishments, the warchief has commissioned his personal smith to forge a weapon for you. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots , and sinew from the ghouls and geists there.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots , and 5 Deathless Sinew . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 29329, 60872, 60874, 60879, 65469, 65470, 65471 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 23128, ["x"] = 0.491, ["y"] = 0.715 }, { ["mapID"] = 85, ["npcID"] = 168597, ["x"] = 0.733, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3355, ["x"] = 0.596667, ["y"] = 0.528667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.491, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27435] = { ["id"] = 27435, ["name"] = "A Seer's Staff", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 6, 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27435 }, ["series"] = { 27331 }, ["description"] = "Your skills have grown and you are now ready to become a full seer. You have completed your early training with skill and dedication. To mark this occasion, the warchief has commissioned his master enchanter to create a staff for you. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and the essence of the ghosts that haunt the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65481, 65484, 65485 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 44735, ["x"] = 0.455, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3345, ["x"] = 0.42, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27436] = { ["id"] = 27436, ["name"] = "A Seer's Staff", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27436 }, ["series"] = { 27332 }, ["description"] = "Your skills have grown and you are now ready to become a full seer. You have completed your early training with skill and dedication. To mark this occasion, the warchief has commissioned his master enchanter to create a staff for you. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and the essence of the ghosts that haunt the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65481, 65484, 65485 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45137, ["x"] = 0.3555, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3345, ["x"] = 0.42, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.3555, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27437] = { ["id"] = 27437, ["name"] = "Forsaken Faith", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27437 }, ["series"] = { 27334 }, ["description"] = "You have been a diligent student and servant to our cause. Always use your talents in accord with Lady Sylvanas's wishes and you will be blessed by the shadow. Our queen has arranged for Orgrimmar's master enchanter to create a powerful staff to recognize your service. The materials you will need only come from Shadowfang Keep in the heart of Silverpine Forest. Find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and the essence of the ghosts that haunt the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65479 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45339, ["x"] = 0.484, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3345, ["x"] = 0.42, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27439] = { ["id"] = 27439, ["name"] = "Staff of the Light", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27439 }, ["series"] = { 27335 }, ["description"] = "You are quickly becoming a talented servant of the Light and of Silvermoon, <name>. Your loyalty to our people and to the Horde are exemplary. In recognition of your dedication, the warchief has commissioned his master enchanter to create a staff for you. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and the essence of the ghosts that haunt the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65478 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45337, ["x"] = 0.49, ["y"] = 0.713 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3345, ["x"] = 0.42, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.713 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27440] = { ["id"] = 27440, ["name"] = "Trolls, Ogres, and Orcs, Oh My!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1583, ["storyline"] = { 27440 }, ["description"] = "The black dragonkin Overlord Wyrmthalak oversees the forces of the Lower Spire, who are nearly prepared to launch a full assault on the Dark Iron Dwarves far below. We simply cannot allow the black dragonflight to gain control of the mountain! You must kill War Master Voone , Highlord Omokk , and Overlord Wyrmthalak . Their deaths will cause the army's momentum to grind to a halt and will buy us valuable time.", ["objectivesText"] = "Kill War Master Voone , Highlord Omokk , and Overlord Wyrmthalak . Progress: These are not mindless beasts you are up against, <race>. It is a massive army backed by the ruthless black dragonflight. Exercise caution in these corridors.", ["rewardGold"] = 420000, ["rewardXP"] = 2075, ["rewardItems"] = { 65933, 65957, 65981, 66000 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1583 } }, ["questType"] = "dungeon" },
[27441] = { ["id"] = 27441, ["name"] = "A Seer's Staff", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27441 }, ["series"] = { 28164 }, ["description"] = "I hear that word of your deeds in service to the Horde has even reached the ears of the warchief. He has agreed to allow Orgrimmar's master enchanter to create a staff for you. The cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood , and the essence of the ghosts that haunt the keep.", ["objectivesText"] = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood , and 5 Ghostly Essence . Progress: Did you bring the materials I'll need for your weapon?", ["rewardXP"] = 2290, ["rewardItems"] = { 60871, 60875, 60879, 65481, 65484, 65485 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45347, ["x"] = 0.377143, ["y"] = 0.724286 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3345, ["x"] = 0.42, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.377143, ["y"] = 0.724286 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[27442] = { ["id"] = 27442, ["name"] = "The War Has Many Fronts", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5146, ["mapID"] = 203, ["storyline"] = { 27442 }, ["description"] = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived. Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation. I've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical. Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", ["objectivesText"] = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar .", ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 203, ["npcID"] = 45460, ["x"] = 0.644, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 203, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 85, 203 }, ["zone"] = { 5146 } }, ["questType"] = "standard" },
[27443] = { ["id"] = 27443, ["name"] = "The War Has Many Fronts", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5146, ["mapID"] = 205, ["storyline"] = { 27443 }, ["description"] = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived. Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation. I've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical. Speak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City for further instructions.", ["objectivesText"] = "Speak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City .", ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 45462, ["x"] = 0.571, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 84, 205 }, ["zone"] = { 5146 } }, ["questType"] = "standard" },
[27469] = { ["id"] = 27469, ["name"] = "Friends on The Other Side", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 27469 }, ["description"] = "I come with news from Blackrock Spire . We have a new visitor. His name is Acride . He seeks people of strength, people of intelligence, of dexterity. You ought to go to Blackrock Spire and speak with him.", ["objectivesText"] = "Find Acride .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 9563, ["x"] = 0.727, ["y"] = 0.645 }, { ["mapID"] = 36, ["npcID"] = 56899, ["x"] = 0.542, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.727, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "dungeon" },
[27470] = { ["id"] = 27470, ["name"] = "A Potential Ally", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 51, ["mapID"] = 32, ["storyline"] = { 27470 }, ["description"] = "It is no secret that we aren't fans of the orcs in Blackrock Mountain, but we do carefully watch their every move. Nothing happens in that Mountain without me knowing about it, <class>. Recently, a different sort of orc came into Blackrock. He resides just inside Blackrock Spire , and I know he's somehow planning to overthrow Nefarian and his whole army of orcs. Normally I wouldn't trust their kind, but we share a common goal for the time being. Find him, he's called Acride .", ["objectivesText"] = "Find Acride .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 112440, 112441, 112442, 112443 }, ["starts"] = { { ["mapID"] = 32, ["npcID"] = 14625, ["x"] = 0.4632, ["y"] = 0.3972 } }, ["coords"] = { ["mapID"] = 32, ["source"] = "quest_giver", ["x"] = 0.4632, ["y"] = 0.3972 }, ["mapCandidates"] = { ["npc"] = { 32 }, ["zone"] = { 51 } }, ["questType"] = "dungeon" },
[27471] = { ["id"] = 27471, ["name"] = "Blackrock Anomaly", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 27471 }, ["description"] = "There is an orc inside Blackrock Spire much unlike the others. He speaks with the intelligence and wisdom of one beyond his appeared years, and does not fight against our soldiers like the others do. You must travel northwest to Blackrock Spire and find this orc, known only to us as Acride . Perhaps he is the key to stopping the orcish army. Perhaps we can stop Nefarian before it is too late...", ["objectivesText"] = "Find Acride .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 9562, ["x"] = 0.734, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.734, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "dungeon" },
