[27565] = { ["id"] = 27565, ["name"] = "Into the Prison", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27565 }, ["series"] = { 27567 }, ["description"] = "We've managed to infiltrate the Dark Iron Prison! Well...we may have, anyway. Kevin Dawson had the...honor...of seeing what was going on over there, and we haven't heard back from him since. You look like the type that doesn't like to die, you should go see if he's ok! He's supposed to be inside the hall on the south end of the cavern ahead...though something tells me he may not have made it quite that far.", ["objectivesText"] = "Find Kevin Dawson .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27567] = { ["id"] = 27567, ["name"] = "Twilight?! No!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27567 }, ["series"] = { 27565 }, ["description"] = "This is a little hard to believe, but there are Twilight's Hammer members here in Blackrock Depths ! I don't know how many there are crawling throughout this place, but I did hear that their lead interrogator, Gerstahn, is in this hallway. I don't know what they're here torturing for, but maybe you can find out by confronting Gerstahn?", ["objectivesText"] = "\"Interrogate\" High Interrogator Gerstahn . Progress: Go! Go! Go!", ["rewardGold"] = 1123600, ["rewardXP"] = 2075, ["rewardItems"] = { 33250, 52605, 52627, 57290, 57291, 57292, 57293, 57851, 63652, 63653, 63654, 63655, 63787, 63788, 63789, 63790, 63791, 63792, 63868, 63869, 63870, 65616, 65633, 65634, 65635, 65636, 65637, 72884, 72886, 76153, 131253, 131280, 237812, 246445, 260468, 260469, 260470, 260471 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27568] = { ["id"] = 27568, ["name"] = "Infiltrating Shadowforge City", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27568 }, ["series"] = { 27569, 27571, 27573, 27578 }, ["description"] = "Can ye keep a secret? I have a secret tae share with ye if ye can. Everybody here is CRAZY!!! There's goblins over there, Dark Irons right over there, and a giant living fire thing right past this gate! An' that's just what I see in this little cave! And ye! What're ye doin' here!? Oh, I see. Winky sent ye, did he? Sent ye tae talk t' Prospector Seymour , past this gate and t' the right, did he? Well go! Oralius doesn't even care! ...I'll GET YOU FOR THIS WINKY!!! < Oralius begins to sob.>", ["objectivesText"] = "Speak to Prospector Seymour .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27569] = { ["id"] = 27569, ["name"] = "Dark Iron Tacticians", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27569 }, ["series"] = { 27568, 27571, 27573, 27578 }, ["description"] = "General Angerforge and Golem Lord Argelmach lead the Dark Iron armies and their golems against us. If we are to overcome them, the two must be slain. Go through this door and unlock The Shadowforge Lock, which separates the East and West Garrisons. Then, follow the stairs and keep to the left at the top until you reach the West Garrison. It is there you will find the General and Golem Lord. Keep your wits about you, they are both well-seasoned combatants. Find Mayara Brightwing should you succeed.", ["objectivesText"] = "Kill General Angerforge and Golem Lord Argelmach .", ["rewardGold"] = 1239200, ["rewardXP"] = 2075, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27571] = { ["id"] = 27571, ["name"] = "The Grim Guzzler", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27571 }, ["series"] = { 27568, 27569, 27573, 27578 }, ["description"] = "Some say that the Grim Guzzler is the secret to the Dark Iron war effort. Their warriors recharge there and emerge thirsty for another innocent soul. I think we can seriously hinder them by causing a bit of chaos here. I need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot ...just talk to the little hothead. Report to Orfus when you're done.", ["objectivesText"] = "Fight Hurley Blackbreath , Plugger Spazzring , and Ribbly Screwspigot . Progress: Hurry, please. Time is not a luxury we currently have.", ["rewardGold"] = 309800, ["rewardXP"] = 5530, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27573] = { ["id"] = 27573, ["name"] = "The Dark Iron Pact", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27573 }, ["series"] = { 27568, 27569, 27571, 27578 }, ["description"] = "Ahead is the creature known only as Ambassador Flamelash . He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world. You may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them, so that this nation may perhaps one day be redeemed.", ["objectivesText"] = "Kill Ambassador Flamelash and Doom'rel .", ["rewardGold"] = 309800, ["rewardXP"] = 5530, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27578] = { ["id"] = 27578, ["name"] = "Morgan's Fruition", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27578 }, ["series"] = { 27568, 27569, 27571, 27573 }, ["description"] = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign. You'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne. Note that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", ["objectivesText"] = "Kill Emperor Dagran Thaurissan . Progress: If you do not succeed, I have no doubt that Thaurissan will execute the lot of us.", ["rewardGold"] = 280900, ["rewardXP"] = 5530, ["rewardItems"] = { 65932, 65956, 65980 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27579] = { ["id"] = 27579, ["name"] = "Into the Prison", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27579 }, ["series"] = { 27581 }, ["description"] = "Da Twilight's Hammer be here for some reason. We don't know why, but Thal'trak be lettin' you in on a lil' secret of ours - da rogue Lexlort waits outside da hall where High Interrogator Gerstahn be so he can kill her if he gets da chance. She's too smart for dat, though, so you gonna go in an' do it, ya? Go talk to Lexlort and let him know. I'm sure he be ok with it.", ["objectivesText"] = "Find Lexlort .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27581] = { ["id"] = 27581, ["name"] = "Twilight?! No!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27581 }, ["series"] = { 27579 }, ["description"] = "Gerstahn is too heavily guarded and too smart to leave her post, so I'm not going to kill her. You are. I'll throw in a little something I picked up off of a guard to make it worth your while.", ["objectivesText"] = "Kill High Interrogator Gerstahn . Progress: Does it look like I want to be waiting her any longer than is necessary?", ["rewardGold"] = 280900, ["rewardXP"] = 5530, ["rewardItems"] = { 33250, 52605, 52627, 57290, 57291, 57292, 57293, 57851, 63652, 63653, 63654, 63655, 63787, 63788, 63789, 63790, 63791, 63792, 63868, 63869, 63870, 65616, 65633, 65634, 65635, 65636, 65637, 72884, 72886, 76153, 131253, 131280, 237812, 246445, 260468, 260469, 260470, 260471 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27582] = { ["id"] = 27582, ["name"] = "Infiltrating Shadowforge City", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27582 }, ["series"] = { 27585, 27589, 27591, 27593 }, ["description"] = "We're fighting a losing battle right now, I'm afraid. The Dark Irons would be difficult to defeat on their own, but their elemental allies have given them new bleeding edge warriors that we simply can't compete with. I need you to help us infiltrate their domain and kill as many of their vital leaders as possible. Hopefully that will shock their forces and turn the tide in our favor. Report to Razal'blade for further instruction. He's stationed beyond this gate and to the right.", ["objectivesText"] = "Speak to Razal'blade .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27585] = { ["id"] = 27585, ["name"] = "The 109th Division", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27585 }, ["series"] = { 27582, 27589, 27591, 27593 }, ["description"] = "General Angerforge and Golem Lord Argelmach are directly responsible for the horrific slaughter of the 109th Division of the Kargath Expeditionary Force. There were a lot of good trolls and orcs in that division, many of them my close friends. Well, young <race>, it's time for our fallen brothers to at last have their revenge. Unlock The Shadowforge Lock, go up the stairs and bear left until you reach the West Garrison. Kill Angerforge and Argelmach, and don't you dare show them any mercy.", ["objectivesText"] = "Kill General Angerforge and Golem Lord Argelmach . Progress: I'm quite surprised to see you here! You'll be very useful indeed.", ["rewardGold"] = 105000, ["rewardXP"] = 5530, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27588] = { ["id"] = 27588, ["name"] = "Signal the Attack", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 27177, 27178, 27299, 27300, 27301, 27302, 27303, 27338, 27341, 27366, 27376, 27377, 27378, 27379, 27380, 27433, 27468, 27485, 27490, 27492, 27494, 27496, 27498, 27500, 27502, 27504, 27505, 27506, 27507, 27508, 27509, 27514, 27515, 27516, 27537, 27538, 27545, 27564, 27588, 27608, 27621, 27636, 27637, 27640, 27641, 27642, 27643, 27644, 27645, 27646, 27647, 27648, 27649, 27650, 27651, 27652, 27654, 27657, 27659, 27660, 27661, 27662, 27688, 27695, 27700, 27702, 27719, 27720, 27742, 27743, 27744, 27745, 27752, 27753, 27754, 27784, 27787, 27803, 27804, 27805, 27806, 27807, 27808, 27809, 27810, 27811, 27812, 27813, 27814, 27815, 27816, 27817, 27861, 27862, 27863, 27864, 27866, 27867, 27868, 27999, 28101, 28103, 28104, 28107, 28108, 28109, 28171, 28173, 28175, 28176, 28191, 28211, 28212, 28215, 28233, 28234, 28238, 28241, 28242, 28243, 28244, 28247, 28248, 28280, 28281, 28282, 28294, 28346, 28377, 28378, 28379, 28407, 28408, 28409, 28410, 28411, 28413, 28596, 28597, 28598, 28599, 28655, 28712, 28758, 28832 }, ["description"] = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", ["objectivesText"] = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 61511 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 45668, ["x"] = 0.434, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 546, ["name"] = "Twilight Highlands", ["orderIndex"] = 194, ["flags"] = 0 } } },
[27589] = { ["id"] = 27589, ["name"] = "The Grim Guzzler", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27589 }, ["series"] = { 27582, 27585, 27591, 27593 }, ["description"] = "Everyone inside the Grim Guzzler is absolutely hammered and, therefore, easily angered. I think we can seriously hinder the Dark Irons by causing a bit of chaos here. I need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot ...just talk to the little hothead. Report to Thunderheart when you're done.", ["objectivesText"] = "Fight Hurley Blackbreath , Plugger Spazzring , and Ribbly Screwspigot . Progress: Hurry, please. Time is not a luxury we currently have.", ["rewardGold"] = 105000, ["rewardXP"] = 5530, ["rewardItems"] = { 11325 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27590] = { ["id"] = 27590, ["name"] = "Signal the Attack", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 26293, 26294, 26311, 26324, 26335, 26337, 26358, 26361, 26372, 26374, 26388, 26538, 26539, 26540, 26549, 26608, 26619, 26621, 26622, 26784, 26786, 26788, 26798, 26830, 26840, 27299, 27300, 27301, 27302, 27303, 27376, 27377, 27378, 27379, 27380, 27486, 27491, 27493, 27495, 27497, 27499, 27501, 27503, 27504, 27505, 27506, 27507, 27508, 27509, 27564, 27576, 27583, 27584, 27586, 27590, 27606, 27607, 27609, 27610, 27611, 27622, 27638, 27639, 27653, 27655, 27658, 27659, 27660, 27661, 27662, 27689, 27690, 27696, 27701, 27703, 27742, 27743, 27744, 27745, 27747, 27750, 27751, 27786, 27788, 27798, 27861, 27862, 27863, 27865, 27866, 27867, 27868, 27929, 27945, 27947, 27951, 27954, 27955, 28041, 28043, 28090, 28091, 28092, 28093, 28094, 28097, 28123, 28133, 28171, 28173, 28175, 28176, 28191, 28247, 28249, 28583, 28584, 28586, 28588, 28589, 28590, 28591, 28592, 28593, 28594, 28595, 28712, 28758, 28849, 28885 }, ["description"] = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", ["objectivesText"] = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 61511 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 45658, ["x"] = 0.452, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 546, ["name"] = "Twilight Highlands", ["orderIndex"] = 195, ["flags"] = 0 } } },
[27591] = { ["id"] = 27591, ["name"] = "The Dark Iron Pact", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27591 }, ["series"] = { 27582, 27585, 27589, 27593 }, ["description"] = "Inside this chamber lies Ambassador Flamelash . He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world. You may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them all, and may this unholy union cease.", ["objectivesText"] = "Kill Ambassador Flamelash and Doom'rel .", ["rewardGold"] = 309800, ["rewardXP"] = 5530, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27593] = { ["id"] = 27593, ["name"] = "Rebirth of the K.E.F.", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27593 }, ["series"] = { 27582, 27585, 27589, 27591 }, ["description"] = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign. You'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne. Note that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", ["objectivesText"] = "Kill Emperor Dagran Thaurissan . Progress: If you do not succeed, I have no doubt that Thaurissan will execute the lot of us.", ["rewardGold"] = 280900, ["rewardXP"] = 5530, ["rewardItems"] = { 11885, 68052, 68053, 68054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27596] = { ["id"] = 27596, ["name"] = "The Heart of the Mountain", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27596 }, ["description"] = "For years I have sought a certain gem. It is called the Heart of the Mountain and it's the size of your fist! The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it. So I must resort to force. Fight your way to The Black Vault near the Hall of Crafting, breach its secret safe and gain the Heart. To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault! Good luck.", ["objectivesText"] = "Obtain the Heart of the Mountain . Progress: Do you have the Heart of the Mountain ? To me, its value is without limit.", ["rewardGold"] = 105000, ["rewardXP"] = 5530, ["rewardItems"] = { 11078, 11309, 123975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27603] = { ["id"] = 27603, ["name"] = "The Sealed Gate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1584, ["storyline"] = { 27603 }, ["description"] = "At one end of the Dark Iron Highway stands a massive gate much like the one that protects Shadowforge City on the opposite side. However, we have no idea what's behind it! All we know is that it's heavily guarded by Anvilrage patrols and the molten giant Bael'gar . You simply must dispose of them and see if you can pry that gate open! Just imagine what could lie behind it...there could be an entire other half of the city we never knew about! Or nothing! Who knows! Though, it's probably something...", ["objectivesText"] = "Kill Bael'gar . Progress: Were you able to get past the gate? Or scale it? What's behind it???", ["rewardGold"] = 280900, ["rewardXP"] = 5530, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[27604] = { ["id"] = 27604, ["name"] = "Jammal'an the Prophet", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1477, ["storyline"] = { 27604 }, ["description"] = "Jammal'an the Prophet, leader of the Atal'ai and Hakkari trolls, has obtained a small amount of Hakkar the Soulflayer's blood. They are injecting it into the green dragons to use their bodies to produce the massive quantities of blood necessary to summon Hakkar into our world. We cannot allow this to come to pass. Slaughter Jammal'an and his priests before they get any further in their efforts!", ["objectivesText"] = "Obtain Jammal'an the Prophet's Head. Progress: Were you able to kill Jammal'an? I'll need proof that the deed is done.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 6212 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1477 } }, ["questType"] = "dungeon" },
[27605] = { ["id"] = 27605, ["name"] = "Eranikus", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1477, ["storyline"] = { 27605 }, ["description"] = "The Hakkar blood the Atal'ai have been injecting into the green dragons has had devastating effects on the dragons themselves. It appears that these dragons, former jailors of the Atal'ai, have been corrupted by its presence in their bodies and have become creatures of Nightmare. Eranikus, Ysera's primary consort and lead watcher over the temple, was infused with the largest quantities of blood and has become twisted beyond imagination. After Jammal'an is dead, find Eranikus and end him.", ["objectivesText"] = "Kill Eranikus. Progress: Did you defeat Eranikus?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 65931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1477 } }, ["questType"] = "dungeon" },
[27608] = { ["id"] = 27608, ["name"] = "Four Heads are Better than None", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 27177, 27178, 27299, 27300, 27301, 27302, 27303, 27338, 27341, 27366, 27376, 27377, 27378, 27379, 27380, 27433, 27468, 27485, 27490, 27492, 27494, 27496, 27498, 27500, 27502, 27504, 27505, 27506, 27507, 27508, 27509, 27514, 27515, 27516, 27537, 27538, 27545, 27564, 27588, 27608, 27621, 27636, 27637, 27640, 27641, 27642, 27643, 27644, 27645, 27646, 27647, 27648, 27649, 27650, 27651, 27652, 27654, 27657, 27659, 27660, 27661, 27662, 27688, 27695, 27700, 27702, 27719, 27720, 27742, 27743, 27744, 27745, 27752, 27753, 27754, 27784, 27787, 27803, 27804, 27805, 27806, 27807, 27808, 27809, 27810, 27811, 27812, 27813, 27814, 27815, 27816, 27817, 27861, 27862, 27863, 27864, 27866, 27867, 27868, 27999, 28101, 28103, 28104, 28107, 28108, 28109, 28171, 28173, 28175, 28176, 28191, 28211, 28212, 28215, 28233, 28234, 28238, 28241, 28242, 28243, 28244, 28247, 28248, 28280, 28281, 28282, 28294, 28346, 28377, 28378, 28379, 28407, 28408, 28409, 28410, 28411, 28413, 28596, 28597, 28598, 28599, 28655, 28712, 28758, 28832 }, ["series"] = { 27502, 27636 }, ["description"] = "We're about to launch the attack upon the Twilight Gate, but there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall. Intelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate. Would you go back in there and kill them?", ["objectivesText"] = "Collect the four heads of Za'brox and Beeble'phod. Progress: Is that blood dripping from your pack?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 61924, 61925, 61926, 61927, 63742, 63743, 63744, 63745, 63746, 63747 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 45669, ["x"] = 0.