[27609] = { ["id"] = 27609, ["name"] = "Four Heads are Better than None", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 26293, 26294, 26311, 26324, 26335, 26337, 26358, 26361, 26372, 26374, 26388, 26538, 26539, 26540, 26549, 26608, 26619, 26621, 26622, 26784, 26786, 26788, 26798, 26830, 26840, 27299, 27300, 27301, 27302, 27303, 27376, 27377, 27378, 27379, 27380, 27486, 27491, 27493, 27495, 27497, 27499, 27501, 27503, 27504, 27505, 27506, 27507, 27508, 27509, 27564, 27576, 27583, 27584, 27586, 27590, 27606, 27607, 27609, 27610, 27611, 27622, 27638, 27639, 27653, 27655, 27658, 27659, 27660, 27661, 27662, 27689, 27690, 27696, 27701, 27703, 27742, 27743, 27744, 27745, 27747, 27750, 27751, 27786, 27788, 27798, 27861, 27862, 27863, 27865, 27866, 27867, 27868, 27929, 27945, 27947, 27951, 27954, 27955, 28041, 28043, 28090, 28091, 28092, 28093, 28094, 28097, 28123, 28133, 28171, 28173, 28175, 28176, 28191, 28247, 28249, 28583, 28584, 28586, 28588, 28589, 28590, 28591, 28592, 28593, 28594, 28595, 28712, 28758, 28849, 28885 }, ["series"] = { 27503, 27638 }, ["description"] = "Now, while we're about to launch the attack upon the Twilight Gate, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall. Intelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate. Please head back in and kill them.", ["objectivesText"] = "Collect the four heads of Za'brox and Beeble'phod. Progress: Is that blood dripping from your pack? I hope that it's not yours.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 9648, 30632, 61924, 61925, 61926, 61927, 63742, 63743, 63744, 63745, 63746, 63747 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 45665, ["x"] = 0.452, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 45665, ["x"] = 0.452, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 546, ["name"] = "Twilight Highlands", ["orderIndex"] = 199, ["flags"] = 0 } } },
[27633] = { ["id"] = 27633, ["name"] = "The Blood God Hakkar", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1477, ["storyline"] = { 27633 }, ["description"] = "Hakkar... The mere mention of The Soulflayer's name will send many running. In the Sanctum of the Fallen God the Atal'ai have recovered a significant portion of his skeleton and seek to restore him to life. Already his children have begun to show up in the area. Place this egg in that sanctum, and it will force his summoning prematurely. <name>, do not hesitate. Strike once his avatar appears!", ["objectivesText"] = "Kill the Avatar of Hakkar .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 10465 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1477 } }, ["questType"] = "dungeon" },
[27635] = { ["id"] = 27635, ["name"] = "Decontamination", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 30, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 27674 }, ["description"] = "You've been down here in Gnomeregan for a long time, <name>, and it's amazing that you've survived and kept your wits so long! We need to get you out. Before we can send you to the surface to join the rest of the gnomes, you have to go through the decontamination process. Just head into the next room and board the Sanitron 500 . It will do the rest! It shouldn't even hurt... much. When you're all done, check in with Technician Braggle and he'll make sure you get some suitable gear.", ["objectivesText"] = "Board the Sanitron 500 to begin the decontamination process.", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 30, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 4, ["flags"] = 0 } } },
[27664] = { ["id"] = 27664, ["name"] = "Darkmoon Volcanic Deck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 27664 }, ["description"] = "Now that you have gathered all of the Ember cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Volcanic Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Volcanic deck ! Congratulations!", ["rewardItems"] = { 62021, 62047 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 62021 } },
[27665] = { ["id"] = 27665, ["name"] = "Darkmoon Hurricane Deck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 27665 }, ["description"] = "Now that you have gathered all of the Wind cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Hurricane Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Hurricane deck ! Congratulations!", ["rewardItems"] = { 19289, 62045, 62049, 62051 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 62045 } },
[27666] = { ["id"] = 27666, ["name"] = "Darkmoon Tsunami Deck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 27666 }, ["description"] = "Now that you have gathered all of the Wave cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Tsunami Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Tsunami deck ! Congratulations!", ["rewardItems"] = { 62012, 62013, 62014, 62015, 62016, 62017, 62018, 62019, 62044, 62050 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 62044 } },
[27667] = { ["id"] = 27667, ["name"] = "Darkmoon Earthquake Deck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 27667 }, ["description"] = "Now that you have gathered all of the Stone cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Earthquake Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete an Earthquake deck ! Congratulations!", ["rewardItems"] = { 62046, 62047, 62048, 62049, 62050, 62051 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 62046 } },
[27668] = { ["id"] = 27668, ["name"] = "Pay Attention!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 27668 }, ["series"] = { 25942, 25943, 25944, 25946, 25947, 25948, 25949 }, ["description"] = "Listen, <race>. It's not that I don't appreciate the rescue and all, but this is a dire situation. You have to pay better attention out there! I was watching, and you passed right over a busted alliance crate. There's bound to be something in there that could help me and my boys. How about you get out there and take a look-see, hrm?", ["objectivesText"] = "Nazgrim wants you to see what lies in the broken Alliance crate north of The Immortal Coil.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 55186 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 41711, ["x"] = 0.39, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard" },
[27670] = { ["id"] = 27670, ["name"] = "Pinned Down", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredRaces"] = { 7, 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 30, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["description"] = "My name is Nevin Twistwrench and I'm the commander of the Survivor Assistance Facilitation Expedition, or S.A.F.E. I don't know how you managed to survive the radiation down here, <name>, but most of the others haven't fared so well. My team is rounding up the survivors, but the radiation-addled leper gnomes are too numerous for us to hold back much longer. They've lost their minds! If you're still strong enough to wield a weapon or cast a spell, would you help us clear out some of these leper gnomes?", ["objectivesText"] = "Kill 6 Crazed Leper Gnomes . Progress: Help my men get the way cleared out so we can help the other survivors get out of here!", ["rewardGold"] = 2000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 30, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 0, ["flags"] = 0 } } },
[27671] = { ["id"] = 27671, ["name"] = "See to the Survivors", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredRaces"] = { 7, 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 30, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 28167 }, ["description"] = "If we don't do something quick, neither Nevin nor the survivors will make it out of here alive. I'm going to give you my squad's emergency teleport beacon . We still have enough strength and ammunition to fight our way out of here, but those survivors are in no condition to make a run for it. Use the beacon on survivors to arrange for them to be teleported out of here to the safe area my men have set up. Once you've done that, report back to me and we'll make arrangements to get you out of here.", ["objectivesText"] = "Use the Teleport Beacon to teleport 6 Survivors to safety. Progress: Nevin's team found a lot of survivors this time, but he's cutting it awful close.", ["rewardGold"] = 2000, ["rewardXP"] = 300, ["rewardItems"] = { 62057 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 30, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 2, ["flags"] = 0 } } },
[27672] = { ["id"] = 27672, ["name"] = "The Chamber of Khaz'mul", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27672 }, ["series"] = { 27677 }, ["description"] = "In the Map Chamber there is a door which leads to the legendary Chamber of Khaz'mul. Who knows what secrets could be hidden inside! What we do know is that it is guarded by Ironaya , a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to unlock the secrets of Uldaman !", ["objectivesText"] = "Defeat Ironaya .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27673] = { ["id"] = 27673, ["name"] = "It's What's Inside That Counts", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27673 }, ["description"] = "The Makers built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something. I fear that one of the Old Gods is responsible for this, and you're going to help me see if that's the case! Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", ["objectivesText"] = "Obtain the Obsidian Power Core and the Titan Power Core . Progress: Where are the cores, lad? By Muradin's Beard, where are the bloody cores? <Kand takes a deep breath.> Sorry about that. Have you been able to obtain the cores?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 62053, 62055 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27674] = { ["id"] = 27674, ["name"] = "To the Surface", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26421, 26422, 26423, 26424, 26425, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 31135, 31137, 41217, 41218 }, ["series"] = { 27635 }, ["description"] = "Nevin has just sent word that he and his men are making their way to the surface. He'll be waiting for you in the building that S.A.F.E. has established as its headquarters. See Torben Zapblast over there? Talk to him when you're ready to head to the surface and he'll arrange to have you transported up there. It's been a pleasure meeting you, <name>, and I'm honored to have played a small role in helping you escape from Gnomeregan to start your life on the surface.", ["objectivesText"] = "Speak to Torben Zapblast to get teleported to the surface and report to Nevin Twistwrench . Progress: It's good to see you again, <name>.", ["rewardGold"] = 200, ["rewardXP"] = 25, ["rewardItems"] = { 152668, 162339 }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42396, ["x"] = 0.339, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 5, ["flags"] = 0 } } },
[27675] = { ["id"] = 27675, ["name"] = "Forged Documents", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27675 }, ["description"] = "Find a resident in Stormwind City to accept your forged documents .", ["objectivesText"] = "Find a resident of Stormwind City to accept your Forged Documents . Progress: Do you have something for me?", ["rewardItems"] = { 43126, 43127, 61978, 61980, 61981, 62056, 62062 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 332, ["x"] = 0.658667, ["y"] = 0.536 }, { ["mapID"] = 84, ["npcID"] = 3518, ["x"] = 0.634267, ["y"] = 0.711333 }, { ["mapID"] = 84, ["npcID"] = 8670, ["x"] = 0.609, ["y"] = 0.713 }, { ["mapID"] = 84, ["npcID"] = 14721, ["x"] = 0.712, ["y"] = 0.805 }, { ["mapID"] = 84, ["npcID"] = 29142, ["x"] = 0.614, ["y"] = 0.6455 }, { ["mapID"] = 84, ["npcID"] = 43693, ["x"] = 0.775, ["y"] = 0.6745 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.658667, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 62056 } },
[27676] = { ["id"] = 27676, ["name"] = "Behind Closed Doors", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27676 }, ["description"] = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about! I've had it with their men getting in the way of our work here! The Explorers' League is the only group authorized to handle the artifacts throughout Uldaman ! Go to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", ["objectivesText"] = "Kill Galgann Firehammer .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27677] = { ["id"] = 27677, ["name"] = "Archaedas, The Ancient Stone Watcher", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27677 }, ["series"] = { 27672 }, ["description"] = "The true goal in Uldaman is to obtain the Discs of Norgannon. The secrets on these discs could change everything about how we view our world. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine. The problem is that Archaedas , an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for the Explorers' League!", ["objectivesText"] = "Defeat Archaedas .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27679] = { ["id"] = 27679, ["name"] = "The Chamber of Khaz'mul", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27679 }, ["series"] = { 27680 }, ["description"] = "In the Map Chamber there is a locked door which I believe leads to the legendary Chamber of Khaz'mul. We do not yet know what artifacts wait inside it. What we do know is that it is guarded by Ironaya , a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to progress any further into this place.", ["objectivesText"] = "Defeat Ironaya .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27680] = { ["id"] = 27680, ["name"] = "Archaedas, The Ancient Stone Watcher", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27680 }, ["series"] = { 27679 }, ["description"] = "The true goal in Uldaman is to obtain the Discs of Norgannon. These platinum discs could grant our order unbelievable power. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine. The only problem in obtaining them is that Archaedas , an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for The Reliquary.", ["objectivesText"] = "Defeat Archaedas .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27681] = { ["id"] = 27681, ["name"] = "Behind Closed Doors", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27681 }, ["description"] = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about! I've had it with their men getting in the way of our work here! The Reliquary is the only group authorized to handle the artifacts throughout Uldaman ! Go to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", ["objectivesText"] = "Kill Galgann Firehammer .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27682] = { ["id"] = 27682, ["name"] = "We Require More Minerals", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1337, ["storyline"] = { 27682 }, ["description"] = "The Titans built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something. I suspect that one of the Old Gods is responsible for this, and you're going to help me see if that is indeed true. Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", ["objectivesText"] = "Obtain the Obsidian Power Core and the Titan Power Core . Progress: Do you have the cores with you, or are you just here to chat? Perhaps we should stop this whole charade and enjoy some snacks and fine wine instead?", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 62053, 62055, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1337 } }, ["questType"] = "dungeon" },
[27685] = { ["id"] = 27685, ["name"] = "Good Deed Left Undone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 27685 }, ["series"] = { 25587, 25598 }, ["description"] = "G'day, <laddie/lassie>. The name's Rendel. Seems ol' Moanah and I got here in the nick of time, eh? Erunak wasn't kiddin' when he said it was life or death! So... in our rush ta git over here, we left a little unfinished business off to the east a ways. A little lady was near death herself. We had no choice but ta leave her by a little air vent when we came here to yer rescue. How bout yeh git over and help her while there's still time?", ["objectivesText"] = "Speak to Adarrah in the Kelp'thar Forest .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 53053, 54345, 54639, 55186 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 41252, ["x"] = 0.465, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39667, ["x"] = 0.534667, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard" },
[27686] = { ["id"] = 27686, ["name"] = "Forged Documents", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27686 }, ["description"] = "Find a resident in Orgimmar to accept your forged documents .", ["objectivesText"] = "Find a resident of Orgimmar to accept your Forged Documents . Progress: Do you have something for me?", ["rewardItems"] = { 61978, 62062, 63276 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 14375, ["x"] = 0.5102, ["y"] = 0.7734 }, { ["mapID"] = 85, ["npcID"] = 17098, ["x"] = 0.487333, ["y"] = 0.715333 }, { ["mapID"] = 85, ["npcID"] = 44853, ["x"] = 0.485, ["y"] = 0.829 }, { ["mapID"] = 85, ["npcID"] = 44871, ["x"] = 0.536667, ["y"] = 0.738 }, { ["mapID"] = 85, ["npcID"] = 46708, ["x"] = 0.565, ["y"] = 0.614 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5102, ["y"] = 0.7734 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["startItems"] = { 63276 } },
[27687] = { ["id"] = 27687, ["name"] = "An Opened Can of Whoop Gnash", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 27687 }, ["description"] = "What an accomplishment, felling a mighty sea giant! The new residents of Smuggler's Hole will feel considerably safer knowing this monster is no longer loitering outside their haven.", ["objectivesText"] = "Bring Gnash's Head to Samir in Smuggler's Hole. Progress: You took down that Sea Giant, <class>?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 55186, 62138 }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39884, ["x"] = 0.572, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 62138 } },
[27692] = { ["id"] = 27692, ["name"] = "Princess Theradras", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 2100, ["storyline"] = { 27692 }, ["description"] = "Do not be alarmed, young <race>. I am Zaetar, son of Cenarius, and I come to you for your assistance. Long ago, I made the mistake of mating with Princess Theradras , a powerful earth elemental aligned with the Old Gods. Our children, the centuar Kahns, turned on me upon birth and slew me mercilessly. Now, Theradras' taint runs deep and threatens far more than just Maraudon . Come slay her and free my spirit so that we may restore Desolace to a place of verdant life and promise, as Cenarius would want.", ["objectivesText"] = "Kill Princess Theradras .", ["rewardGold"] = 280900, ["rewardXP"] = 2830, ["rewardItems"] = { 65919, 65945, 65969, 65992, 66008, 131681, 131682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2100 } }, ["questType"] = "dungeon" },
[27697] = { ["id"] = 27697, ["name"] = "Corruption in Maraudon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 2100, ["storyline"] = { 27697 }, ["description"] = "<name>, I require your assistance immediately! I am Zaetar, son of Cenarius, and I am trapped here after an unfortunate series of events! Before saving me is an option, you must help me clean out the corruption that runs so rampant through Maraudon . Lord Vyletongue is the satyr ruler of the purple crystal caverns. He is an insidious agent of the Burning Legion and his continued presence can only lead to chaos and death. He can live no longer!", ["objectivesText"] = "Kill Lord Vyletongue .", ["rewardGold"] = 280900, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2100 } }, ["questType"] = "dungeon" },
[27698] = { ["id"] = 27698, ["name"] = "Servants of Theradras", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 2100, ["storyline"] = { 27698 }, ["description"] = "Princess Theradras, my former mate, has used her enormous power to corrupt the very nature of Maraudon . Even now her creations run rampant here, and I fear that they may soon escape into the open world to sow the seeds of death and destruction. <name>, venture forth and kill Noxxion and Razorlash . They are two of her most powerful minions and their deaths would cause the callous Princess much deserved grief and suffering of her own. Then, perhaps, you can help free my spirit from her grasp.", ["objectivesText"] = "Kill Noxxion and Razorlash .", ["rewardGold"] = 105000, ["rewardXP"] = 2830, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2100 } }, ["questType"] = "dungeon" },
[27716] = { ["id"] = 27716, ["name"] = "Piece of the Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 27716 }, ["description"] = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.> < Levia Dreamwaker , back with the Nespirah survivors, was looking for something exactly like this.>", ["objectivesText"] = "Bring the Ancient Elven Etching to Levia Dreamwalker. You should find her with the Alliance Nespirah Survivors. Progress: Hah! Did you see the admiral giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess. I'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 54614, 55171, 55966, 59693, 59694, 59695, 59696, 59697, 59698, 62281 }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 40644, ["x"] = 0.4125, ["y"] = 0.623 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.4125, ["y"] = 0.623 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 5144 } }, ["questType"] = "standard", ["startItems"] = { 62281 } },
[27717] = { ["id"] = 27717, ["name"] = "Piece of the Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 27717 }, ["description"] = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.> < Elendri Goldenbrow , back with the Nespirah survivors, was looking for something exactly like this.>", ["objectivesText"] = "Bring the Ancient Elven Etching to Elendri Goldenbrow . You should find her with the Horde Nespirah Survivors. Progress: Hah! Did you see the captain giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess. I'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 55966, 59693, 59694, 59695, 59696, 59697, 59698, 62282 }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 40920, ["x"] = 0.473333, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.473333, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 5144 } }, ["questType"] = "standard", ["startItems"] = { 62282 } },
[27718] = { ["id"] = 27718, ["name"] = "Warchief's Command: Vashj'ir!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 27718, 27721, 27722, 28557, 28717, 60887 }, ["series"] = { 25924, 25929, 25936, 25941, 28805, 28816 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Commander Thorak at Bladefist Bay in Durotar. Now, more than ever, your help is needed in battling our most hated enemy, the Alliance! To reach Bladefist Bay you must travel south through the main gates of Orgrimmar and enter Durotar. From there, follow the path east to the coast. Thorak will be standing at his post near the docks. Onward, <brother/sister>! Destiny calls!", ["objectivesText"] = "Report to Commander Thorak at Bladefist Bay in Durotar.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 55186 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 41621, ["x"] = 0.558, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 5580, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 2, ["flags"] = 0 } } },
[27721] = { ["id"] = 27721, ["name"] = "Warchief's Command: Mount Hyjal!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 80, ["storyline"] = { 27718, 27721, 27722, 28557, 28717, 60887 }, ["series"] = { 25316, 25317, 25319, 27726, 49855 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Emissary Windsong at Nighthaven in Moonglade. Our brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground! Speak with Cenarion Emissary Blackhoof to gain entry into Moonglade. Blackhoof is located at the tauren district in the Valley of Wisdom in Orgrimmar. Onward, <brother/sister>! Destiny calls!", ["objectivesText"] = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", ["rewardGold"] = 13740, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 39865, ["x"] = 0.454667, ["y"] = 0.447333 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.447333 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5580, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 1, ["flags"] = 0 } } },
[27722] = { ["id"] = 27722, ["name"] = "Warchief's Command: Deepholm!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27718, 27721, 27722, 28557, 28717, 60887 }, ["series"] = { 26245, 26246, 26247, 27123, 27203, 27727 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Farseer Krogar at the Western Earthshrine in Orgrimmar. The Earthen Ring, lead by our former Warchief, Thrall, requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world! The Western Earthshrine can be found just north of the Valley of Wisdom. Onward, <brother/sister>! Destiny calls!", ["objectivesText"] = "Speak with Farseer Krogar at the Western Earthshrine in Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.469714, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5580, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 3, ["flags"] = 0 } } },
[27724] = { ["id"] = 27724, ["name"] = "Hero's Call: Vashj'ir!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27724, 27726, 27727, 28558, 28716, 60891 }, ["series"] = { 14481, 14482, 24432, 25281, 25405, 28825, 28826, 28827 }, ["description"] = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Recruiter Burns in Stormwind Harbor. Recent attacks by the Horde on our trade ships must be met with swift and just force! Stormwind Harbor can be found in the northwest region of Stormwind City . For the glory and honor of the Alliance! Fight on, <brother/sister>!", ["objectivesText"] = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 53053, 54345, 54639, 55186 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 36799, ["x"] = 0.2745, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.2745, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5581, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 2, ["flags"] = 0 } } },
[27726] = { ["id"] = 27726, ["name"] = "Hero's Call: Mount Hyjal!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 80, ["storyline"] = { 27724, 27726, 27727, 28558, 28716, 60891 }, ["series"] = { 25316, 25317, 25319, 27721, 49855 }, ["description"] = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Emissary Windsong at Nighthaven in Moonglade. Our brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground! Speak with Cenarion Emissary Jademoon in Stormwind Keep to gain entry into Moonglade. For the glory and honor of the Alliance! Fight on, <brother/sister>!", ["objectivesText"] = "Speak to Cenarion Emissary Jademoon to secure transportation to Moonglade. Progress: Help us!", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 39865, ["x"] = 0.454667, ["y"] = 0.447333 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.447333 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5581, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 1, ["flags"] = 0 } } },
[27727] = { ["id"] = 27727, ["name"] = "Hero's Call: Deepholm!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27724, 27726, 27727, 28558, 28716, 60891 }, ["series"] = { 26245, 26246, 26247, 27123, 27203, 27722 }, ["description"] = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City. The Earthen Ring requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world and destroy all life on Azeroth! The Eastern Earthshrine can be found directly northwest of Stormwind Keep. For the glory and honor of the Alliance! Fight on, <brother/sister>!", ["objectivesText"] = "Speak with Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5581, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 3, ["flags"] = 0 } } },
[27733] = { ["id"] = 27733, ["name"] = "The Good Ol' Switcheroo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 717, ["storyline"] = { 27733 }, ["description"] = "Look, I'd love to give the order and have my men blast these rebels to bits right now, but I can't because the entire Stockade is under Warden Thelwater's jurisdiction, and he only wants to contain them right now. Rather than disobey orders, we're going to take care of this in a slightly different manner! We've managed to befriend Mortimer Moloch, who just so happens to be the ruthless rebel leader Randolph Moloch 's twin. Kill Randolph, and we'll switch 'em so Mortimer can stop the rebellion peacefully!", ["objectivesText"] = "Kill Randolph Moloch . Progress: We can't make the switch until Randolph is dead!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 717 } }, ["questType"] = "dungeon" },
[27737] = { ["id"] = 27737, ["name"] = "By Fire Be Saved!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 717, ["storyline"] = { 27737 }, ["description"] = "I'm well-versed in first aid and other forms of healing, and with the help of my Lightwell I've been able to nurse many of our men back to full health. The problem we still have is that it's so cold and damp down here that I'm losing them anyways, despite healing their wounds! The quakes angered the elements that reside in the prison...when they erupted out of the earth they slaughtered half of the prisoners. If you slay their leader, Lord Overheat, and bring me his core I can use it to warm our men!", ["objectivesText"] = "Obtain Lord Overheat's Fiery Core . Progress: Do you have the core? Our men are dying in here!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 62305 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 717 } }, ["questType"] = "dungeon" },
[27739] = { ["id"] = 27739, ["name"] = "The Gnoll King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 717, ["storyline"] = { 27739 }, ["description"] = "<name>, I'm afraid I must ask of you the impossible. I received my eyepatch because he willed it so. Countless thousands have perished to his wrath. It was only by sheer miracle that we were able to imprison him here. Doing so was a grave mistake. We held out as long as we could, but then they came. From the shadows and darkness, gnolls in service of Hogger ripped my best men to pieces. You must defeat the Gnoll King, lest he mounts another attack and slaughters us all in cold, bloodthirsty rage.", ["objectivesText"] = "Defeat Hogger . Progress: Have you defeated Hogger ?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 65915, 65941, 65965, 65989, 131683 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 717 } }, ["questType"] = "dungeon" },
[27756] = { ["id"] = 27756, ["name"] = "The Foreman", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27756 }, ["description"] = "If we're to find out what's going on down here it looks like we're going to have to fight our way through the entire Deadmines! Glubtok the Foreman will be the first major foe you encounter, a powerful ogre magi. Be careful, he possesses the brute strength of his race backed by his wicked spellcasting! Take this communicator so that I can keep in touch with you as we continue our investigation. Be careful down there.", ["objectivesText"] = "Kill Glubtok . Progress: Yes?", ["rewardGold"] = 105000, ["rewardXP"] = 1010, ["rewardItems"] = { 60700, 60701, 60702, 62334, 131543, 219362, 219366, 219371, 219376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27758] = { ["id"] = 27758, ["name"] = "The Carpenter", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27758 }, ["description"] = "<Bzzzzzzzzzzzzt.> Hello, can you hear me? Excellent! It looks like Helix is in charge of building an enormous mast. You don't think they're trying to finish the Defias Juggernaut, do you? You'd better go investigate <name>, and don't be afraid to get your hands dirty! You have clearance to use deadly force if necessary and, let's face it, it's probably going to be necessary.", ["objectivesText"] = "Defeat Helix Gearbreaker . Progress: Yes?", ["rewardGold"] = 280900, ["rewardXP"] = 1010, ["rewardItems"] = { 62334 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27781] = { ["id"] = 27781, ["name"] = "The Machination", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27781 }, ["description"] = "<Bzzzzzzzzzzzzt.> <Bzzzzzzzzzzzzt.> He-hello? <name>, are you there? Are you still alive? Hello? Oh good, you're still there! What in the name of Lordareon are they building? It's some sort of mechanized monstrosity! You have to stop them from completing that...that...thing! Throw out the rules, do whatever you have to do to thwart them!", ["objectivesText"] = "Destroy the Foe Reaper 5000 .", ["rewardGold"] = 105000, ["rewardXP"] = 1010, ["rewardItems"] = { 62334, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27785] = { ["id"] = 27785, ["name"] = "The Admiral", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27785 }, ["series"] = { 27790 }, ["description"] = "<Bzzzzzzzzzzzzt.> I can't believe it...they're almost done rebuilding it! We don't have much time, <name>. Admiral Ripsnarl , Vanessa's right hand man, is bound to be on board. We'll never get to her if he's still alive to do anything about it. You're going to need to scale the unfinished Juggernaut, find Ripsnarl, and kill him so we can get to Vanessa's private quarters on the top deck. Be careful, the Admiral bears the worgen curse and would take much pleasure in digging his claws into you!", ["objectivesText"] = "Kill Admiral Ripsnarl .", ["rewardGold"] = 309800, ["rewardXP"] = 1010, ["rewardItems"] = { 44017, 44033, 44034, 44035, 62334, 114945, 118079, 118080, 118081, 118082, 118083, 118084, 118085, 118086, 123975, 152668, 162360, 163857, 165867, 165869, 166295, 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27790] = { ["id"] = 27790, ["name"] = "The Defias Kingpin", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27790 }, ["series"] = { 27785 }, ["description"] = "Hello there, <name>. I've heard a great deal about you. Listen closely, you're only going to have one solid shot at this. The new Defias Kingpin must be inside the hut orchestrating this entire operation. I want you to go inside and take her down, for the sake of the hundreds of innocent people the organization her father started has killed and terrorized. I'm shocked that she would let you get so close to her domain without fleeing and waiting until more favorable conditions, but it seems we're in luck.", ["objectivesText"] = "Kill the Defias Kingpin.", ["rewardGold"] = 105000, ["rewardXP"] = 1010, ["rewardItems"] = { 62334, 65935, 65959, 65983, 66019, 66028, 66037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27841] = { ["id"] = 27841, ["name"] = "The Grateful Dead", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Day of the Dead", ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 27841 }, ["description"] = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me! Might I trouble you for some more of that delicious Bread of the Dead ? I'd be most grateful... Chapman there sells the recipe, I think.", ["objectivesText"] = "Acquire some Bread of the Dead and give it to the Cheerful Goblin Spirit in Orgrimmar's graveyard. Use an Orange Marigold to see the otherwise invisible spirit. Progress: You don't have any Bread of the Dead , do you?", ["rewardXP"] = 200, ["rewardItems"] = { 46691, 46718, 46831 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 46901, ["x"] = 0.472, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 46901, ["x"] = 0.472, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2801 } },
[27842] = { ["id"] = 27842, ["name"] = "Only the Beginning", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27842 }, ["series"] = { 27848, 27850 }, ["description"] = "I miss the days when legions of powerful ogres marched by the Horde's side into battle, the pathetic Alliance cowering at their ferocity. Perhaps those days will return before I am gone to the ancestors. However, that is not the case now. An ogre magi, Glubtok , has joined forces with the despicable Defias Brotherhood and acts as Foreman over their mining operations. The pathetic fool! End his life for me, and for the spirit and glory of the Horde!", ["objectivesText"] = "Kill Glubtok .", ["rewardGold"] = 280900, ["rewardXP"] = 1010, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27844] = { ["id"] = 27844, ["name"] = "Traitors!!!", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27844 }, ["description"] = "The goblins you'll find working with the Defias are officially traitors to the Bilgewater Cartel, the Shattered Hand, and the Horde itself! I haven't yet been initiated into the Shattered Hand, so my loyalties lie strongly with my people. Helix Gearbreaker apparently has no time for such associations, and works on building a mast for the Defias Juggernaut. On behalf of Miss Mayhem and myself, would you kindly 'dispose' of Helix?", ["objectivesText"] = "Defeat Helix Gearbreaker . Progress: Yes?", ["rewardGold"] = 280900, ["rewardXP"] = 1010, ["rewardItems"] = { 22980, 22982, 22984, 22995, 63912, 63913, 63914, 63915, 63916, 113232, 113233, 113234, 113235, 155462, 155471, 155479, 155487, 156941, 158599, 158600, 158601, 158602, 248065, 248069, 250355, 251330, 251548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27846] = { ["id"] = 27846, ["name"] = "The Grateful Dead", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Day of the Dead", ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 27846 }, ["description"] = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me! Might I trouble you for some more of that delicious Bread of the Dead ? I'd be most grateful... Chapman there sells the recipe, I think.", ["objectivesText"] = "Acquire some Bread of the Dead and give it to the Cheerful Worgen Spirit in Darnassus' graveyard. Use an Orange Marigold to see the otherwise invisible spirit. Progress: You don't have any Bread of the Dead , do you?", ["rewardXP"] = 200, ["rewardItems"] = { 1179, 30817, 46691, 46710, 46718, 46831, 188689 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 46908, ["x"] = 0.696667, ["y"] = 0.407333 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 46908, ["x"] = 0.696667, ["y"] = 0.407333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.696667, ["y"] = 0.407333 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2801 } },
[27847] = { ["id"] = 27847, ["name"] = "Not Quite There", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27847 }, ["description"] = "These prototypes are going to change the face of Horde warfare when I perfect them! The issue I've been having is that their power sources don't allow for complicated combat maneuvers or large frames, both highly desired traits when it comes to fighting Alliance. The Defias, with some help from goblin traitors like Helix, have almost completed the Foe Reaper 5000 , a massive golem that will actually work! We can't have that going public, can we? I'll lose customers!", ["objectivesText"] = "Destroy the Foe Reaper 5000 .", ["rewardGold"] = 280900, ["rewardXP"] = 1010, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27848] = { ["id"] = 27848, ["name"] = "Good Intentions...Poor Execution", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27848 }, ["series"] = { 27842, 27850 }, ["description"] = "The Defias plan to finish their Juggernaut and use it to lay waste to Stormwind. It is a noble cause any true orc warrior would embrace without a single thought! Vanessa's fault lies in her execution of their plan. The ship is poorly constructed, the crew practically untrained, and, worst of all, there's a worgen in their midst! His name is Admiral Ripsnarl , and he must be mercilessly slain in the name of the Warchief. Lok'tar ogar!", ["objectivesText"] = "Kill Admiral Ripsnarl .", ["rewardGold"] = 280900, ["rewardXP"] = 1010, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27850] = { ["id"] = 27850, ["name"] = "The Defias Kingpin", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1581, ["storyline"] = { 27850 }, ["series"] = { 27842, 27848 }, ["description"] = "The Shattered Hand has laid mostly quiet for years now. No more! You will be the instrument of our rebirth, <name>. Slay the Defias Kingpin and commandeer her ship for the Horde! We will outfit it as a proper orc warship and use it to finally lay waste to Stormwind Any survivors will spread word of our unstoppable power across all of Azeroth, and all will tremble before our might! Go now, VanCleef's death will be your greatest triumph yet hero.", ["objectivesText"] = "Kill the Defias Kingpin.", ["rewardGold"] = 280900, ["rewardXP"] = 1010, ["rewardItems"] = { 65935, 65959, 65983, 66019, 66028, 66037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "dungeon" },
[27861] = { ["id"] = 27861, ["name"] = "The Crucible of Carnage: The Bloodeye Bruiser!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["mapID"] = 241, ["storyline"] = { 26293, 26294, 26311, 26324, 26335, 26337, 26358, 26361, 26372, 26374, 26388, 26538, 26539, 26540, 26549, 26608, 26619, 26621, 26622, 26784, 26786, 26788, 26798, 26830, 26840, 27177, 27178, 27299, 27300, 27301, 27302, 27303, 27338, 27341, 27366, 27376, 27377, 27378, 27379, 27380, 27433, 27468, 27485, 27486, 27490, 27491, 27492, 27493, 27494, 27495, 27496, 27497, 27498, 27499, 27500, 27501, 27502, 27503, 27504, 27505, 27506, 27507, 27508, 27509, 27514, 27515, 27516, 27537, 27538, 27545, 27564, 27576, 27583, 27584, 27586, 27588, 27590, 27606, 27607, 27608, 27609, 27610, 27611, 27621, 27622, 27636, 27637, 27638, 27639, 27640, 27641, 27642, 27643, 27644, 27645, 27646, 27647, 27648, 27649, 27650, 27651, 27652, 27653, 27654, 27655, 27657, 27658, 27659, 27660, 27661, 27662, 27688, 27689, 27690, 27695, 27696, 27700, 27701, 27702, 27703, 27719, 27720, 27742, 27743, 27744, 27745, 27747, 27750, 27751, 27752, 27753, 27754, 27784, 27786, 27787, 27788, 27798, 27803, 27804, 27805, 27806, 27807, 27808, 27809, 27810, 27811, 27812, 27813, 27814, 27815, 27816, 27817, 27861, 27862, 27863, 27864, 27865, 27866, 27867, 27868, 27929, 27945, 27947, 27951, 27954, 27955, 27999, 28041, 28043, 28090, 28091, 28092, 28093, 28094, 28097, 28101, 28103, 28104, 28107, 28108, 28109, 28123, 28133, 28171, 28173, 28175, 28176, 28191, 28211, 28212, 28215, 28233, 28234, 28238, 28241, 28242, 28243, 28244, 28247, 28248, 28249, 28280, 28281, 28282, 28294, 28346, 28377, 28378, 28379, 28407, 28408, 28409, 28410, 28411, 28413, 28583, 28584, 28586, 28588, 28589, 28590, 28591, 28592, 28593, 28594, 28595, 28596, 28597, 28598, 28599, 28655, 28712, 28758, 28832, 28849, 28885 }, ["series"] = { 27862, 27863, 27864, 27865, 27866, 27867, 27868 }, ["description"] = "I was wondering when you'd show up, <name>! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH! Anyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold! You know the drill, <name>. When you're ready, let me know and we'll get this show on the road!", ["objectivesText"] = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "group", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 546, ["name"] = "Twilight Highlands", ["orderIndex"] = 110, ["flags"] = 0 } } },
