[28292] = { ["id"] = 28292, ["name"] = "That's No Pyramid!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 28292 }, ["series"] = { 27003, 27004, 27005, 27040, 27041, 27058, 27059, 27952, 27953, 28293, 28295, 28296, 28557, 28558 }, ["description"] = "That pyramid at the Maker's Terrace in Uldum is nothing of the sort. It's a giant machine that can be reconfigured for any number of uses. Deathwing was going to have the Twilight's Hammer turn it into a massive weapon! <name>, you have to take the portal to get this information to Harrison Jones in Stormwind. He'll know what to do.", ["objectivesText"] = "Speak with Harrison Jones at Stormwind Keep in Stormwind City.", ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44799, ["x"] = 0.474, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 44238, ["x"] = 0.676, ["y"] = 0.3276 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 84, 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
