[28328] = { ["id"] = 28328, ["name"] = "Twilight Scheming", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28328 }, ["series"] = { 28285 }, ["description"] = "The influence of Twilight's Hammer reaches far and wide. They search ceaselessly for allies in their battle against us and they are recruiting the Dark Iron dwarves of Blackrock Depths to their cause. Moira's grip on the Dark Irons is tenuous at best and more of her people fall away from her rule with each day. We must sabotage their recruitment efforts. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", ["objectivesText"] = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths . Progress: We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 63428, 65616, 65633, 65634, 65635, 65636, 65637 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 376, ["x"] = 0.495, ["y"] = 0.4455 }, { ["mapID"] = 84, ["npcID"] = 164949, ["x"] = 0.794, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 376, ["x"] = 0.495, ["y"] = 0.4455 }, { ["mapID"] = 84, ["npcID"] = 164949, ["x"] = 0.794, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.4455 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[28343] = { ["id"] = 28343, ["name"] = "The Breath of Cenarius", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 28343 }, ["series"] = { 28289 }, ["description"] = "<name>, we have learned that a missing Cenarion artifact has surfaced in the hands of a Twilight's Hammer pyromancer. Pyromancer Loregrain has taken this artifact, the Breath of Cenarius , into Blackrock Depths and uses its power to open elemental gates. We must act to keep Loregrain from summoning elementals to bolster the ranks of his Dark Iron allies. Recover the artifact from him and use its power to close the gates that Loregrain has been using.", ["objectivesText"] = "Recover the Breath of Cenarius from Pyromancer Loregrain in Blackrock Depths and use the artifact to close 3 Elemental Gates. Progress: We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 63469, 65617, 65638 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 12042, ["x"] = 0.525, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 12042, ["x"] = 0.525, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "dungeon" },
[28349] = { ["id"] = 28349, ["name"] = "Megs in Marketing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24488, 24502, 24503, 24520, 24567, 25473, 28414 }, ["description"] = "Boss, while you were down at the mines, Megs Dreadshredder in marketing was asking for you. Something about your \"new image\" or whatever. She's right outside the building to the left.", ["objectivesText"] = "Speak with Megs Dreadshredder at KTC Headquarters on Kezan .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 4, ["flags"] = 0 } } },
[28376] = { ["id"] = 28376, ["name"] = "Myzerian's Head", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["description"] = "The head of one of Deathwing's most formidable black dragons is now in your possession. While many in Azeroth would pay dearly for such an artifact, something tells you that it belongs in a museum for all to see and remember. Harrison Jones is likely to have the proper connections. Sullah would certainly be happy to deliver it to him.", ["objectivesText"] = "Take Myzerian's Head to Sullah at Sullah 's Sideshow. Progress: You took down that dragon!? Remarkable!", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["rewardItems"] = { 52190, 52191, 52195, 63700 }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48431, ["x"] = 0.466667, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.466667, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 88, ["flags"] = 0 } }, ["startItems"] = { 63700 } },
[28390] = { ["id"] = 28390, ["name"] = "Glop, Son of Glop", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 28390 }, ["description"] = "Glop had a son. In his grave hubris, he named it Glop. And so the line of fungalmancers continues. I require you to slay this new fungalmancer. Your shaman ally has already returned, and awaits you at his cave in the southwest of Verlok Stand.", ["objectivesText"] = "Speak to Earthmender Norsala, then kill Fungalmancer Glop . Progress: To this day, I do not understand how filthy stone troggs breed so quickly. Perhaps it is better that it is left that way.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44973, ["x"] = 0.595, ["y"] = 0.14 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44973, ["x"] = 0.595, ["y"] = 0.14 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.14 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[28391] = { ["id"] = 28391, ["name"] = "The Restless Brood", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 28391 }, ["description"] = "Aeosera is restless and stubborn. She scoffs at our dominance, and she needs to be reminded of her place. I still have the mallet you retrieved for me. Return to the western edge of the Pale Roost and strike the resonating crystal. I will meet you there and lend what aid I can. Put her back in her place, <class>.", ["objectivesText"] = "Defeat Aeosera . Progress: And so continues the cycle of the stone drakes. Tumultuous wills in stoic frames.", ["rewardGold"] = 274800, ["rewardXP"] = 5145, ["rewardItems"] = { 60266 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43806, ["x"] = 0.556571, ["y"] = 0.136857 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42466, ["x"] = 0.4032, ["y"] = 0.2008 }, { ["mapID"] = 207, ["npcID"] = 43806, ["x"] = 0.556571, ["y"] = 0.136857 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.556571, ["y"] = 0.136857 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[28393] = { ["id"] = 28393, ["name"] = "A Dangerous Alliance", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28393 }, ["series"] = { 28258 }, ["description"] = "SI:7's latest report about Twilight's Hammer and Dark Iron activity worries me, <name>. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We'll be hard-pressed to turn back such a combined force, but if we act before they're ready to strike, we might be able to blunt the attack. You must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Do not hesitate to take out the elementals supporting his forces.", ["objectivesText"] = "Kill 6 Fireguard Destroyers and recover the General's Attack Plans from General Angerforge at the West Garrison in Blackrock Depths . Progress: We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64302, 65618, 65625, 65639, 65642 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 914, ["x"] = 0.795, ["y"] = 0.693 }, { ["mapID"] = 84, ["npcID"] = 164939, ["x"] = 0.802, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 914, ["x"] = 0.795, ["y"] = 0.693 }, { ["mapID"] = 84, ["npcID"] = 164939, ["x"] = 0.802, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.795, ["y"] = 0.693 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[28394] = { ["id"] = 28394, ["name"] = "The Golem Lord's Creations", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1584, ["mapID"] = 84, ["storyline"] = { 28394 }, ["series"] = { 28260 }, ["description"] = "The latest SI:7 intelligence on Blackrock Depths is troubling, <name>. It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could prove to be a devastating weapon if used against us. You must prevent that from happening, <name>. Find the Manufactory in Blackrock Depths , capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", ["objectivesText"] = "Obtain 5 Elemental Modules from the golems in the Manufactory of Blackrock Depths and recover the Elemental Golem Blueprints . Progress: We cannot afford to allow those golems to be used against us.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64303, 64304, 65619, 65628 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 44247, ["x"] = 0.640667, ["y"] = 0.598 }, { ["mapID"] = 84, ["npcID"] = 164960, ["x"] = 0.792, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 44247, ["x"] = 0.640667, ["y"] = 0.598 }, { ["mapID"] = 84, ["npcID"] = 164960, ["x"] = 0.792, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.640667, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[28398] = { ["id"] = 28398, ["name"] = "The Pyromancer's Grimoire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28398 }, ["series"] = { 28263 }, ["description"] = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain, a magus of renown, plays an important role in leading the Twilight's Hammer forces there. If we could get our hands on his grimoire, I might be able to devise counterspells and other ways of dampening their elemental magics. You must descend into Blackrock Depths , locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", ["objectivesText"] = "Kill 6 Twilight Emissaries and recover Loregrain's Grimoire from Pyromancer Loregrain at the Shrine of Thaurissan in Blackrock Depths . Progress: Have you managed to capture the pyromancer's grimoire?", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64305, 65620, 65626 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 331, ["x"] = 0.476, ["y"] = 0.89 }, { ["mapID"] = 84, ["npcID"] = 164955, ["x"] = 0.799, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 331, ["x"] = 0.476, ["y"] = 0.89 }, { ["mapID"] = 84, ["npcID"] = 164955, ["x"] = 0.799, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.89 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[28399] = { ["id"] = 28399, ["name"] = "Stones of Binding", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28399 }, ["series"] = { 28259 }, ["description"] = "I have it on good authority that SI:7 is concerned about collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths . We can act on this information, prove our value to the Alliance, and gain something for ourselves at the same time. The report mentions that the Twilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", ["objectivesText"] = "Recover 6 Elemental Binding Stones from Blackrock Depths . You can find the stones in Shadowforge City, the Domicile, the Shrine of Thaurissan, the East Garrison, and the West Garrison. Progress: Have you managed to find those binding stones?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64308, 65621, 65627 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 461, ["x"] = 0.3945, ["y"] = 0.8485 }, { ["mapID"] = 84, ["npcID"] = 164942, ["x"] = 0.7945, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 461, ["x"] = 0.3945, ["y"] = 0.8485 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.3945, ["y"] = 0.8485 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[28401] = { ["id"] = 28401, ["name"] = "Slaves of the Firelord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 7 }, ["requiredRaces"] = { 3, 11, 34 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 28401 }, ["series"] = { 28287 }, ["description"] = "Within the halls of Blackrock Depths , the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros. If we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", ["objectivesText"] = "Use the Totem of Freedom to free the essences of 6 Fireguards, Fireguard Destroyers, or Blazing Fireguards in Blackrock Depths .", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64312, 65622, 65630, 65640, 65643 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[28405] = { ["id"] = 28405, ["name"] = "Weapons of Darkness", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 3, 11, 30 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28405 }, ["series"] = { 28268 }, ["description"] = "Blackrock Depths has long been home to our enemies, but now SI:7 sends word that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the knowledge of the cult, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons. I want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", ["objectivesText"] = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths , then break them over the Black Anvil in Shadowforge City.", ["rewardGold"] = 491400, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64313, 65623, 65631, 65632, 65641, 65644, 65645, 65646, 65647, 65648, 212174 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 928, ["x"] = 0.525, ["y"] = 0.452 }, { ["mapID"] = 84, ["npcID"] = 164952, ["x"] = 0.792, ["y"] = 0.698667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 928, ["x"] = 0.525, ["y"] = 0.452 }, { ["mapID"] = 84, ["npcID"] = 164952, ["x"] = 0.792, ["y"] = 0.698667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[28406] = { ["id"] = 28406, ["name"] = "The Dark Iron Army", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28406 }, ["series"] = { 28262 }, ["description"] = "Things are getting interesting in Blackrock Mountain, <name>. Our sources report that the Dark Iron dwarves have formed closer ties with Twilight's Hammer and both are preparing for a major offensive. I've made the contents of the report known to key leaders in Stormwind and I want you to help deal with this emerging Dark Iron threat. The rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths . Take this poison and apply it to their grain reserves.", ["objectivesText"] = "Use the Fast-Acting Poison to contaminate 6 Grain Rations in the West Garrison or East Garrison of Blackrock Depths .", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 37863, 64341, 65624, 65629 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 13283, ["x"] = 0.644667, ["y"] = 0.518 }, { ["mapID"] = 84, ["npcID"] = 164946, ["x"] = 0.787333, ["y"] = 0.705333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 13283, ["x"] = 0.644667, ["y"] = 0.518 }, { ["mapID"] = 84, ["npcID"] = 164946, ["x"] = 0.787333, ["y"] = 0.705333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.644667, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[28414] = { ["id"] = 28414, ["name"] = "Fourth and Goal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24488, 24502, 24503, 24520, 24567, 25473, 28349 }, ["description"] = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal. <The coach leans in close and whispers in your ear.> Now, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal! I've modified the footbomb to give you the extra power that you'll need. Now get out there and make me proud!", ["objectivesText"] = "Get in the Bilgewater Buccaneer and score the winning goal by kicking the Footbomb through the smokestacks behind the opposing goal.", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 54294, 54295 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 37106, ["x"] = 0.485333, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.579333 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 16, ["flags"] = 0 } } },
[28457] = { ["id"] = 28457, ["name"] = "A Dangerous Alliance", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28457 }, ["series"] = { 28290 }, ["description"] = "The Shattered Hand believes that the Dark Iron dwarves and Twilight's Hammer are working together. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We can't allow such a force to depart Blackrock Mountain. You must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Eliminate the elementals Twilight's Hammer has provided to support his forces.", ["objectivesText"] = "Kill 6 Fireguard Destroyers and recover the General's Attack Plans from General Angerforge at the West Garrison in Blackrock Depths . Progress: We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64302, 65618, 65625, 65639, 65642 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3353, ["x"] = 0.735, ["y"] = 0.455 }, { ["mapID"] = 85, ["npcID"] = 168596, ["x"] = 0.735, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3353, ["x"] = 0.735, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[28458] = { ["id"] = 28458, ["name"] = "The Pyromancer's Grimoire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28458 }, ["series"] = { 28300 }, ["description"] = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain is a powerful and influential magus in the Twilight's Hammer delegation. If we could get our hands on his grimoire, I could develop counters for Twilight's Hammer spells and curses. You must descend into Blackrock Depths , locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", ["objectivesText"] = "Kill 6 Twilight Emissaries and recover Loregrain's Grimoire from Pyromancer Loregrain at the Shrine of Thaurissan in Blackrock Depths . Progress: Have you managed to capture the pyromancer's grimoire?", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64305, 65620, 65626 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168626, ["x"] = 0.747, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 168626, ["x"] = 0.747, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.747, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[28459] = { ["id"] = 28459, ["name"] = "Stones of Binding", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28459 }, ["series"] = { 28299 }, ["description"] = "The Shattered Hand has discovered increased collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths . We have an opportunity to strike at our enemies and empower ourselves, <name>. Twilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", ["objectivesText"] = "Recover 6 Elemental Binding Stones from Blackrock Depths . You can find the stones in Shadowforge City, the Domicile, the Shrine of Thaurissan, the East Garrison, and the West Garrison. Progress: Have you managed to find those binding stones?", ["rewardGold"] = 210000, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64308, 65621, 65627 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168623, ["x"] = 0.745, ["y"] = 0.471 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.471 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[28461] = { ["id"] = 28461, ["name"] = "The Golem Lord's Creations", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1584, ["mapID"] = 85, ["storyline"] = { 28461 }, ["series"] = { 28297 }, ["description"] = "The Shattered Hand has discovered some disturbing information in Blackrock Depths . It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could be a great advantage for our enemies. It is your duty to prevent that from happening. Find the Manufactory in Blackrock Depths , capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", ["objectivesText"] = "Obtain 5 Elemental Modules from the golems in the Manufactory of Blackrock Depths and recover the Elemental Golem Blueprints . Progress: We cannot afford to allow those golems to be used against us.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64303, 64304, 65619, 65628 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3352, ["x"] = 0.554, ["y"] = 0.4384 }, { ["mapID"] = 85, ["npcID"] = 168551, ["x"] = 0.738, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3352, ["x"] = 0.554, ["y"] = 0.4384 }, { ["mapID"] = 85, ["npcID"] = 168551, ["x"] = 0.738, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.4384 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[28463] = { ["id"] = 28463, ["name"] = "The Dark Iron Army", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28463 }, ["series"] = { 28298 }, ["description"] = "As a member of the Shattered Hand, you know that it is our job to watch the Horde's enemies. We have discovered that the Dark Iron dwarves and their new allies, Twilight's Hammer, are preparing to attack. I'm sending you to help deal with this threat before the Dark Iron army marches. Take this poison and apply it to the soldiers' rations of grain in Blackrock Depths . The rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths .", ["objectivesText"] = "Use the Fast-Acting Poison to contaminate 6 Grain Rations in the West Garrison or East Garrison of Blackrock Depths .", ["rewardGold"] = 210000, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64341, 65624, 65629 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168598, ["x"] = 0.752, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[28465] = { ["id"] = 28465, ["name"] = "Slaves of the Firelord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28465 }, ["series"] = { 28301 }, ["description"] = "Within the halls of Blackrock Depths , the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros. If we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", ["objectivesText"] = "Use the Totem of Freedom to free the essences of 6 Fireguards, Fireguard Destroyers, or Blazing Fireguards in Blackrock Depths .", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64312, 65622, 65630, 65640, 65643 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3344, ["x"] = 0.39, ["y"] = 0.475 }, { ["mapID"] = 85, ["npcID"] = 168628, ["x"] = 0.734, ["y"] = 0.4345 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3344, ["x"] = 0.39, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[28466] = { ["id"] = 28466, ["name"] = "Weapons of Darkness", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 6, 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28466 }, ["series"] = { 28302 }, ["description"] = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons. I want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", ["objectivesText"] = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths , then break them over the Black Anvil in Shadowforge City.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 22223, 25549, 63672, 64313, 65623, 65631, 65632, 65641, 65644, 65645, 65646, 65647, 65648 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 44725, ["x"] = 0.453333, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 44725, ["x"] = 0.453333, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.453333, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[28473] = { ["id"] = 28473, ["name"] = "Weapons of Darkness", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28473 }, ["series"] = { 28303 }, ["description"] = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons. I want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", ["objectivesText"] = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths , then break them over the Black Anvil in Shadowforge City.", ["rewardGold"] = 210000, ["rewardXP"] = 3455, ["rewardItems"] = { 11765, 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 64313, 65623, 65631, 65632, 65641, 65644, 65645, 65646, 65647, 65648 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 23128, ["x"] = 0.491, ["y"] = 0.715 }, { ["mapID"] = 85, ["npcID"] = 168597, ["x"] = 0.733, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 23128, ["x"] = 0.491, ["y"] = 0.715 }, { ["mapID"] = 85, ["npcID"] = 168597, ["x"] = 0.733, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.491, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[28474] = { ["id"] = 28474, ["name"] = "Twilight Scheming", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28474 }, ["series"] = { 28304 }, ["description"] = "The influence of Twilight's Hammer grows within Blackrock Depths . They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain. We must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", ["objectivesText"] = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths .", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 16795, 16808, 16813, 16821, 16834, 16842, 16846, 16854, 16866, 25549, 63428, 65616, 65633, 65634, 65635, 65636, 65637 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45339, ["x"] = 0.484, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 45339, ["x"] = 0.484, ["y"] = 0.7255 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
