[28502] = { ["id"] = 28502, ["name"] = "The Bandit Warlord", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28502 }, ["description"] = "Our law demands that those behind this attack face proper retribution. The band of bandits' ringleader is a man known as Warlord Ihsenn . You will find him in the far west of the desert. Make sure his transgressions do not go unpunished.", ["objectivesText"] = "Slay Warlord Ihsenn .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 65796, 65797, 65798, 65799 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47715, ["x"] = 0.53, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47715, ["x"] = 0.53, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[28517] = { ["id"] = 28517, ["name"] = "The Howling Oak", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 28517 }, ["description"] = "So this is it... our new home. I'm not sure if I'll ever feel like I truly have a home again. We mustn't be unappreciative of what the night elves have offered us though. Their race is not one to throw out idle welcomes to just anyone. It is a true testament to faith and generosity that they've taken us in. Gwen and Greymane are in the city proper, at the Howling Oak. You should stop by. Take the portal beneath the tree north of us, then seek out the Howling Oak in the northern portion of the city.", ["objectivesText"] = "Speak to Genn Greymane at the Howling Oak in Darnassus .", ["rewardGold"] = 140450, ["rewardXP"] = 370, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 42968, ["x"] = 0.552, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 48736, ["x"] = 0.485, ["y"] = 0.145 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 57, 89 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Paladin" },
[28557] = { ["id"] = 28557, ["name"] = "Warchief's Command: Uldum!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 71, ["storyline"] = { 27718, 27721, 27722, 28557, 28717, 60887 }, ["series"] = { 27003, 27004, 27005, 27040, 27041, 27058, 27059, 27952, 27953, 28292, 28293, 28295, 28296, 28558 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Adarrah at the Thistleshrub Valley in Tanaris. Ancient texts tell us that Uldum is home to untold riches and treasures beyond compare. Go forth and claim these in the name of the Horde! You can reach Adarrah 's caravan by traveling to the southwestern part of Tanaris and looking for her in Thistleshrub Valley. Destiny calls!", ["objectivesText"] = "Speak with Adarrah in Thistleshrub Valley in western Tanaris.", ["rewardGold"] = 13740, ["rewardXP"] = 515, ["rewardItems"] = { 30632, 58487 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 44833, ["x"] = 0.305, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["questLines"] = { { ["id"] = 5580, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } } },
[28558] = { ["id"] = 28558, ["name"] = "Hero's Call: Uldum!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 71, ["storyline"] = { 27724, 27726, 27727, 28558, 28716, 60891 }, ["series"] = { 27003, 27004, 27005, 27040, 27041, 27058, 27059, 27952, 27953, 28292, 28293, 28295, 28296, 28557 }, ["description"] = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Adarrah at Thistleshrub Valley in Tanaris. Be one of the first to enter glorious Uldum and claim its treasures in honor of the Alliance! You can reach Adarrah 's caravan by traveling to the western reaches of Tanaris. For the glory and honor of the Alliance!", ["objectivesText"] = "Speak with Adarrah at Thistleshrub Valley in Tanaris.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 40585, 40586, 44934, 44935 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 44833, ["x"] = 0.305, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["questLines"] = { { ["id"] = 5581, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } } },
[28559] = { ["id"] = 28559, ["name"] = "Hero's Call: Bloodmyst Isle!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3557, ["mapID"] = 106, ["storyline"] = { 28559 }, ["series"] = { 9634 }, ["description"] = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Vorkhan the Elekk Herder at Kessel's Crossing. The people of Bloodmyst need your help to deal with treacherous blood elves and dangerous creatures loose on the island. You can reach Kessel's Crossing on Bloodmyst Isle by taking the bridge north from Azuremyst Isle. For the glory and honor of the Alliance!", ["objectivesText"] = "Report to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle .", ["rewardGold"] = 200, ["rewardXP"] = 25, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17586, ["x"] = 0.63, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[28560] = { ["id"] = 28560, ["name"] = "Warchief's Command: Ghostlands!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3487, ["mapID"] = 95, ["storyline"] = { 28560 }, ["series"] = { 9138, 9139, 9140, 9327, 9329, 9758 }, ["description"] = "All able bodied members of the Horde are hereby ordered to report to Arcanist Vandril at Tranquillien in the Ghostlands . Your help is needed to turn back the numberless Scourge invaders and secure the help of the Forsaken in fighting our common enemy. To reach Tranquillien, follow the road south from Fairbreeze Square and into the Ghostlands . Destiny calls!", ["objectivesText"] = "Report to Arcanist Vandril at Tranquillien in the Ghostlands .", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3487 } }, ["questType"] = "standard" },
