[28650] = { ["id"] = 28650, ["name"] = "A Special Surprise", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13189, 28650 }, ["series"] = { 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 28649 }, ["description"] = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, <name>. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing. I was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty goblin in there that I think you'll take great pleasure in executing.", ["objectivesText"] = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Gally Lumpstain , an Argent Dawn prisoner inside the nearby prison house. Progress: How does it feel?", ["rewardGold"] = 105000, ["rewardXP"] = 1720, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 40, ["flags"] = 0 } } },
[28651] = { ["id"] = 28651, ["name"] = "Novice Elreth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28652, 28653, 28672 }, ["description"] = "Why don't you go speak with my novice, Elreth? She serves me, and will have some tasks to which you can apply your new abilities.", ["objectivesText"] = "Speak to Novice Elreth at Deathknell in Tirisfal Glades.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1569, ["x"] = 0.308, ["y"] = 0.662 }, { ["mapID"] = 465, ["npcID"] = 38911, ["x"] = 0.4955, ["y"] = 0.5645 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1661, ["x"] = 0.308, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 18, 465 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 9, ["flags"] = 0 } } },
[28652] = { ["id"] = 28652, ["name"] = "Caretaker Caice", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28653, 28672 }, ["description"] = "I am done with you. There are, however, others who can use your aid. Caretaker Caice , standing on that stump behind me, can probably give you another assignment. You should speak with him now.", ["objectivesText"] = "Speak with Caretaker Caice at the Deathknell Graves in Tirisfal Glades.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1568, ["x"] = 0.3, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 2307, ["x"] = 0.306, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 3, ["flags"] = 0 } } },
[28653] = { ["id"] = 28653, ["name"] = "Shadow Priest Sarvis", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28672 }, ["description"] = "Are you still here, <name>? You know, I'm only a deathguard. I don't have many tasks I can hand out to passers-by like you. I'd recommend that you talk to Shadow Priest Sarvis . I remember, he helped me get on my feet after I was plucked out of that tomb. I'm sure he'll do the same for you. You'll find him just inside the chapel, here on the west side of town.", ["objectivesText"] = "Speak with Shadow Priest Sarvis at Deathknell in Tirisfal Glades.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1740, ["x"] = 0.316, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1569, ["x"] = 0.308, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 7, ["flags"] = 0 } } },
[28654] = { ["id"] = 28654, ["name"] = "The Heart of the Matter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28654 }, ["series"] = { 27748, 28482, 28497, 28612, 28613, 28621, 28622, 28633, 28746, 28753 }, ["description"] = "Well, <laddie/little lady>, half of me wishes I could stick around a while and take in the sights with ye. I've seen some mighty amazin' things in my day, but this here takes the cake. Sadly, I have a fair bit o' research ta do on these discs before I make my way into the Halls of Origination . You seem ta be worth your salt, perhaps ye'd like ta tag along and see how a REAL archaeologist works, eh?", ["objectivesText"] = "Brann Bronzebeard wants you to meet him in the Halls of Origination .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 25540, 25541, 28029, 65682, 65702, 65720, 65731, 131698, 237812 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 49204, ["x"] = 0.325, ["y"] = 0.308 }, { ["mapID"] = 249, ["npcID"] = 49351, ["x"] = 0.448, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "dungeon" },
[28657] = { ["id"] = 28657, ["name"] = "A Huge Problem", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28657 }, ["description"] = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols! <name>, I need you to round up a few friends and take that ettin down. We can't have a beast like that roaming around, wreaking havoc. Stay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", ["objectivesText"] = "You have been asked to kill Problim , a giant ettin that roams the paths of Tol Barad . Progress: Did you find problim yet? Pretty hard to miss that guy with how huge he is.", ["rewardGold"] = 578600, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48069, ["x"] = 0.5065, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48069, ["x"] = 0.5065, ["y"] = 0.499 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.5065, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "group" },
[28659] = { ["id"] = 28659, ["name"] = "The Leftovers", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28659 }, ["description"] = "We fought hard to capture this island, <race>. We cleared out most of the Alliance filth but I can still smell their foul stench in the air. I need you to investigate the slagworks, warden's vigil and the ironclad garrison. Kill any Alliance that you find. You know what they say, the only good Alliance is a dead Alliance!", ["objectivesText"] = "You have been instructed to kill 12 Alliance Infantry on Tol Barad . You can find the holdouts in The Slagworks, Warden's Vigil and the Ironclad Garrison, here on Tol Barad . Progress: Gah, the smell of their weak bodies is sickening me.", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48069, ["x"] = 0.5065, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48069, ["x"] = 0.5065, ["y"] = 0.499 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.5065, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28660] = { ["id"] = 28660, ["name"] = "Clearing the Depths", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28660 }, ["description"] = "You are a sight for sore eyes, <name>. Now that we have claimed tol barad , the battle has just begun. We discovered a cell block just east of here that we need you to clear out. Turns out that its chock full of ghosts that have been locked up down there for who knows how long. Clear out as much as you can and report back to me when you are done.", ["objectivesText"] = "You have been asked to kill 9 ghosts of any type in the Cursed Depths, just east of Baradin Hold.", ["rewardGold"] = 561800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48071, ["x"] = 0.5155, ["y"] = 0.4945 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48071, ["x"] = 0.5155, ["y"] = 0.4945 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.5155, ["y"] = 0.4945 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28662] = { ["id"] = 28662, ["name"] = "Learning From The Past", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28662 }, ["description"] = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition. Some of our troops have discovered journals around the entrance to Cursed Depths cellblock just east of here. These journals are of particular interest to our elder scribes back at base camp. I need you to recover four of them and bring them back to me as fast as you can. <name>, be careful down there, that place is crawling with undead.", ["objectivesText"] = "You have been asked to recover four Dusty Prison Journals from the Cursed Depths, just east of Baradin Hold. Progress: Were you able to recover the journals? Reports mentioned that they were sighted both in and out of the cells down there.", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["rewardItems"] = { 63034 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48071, ["x"] = 0.5155, ["y"] = 0.4945 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48071, ["x"] = 0.5155, ["y"] = 0.4945 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.5155, ["y"] = 0.4945 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28663] = { ["id"] = 28663, ["name"] = "D-Block", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28663 }, ["description"] = "Have you heard of the D-Block yet <name>? It's one of the old cellblocks here on the island. Problem is, it's infested with demons. We planned on using it to lock up the leftover Alliance we found on the island, but that is not going to happen in its current state. I need you to head down there and clear those demons out. Report back to me when you are done.", ["objectivesText"] = "You have been instructed to kill 10 demons of any type in the D-Block, just northwest of Baradin Hold.", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48070, ["x"] = 0.515, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48070, ["x"] = 0.515, ["y"] = 0.495 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28668] = { ["id"] = 28668, ["name"] = "Prison Revolt", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28668 }, ["description"] = "We have the island, now we need to put the resources here to work. We found an abandoned cellblock just southwest of here and we need you to go check it out <name>. Reports have come back that it is overrun with prisoners that have been stuck down there for years. Do whatever you need to do to clear that place out. Report back to me when you are done.", ["objectivesText"] = "You have been instructed to kill 10 prisoners of any type in The Hole, just southwest of Baradin Hold.", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48062, ["x"] = 0.515, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48062, ["x"] = 0.515, ["y"] = 0.496 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28672] = { ["id"] = 28672, ["name"] = "The Executor In the Field", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653 }, ["description"] = "I can keep you busy here in town all week... but you seem to be more the fighting type. <Elreth looks you over and nods.> Yes, you'll do just fine. I'd like you to go talk to Executor Arren . Follow the path north, out of Deathknell . You'll find him not far past the barricades.", ["objectivesText"] = "Report to Executor Arren .", ["rewardGold"] = 100, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1661, ["x"] = 0.308, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1570, ["x"] = 0.328, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 11, ["flags"] = 0 } } },
[28678] = { ["id"] = 28678, ["name"] = "Captain P. Harris", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28678 }, ["description"] = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad. Half of our supply ships end up on the rocks down there. To make matters worse, it's been overrun by a gang of undead sailors. We have tried thinning the ranks, but they just seem to keep coming back. Our last resort is to try and take out the captain that they report to. You should be able to find him on a ship, just off the shoreline. Oh, and I hope you are not too scared of sharks.", ["objectivesText"] = "You have been tasked with killing Captain P. Harris at the Cape of Lost Hope. The Cape of Lost Hope can be found northwest of here, along the coast. Just look for the shipwrecks.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.807 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28679] = { ["id"] = 28679, ["name"] = "Rattling Their Cages", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28679 }, ["description"] = "We have been having issues with the undead down at the Cape of Lost Hope for a while now. Every time a new ship wrecks, they end up getting more undead to join their ranks. Can you do us a favor and thin out the ranks up there? I know you won't be able to kill them all, but anything you can do will help at this point. Keep an eye out for alliance, we have been getting reports of them ambushing the beach lately.", ["objectivesText"] = "3rd Officer Kronkar has asked you to kill 8 Shipwrecked Sailors at the Cape of Lost Hope. The cape is located due northwest of here, on the beach.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.807 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28680] = { ["id"] = 28680, ["name"] = "Boosting Morale", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28680 }, ["description"] = "Morale is low these days, <name>. We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum. I have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls. Can you head up there and investigate? Bring back any rum you can find.", ["objectivesText"] = "You have been asked to recover 6 Barrels of Southsea Rum from the shipwrecks on the Cape of Lost Hope. The cape can be found north of here, along the coast. Progress: Were you able to recover the rum? I would try but I am deathly afraid of the water. Not to mention that crazy shark.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 62810 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.807 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28681] = { ["id"] = 28681, ["name"] = "Shark Tank", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28681 }, ["description"] = "I hate sharks. All of my troops hate sharks too. This is where you come in, <name>. I need you to head up to the Cape of Lost Hope and take out a huge shark named Tank . Tank is not to be trifled with so I would bring a few friends if I were you.", ["objectivesText"] = "You have been tasked to kill Tank , a large shark cruising the waters of the Cape of Lost Hope. The cape can be found north of here, along the northern coastline.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.807 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "group" },
[28682] = { ["id"] = 28682, ["name"] = "Claiming The Keep", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28682 }, ["description"] = "Have you seen the keep on the north side of the island, <name>? That is where Keep Lord Farson runs his operation from. Farson has a small group of dedicated followers and they have been giving us trouble since we got here. We sent a small group to investigate and they reported back on his exact position within the keep. Can you finish him off for us?", ["objectivesText"] = "You have been asked to kill Keep Lord Farson at the Farson Hold. Farson Hold can be found on the north side of the island.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.535333, ["y"] = 0.804667 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28683] = { ["id"] = 28683, ["name"] = "Thinning the Brood", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28683 }, ["description"] = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders. Do me a favor and see if you can thin them out enough for us to set up an attack. Careful out there, I have heard reports of Alliance troops nearby earlier in the week.", ["objectivesText"] = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just north of here, across the bridge on the central island.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.807 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28684] = { ["id"] = 28684, ["name"] = "A Sticky Task", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28684 }, ["description"] = "Finding supplies on the island has been difficult, to say the least. Fortunately, we have found a good supply of silk in The Darkwood, just north of here. The bad part of this story is that the silk comes from the glands on Broodmother spiders. I need you to gather 4 of these for me. That should be just enough to finish up this last set of shirts.", ["objectivesText"] = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island. Progress: Were you able to gather the sticky silk glands ?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 62803 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48360, ["x"] = 0.552, ["y"] = 0.807 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.807 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28685] = { ["id"] = 28685, ["name"] = "Leave No Weapon Behind", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28685 }, ["description"] = "Battle supplies are hard to come by on this rock. Every time we hold off another Alliance attack, it feels like we are fighting with sticks and stones. Reports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use. Can you head down there and check it out? Be careful <name>, Farson's followers will do anything to protect him.", ["objectivesText"] = "Retrieve 12 Rusty Rifles from Farson Hold on the north side of Tol Barad Peninsula . Progress: Any luck with those rifles?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 62921 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.535333, ["y"] = 0.804667 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28686] = { ["id"] = 28686, ["name"] = "Not The Friendliest Town", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28686 }, ["description"] = "Have you been up to Rustberg Village yet <name>? I would suggest you bring a sharpened blade if you are heading that direction. The folks in that town look alright but something suspicious is going on in there. Reports have been coming in that they are picking off our soldiers left and right. We have had just about enough of that, so I need you to head down there and do a little cleaning house for us. Take down as many as you can and report back when you are done.", ["objectivesText"] = "Commander Larmash has asked you to kill 14 villagers in Rustberg Village. Rustberg Village is just north of base camp, on the right side. Progress: Did you find out what's up with that village? Something seems off...", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.535333, ["y"] = 0.804667 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28687] = { ["id"] = 28687, ["name"] = "Teach A Man To Fish.... Or Steal", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28687 }, ["description"] = "Rustberg Village. That place is a curse and a blessing for us, <name>. I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now. I need you to head down there and steal as many of their fish reserves as possible. We have been living off scraps since we retook the island and this is our best chance at some solid food reserves. Keep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", ["objectivesText"] = "You must steal 22 Rustberg Seabass from Rustberg Village. The fish can be found on string stands at the docks, round back of the village. Rustberg Village is due north of base camp, on the right side. Progress: Were you able to pull off the heist and get us some fish?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 63047 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.535333, ["y"] = 0.804667 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28689] = { ["id"] = 28689, ["name"] = "The Forgotten", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28689 }, ["description"] = "Many soldiers died on this island <name>. It is only fair that we pay our respects to them in any way that we can. I need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place. Do be careful over there, reports of undead have been ongoing in the area.", ["objectivesText"] = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Restless Front. Progress: Were you able to release our forgotten brothers in arms?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.5464, ["y"] = 0.7928 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28690] = { ["id"] = 28690, ["name"] = "Salvaging the Remains", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28690 }, ["description"] = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle. We have tried to clear them out many times but they always seem to come back. One of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight. Think you can help us out with this one?", ["objectivesText"] = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front. Progress: Were you able to recover the femur bones? Better for you to try than me.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 62808 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.5464, ["y"] = 0.7928 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28691] = { ["id"] = 28691, ["name"] = "First Lieutenant Connor", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28691 }, ["description"] = "The first time I heard about Lt. Connor, I was just a young recruit in Ragefire Chasm. None of us could believe he ended up here on Tol Barad. Sadly, he still roams these wretched islands, wreaking havoc on our troops morale. I need you to put an end to his misery... and ours.", ["objectivesText"] = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.5464, ["y"] = 0.7928 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28692] = { ["id"] = 28692, ["name"] = "Magnets, How Do They Work?", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28692 }, ["description"] = "Getting useful machine parts out here on the island has been difficult, <name>. We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts. Our second regiment reported some wrecked out siege engines in a old battlefield to the west. Maybe we could find some parts over there? You are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", ["objectivesText"] = "You have been tasked with recovering 7 pieces of Siege Engine Scrap . Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge. Progress: Did that magnet contraptaion actually work?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 52325, 52326, 52327, 52328, 62829, 62830 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.5464, ["y"] = 0.7928 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28693] = { ["id"] = 28693, ["name"] = "Finish The Job", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28693 }, ["description"] = "We have been trying to collect useful scraps from the front all week. Every time we gather a batch to bring back to camp, we get assaulted by the restless soldiers in the area. Can you head over there and clear them out?", ["objectivesText"] = "Kill 5 Restless Soldiers at the Restless Front. You can find the front on the west side of the island, just before Forgotten Hill. Progress: Were you able to finish the job?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48363, ["x"] = 0.5464, ["y"] = 0.7928 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.5464, ["y"] = 0.7928 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28694] = { ["id"] = 28694, ["name"] = "Watch Out For Splinters!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28694 }, ["description"] = "Have you been over to the Wellson Shipyard yet, <name>? Best to stay away from there unless you have a good reason to venture in. Unfortunately, that is exactly what I need you to do. You see, we have been short on supplies ever since we recaptured the island. That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back. Can you help us out?", ["objectivesText"] = "Private Sarlosk has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast. Progress: Did the ghosts scare you off?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 62811 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28695] = { ["id"] = 28695, ["name"] = "WANTED: Foreman Wellson", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28695 }, ["description"] = "Foreman Wellson has been a pain in our side since we got here. His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them. He keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard. I need you to take out Wellson for good this time. Be careful <name>, we have been receiving reports of dirty Alliance all around the area.", ["objectivesText"] = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found north of here, on the western coast.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28696] = { ["id"] = 28696, ["name"] = "Bombs Away!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28696 }, ["description"] = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it. They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships. Head down there and see what you can do. Report back to me on your progress.", ["objectivesText"] = "Destroy 10 Ghastly Supply Boats.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28697] = { ["id"] = 28697, ["name"] = "Ghostbuster", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28697 }, ["description"] = "See that hill with the towers to the northeast? That's Largo's Overlook and it's not a fun place to set up camp next to. We have been dealing with those spirits and spectres ever since we setup camp. Can you head up there and let them know we don't plan on leaving anytime soon? A few good kills on their ranks should put them in line. Thanks for your help on this, <name>.", ["objectivesText"] = "Kill 14 ghosts of any type at Largo's Overlook, northeast of the Horde camp.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28700] = { ["id"] = 28700, ["name"] = "Taking the Overlook Back", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28700 }, ["description"] = "There is only one way for us to take Largo's Overlook back. I think you know what we need to do <name>. Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", ["objectivesText"] = "Private Sarlosk has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48361, ["x"] = 0.555, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28713] = { ["id"] = 28713, ["name"] = "The Balance of Nature", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28714, 28715, 28734 }, ["description"] = "Greetings, <name>. I am Ilthalaine . My purpose in Shadowglen is to train young <class>s like you and to ensure that the balance of nature is maintained. The spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered. Unfortunately, the nightsaber numbers grew too large, and they will devastate the other populations if they are not culled. Journey forth, young <class>, and thin saber populations so that nature's harmony will be preserved.", ["objectivesText"] = "Kill 6 Young Nightsabers . Progress: There is still work to be done, <name>. Return to me once you have thinned the nightsaber population.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 5394, 11187, 131815 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2079, ["x"] = 0.578, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 2079, ["x"] = 0.578, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 460, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 0, ["flags"] = 0 } } },
[28714] = { ["id"] = 28714, ["name"] = "Fel Moss Corruption", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28713, 28715, 28734 }, ["description"] = "You seem to know what you're doing. Perhaps I can task you with something a little more important. As you may well know, the corruption in Teldrassil was supposedly wiped away. Yet something lingers. The creatures have not calmed and all manner of problems still plague us. I need you to deal with the grellkin that have gathered to the west, and while you're there, I want you to search them for fel moss . This will help me determine from where this continuing corruption stems.", ["objectivesText"] = "Collect 6 Fel Moss from the grellkin to the west of Ilthalaine . Progress: Satisfy my suspicions, <name>. Bring to me fel moss from the grellkin.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 961, 3297, 5398, 5399, 11190, 131816 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2079, ["x"] = 0.578, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 2079, ["x"] = 0.578, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 460, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 1, ["flags"] = 0 } } },
[28715] = { ["id"] = 28715, ["name"] = "Demonic Thieves", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28713, 28714, 28734 }, ["description"] = "Vicious little grell! They've been stealing from our foodstores again. If you wouldn't mind lending a hand, they are sure to have my stolen bags within their camps to the west. I would be glad to reward you if you can bring them back to me.", ["objectivesText"] = "Recover Melithar's Stolen Bags near the grellkin to the west. Progress: I don't have any spare supplies for my customers until my stolen goods are recovered. Have you had any luck?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 46700, 46753 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2077, ["x"] = 0.58, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 2077, ["x"] = 0.58, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 3, ["flags"] = 0 } } },
[28716] = { ["id"] = 28716, ["name"] = "Hero's Call: Twilight Highlands!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 27724, 27726, 27727, 28558, 28716, 60891 }, ["series"] = { 28238, 28596, 28832 }, ["description"] = "By order of his royal highness, King Anduin Wrynn , all able-bodied citizens of the Alliance are to report to the throne room in Stormwind Keep. King Wrynn requires a trustworthy and proven hero for a mission of the utmost importance. Stormwind Keep can be found in the eastern portion of Stormwind City . Anyone willing may report to Grand Admiral Jes-Tereth for briefing. For the glory and honor of the Alliance!", ["objectivesText"] = "Speak with Grand Admiral Jes-Tereth at Stormwind Keep in Stormwind.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 52326 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1750, ["x"] = 0.855, ["y"] = 0.326 }, { ["mapID"] = 84, ["npcID"] = 29611, ["x"] = 0.855, ["y"] = 0.32 }, { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5581, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[28717] = { ["id"] = 28717, ["name"] = "Warchief's Command: Twilight Highlands!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27718, 27721, 27722, 28557, 28717, 60887 }, ["series"] = { 26293, 26294 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to High Overlord Saurfang in Grommash Hold. High Overlord Saurfang requires your help to prepare for the glorious assault on the Twilight Highlands and our dual enemies, the Alliance and Twilight's Hammer. Meet with him in Grommash Hold at the center of Orgrimmar's Valley of Strength. Destiny calls!", ["objectivesText"] = "Report to High Overlord Saurfang at Grommash Hold in Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 14720, ["x"] = 0.485, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 39605, ["x"] = 0.4745, ["y"] = 0.5395 }, { ["mapID"] = 85, ["npcID"] = 86832, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5580, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[28721] = { ["id"] = 28721, ["name"] = "Walk A Mile In Their Shoes", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28721 }, ["description"] = "We have sent at least 3 different recon groups to investigate Farson Hold in the last few weeks. Sadly, not one of them has returned back with any info. At this point, all we can hope is that they are being held alive as prisoners. I need you to infiltrate the keep and help get our soldiers back. This won't be easy <name>, but if anyone can help us, it's you.", ["objectivesText"] = "Escort a Farson Keep Prisoner to safety. The hold is located on the northern tip of the island.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 11409 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 48358, ["x"] = 0.535333, ["y"] = 0.804667 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.535333, ["y"] = 0.804667 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "standard" },
[28723] = { ["id"] = 28723, ["name"] = "Priestess of the Moon", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731 }, ["description"] = "Perhaps you'd be willing to aid us in further pursuing the corruption haunting Shadowglen . Dentaria Silverglade , Priestess of the Moon, has offered to aid us. You should find her between the two pools just north of our great tree. Circle around the tree to reach her and offer her any help that you can, young <class>.", ["objectivesText"] = "Speak to Dentaria Silverglade between the two pools in the center of Shadowglen .", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2079, ["x"] = 0.578, ["y"] = 0.392 }, { ["mapID"] = 57, ["npcID"] = 3593, ["x"] = 0.588, ["y"] = 0.338 }, { ["mapID"] = 57, ["npcID"] = 3594, ["x"] = 0.588, ["y"] = 0.338 }, { ["mapID"] = 460, ["npcID"] = 3595, ["x"] = 0.485, ["y"] = 0.604333 }, { ["mapID"] = 57, ["npcID"] = 3596, ["x"] = 0.588, ["y"] = 0.358 }, { ["mapID"] = 57, ["npcID"] = 3597, ["x"] = 0.582, ["y"] = 0.35 }, { ["mapID"] = 460, ["npcID"] = 43006, ["x"] = 0.48525, ["y"] = 0.60875 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 57, 460 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 4, ["flags"] = 0 } } },
[28724] = { ["id"] = 28724, ["name"] = "Iverron's Antidote", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28725, 28726, 28727, 28728, 28729, 28730, 28731 }, ["description"] = "Our friend Iverron has fallen to poison from the nearby webwood spiders. I can tend to him to keep his state from deteriorating, but I need someone to gather an ingredient to prepare him an antidote. All around the ponds you should find Moonpetal Lilies . These flowers have great healing properties, and I can use them with the ingredients I already have to restore Iverron to better health. Would you gather them for me? There should be many just in sight of here, near the water's edge.", ["objectivesText"] = "Collect 7 Moonpetal Lilies . Progress: Our dear friend is not doing well, even with my mending. Have you brought the supplies I require?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 10641, 10655, 10656 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 5, ["flags"] = 0 } } },
[28725] = { ["id"] = 28725, ["name"] = "The Woodland Protector", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28724, 28726, 28727, 28728, 28729, 28730, 28731 }, ["description"] = "I must ask something more dangerous of you. Strange news has traveled to me through the whisperings of the forest spirits. The mysterious woodland protector, Tarindrella , has returned to Shadowglen again. The dryad's presence has not been felt in the forests since before the blessing of Teldrassil. Something is surely amiss if she has journeyed back to this land. Seek out Tarindrella in the Shadowthread cave to the north. It is dangerous, but we will be prepared with this antidote just in case.", ["objectivesText"] = "Seek out the dryad known as Tarindrella within the Shadowthread Cave at the northern end of Shadowglen .", ["rewardGold"] = 210675, ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 460, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 7, ["flags"] = 0 } } },
[28726] = { ["id"] = 28726, ["name"] = "Webwood Corruption", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 460, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28724, 28725, 28727, 28728, 28729, 28730, 28731 }, ["description"] = "I'd hoped to never return to Teldrassil for such grim business. I'd hoped that its corruption had been wiped away completely. Something foul lingers. These spiders suffer much more deeply from the corruption than the other nearby wildlife. They are becoming a danger to your people and a danger to the forest. We must thin their numbers, but more importantly, we need to find the source of the corruption that plagues them. I will come with you and aid you in this.", ["objectivesText"] = "Kill 12 Webwood Spiders . Progress: This is grim work. It pains me to have to inflict such violence on creature of the forest, corrupt or not.", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 5392, 5393, 5586, 10544 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 460, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 8, ["flags"] = 0 } } },
[28727] = { ["id"] = 28727, ["name"] = "Vile Touch", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 460, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28724, 28725, 28726, 28728, 28729, 28730, 28731 }, ["description"] = "If these spiders are born with corruption in their veins, then their broodmother must be at the root of this evil. Let us make our way to the far north end of the cave and seek out Githyiss the Vile . The answers we seek lie with her.", ["objectivesText"] = "Kill Githyiss the Vile at the northen end of the Shadowthread Cave. Progress: I adore these forests. I want to see the corruption purged from them completely. When next I return, I want to do so with a lighter heart.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 5405, 6058, 131704 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 460, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 9, ["flags"] = 0 } } },
[28728] = { ["id"] = 28728, ["name"] = "Signs of Things to Come", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28724, 28725, 28726, 28727, 28729, 28730, 28731 }, ["description"] = "I will pursue the trail of the Gnarlpine and track this corruption to its source. If you ever encounter Athridas Bearmantle in Dolanaar, he knows intimately of the problems that plague this forest, and he can direct you on how to help further. I'm sure we will meet again with time. Perhaps you can aid me in dealing with the source of this corruption once I locate it. For now, I will take you back to Dentaria so that you may finish your training. Thank you for all that you have done, <name>.", ["objectivesText"] = "Speak to Dentaria Silverglade between the pools in northern Shadowglen .", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 10, ["flags"] = 0 } } },
[28729] = { ["id"] = 28729, ["name"] = "Teldrassil: Crown of Azeroth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4, 22 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28724, 28725, 28726, 28727, 28728, 28730, 28731 }, ["description"] = "As part of a ritual to complete your training here in Shadowglen , you must learn about our recent history. There is a task you must perform. Go to the moonwell to our northeast and retrieve a phial of its water. While there, you will witness a glimpse of our magics and learn of our past. When you are done there, bring the water back to me, and I will direct you further.", ["objectivesText"] = "Fill the Crystal Phial at the moonwell in northeast Shadowglen . Progress: Our recent history is fraught with strife and violence. There is still much with which we must come to terms.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["rewardItems"] = { 5184, 5185 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 460, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 11, ["flags"] = 0 } } },
[28730] = { ["id"] = 28730, ["name"] = "Precious Waters", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4, 22 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28731 }, ["description"] = "Tenaron Stormgrip oversees all that happens in this glade. He presides at the top of Aldrassil. If you look to your south, you will see the underside of the ramp that leads up to him. Ascend this ramp and complete your training. It was wonderful to have met you, <name>. I swell with pride knowing that among young night elves, there are some so selfless and full of life as you are. You will do great things for our people. You will do great things for this world. Until we meet again.", ["objectivesText"] = "Bring the filled crystal phial to Tenaron Stormgrip at the top of Aldrassil in Shadowglen . Progress: The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world. The druids take advantage of its properties, the Sentinels revere the wells as shrines to Elune, and now even the returning Highborne look to the wells longingly.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["rewardItems"] = { 4907, 5184, 5395, 11189, 131705 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 49479, ["x"] = 0.572, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 3514, ["x"] = 0.584, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 460, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 6, ["flags"] = 0 } } },
[28731] = { ["id"] = 28731, ["name"] = "Teldrassil: Passing Awareness", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730 }, ["description"] = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him. Seek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen , and continue to follow the cobblestones as the road turns west. Mind you stay on the road though, <name>. There are dangerous beasts in the forests of late.", ["objectivesText"] = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar. Progress: Greetings, <class>. For what purpose do I owe the pleasure of our meeting?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 5186 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 3514, ["x"] = 0.584, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 3515, ["x"] = 0.459333, ["y"] = 0.482667 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 12, ["flags"] = 0 } } },
[28734] = { ["id"] = 28734, ["name"] = "A Favor for Melithar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6450, ["mapID"] = 57, ["storyline"] = { 28713, 28714, 28715, 28723, 28724, 28725, 28726, 28727, 28728, 28729, 28730, 28731, 28734 }, ["series"] = { 28713, 28714, 28715 }, ["description"] = "You should speak with Melithar. I believe he had some troubles with the grell already. I expect he can offer you a well needed place to store more of your goods should you aid him.", ["objectivesText"] = "Speak to Melithar Staghelm in Shadowglen .", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2079, ["x"] = 0.578, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 2077, ["x"] = 0.58, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 6450 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["questLines"] = { { ["id"] = 5396, ["name"] = "Shadowglen", ["orderIndex"] = 2, ["flags"] = 0 } } },
[28735] = { ["id"] = 28735, ["name"] = "To the Chamber of Incineration!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4926, ["storyline"] = { 28735 }, ["series"] = { 28732 }, ["description"] = "It was an ambush, <name>! As soon as we walked in a super-fat ogre named Rom'ogg Bonecrusher attacked us! Raz bravely defended me while I ran off to hide. I watched as they beat him unconscious and then dragged him to a place the fat one called the \"Chamber of Incineration.\" I think it's just down the hall across the bridge. I'm too scared to go any further. Take my all-purpose diving helm and search for Raz. I'll communicate with you through the helm. And if you find that ogre, kill him!", ["objectivesText"] = "Kill Rom'ogg Bonecrusher . Progress: <Pip's helm crackles with static.>", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4926 } }, ["questType"] = "standard" },
[28736] = { ["id"] = 28736, ["name"] = "Fire From the Sky", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28736 }, ["description"] = "The remnants of Schnottz's organization persist here on the Maker's Ascent, making the region deadly to any who draw near. There's plenty of ammunition, but without a good spotter, I'm just firing blind. Hop in and give me a hand here. Those soldiers won't know what hit them!", ["objectivesText"] = "Board the Confiscated Artillery and use it to kill 100 Schnottz Infantrymen. Progress: It's a target-rich environment, <class>.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 65868, 65869, 65870, 211279 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 49523, ["x"] = 0.442, ["y"] = 0.4795 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 49523, ["x"] = 0.442, ["y"] = 0.4795 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.4795 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[28737] = { ["id"] = 28737, ["name"] = "What Is This Place?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4926, ["storyline"] = { 28737 }, ["description"] = "<Pip's helm gives you a slight jolt.> What is this place? It looks like they're doing something terrible to that nether dragon. The energy is being siphoned from the creature into that lady! We need to stop this ritual! Kill Corla to get past this hall!", ["objectivesText"] = "Kill Corla, Herald of Twilight .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4926 } }, ["questType"] = "standard" },
[28738] = { ["id"] = 28738, ["name"] = "The Twilight Forge", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4926, ["storyline"] = { 28738 }, ["description"] = "<Pip's helm hums with energy.> Damn it! Raz won't stop! It's as if he were possessed with a burning vengeance for all things Twilight! It looks like if we're going to get past this room and catch up with Raz we'll need to take out the Twilight armorer, Karsh Steelbender . Kill him quick, <name>.", ["objectivesText"] = "Kill Karsh Steelbender . Progress: <Pip's helm crackles with static.>", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4926 } }, ["questType"] = "standard" },
[28740] = { ["id"] = 28740, ["name"] = "Do My Eyes Deceive Me?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4926, ["storyline"] = { 28740 }, ["description"] = "<Pip's helm explodes with the sound of a loud girlish scream.> IT CAN'T BE! I... I was stuck inside one of those beasts for the better part of a month. Yes, literally stuck inside its stomach. If it weren't for my suit and the all-purpose helm I'd have died a fiery death! And look at that, it's had a litter of pups! Y... You gotta stop that thing, <name>! We can't let it or its pups make it out of here alive!", ["objectivesText"] = "Kill Beauty .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 66887, 66889, 66890 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4926 } }, ["questType"] = "standard" },
[28741] = { ["id"] = 28741, ["name"] = "Ascendant Lord Obsidius", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4926, ["storyline"] = { 28741 }, ["description"] = "<Pip's helm buzzes.> GOOD GOLLY! Look at this place! A... Are those Deathwing's claw marks on the ceiling?! And what's that creature in the center of the chamber? I don't see Raz anywhere. Let's take care of this monster and find Raz!", ["objectivesText"] = "Kill Ascendant Lord Obsidius . Progress: <Pip's helm crackles with static.>", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 66884, 66885, 66886 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4926 } }, ["questType"] = "standard" },
[28746] = { ["id"] = 28746, ["name"] = "Penetrating Their Defenses", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4945, ["storyline"] = { 28746 }, ["series"] = { 27748, 28482, 28497, 28612, 28613, 28621, 28622, 28633, 28654, 28753 }, ["description"] = "Here we go, <name>! Just beyond that door lies the control room. I'll just run in, disable the reorigination mechanism, and then we all go home. Nice an' easy. Ye see, <lad/lass>, it's this level of preparation that separates yer true archaeologist from yer average treasure hunter. No sense in stirring up the beasties if ye don't have to. Just makes a mess a' things...", ["objectivesText"] = "Gain entry to the Titan Control Room. Progress: What is it, <name>?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 66911, 66913, 66914 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4945 } }, ["questType"] = "dungeon" },
[28751] = { ["id"] = 28751, ["name"] = "Tending the Garden", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 28751 }, ["description"] = "Even though we beat Warden Stillwater, his zombies still roam the countryside. Look there, another wave is approaching! Help me fight them off, old buddy! Let's go!", ["objectivesText"] = "Survive 2 Massive Waves of Zombies.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 49687, ["x"] = 0.335, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 49687, ["x"] = 0.335, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 267 } }, ["questType"] = "standard" },
[28757] = { ["id"] = 28757, ["name"] = "Beating Them Back!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 4, 7, 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28769, 28784, 28792, 28818, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31145 }, ["series"] = { 288, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride , commander of this garrison. Glad to have you on board... <McBride looks through some papers.> <name>. It is <name>, right? You've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon. Head northwest into the forest and kill the attacking Blackrock worgs ! Help my soldiers!", ["objectivesText"] = "Kill 6 Blackrock Worgs . Progress: Have you beaten back the Blackrock worgs ?", ["rewardGold"] = 2000, ["rewardXP"] = 400, ["rewardItems"] = { 57253, 57255, 118532, 131899 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 1, ["flags"] = 0 } } },
[28759] = { ["id"] = 28759, ["name"] = "Lions for Lambs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28759, 28767, 28780, 28791, 28817, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31145 }, ["series"] = { 288, 28757, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage. In the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them! Kill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", ["objectivesText"] = "Kill 8 Blackrock Spies . Progress: Kill the spies!", ["rewardGold"] = 1500, ["rewardXP"] = 400, ["rewardItems"] = { 57386, 57387, 57388, 131875 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 9, ["flags"] = 0 } } },
[28760] = { ["id"] = 28760, ["name"] = "Vengeance for Orsis", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5035, ["storyline"] = { 28760 }, ["series"] = { 28845 }, ["description"] = "The great city of Orsis was attacked by the armies of air. We were taken prisoner. We were the lucky ones. Most died, trapped beneath the choking desert sands. Asaad , Al'Akir's caliph, ordered the attack... and he must pay with his life.", ["objectivesText"] = "Slay Asaad .", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 66901, 66902, 66903 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5035 } }, ["questType"] = "dungeon" },
