[28780] = { ["id"] = 28780, ["name"] = "Join the Battle!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["requiredRaces"] = { 1, 32 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28759, 28767, 28780, 28791, 28817, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "I received an urgent message from Sergeant Willem . Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, <name>! Find Sergeant Willem north of the abbey at the command tent. Go!", ["objectivesText"] = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", ["rewardGold"] = 90, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 }, { ["mapID"] = 425, ["npcID"] = 43278, ["x"] = 0.362857, ["y"] = 0.532286 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37, 425 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 18, ["flags"] = 0 } } },
[28781] = { ["id"] = 28781, ["name"] = "Targets of Opportunity", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5396, ["mapID"] = 249, ["storyline"] = { 28781 }, ["description"] = "We were part of a clandestine operation put together by Prince Nadun of Ramkahen. We lost most of our unit during an ambush and we're now unable to finish our mission. Should you be up for it, I can arrange for a sizable reward for you. We were instructed to take out any targets of opportunity that would damage the enemy's military infrastructure. We've spotted General Husam and two of his captains up ahead. Slaying them for us will be a great favor for Ramkahen.", ["objectivesText"] = "Slay General Husam and 2 Oathsworn Captains . Progress: Is it done, <name>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 66905, 66906, 66907, 152733, 152737, 152740 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 50038, ["x"] = 0.3155, ["y"] = 0.1585 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 50038, ["x"] = 0.3155, ["y"] = 0.1585 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.3155, ["y"] = 0.1585 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5396 } }, ["questType"] = "dungeon" },
[28783] = { ["id"] = 28783, ["name"] = "The Source of Their Power", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5396, ["mapID"] = 249, ["storyline"] = { 28783 }, ["description"] = "We managed to do extensive scouting before our crew was ambushed. We discovered that Deathwing's envoy, Siamat , is giving the Neferset their newfound power. They claim it has restored them to the greatness of old, but something else has happened. Their very souls have been corrupted. As one of the four winds, Siamat is incredibly powerful. But that power has been drained considerably by this process. Strike now, while it is possible for you to slay him and bring an end to this madness.", ["objectivesText"] = "Slay Siamat .", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 63444, 66908, 66909, 66910 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 50038, ["x"] = 0.3155, ["y"] = 0.1585 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 50038, ["x"] = 0.3155, ["y"] = 0.1585 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.3155, ["y"] = 0.1585 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5396 } }, ["questType"] = "dungeon" },
