[28791] = { ["id"] = 28791, ["name"] = "They Sent Assassins", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["requiredRaces"] = { 1, 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28759, 28767, 28780, 28791, 28817, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "Have you ever seen a goblin, <name>? They're wretched little monsters that love only two things: gold and themselves. The Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass. I need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", ["objectivesText"] = "Kill 8 Goblin Assassins .", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 2186, 2691, 11192, 131924 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 27, ["flags"] = 0 } } },
