[28798] = { ["id"] = 28798, ["name"] = "Waters of Elune", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5004, ["storyline"] = { 28798 }, ["objectivesText"] = "Progress: You've found an unusual fountain; the water glows like moonlight and hums with soft tones. With a Highborne Scroll , and your impressive skill in archaeology, you could decipher the fountain's purpose.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5004 } }, ["questType"] = "dungeon" },
[28799] = { ["id"] = 28799, ["name"] = "Might of the Earthen", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5088, ["storyline"] = { 28799 }, ["objectivesText"] = "Progress: At first glance, this pillar seems very plain, but your knowledge of archaeology tells you differently. If you had a Dwarf Rune Stone , its originations could be brought to light.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5088 } }, ["questType"] = "dungeon" },
[28800] = { ["id"] = 28800, ["name"] = "Whispers of the Djinn", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5035, ["storyline"] = { 28800 }, ["objectivesText"] = "Progress: This brazier is obviously magical, but it seems impervious to your attempts to invoke its power. If only you had a Tol'vir Heiroglyphic keystone to help decipher the engravings on the side.", ["rewardGold"] = 289300, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5035 } }, ["questType"] = "dungeon" },
[28801] = { ["id"] = 28801, ["name"] = "Tol'vir Hieroglyphics", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5396, ["storyline"] = { 28801 }, ["objectivesText"] = "Progress: This gravestone marks a strange burial site - possibly from one of the original builders. If you could use a Tol'vir Hieroglyphic keystone to understand the words, it could be an important archaeological find!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5396 } }, ["questType"] = "dungeon" },
[28802] = { ["id"] = 28802, ["name"] = "Map of the Architects", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4945, ["storyline"] = { 28802 }, ["objectivesText"] = "Progress: This stone obelisk is obviously some sort of layout or map, but it isn't completely readable. Perhaps if you had a Tol'vir Hieroglyphic keystone, the markings might make more sense.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4945 } }, ["questType"] = "dungeon" },
[28803] = { ["id"] = 28803, ["name"] = "Vengeance of the Wildhammer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4950, ["storyline"] = { 28803 }, ["objectivesText"] = "Progress: These old bones appear dwarven, possibly from the original builders of Grim Batol. It's possible you could compare the markings on the stone belt buckle to a Dwarf Rune Stone , and discover more about this find.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4950 } }, ["questType"] = "dungeon" },
[28804] = { ["id"] = 28804, ["name"] = "Dark Iron Contingency Plan", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4926, ["storyline"] = { 28804 }, ["objectivesText"] = "Progress: These are definitely some sort of plans, but for what you aren't certain. They bear distinctive markings that could be compared to a Dwarf Rune Stone .", ["rewardGold"] = 7150, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4926 } }, ["questType"] = "dungeon" },
[28805] = { ["id"] = 28805, ["name"] = "The Eye of the Storm", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28805 }, ["series"] = { 25924, 25929, 25936, 25941, 27718, 28816 }, ["description"] = "Greetings, <name>. Yes, you are known to the Earthen Ring by name. Your exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes. I am but a messenger. A familiar presence seeks audience with you. Peer into the Waters of Farseeing and behold the fate of our world.", ["objectivesText"] = "Farseer Krogar wants you to look into the Waters of Farseeing. Progress: Yes, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 52584, 52636, 237812 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.469714, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
