[28814] = { ["id"] = 28814, ["name"] = "Followers and Leaders", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5088, ["storyline"] = { 28814 }, ["series"] = { 28815 }, ["description"] = "The documents detail the arrival of High Priestess Azil to the depths of the Stonecore . Azil is described as a high-ranking member of the Twilight Council. Additionally, her entourage of over a hundred devout followers is preparing for an unholy ritual of unforeseen darkness. Sounds like an event you need to put a stop to.", ["objectivesText"] = "Slay High Priestess Azil and 101 Devout Followers . Progress: You've returned, <name>. What news do you bring?", ["rewardGold"] = 137400, ["rewardXP"] = 8230, ["rewardItems"] = { 66891, 66892, 66893 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5088 } }, ["questType"] = "dungeon" },
[28816] = { ["id"] = 28816, ["name"] = "To the Depths", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 28816 }, ["series"] = { 25924, 25929, 25936, 25941, 27718, 28805 }, ["description"] = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies. It is still uncertain what dangers might be faced there. Any information you could gather would be of great value. The Horde is sending warships to the region as we speak. To gain passage, speak to Commander Thorak at Bladefist Bay. May the spirits guide you, <name>.", ["objectivesText"] = "Report to Commander Thorak at Bladefist Bay in Durotar.", ["rewardGold"] = 561800, ["rewardXP"] = 515, ["rewardItems"] = { 1804, 1805, 1806, 1807, 38126, 38127, 38128, 38146, 38148, 38150, 55186, 64592, 64602, 64611, 64619, 77947, 77948, 142357, 155198, 155211, 155212, 155217, 155219, 155226, 160519, 160521, 174360, 181549, 184374, 232471, 232877, 237812 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 41621, ["x"] = 0.558, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.469714, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[28817] = { ["id"] = 28817, ["name"] = "The Rear is Clear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["requiredRaces"] = { 1, 32 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28759, 28767, 28780, 28791, 28817, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "Excellent work, <name>! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, <class>.", ["objectivesText"] = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", ["rewardGold"] = 35, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 36, ["flags"] = 0 } } },
