[28823] = { ["id"] = 28823, ["name"] = "The Rear is Clear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["requiredRaces"] = { 1, 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28766, 28774, 28789, 28797, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "Excellent work, <name>! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, <class>.", ["objectivesText"] = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", ["rewardGold"] = 55, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 44, ["flags"] = 0 } } },
[28824] = { ["id"] = 28824, ["name"] = "Wayward Child", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 28824 }, ["description"] = "One of my children is not with me, <name>. He stayed behind with the Twilight's Hammer at the Stonecore deep within the Temple of Earth. I sent my other children to free him from the dark magic that was surely keeping him from returning here, but... no such magic was placed upon him. Go into the Stonecore and destroy Ozruk . He must be reclaimed by the earth.", ["objectivesText"] = "Slay Ozruk . Progress: Is it done, <race>?", ["rewardGold"] = 280900, ["rewardXP"] = 8230, ["rewardItems"] = { 66894, 66896, 66897 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 }, { ["mapID"] = 207, ["npcID"] = 43792, ["x"] = 0.496, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 }, { ["mapID"] = 207, ["npcID"] = 43792, ["x"] = 0.496, ["y"] = 0.532 }, { ["mapID"] = 207, ["npcID"] = 44025, ["x"] = 0.632, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "dungeon" },
[28825] = { ["id"] = 28825, ["name"] = "A Personal Summons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28825 }, ["series"] = { 14481, 14482, 24432, 25281, 25405, 27724, 28826, 28827 }, ["description"] = "<An unfamiliar feeling wells up from deep within you, flooding your mind with thoughts and images.> Hear my words, <name>. Our world finds itself in the grip of a terrible crisis. I call upon you to lend your aid in this desperate hour. I am Naraat. Seek me out at once, and your calling shall be revealed. I await you at the Eastern Earthshrine in Stormwind City .", ["objectivesText"] = "Speak to Naraat the Earthspeaker in Stormwind.", ["rewardXP"] = 1030, ["rewardItems"] = { 53053, 54345, 54639, 55186 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[28826] = { ["id"] = 28826, ["name"] = "The Eye of the Storm", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28826 }, ["series"] = { 14481, 14482, 24432, 25281, 25405, 27724, 28825, 28827 }, ["description"] = "Greetings, hero of Azeroth. We of the Earthen Ring know you by name, <name>. Your exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes. I am but a messenger. A powerful presence seeks audience with you. Peer into the Waters of Farseeing and behold the dilemma of our world.", ["objectivesText"] = "Naraat the Earthspeaker wants you to look into the Waters of Farseeing. Progress: Yes, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 52584, 52636, 53053, 54345, 54639, 55186, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[28827] = { ["id"] = 28827, ["name"] = "To the Depths", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 28827 }, ["series"] = { 14481, 14482, 24432, 25281, 25405, 27724, 28825, 28826 }, ["description"] = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies. It is still uncertain what dangers might be faced there, so any information you could gather would be of great value. The Alliance is sending warships to the region as we speak. To gain passage, travel northwest of Stormwind and speak to Recruiter Burns at Stormwind Harbor. May the spirits guide you, <name>.", ["objectivesText"] = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City .", ["rewardGold"] = 561800, ["rewardXP"] = 515, ["rewardItems"] = { 1804, 1805, 1806, 1807, 38126, 38127, 38128, 38146, 38148, 38150, 55186, 64592, 64602, 64611, 64619, 77947, 77948, 142357, 155198, 155211, 155212, 155217, 155219, 155226, 160519, 160521, 174360, 181549, 184374, 232471, 232877, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 36799, ["x"] = 0.2745, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[28833] = { ["id"] = 28833, ["name"] = "Rescue the Earthspeaker!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5004, ["storyline"] = { 28833 }, ["description"] = "Good! You've brought allies. You must hurry if we are to rescue Erunak. Fight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives. Don't worry about them coming up from behind you. Nothing's making it past me!", ["objectivesText"] = "Rescue Erunak Stonespeaker .", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 65654, 65655, 65656 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5004 } }, ["questType"] = "dungeon" },
[28834] = { ["id"] = 28834, ["name"] = "Rescue the Earthspeaker!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5004, ["storyline"] = { 28834 }, ["description"] = "Good! You've brought allies. You must hurry if we are to rescue Erunak. Go now. Fight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives. Don't worry about them coming up from behind you. I'll see that nothing makes it past me!", ["objectivesText"] = "Rescue Erunak Stonespeaker . Progress: I thank you, my friend.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 65654, 65655, 65656, 97919 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5004 } }, ["questType"] = "dungeon" },
[28836] = { ["id"] = 28836, ["name"] = "Sins of the Sea Witch", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5004, ["storyline"] = { 28836 }, ["description"] = "That vile worm has earned a thousand deaths! It won't be easy. She and her minions are firmly entrenched in this place, but she's bound to be exhausted from her fight with Neptulon. Now is the time to strike! We won't have another opportunity like this. Run her through, <name>!", ["objectivesText"] = "Slay Lady Naz'jar in the Throne of Tides.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 65657, 65658, 65659 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5004 } }, ["questType"] = "dungeon" },
[28843] = { ["id"] = 28843, ["name"] = "Sins of the Sea Witch", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5004, ["storyline"] = { 28843 }, ["description"] = "Naz'jar! She's the one responsible for this mess. She's in here somewhere, <name>. She must be exhausted after that fight with Neptulon. Now is the time to strike! We won't have another opportunity like this. I'll handle anything that tries to aid her from this direction. Find her, <name>, and run her through!", ["objectivesText"] = "Legionnaire Nazgrim wants you to slay Lady Naz'jar . Progress: Is it done, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 65657, 65658, 65659 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5004 } }, ["questType"] = "dungeon" },
[28845] = { ["id"] = 28845, ["name"] = "The Vortex Pinnacle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28845 }, ["series"] = { 28760 }, ["description"] = "One of our civilian leaders was taken prisoner by the air elementals. They are probably torturing him for information as we speak. Go to the Vortex Pinnacle , where these foul creatures came from, and look for Itesh . You will find the entrance to the Vortex Pinnacle hovering off of the southeastern coast of Uldum.", ["objectivesText"] = "Find Itesh inside the Vortex Pinnacle .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 45772, ["x"] = 0.452, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[28852] = { ["id"] = 28852, ["name"] = "Soften them Up", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4950, ["storyline"] = { 28852 }, ["description"] = "At last, reinforcements! I'm so glad you're here. We never imagined just how entrenched the Twilight's Hammer forces are. And there are so many! Several of our drakes have been captured just inside the main hall. Please, break their bonds and free them. Once free, together we can scourge these halls clean with flame. Just climb aboard a red drake and call out your targets. You will definitely want to cut down the enemy numbers before delving deeper into the ruins.", ["objectivesText"] = "Free a Red Drake within Grim Batol and use it to destroy 30 Troggs and 15 Twilight's Hammer minions.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 66943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4950 } }, ["questType"] = "dungeon" },
[28854] = { ["id"] = 28854, ["name"] = "Closing a Dark Chapter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4950, ["storyline"] = { 28854 }, ["description"] = "This terrible place was Alexstrasza's nightmare. During what mortals call the second war, she was chained in the depths below, her tormented offspring forced to serve the demon-corrupted Horde. Alexstrasza may be free, but the beast known as Erudax still corrupts her offspring below. < Baleflame 's body tenses in anger.> Destroy him, <class>. Crush him that we may end these horrors once and for all!", ["objectivesText"] = "Slay Erudax , the Duke of Below. Progress: What of Erudax , <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 66933, 66934, 66935 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4950 } }, ["questType"] = "dungeon" },
[28860] = { ["id"] = 28860, ["name"] = "Keeping the Dragonmaw at Bay", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28860 }, ["description"] = "With your help we've thumped the Dragonmaw pretty hard, but still their daily attacks in the Thundermar outskirts persist. We need to keep up the pressure! Wade back into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear.", ["objectivesText"] = "Kill Dragonmaw Marauders and collect 8 Dragonmaw Insignias . Named characters within the Thundermar Ruins will also carry insignias. Progress: How goes the fight, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62332 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 46591, ["x"] = 0.49, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 46591, ["x"] = 0.49, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28861] = { ["id"] = 28861, ["name"] = "Fight Like a Wildhammer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28861 }, ["description"] = "<Blundy upends his cup.> I'm all outta ale, <name>! Head out into the Thundermar Ruins and see if there's any left, before those grungy Dragonmaw get their mouths on it. Feel free to have a few sips, yerself. A mug of ol' Thundermar's finest will fortify yer fightin' skills.", ["objectivesText"] = "Collect 10 Kegs of Thundermar Ale from the Thundermar Ruins. Carfeul - it's got some kick! Progress: Got sumthun'?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 6948, 46874, 51558, 62330, 62675, 63206, 63207, 63818, 63819, 63820 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 48010, ["x"] = 0.496, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 48010, ["x"] = 0.496, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28862] = { ["id"] = 28862, ["name"] = "Never Leave a Dinner Behind", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28862 }, ["description"] = "Refugees are still pouring into Thundermar from the fighting, and I'm hungry! I mean them. The refugees, they're hungry. Get me some food from the Thundermar Ruins! Scour the ruins to the south, east, and southwest for any stores that still remain. Especially them big hocks of ham. I love those! Er, the refugees do. And see if you can find some of them little cocktail weenies.", ["objectivesText"] = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins. Progress: Got some eats?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62324 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 48010, ["x"] = 0.496, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 48010, ["x"] = 0.496, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28863] = { ["id"] = 28863, ["name"] = "Warlord Halthar is Back", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28863 }, ["description"] = "He's at it again, <name>. Warlord Halthar ... terror of the shire. He and his drake were spotted causing trouble to the south, among the Thundermar Ruins. Kill Halthar, <name>! We'll send in some warbrands to help out once you engage.", ["objectivesText"] = "Slay Warlord Halthar .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 49386, ["x"] = 0.486, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 49386, ["x"] = 0.486, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "group" },
[28864] = { ["id"] = 28864, ["name"] = "Beer Run", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28864 }, ["description"] = "After my sister's wedding, I developed a taste for that Thunderbrew Lager that Kurdran had imported from Dun Morogh. More is on the way, but our caravan keeps getting jumped by the Dragonmaw! Head on up to the southeast side of Thunderstrike Mountain and catch up with the caravan. Look for a fellow named Hammelhand at the side of the road, and help him get the booze through the pass. Just get it as far as Kirthaven, and we'll take it from there.", ["objectivesText"] = "Speak with Hammelhand on the road southeast of Thunderstrike Mountain and escort a supply caravan to Kirthaven.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 46591, ["x"] = 0.49, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 46591, ["x"] = 0.49, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28866] = { ["id"] = 28866, ["name"] = "Into the Stonecore", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 28866 }, ["description"] = "You say that this Millhouse Manastorm and High Priestess Azil were to meet inside the Stonecore ? Sounds big. We'd best get on their trail. We don't want the Twilight's Hammer pulling off something big right under our noses. Speak to Earthwarden Yrsa inside the Stonecore . She's been stationed there to make sure the Twilight's Hammer doesn't try to retake the Temple of Earth.", ["objectivesText"] = "Speak to Earthwarden Yrsa inside the Stonecore .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44010, ["x"] = 0.645, ["y"] = 0.821 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.821 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "dungeon" },
[28868] = { ["id"] = 28868, ["name"] = "The View from Down Here", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 313, 314, 315, 384, 412, 432, 433, 25667, 25668, 25724, 25792, 25838, 25839, 25840, 25841, 25905, 25932, 25933, 25937, 25978, 25979, 25997, 25998, 26078, 26085, 26094, 26102, 26112, 26118, 28868 }, ["description"] = "We need to halt the construction on this Frostmane village. If we let them get too entrenched, it will be more difficult to keep them from settling here permanently. It's time to give those brutes a gnome's-eye view of the world! Take this gnomish viewpoint equalizer and use it on the Frostmane builders to bring them down to our level. They won't be able to lift their tools and construction will come to a standstill.", ["objectivesText"] = "Use the Viewpoint Equalizer on 5 Frostmane Builders in Frostmane Retreat. Progress: Did you show them what it's like to be a gnome?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 67249 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 50601, ["x"] = 0.625, ["y"] = 0.537 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 50601, ["x"] = 0.625, ["y"] = 0.537 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.537 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 27, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 567, ["name"] = "Dun Morogh", ["orderIndex"] = 10, ["flags"] = 0 } } },
[28870] = { ["id"] = 28870, ["name"] = "Return to the Lost City", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28870 }, ["description"] = "We might've taken Neferset City, but the Neferset have a new seat of power. Thanks to Siamat, the powerful djinn of the south wind, the Neferset have become considerably more dangerous. We just learned that some of Nadun's ambushed reconnaissance party managed to secure the entrance to the Lost City. Go find Captain Hadan and get whatever information you need to bring down Siamat and the Neferset scum.", ["objectivesText"] = "Speak to Captain Hadan inside the Lost City of the Tol'vir .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 62483 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 50038, ["x"] = 0.3155, ["y"] = 0.1585 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "dungeon" },
[28871] = { ["id"] = 28871, ["name"] = "Crushing the Wildhammer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28871 }, ["description"] = "The Wildhammer grow bold with their new Alliance allies. They dare press across the river. Drive them back! Seek out and crush the Wildhammer warbrands who fight in the riverbed and within the Thundermar Ruins along the north bank. The best among them carry insignias - gather them for me to prove your allegiance to the Dragonmaw cause.", ["objectivesText"] = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias . Named characters within the Thundermar Ruins will also carry insignias. Progress: Show me the insignias you've collected, <class>.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62325, 63821, 63822, 63823 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 50622, ["x"] = 0.54, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 50622, ["x"] = 0.54, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28872] = { ["id"] = 28872, ["name"] = "Total War", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28872 }, ["description"] = "Some of the Wildhammer still cling to the hope of reclaiming the Thundermar Ruins to the north, across the river. Burn them out! Smash open kegs of Thundermar ale. That wicked brew is potent enough to explode when set aflame. Don't ask me why. And don't ask me how they drink the stuff.", ["objectivesText"] = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 63815, 63816, 63817 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 46318, ["x"] = 0.55, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 46318, ["x"] = 0.55, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28873] = { ["id"] = 28873, ["name"] = "Another Maw to Feed", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28873 }, ["description"] = "< Griff 's stomach growls.> Still hungry. It's like ... every day, I'm hungry. I hear there's more food stashed up in the Thundermar Ruins across the river to the north, where all the fighting is. Bring some to my mouth.", ["objectivesText"] = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins. Progress: < Griff licks his lips.>", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62324 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 46319, ["x"] = 0.538, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 46319, ["x"] = 0.538, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28874] = { ["id"] = 28874, ["name"] = "Hook 'em High", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28874 }, ["description"] = "The Wildhammer can train war gryphons faster than we can subvert and control drakes. We can't let them continue to outnumber us! Hunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Kill the dismounted gryphon riders!", ["objectivesText"] = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62775 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 46318, ["x"] = 0.55, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 46318, ["x"] = 0.55, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[28875] = { ["id"] = 28875, ["name"] = "Bring Down the High Shaman", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 28875 }, ["description"] = "Our scouts in the field report that High Shaman MacKilligan has moved out of Thundermar and is fighting amidst the Thundermar Ruins northwest of here, across the river. He's a dangerous one, <name>, responsible for the deaths of many a Dragonmaw. He WILL be destroyed, that is not the question. The question is: will you be the one to earn the glory of the kill?", ["objectivesText"] = "Slay High Shaman MacKilligan .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 49387, ["x"] = 0.538, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 49387, ["x"] = 0.538, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "group" },
[28878] = { ["id"] = 28878, ["name"] = "A Winter Veil Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Feast of Winter Veil", ["expansion"] = 3, ["zoneID"] = 1637, ["storyline"] = { 28878 }, ["rewardItems"] = { 34426, 43504, 46740, 67443, 70938, 90892, 104319, 116761, 128653, 139341, 151350, 162644, 172224, 178528, 187561, 192094, 209871, 218311, 244908 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[28879] = { ["id"] = 28879, ["name"] = "Back To The Orphanage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 4395, ["storyline"] = { 28879 }, ["description"] = "We had the best time with you, <name>. We wish you could be our <daddy/mama> now, but you have to take us back to Orphan Matron Aria in Dalaran. Maybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One! We going to miss you, <name>. We promise to write letter sometime, oki?", ["objectivesText"] = "Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.", ["rewardXP"] = 710, ["rewardItems"] = { 23022, 32616, 32617, 32622, 46544, 46545, 69648, 71153, 116202, 241215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[28880] = { ["id"] = 28880, ["name"] = "Back To The Orphanage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 4395, ["storyline"] = { 28880 }, ["description"] = "Know what? You not so bad after all, <name>. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do. You, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes. Kekek gotta go back to orphan-lady Aria now, back in purple human city.", ["objectivesText"] = "Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.", ["rewardXP"] = 710, ["rewardItems"] = { 23022, 32616, 32617, 32622, 46544, 46545, 69648, 71153, 116202, 241215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[28882] = { ["id"] = 28882, ["name"] = "Victory in Tol Barad", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28882 }, ["description"] = "We fought hard to get a foothold on this ugly rock and there is no way we are going to let the Horde get in the way of our plans. Keeping control of Tol Barad is our first priority and we need your help, <name>. Fight your way to victory in Tol Barad and return to me word of your triumph.", ["objectivesText"] = "Win a Tol Barad battle and return to Major Marsden at Baradin Base Camp in Tol Barad Peninsula. Progress: Were you victorious against the Horde?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 51288, ["x"] = 0.745, ["y"] = 0.6045 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 51288, ["x"] = 0.745, ["y"] = 0.6045 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.6045 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "pvp" },
[28884] = { ["id"] = 28884, ["name"] = "Victory in Tol Barad", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5389, ["mapID"] = 245, ["storyline"] = { 28884 }, ["description"] = "Maintaining control of Tol Barad is the key to our strategic plans here in the Eastern Kingdoms, <race>. We must do whatever it takes to keep the Alliance off this island and that means we need your help. Fight with everything you have to win control of Tol Barad and bring me word of victory.", ["objectivesText"] = "Win a Tol Barad battle and return to Colonel Karzag at Hellscream's Grasp in Tol Barad Peninsula. Progress: Were you victorious against the Alliance?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 64402 }, ["starts"] = { { ["mapID"] = 245, ["npcID"] = 51287, ["x"] = 0.543, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 245, ["npcID"] = 51287, ["x"] = 0.543, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 245, ["source"] = "quest_giver", ["x"] = 0.543, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 245 }, ["zone"] = { 5389 } }, ["questType"] = "pvp" },
