[29030] = { ["id"] = 29030, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29030 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Earthen Ring Bonfire in Hyjal.", ["rewardGold"] = 157900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 51682, ["x"] = 0.628, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
