[29036] = { ["id"] = 29036, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 29036 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Earthen Ring Bonfire in Deepholm.", ["rewardGold"] = 110640, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 51698, ["x"] = 0.494, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[29054] = { ["id"] = 29054, ["name"] = "Stink Bombs Away!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 29054 }, ["description"] = "Greetings, <class>! I hope Hallow's End is treating you well. Bah, enough of the small talk... Let's get down to business. Undercity. They have employed Hags and foul magic to launch petty attacks on our town. Some may say, ignore the childish Horde. I say, let's show them! Speak to my sister, Gertrude, and she will send you on your way to toss some stink bombs in Undercity.", ["objectivesText"] = "Speak to Gertrude Fenlow to gain access to a broom, then drop stink bombs in the Undercity. Progress: Bombs away, am I right?", ["rewardXP"] = 1060, ["rewardItems"] = { 33226, 37011, 65360, 68648, 69191 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 51934, ["x"] = 0.557333, ["y"] = 0.775667 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 51934, ["x"] = 0.557333, ["y"] = 0.775667 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.557333, ["y"] = 0.775667 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29067] = { ["id"] = 29067, ["name"] = "Potion Master", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 88, ["storyline"] = { 29067 }, ["description"] = "Potions, potions, potions. Can I teach you about potions! You're going to have to bring me samples of your work, so I know you're ready. Remember <name>, you can only learn ONE specialization, so if you complete your potion training, then elixir and transmutation specialization will no longer be available.", ["objectivesText"] = "Bring a large supply of potions to an alchemy trainer in any capital city. Progress: Have you the potions?", ["rewardItems"] = { 3371, 52983, 52984, 52986, 52987, 52988, 76097, 76098, 93351, 156633 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3009, ["x"] = 0.468, ["y"] = 0.335 }, { ["mapID"] = 85, ["npcID"] = 3347, ["x"] = 0.554333, ["y"] = 0.459333 }, { ["mapID"] = 87, ["npcID"] = 5177, ["x"] = 0.6665, ["y"] = 0.5505 }, { ["mapID"] = 84, ["npcID"] = 5499, ["x"] = 0.555, ["y"] = 0.855 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3347, ["x"] = 0.554333, ["y"] = 0.459333 }, { ["mapID"] = 89, ["npcID"] = 4160, ["x"] = 0.466667, ["y"] = 0.407333 }, { ["mapID"] = 84, ["npcID"] = 5499, ["x"] = 0.555, ["y"] = 0.855 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 87, 88, 89 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29071] = { ["id"] = 29071, ["name"] = "Make Haste to Stormwind!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 6611, ["storyline"] = { 29071 }, ["rewardItems"] = { 68808 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard" },
[29074] = { ["id"] = 29074, ["name"] = "A Season for Celebration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 84, ["storyline"] = { 29074 }, ["series"] = { 29075 }, ["description"] = "Merry met, <class>! Hallow's End is a time for celebration and reflection, though many of us have forgotten why. Indeed some aspects of the festival, like the Wickerman, had been lost to time... until the Gilneans returned to the Alliance fold. Travel outside the gates of Stormwind and speak to Celestine of the Harvest . She can tell you more about the Wickerman ceremony.", ["objectivesText"] = "Speak with Celestine of the Harvest just outside the gates of Stormwind.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 18927, ["x"] = 0.628143, ["y"] = 0.557571 }, { ["mapID"] = 87, ["npcID"] = 19148, ["x"] = 0.3115, ["y"] = 0.665625 }, { ["mapID"] = 103, ["npcID"] = 19171, ["x"] = 0.571375, ["y"] = 0.437 }, { ["mapID"] = 87, ["npcID"] = 19172, ["x"] = 0.575333, ["y"] = 0.489333 }, { ["mapID"] = 89, ["npcID"] = 19173, ["x"] = 0.445, ["y"] = 0.529 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 51665, ["x"] = 0.32, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.628143, ["y"] = 0.557571 }, ["mapCandidates"] = { ["npc"] = { 10, 37, 84, 87, 89, 103, 2339 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29075] = { ["id"] = 29075, ["name"] = "A Time to Gain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 29075 }, ["series"] = { 29074 }, ["description"] = "Greetings, <class>. The Wickerman you see before you symbolizes self. The flames that burn it are a cleansing fire. Tradition states that we take our burdens and give them to the fires. We let go of our burdens as we approach the winter season and we gain clarity and peace. Join us in our tradition, <class>. Take a branch from the nearby bonfire and hurl it at the Wickerman.", ["objectivesText"] = "Use the bonfire in front of the Wickerman. Progress: Have you released your burdens, <class>?", ["rewardXP"] = 710, ["rewardItems"] = { 33226, 68648, 69191 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 51665, ["x"] = 0.32, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 51665, ["x"] = 0.32, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29078] = { ["id"] = 29078, ["name"] = "Beating Them Back!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "Another Alliance recruit, eh? I'm Marshal McBride , commander of this garrison. We don't see many of your kind here, <race>, but we could sure use the help. You've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon. Head northwest into the forest and kill the attacking Blackrock worgs ! Help my soldiers!", ["objectivesText"] = "Kill 6 Blackrock Worgs . Progress: Have you beaten back the Blackrock worgs ?", ["rewardGold"] = 2000, ["rewardXP"] = 400, ["rewardItems"] = { 57253, 57255, 118532, 131899 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 3, ["flags"] = 0 } } },
[29079] = { ["id"] = 29079, ["name"] = "Lions for Lambs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage. In the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them! Kill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", ["objectivesText"] = "Kill 8 Blackrock Spies . Progress: Kill the spies!", ["rewardGold"] = 1500, ["rewardXP"] = 400, ["rewardItems"] = { 57386, 57387, 57388, 131875 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 12, ["flags"] = 0 } } },
[29080] = { ["id"] = 29080, ["name"] = "Join the Battle!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "I have here an urgent message from Sergeant Willem . Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, <name>! Find Sergeant Willem north of the abbey at the command tent. Go!", ["objectivesText"] = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", ["rewardGold"] = 430, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 21, ["flags"] = 0 } } },
[29081] = { ["id"] = 29081, ["name"] = "They Sent Assassins", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 31139, 31140, 31143, 31144 }, ["description"] = "Have you ever seen a goblin, <name>? They're wretched little monsters that love only two things: gold and themselves. The Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass. I need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", ["objectivesText"] = "Kill 8 Goblin Assassins .", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 2186, 2691, 11192, 131924 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 30, ["flags"] = 0 } } },
[29082] = { ["id"] = 29082, ["name"] = "Fear No Evil", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 29082 }, ["description"] = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.", ["objectivesText"] = "Revive 4 Injured Stormwind Soldiers. Progress: Rescue our soldiers!", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57256, 57257, 57258, 65733, 131874 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard" },
[29083] = { ["id"] = 29083, ["name"] = "The Rear is Clear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 54, 26389, 26390, 26391, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 28823, 29078, 29079, 29080, 29081, 29083, 31139, 31140, 31143, 31144, 31145 }, ["series"] = { 288, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 28791, 28792, 28793, 28794, 28795, 28796, 28797, 28817, 28818, 28819, 28820, 28821, 28822, 29078, 29079, 29080, 29081, 31139, 31140, 31143, 31144 }, ["description"] = "Excellent work, <name>! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, <class>.", ["objectivesText"] = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", ["rewardGold"] = 170, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 823, ["x"] = 0.488, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 197, ["x"] = 0.48, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 39, ["flags"] = 0 } } },
[29084] = { ["id"] = 29084, ["name"] = "Classic Random 35-39 (1st)", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29084 }, ["rewardGold"] = 18000, ["rewardXP"] = 400, ["rewardItems"] = { 156683 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29092] = { ["id"] = 29092, ["name"] = "Inform the Elder", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 3, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 29092 }, ["description"] = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", ["objectivesText"] = "Travel to a capital city and speak to the Earthen Ring Elder .", ["rewardXP"] = 100, ["rewardItems"] = { 35828 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 25324, ["x"] = 0.133659, ["y"] = 0.17678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.133659, ["y"] = 0.17678 }, ["mapCandidates"] = { ["npc"] = { 18, 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[29093] = { ["id"] = 29093, ["name"] = "Cruisin' the Chasm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 40, ["storyline"] = { 29093 }, ["description"] = "One of my friends says that a steam tank mechanic in Westfall lets visitors use his choppers. My friend even got to ride one! I've seen people ride by the orphanage in choppers. They're real loud and just about the fastest thing I've ever seen! I want to try one out! Could we go to Sentinel Hill in Westfall and ride one of those choppers? Please? I promise to behave myself and we could see the crazy giant hole left when the world changed!", ["objectivesText"] = "Travel to Sentinel Hill in Westfall and climb aboard a Rental Chopper to tour the Raging Chasm with your orphan. Progress: This is going to be the best week ever!", ["rewardXP"] = 1415, ["rewardItems"] = { 18598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard" },
[29100] = { ["id"] = 29100, ["name"] = "Bwemba's Spirit", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29100 }, ["description"] = "Dese be troublin' times for us Darkspear. Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost. We tryin' to warn all dat we can. But it might be too late. Another Darkspear gone down to Stranglethorn to warn da people. But it ain't safe to travel alone in Stranglethorn. Help me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes. I gonna bind my spirit wit' ya. When ya get to Stranglethorn, I be able to aid ya.", ["objectivesText"] = "Warn the people of Stranglethorn and find the other Darkspear emissary. Progress: Dis won't be no easy task, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 4397, 9172, 68833 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 52654, ["x"] = 0.297, ["y"] = 0.3995 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.297, ["y"] = 0.3995 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29101] = { ["id"] = 29101, ["name"] = "Punting Season", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29101 }, ["series"] = { 29122 }, ["description"] = "Baby turtles are sweet, even if they can be somewhat bitey. < Mylune holds up a bandaged finger.> But they're so slow with their tiny little legs, they can't escape the fire creatures who are attacking Hyjal! < Mylune claps her hands together.> PLEASE save them, <name>! Pick up the wee turtles and punt them into the water of the Ashen Lake. Don't worry about the kicking, they have hard shells. They also have hard teeth, so don't pick them up by the mouth.", ["objectivesText"] = "Punt 5 Children of Tortolla into water.", ["rewardXP"] = 3290, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29102] = { ["id"] = 29102, ["name"] = "To Fort Livingston", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29102 }, ["series"] = { 29103 }, ["description"] = "Da first place we check gonna be da place most likely to be attacked first. You call it Fort Livingston. Fort Livingston be surrounded by troll ruins... It make for an easy target. Maybe we find da emissary dere. Hopefully it ain't too late.", ["objectivesText"] = "Head to Fort Livingston in Northern Stranglethorn Vale to find the Darkspear emissary.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 52654, ["x"] = 0.297, ["y"] = 0.3995 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52281, ["x"] = 0.526, ["y"] = 0.666667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.297, ["y"] = 0.3995 }, ["mapCandidates"] = { ["npc"] = { 50, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29103] = { ["id"] = 29103, ["name"] = "Serpents and Poison", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29103 }, ["series"] = { 29102 }, ["description"] = "Because of the emissary's warning we were able to gather more adventurers to help defend. But we thought we were going to be fighting trolls. Instead we found ourselves overwhelmed by serpents! They seem to have come from everywhere. We are barely able to hold on, and I only suspect it's going to get worse. Help us and eliminate the serpents and perhaps your troll friend here can use some magic to cure the poisoned.", ["objectivesText"] = "Kill Jungle Serpents and inspect the poisoned adventurers to allow Bwemba to heal them. Progress: It doesn't look like there is an end to these serpents.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52281, ["x"] = 0.526, ["y"] = 0.666667 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52281, ["x"] = 0.526, ["y"] = 0.666667 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.666667 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29104] = { ["id"] = 29104, ["name"] = "Spirits Are With Us", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29104 }, ["description"] = "Dere was somethin' not right about dem serpents, <name>. Dere was a trace of some bad mojo in da poison an' dat don't happen naturally. Da bonfire in da middle of da camp, we can use dat to perform a ritual. Whatever be makin' dese serpents attack, dey probably still watchin' over dem. Da only problem, <name>, is dat I only be here in spirit form. I need you to be my hands. I need you to go to da fire an' prepare it for me. Den I'll handle da rest.", ["objectivesText"] = "Prepare the bonfire in Fort Livingston for Bwemba 's ritual.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29105] = { ["id"] = 29105, ["name"] = "Nesingwary Will Know", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29105 }, ["series"] = { 29114, 29115 }, ["description"] = "Great, just what we need, the Gurubashi on the rampage using serpents to lead the charge. Well at least we know that much. It's probably a safe bet that the hunters at Nesingwary's Expedition have some insight into this. If they don't they at least know how to fight the serpents. Head there and let them know what you saw here. Let them know that the trolls are using serpents as their weapon.", ["objectivesText"] = "Warn the hunters at Nesingwary's Expedition in Northern Stranglethorn Vale.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52281, ["x"] = 0.526, ["y"] = 0.666667 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52294, ["x"] = 0.44, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.666667 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29106] = { ["id"] = 29106, ["name"] = "The Biggest Diamond Ever!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["storyline"] = { 29106 }, ["description"] = "I heard that Magni Bronzebeard, who used to be the king of Ironforge, turned into a giant diamond! Is that true? How does someone just turn into a diamond? Maybe you have to be a king and that's why no one's done it before. Can we go see him? He should be in the part of Ironforge called Old Ironforge underneath the High Seat.", ["objectivesText"] = "Take your Human Orphan into Old Ironforge, beneath the High Seat. Make sure to call for him if he is not present when you arrive. Progress: I've never met a king before.", ["rewardXP"] = 1415, ["rewardItems"] = { 18598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29114] = { ["id"] = 29114, ["name"] = "Track the Tracker", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29114 }, ["series"] = { 29105, 29115 }, ["description"] = "We've been fending off serpents for days now, <name>. But the serpents are nothing compared to what else is out in that jungle. We hunters are being hunted. A large panther named Mauti has been dragging my men off into the bush. We sent Grent Direhammer , one of our best hunters, to track this beast down. Direhammer headed off to the east, perhaps you can find them there.", ["objectivesText"] = "Find Grent Direhammer in Northern Stranglethorn Vale.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 94219 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52294, ["x"] = 0.44, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52346, ["x"] = 0.502, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29115] = { ["id"] = 29115, ["name"] = "The Hunter's Revenge", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29115 }, ["series"] = { 29105, 29114 }, ["description"] = "The beast that's been hunting us... I've been hunting it. We call him Mauti. He's a clever one. But he made a grave mistake when he killed my brother. Now that mistake is going to cost him. Ol' Direhammer has got his scent. I've noticed him roaming just above Kurzen's Compound. If we act fast, we can take him down. Are you ready, <name>?", ["objectivesText"] = "Give Grent Direhammer the closure he needs by killing Mauti.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52346, ["x"] = 0.502, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.216 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29117] = { ["id"] = 29117, ["name"] = "Let's Go Fly a Kite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 1519, ["storyline"] = { 29117 }, ["description"] = "The other day, when some of us were out with the matron, I saw a gnome pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time. I think the gnome's name was Craggle Wobbletop or something like that. If we can find him, could we get some kites and fly them together? I saw him walking around the canals outside the Trade District.", ["objectivesText"] = "Purchase a Dragon Kite Two-Pack from Craggle Wobbletop in Stormwind and then use it to fly kites with your Human Orphan . If your orphan is not present, call for him. Progress: I thought for sure I was going to have to save all my money for like a million years to get a kite!", ["rewardXP"] = 1415, ["rewardItems"] = { 18598, 35223, 68890, 69231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29118] = { ["id"] = 29118, ["name"] = "Follow That Cat", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["storyline"] = { 29118 }, ["series"] = { 29120, 29121, 29213 }, ["description"] = "The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him. Find Direhammer before it's too late!", ["objectivesText"] = "Find where Mauti has taken Grent Direhammer.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29119] = { ["id"] = 29119, ["name"] = "You Scream, I Scream...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 1519, ["storyline"] = { 29119 }, ["description"] = "There's a brand new ice cream shop in Stormwind, and it's not just any old ice cream either. This ice cream is made by mages! You don't think I'm going to be hungry fifteen minutes after eating it, do you? I bet it tastes really good. Let's go try it! I heard some of the other kids talking about it, and they were saying the store is called The Cone of Cold and it's over near the Blue Recluse in the Mage Quarter.", ["objectivesText"] = "Purchase ice cream at The Cone of Cold and then share it with your orphan. Progress: Ice cream is my favorite.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 18598, 63582, 63583, 63584, 63585, 63586, 69027, 87399, 108439, 157017, 157018, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29120] = { ["id"] = 29120, ["name"] = "Mauti", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29120 }, ["series"] = { 29118, 29121, 29213 }, ["description"] = "I got da feeling dat somethin' ain't right wit' dat panther, <name>. It ain't natural. I gonna need to perform some rituals over da body. Put Mauti down, an' den let's see what we can find out, <name>.", ["objectivesText"] = "Bring Bwemba to the remains of Mauti. Progress: Mauti, she got some powerful mojo, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 8630 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29121] = { ["id"] = 29121, ["name"] = "Bury Me With Me Boots...", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29121 }, ["series"] = { 29118, 29120, 29213 }, ["description"] = "Ah... It's you, <name>. Mauti... He's dead? Then my brother has been avenged. I've only one request from ya... This scamp here, he's been pawing at me bare feet. No dwarf should go to the earth with bare feet. Please, bury me with me boots.", ["objectivesText"] = "Collect Grent Direhammer's boots . Progress: Do ya have me boots? Grant a dwarf his last request will ya?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 68937 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52371, ["x"] = 0.76, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52371, ["x"] = 0.76, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29122] = { ["id"] = 29122, ["name"] = "Echoes of Nemesis", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29122 }, ["series"] = { 29101 }, ["description"] = "< Mylune 's voice sings like a melody in your head.> Remember that awful fire turtle, Nemesis , from the Firelands? He's dead now (yay!) but echoes of him keep trying to break through to Mount Hyjal. Go to the shores of the Ashen Lake and speak with my friend Tooga. Let him know you're ready to fight an echo of Nemesis , and the turtles will draw him into this world. Then you can hit him! Hard! Hide inside of Tooga's shell if he starts to erupt.", ["objectivesText"] = "Speak with Tooga to summon and kill Nemesis . Stand under Tooga's shell to protect you from Nemesis ' Molten Fury.", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29124] = { ["id"] = 29124, ["name"] = "Warn the Rebel Camp", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29124 }, ["series"] = { 29131 }, ["description"] = "Dis death ain't be in vain, <name>. We figure out dat Kilnara be on da prowl. Tings don't look good. We better check out da Rebel Camp to da north. Maybe we find my contact dere.", ["objectivesText"] = "Make your way to the Rebel Camp.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52410, ["x"] = 0.432, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29125] = { ["id"] = 29125, ["name"] = "Between the Trees", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29125 }, ["series"] = { 29126 }, ["description"] = "Spirit fragments of Malorne - seen to us mortals as ghostly white deer - still frolic through these forests. While Malorne is no longer with us, these pieces of his spirit may be of use to us. Travel east and walk among the trees. If you are able to get close enough to one of the spirit fragments, it will bestow its power to you. Oh, and take this staff. You may need it later.", ["objectivesText"] = "Catch three Spirits of Malorne by walking close to them.", ["rewardXP"] = 3290, ["rewardItems"] = { 63122, 69645 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29126] = { ["id"] = 29126, ["name"] = "The Power of Malorne", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29126 }, ["series"] = { 29125 }, ["description"] = "< Matoclaw 's voice continues.> The portal that opened up to our east is guarded by a powerful flamewaker by the name of Galenges . We will need all of Malorne's help in defeating him. Do you remember the staff that I gave you? Place it in the pile of ash in front of the portal. Then pray that Malorne comes to your aid.", ["objectivesText"] = "Use the Guardian's Staff to summon and defeat Galenges .", ["rewardGold"] = 137400, ["rewardXP"] = 4385, ["rewardItems"] = { 68997 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29128] = { ["id"] = 29128, ["name"] = "The Protectors of Hyjal", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29128 }, ["description"] = "We need to place pressure on the assault camp at Sethria's Roost. Ragnaros' minions are using this area as a point to push their battlefront beyond the bounds of Hyjal. I'm putting you in charge of a small squad to deal with them. I have selected an elite group of fighters to assist you. Travel to Sethria's Roost. Your compatriots have been instructed to meet you once you arrive. Then put an end to the elementals' assault.", ["objectivesText"] = "Slay 6 Fiery Behemoths or Seething Pyrelords . Progress: I believe your assignment requires you to be in Hyjal, <race>.", ["rewardGold"] = 274800, ["rewardXP"] = 5480, ["rewardItems"] = { 52506, 69677, 69678 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 53073, ["x"] = 0.275, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29129] = { ["id"] = 29129, ["name"] = "A Legendary Engagement", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29129 }, ["series"] = { 29132, 29134, 29135, 29452, 29453 }, ["description"] = "A pleasure, <class>. < Ziradormi smiles.> It was kind of you to arrive so quickly. For reasons unknown to me, my master seeks audience with you. I would counsel you not to take this invitation lightly. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once. Speak to me when you are ready and I shall personally deliver you.", ["objectivesText"] = "Speak to Anachronos in the Caverns of Time.", ["rewardGold"] = 58650, ["rewardXP"] = 4790, ["rewardItems"] = { 71086 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 52382, ["x"] = 0.486667, ["y"] = 0.707333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.486667, ["y"] = 0.707333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29131] = { ["id"] = 29131, ["name"] = "Defend the Rebel Camp", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29131 }, ["series"] = { 29124 }, ["description"] = "We are in trouble here, <name>. Your troll friend has been through here and warned us that things were going to get serious, but I didn't think it would be this bad. We are doing our best to hold off these trolls. But any help you can offer would greatly help.", ["objectivesText"] = "Help defend the Rebel Camp for three minutes. Progress: There is no end to these trolls, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52410, ["x"] = 0.432, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52410, ["x"] = 0.432, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29132] = { ["id"] = 29132, ["name"] = "A Legendary Engagement", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29132 }, ["series"] = { 29129, 29134, 29135, 29452, 29453 }, ["description"] = "I expected that I would find you here, <class>. But then, we of the bronze flight have somewhat of an advantage when it comes to such things. < Coridormi smiles.> For reasons unknown to me, my master seeks audience with you. I would counsel you not to take this invitation lightly, <name>. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once. Speak to me when you are ready and I shall personally deliver you.", ["objectivesText"] = "Speak to Anachronos in the Caverns of Time.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 71086 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 52408, ["x"] = 0.4885, ["y"] = 0.884 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4885, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29133] = { ["id"] = 29133, ["name"] = "To the Digsite", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29133 }, ["series"] = { 29150, 29151 }, ["description"] = "The other Darkspear emissary was here briefly. He was eager to get to the next location and warn them. I sent him on a flight to the Explorers' League Digsite in the Cape of Stranglethorn. I hope he wasn't too late. I will give you use of one of my gryphons, a direct flight there. Talk to me when you are ready to go, <name>.", ["objectivesText"] = "Head to the Explorers' League Digsite in Southern Stranglethorn Vale.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52753, ["x"] = 0.433, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.433, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29134] = { ["id"] = 29134, ["name"] = "A Wrinkle in Time", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 440, ["storyline"] = { 29134 }, ["series"] = { 29129, 29132, 29135, 29452, 29453 }, ["description"] = "Listen carefully, <class>, for though we are only beginning, time already grows short and the consequences of our failure are unfathomable. An event in the recent past has been obscured from my vision by the most powerful of magics. Its impact, however, has not. If action is not taken to change the course of this timeline's future, the outcome is clear. Brace yourself, mortal, and behold the future of Azeroth.", ["objectivesText"] = "Speak to Anachronos in the Caverns of Time to witness the future of Azeroth. Progress: Witness the undoing of our world, <class>.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[29135] = { ["id"] = 29135, ["name"] = "All-Seeing Eye", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 440, ["storyline"] = { 29135 }, ["series"] = { 29129, 29132, 29134, 29452, 29453 }, ["description"] = "I perceive the questions that burn within your mind and I must confess that I share in your uncertainty... a rare position for one such as I, and a most unsettling one. As I scour time to find traces of this obscured event, you must aid me in the creation of an Eye, both to test your worthiness, and to provide an essential tool in the unraveling of this mystery. Venture into the Plane of Fire, <class>, and gather Eternal Embers . Bring them to me with Sands of Time and I will create the Eye.", ["objectivesText"] = "Collect 25 Eternal Embers from The Firelands and 3 Sands of Time . Progress: Well, <class>? Have you acquired the necessary materials?", ["rewardGold"] = 412200, ["rewardXP"] = 7185, ["rewardItems"] = { 65893, 69237, 69815, 71141 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "raid", ["db2QuestSortName"] = "Nightborne" },
[29137] = { ["id"] = 29137, ["name"] = "Breach in the Defenses", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29137 }, ["description"] = "Lava worms are bursting through the ground behind our lines, breaking our formations and allowing elementals to slip through. You'll find them scattered throughout our entire front to the north, and upon the Ashen Fields further out. Stomp them back into their holes.", ["objectivesText"] = "Kill 5 Lava Bursters .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 63775, 63780, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29138] = { ["id"] = 29138, ["name"] = "Burn Victims", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29138 }, ["description"] = "We have warriors out in the field who are falling wounded, and many of our druids are too busy fighting to give them proper aid. I need you to go to the north, towards the Ashen Fields, and tend their wounds at least enough that they can make it back to safety. If you haven't any bandages or healing spells, I had Rayne put together this salve, which should prove sufficient to get them on their feet.", ["objectivesText"] = "Heal 8 Wounded Hyjal Defenders .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69240 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29139] = { ["id"] = 29139, ["name"] = "Aggressive Growth", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29139 }, ["description"] = "Our warriors are doing everything they can to hold back the elementals, but their numbers are endless. We need to do something to slow down the assault. Find some suitable patches of dirt or ash out on the Ashen Fields to our north and plant these seeds. They will grow deadly vines that may slow down our enemies a bit. It's not much, but every bit helps.", ["objectivesText"] = "Plant 5 Smothervine Seeds in the Ash Piles in the Ashen Fields.", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69749 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29141] = { ["id"] = 29141, ["name"] = "The Harder They Fall", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29141 }, ["description"] = "Molten Behemoths have joined the elementals upon the battlefield. They are crushing our front lines. I need you to halt their momentum. You'll find the beasts slow and clumsy. They can easily be outmaneuvered, but they will pack a devastating punch if they hit you. Be nimble, <class>.", ["objectivesText"] = "Kill 3 Molten Behemoths .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69240 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29142] = { ["id"] = 29142, ["name"] = "Traitors Return", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29142 }, ["description"] = "The Druids of the Flame assault our front line, <name>. These vile creatures have turned their backs on Elune's teachings and worship instead the Fire Lord, Ragnaros. Twisted by his insane power, they desire nothing more than to bury us in ash. We must counter their attack immediately!", ["objectivesText"] = "Kill 3 Druids of the Flame .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29143] = { ["id"] = 29143, ["name"] = "Wisp Away", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29143 }, ["description"] = "The fire elementals are pouring out of portals on the far side of the Ashen Fields. We need someone to close them. Cut off some of their reinforcements. Banishing these kinds of elemental magics is something our wisps are perfectly suited for. One will come with you. Lead it to a portal and keep it alive until it finishes.", ["objectivesText"] = "Lead a Hyjal Wisp to one of the fire portals in the Ashen Fields, and protect the wisp until it closes the portal. If you lose your wisp, return to Rayne Feathersong at Malfurion's Breach.", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29144] = { ["id"] = 29144, ["name"] = "Clean Up in Stormwind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 29144 }, ["description"] = "Greetings, <class>! Are you enjoying Hallow's End? It seems that in response to our stink bombing the Undercity, the Horde has decided to stink bomb our city. The stink bombs they drop are more potent than the ones used in the past. The power of pine won't be enough. We will need something with a little more power. Use this Arcane Cleanser to remove the stink bombs from the city.", ["objectivesText"] = "Use the Arcane Cleanser to remove stink bombs around Stormwind. Progress: Arcane magic... Works every time.", ["rewardXP"] = 1060, ["rewardItems"] = { 33226, 68648, 69191 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 51934, ["x"] = 0.557333, ["y"] = 0.775667 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 51934, ["x"] = 0.557333, ["y"] = 0.775667 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.557333, ["y"] = 0.775667 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29145] = { ["id"] = 29145, ["name"] = "Opening the Door", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29145 }, ["series"] = { 29195, 29196, 29197, 29198, 29387, 29388, 29389, 29390 }, ["description"] = "You're a bit late. Hamuul, Malfurion, and some of our esteemed guests have already traveled to the invasion point, atop that cliff. Our gate to the Firelands is not yet completed, but it will be shortly. The sooner we can break through, the better. Go on! Hamuul will be expecting you.", ["objectivesText"] = "Report to Arch Druid Hamuul Runetotem at Nordune Ridge in Mount Hyjal.", ["rewardGold"] = 28090, ["rewardXP"] = 550, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29146] = { ["id"] = 29146, ["name"] = "Ridin' the Rocketway", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 16, ["storyline"] = { 29146 }, ["description"] = "I heard that the goblins, built a crazy road in Azshara and it's just for rockets! Can you imagine? Ever since I heard about it, I've wanted to pay a visit. I asked Matron Battlewail about it and she said it's called the Rocketway! She even told me they're working on a prototype rocket with two seats. D'you wanna go there and see if we can try it out? I bet the experimental rocket is near the Secret Lab at the south end of the Rocketway...", ["objectivesText"] = "Head to the Southern Rocketway Terminus in Azshara and board the Redhound Two-Seater prototype at the top of the tower. Progress: This is gonna be the best Children's Week ever!", ["rewardXP"] = 1415, ["rewardItems"] = { 18597, 23002, 23007, 23015, 66073, 69057, 69231, 69233 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16 } }, ["questType"] = "standard" },
[29147] = { ["id"] = 29147, ["name"] = "Call the Flock", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29147 }, ["series"] = { 29148 }, ["description"] = "Today, we have an opportunity to make another assault against one of Ragnaros' greater minions: Millagazor. However, we first need to get some assistance. < Matoclaw holds up a large, silky feather.> Use this artifact to invoke the power of Aviana. Once you have done so, travel northwest and gather some of her flock by calling out to them. Once you have done so, we may proceed against Millagazor.", ["objectivesText"] = "Use your Call the Flock ability to gather 12 Alpine Songbirds , 5 Forest Owls , and 2 Goldwing Hawks .", ["rewardXP"] = 3290, ["rewardItems"] = { 69234 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29148] = { ["id"] = 29148, ["name"] = "Wings Aflame", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29148 }, ["series"] = { 29147 }, ["description"] = "< Matoclaw 's voice continues to echo within your head.> Millagazor is a creature of flame, but in many ways, he is not unlike the birds of this land. As such, Aviana's artifacts may still have the power to summon him. The fiery portal to the west is where you will find him. Use the quill near the portal's entrance, then prepare for a fierce battle.", ["objectivesText"] = "Use the Quill of the Bird-Queen to summon and defeat Millagazor . Progress: Earth-Mother guide your path.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69212 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29150] = { ["id"] = 29150, ["name"] = "Voodoo Zombies", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29150 }, ["series"] = { 29133, 29151 }, ["description"] = "Da people... Dey all zombies, voodoo zombies! Dis ain't gonna be pretty, <name>. You gotta kill dem. But once dey killed, dere is a moment where I can save dem. Change dem back into da person dey were before. We gotta act fast. Da zombies don' rest.", ["objectivesText"] = "Rescue 10 Digsite Survivors.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29151] = { ["id"] = 29151, ["name"] = "Bad Supplies", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29151 }, ["series"] = { 29133, 29150 }, ["description"] = "Some of da survivors mentioned food, <name>. We better check da food supplies. I gotta a bad feelin' about dis.", ["objectivesText"] = "Check out the food supplies at the Explorers' League Digsite.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29152] = { ["id"] = 29152, ["name"] = "Making Contact", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 29152 }, ["description"] = "You aren't one of the zombies... A troll? I did see one, just before the outbreak... He warned us, told us to be on our guard... But it was too late. Your troll friend headed to Booty Bay to warn them...", ["objectivesText"] = "Head to Booty Bay and find Bwemba's contact.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 52646, ["x"] = 0.497, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 52767, ["x"] = 0.41, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.497, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[29153] = { ["id"] = 29153, ["name"] = "Booty Bay's Interests", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1977, ["mapID"] = 210, ["storyline"] = { 29153 }, ["series"] = { 29154, 29155 }, ["description"] = "Look, <name>. You've helped out plenty so far, but that's not going to be enough. I need these crazy trolls stopped, or at least stopped from getting into Booty Bay. I'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen. At the very least, I want you to find me something that will help keep these trolls out of Booty Bay. You do that and we'll treat you right.", ["objectivesText"] = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay. Progress: Did you find something, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 69774, 133997 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29154] = { ["id"] = 29154, ["name"] = "Booty Bay's Interests", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1977, ["mapID"] = 210, ["storyline"] = { 29154 }, ["series"] = { 29153, 29155 }, ["description"] = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted. Or that it is at least halted at the gates of Booty Bay. I want action and I want results. I want you to get in there and kill. I want you to get in there and find me something that will help keep these trolls out of Booty Bay. You do that and we'll make sure you get paid.", ["objectivesText"] = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay. Progress: Did you find something, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 69774, 133997 }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29155] = { ["id"] = 29155, ["name"] = "A Shiny Reward", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 29155 }, ["series"] = { 29153, 29154 }, ["description"] = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale. Head to the statue and claim your prize, <class>.", ["objectivesText"] = "Get your reward from a chest in the statue at Janeiro's Point.", ["rewardGold"] = 280900, ["rewardItems"] = { 64457, 69262, 69863, 69864, 69865, 71037, 133997 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[29156] = { ["id"] = 29156, ["name"] = "The Troll Incursion", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29156 }, ["description"] = "A group of trolls, claiming to represent the Darkspear tribe, have arrived at Stormwind Harbor. Our guards are keeping them at bay, for now. The Stormwind Harbor Guards are seeking seasoned adventurers for help in removing the trolls from the harbor. Report to Commander Sharp at Stormwind Harbor.", ["objectivesText"] = "Speak with Commander Sharp in Stormwind Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["rewardItems"] = { 68833 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 53352, ["x"] = 0.2944, ["y"] = 0.3796 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.2944, ["y"] = 0.3796 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29159] = { ["id"] = 29159, ["name"] = "Pyrorachnophobia", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29159 }, ["description"] = "We've fought hard to secure this area, but our foothold is tenuous. Our scouts report that the area around us is teeming with vicious fire spiders. They are the spawn of the vicious brood widow, Beth'tilac. Help us hold our line by clearing the area of Cinderweb Spinners or Cinderweb Creepers . It will drive her mad to see her children slain.", ["objectivesText"] = "Kill 8 Cinderweb Spinners or Cinderweb Creepers .", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29160] = { ["id"] = 29160, ["name"] = "Egg-stinction", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29160 }, ["description"] = "We have a real problem on our hands. Not only are the nearby spiders vicious and predatory, their numbers appear to be endless. We need to stop the growth of their army. Cut their heads off in the egg, not on the battlefield. The Cinderweb Spinners' eggs are laid among the stone pillars to the north. Collect 20 eggs and bring them back to me.", ["objectivesText"] = "Collect 20 Cinderweb Eggs from the pillars in The Widow's Clutch. Progress: It appears the Cinderweb Spinners are the caretakers of Beth'tilac's brood.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69214 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29161] = { ["id"] = 29161, ["name"] = "Those Bears Up There", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29161 }, ["series"] = { 29162 }, ["description"] = "Oh, raspberries! Just when we had saved the last bear cub from the treetops, the fires returned and scared them again! I don't know if you know this, but baby bears are precious and soft. Go to the Whistling Grove, far to the northwest. Climb the trees, grab the bear cubs, and chuck them - gently! - to the soft target in the center of the grove. <Without warning, Mylune suddenly smashes you against her bosom and begins sobbing.> Lil' b-b-b-baby bears! Save them, <name>!", ["objectivesText"] = "Climb up trees in the Whistling Grove, grab stranded Hyjal Bear Cubs, and then hurl them at the Soft Target from the top of the tree. This is perfectly safe.", ["rewardXP"] = 3290, ["rewardItems"] = { 69210, 69649 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29162] = { ["id"] = 29162, ["name"] = "Nature's Blessing", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29162 }, ["series"] = { 29161 }, ["description"] = "< Mylune 's voice rings in your head, like the sound of birds chirping.> I love all creatures of the forest, even spiders, despite the fact that they are icky. But the spiders from the Firelands are worse than icky. They're burny, and don't belong here. Find the fire portal in the western Regrowth, and use the gem I gave you earlier to force it open. When a fire spider emerges, step on it! Unless it's big. Then, do something <class>y to it. Oh, and use the gem if spider venom makes you woozy!", ["objectivesText"] = "Use the Emerald of Aessina to summon and kill Pyrachnis .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69232 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52671, ["x"] = 0.456, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29164] = { ["id"] = 29164, ["name"] = "Perfecting Your Howl", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29164 }, ["series"] = { 29165 }, ["description"] = "The wolf ancient, Lo'gosh - or, if you prefer, Goldrinn - has many weapons available to him, but always the most underestimated is his howl. Today, we will use this weapon to summon and defeat Lylagar, one of the lieutenants of flame that lurk within the Firelands. Defeat any of the creatures of flame within the Regrowth, and then use the Fang of the Wolf while standing atop their corpse. Soon, your howl will echo across all of Kalimdor.", ["objectivesText"] = "Use the Fang of the Wolf atop the corpses of 10 Firelands invaders within the Regrowth.", ["rewardXP"] = 3290, ["rewardItems"] = { 69235 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29165] = { ["id"] = 29165, ["name"] = "The Call of the Pack", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29165 }, ["series"] = { 29164 }, ["description"] = "< Matoclaw continues:> The easternmost portal of flame is the domain of Lylagar . Stand before the portal, deliver a challenging howl, and then force the fiery beast to submit.", ["objectivesText"] = "Use the Fang of the Wolf to summon and defeat Lylagar . Progress: Are you beginning to see the parallels between the Firelands and our world?", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69225 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29166] = { ["id"] = 29166, ["name"] = "Supplies for the Other Side", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29166 }, ["description"] = "One of the biggest dangers that our druids face when fighting within the Firelands is simple dehydration. Our proveditors spend a significant amount of time preparing canteens for the troops on the other side. We do have other methods, however. In the greener thickets to the east, you should still find some blueroot vines which have not yet burned. These plants hold a tremendous amount of water in their roots - and also provide some energy for the weary soldier.", ["objectivesText"] = "Obtain 7 Blueroot Vines . Progress: Let's see... how many have you managed to gather?", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69236 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29172] = { ["id"] = 29172, ["name"] = "The Beasts Within", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1977, ["storyline"] = { 29172 }, ["description"] = "< Bloodslayer T'ara eyes you for a moment.> After de fall of Hakkar, de city of de Gurubashi fell into disrepair, and de jungle claimed most of Zul'Gurub for its own. Some powerful beasts now be livin' in da cracks an' hollows of de ancient city. We seen de powers dem Gurubashi priests wield - dey turn de very plantlife against us wit' venomous concoctions. You tink you be strong? Dispose of dese beasts, before dey become mindless agents of Jin'do.", ["objectivesText"] = "Kill the Florawing Hive Queen , Tor-Tun the Slumberer, and a Lost Offspring of Ghaz'Ranka inside of Zul'Gurub on Heroic difficulty. Progress: The very beasts of Zul'Gurub already turn against us. You must hurry!", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 69777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29173] = { ["id"] = 29173, ["name"] = "Secondary Targets", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1977, ["storyline"] = { 29173 }, ["description"] = "Da Gurubashi trolls gathered dere most powerful allies ta rebuild Zul'Gurub an' re-take Stranglethorn Vale. Chief among dem be two monstrous trolls: Kaulema da Mover an' Mor'Lek da Dismantler, an' a powerful soul-stealer called Mortaxx . Dey don't be leaders of da Gurubashi, but killing dem powerful minions gonna help us prevent da rise of da Gurubashi.", ["objectivesText"] = "Kill Kaulema the Mover , Mor'Lek the Dismantler , and Mortaxx , the Tolling Bell inside of Zul'Gurub on Heroic difficulty. Progress: The most powerful underlings of the Gurubashi must be dealt with!", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 69777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29175] = { ["id"] = 29175, ["name"] = "Break Their Spirits", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1977, ["storyline"] = { 29175 }, ["description"] = "A city like Zul'Gurub be similar ta one of de many towering trees you see nearby. De trunk may be thick, and de canopy vast and leafy, but without nutrients from de roots far below, de tree gonna wither and fall. Jin'do's army be fed largely by de actions of a couple a' minor Gurubashi trolls. Sever dem roots, and de city gonna fall.", ["objectivesText"] = "Kill Gub and the Gurubashi Master Chef inside of Zul'Gurub on Heroic difficulty. Progress: You must disrupt their supply lines!", ["rewardGold"] = 137400, ["rewardXP"] = 4790, ["rewardItems"] = { 69777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29176] = { ["id"] = 29176, ["name"] = "The Fallen Chieftain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 215, ["storyline"] = { 29176 }, ["description"] = "Matron Battlewail says that when Cairne Bloodhoof died, the Horde lost a 'voice of wisdom'. I don't know what that means, but I always wanted to meet him. Some of the other orphans even have his hoofprint. Would you take me with you to Mulgore? Our tutor says tauren bring their dead to a place called Red Rocks to honor them. We should go there and see if we can find Cairne.", ["objectivesText"] = "Take your orphan to Red Rocks to visit the funeral pyre of Cairne Bloodhoof. Call for your orphan if he is not present when you arrive. Progress: I want to visit Mulgore more often.", ["rewardXP"] = 1415, ["rewardItems"] = { 18597, 23002, 23007, 23015, 66073, 69057, 69231, 69233 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 215 } }, ["questType"] = "standard" },
[29177] = { ["id"] = 29177, ["name"] = "Vigilance on Wings", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29177 }, ["description"] = "The agents of Twilight continue their assault within this pocket of the Firelands. We must not let our offensive fall! Take wing, and destroy as many of those lancers as you can! Do not forget to pick up and equip your lance first.", ["objectivesText"] = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Lancers by flying into them. Press the flap button to flap your mount's wings! Progress: Our vigilance must not fall. Especially not now, in this most trying of times!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 69838 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40578, ["x"] = 0.372, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 40578, ["x"] = 0.372, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29179] = { ["id"] = 29179, ["name"] = "Hostile Elements", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29179 }, ["description"] = "The elementals continue to press on us, and I do not expect them to subside any time soon. You'll find them pouring across the Ashen Fields to the north. Thin their ranks.", ["objectivesText"] = "Kill 8 Charred Soldiers or Charred Vanquishers .", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29180] = { ["id"] = 29180, ["name"] = "Promises, Promises...", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 29180 }, ["series"] = { 29184, 29186 }, ["description"] = "My inscrutable theories confirm rumors of vast treasure in Zul'Aman . There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all.... Our initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk. Forget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman !", ["objectivesText"] = "Retrieve Budd's Map of Zul'Aman from High Priest Nalorakk's terrace in Zul'Aman .", ["rewardGold"] = 188000, ["rewardXP"] = 925, ["rewardItems"] = { 33013, 69777, 88417, 116067, 211279, 245721, 245722, 245723, 245724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[29181] = { ["id"] = 29181, ["name"] = "Druids of the Talon", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["mapID"] = 198, ["storyline"] = { 29181 }, ["description"] = "Skylord Omnuron and his Druids of the Talon have been a fearsome force for us back in Hyjal. I know that they prefer the familiar skies of that battlefield, but the time may come when we need them here nonetheless. If you get your hands on enough marks, you should appeal to Omnuron that his druids should be on the main front. Omnuron watches out for his own, but he also understands the importance of this effort.", ["objectivesText"] = "Obtain 150 Marks of the World Tree . Progress: It is good to see you again.", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 69213 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 50082, ["x"] = 0.435, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29182] = { ["id"] = 29182, ["name"] = "Flight of the Storm Crows", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29182 }, ["description"] = "Many of the Druids of the Talon have made their way to the Molten Front, at your beckoning. You should go to Skylord Omnuron at Malfurion's Breach and see how their wings are faring in those burning skies.", ["objectivesText"] = "Speak to Skylord Omnuron at Malfurion's Breach.", ["rewardGold"] = 70225, ["rewardXP"] = 1095, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 50068, ["x"] = 0.426, ["y"] = 0.455 }, { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29184] = { ["id"] = 29184, ["name"] = "X Marks... Your Doom!", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 29184 }, ["series"] = { 29180, 29186 }, ["description"] = "How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you. Succeed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you. There are yet a few portions of my map that require further exploration before our excavation can be initiated....", ["objectivesText"] = "Visit Halazzi's Chamber, Jan'alai's Platform, and Akil'zon's Platform in Zul'Aman .", ["rewardGold"] = 282000, ["rewardXP"] = 1110, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[29185] = { ["id"] = 29185, ["name"] = "Daily Tier 2 Heroic (1st)", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29185 }, ["rewardGold"] = 786300, ["rewardXP"] = 9580, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29186] = { ["id"] = 29186, ["name"] = "The Hex Lord's Fetish", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3805, ["storyline"] = { 29186 }, ["series"] = { 29180, 29184 }, ["description"] = "Dis new warlord of da Amani, he be nothin' but an overgrown brute without da protection of a strong witch doctor and he has just dat. Da new warlord's ally be Hex Lord Malacrass, da most feared witch doctor to walk among da Amani in decades. Without da hex lord's say-so, Daakara won't be submitting his people to da control of da Zandalari. Defeat Hex Lord Malacrass, bring me his favorite fetish, and I be seein' that ya get a fittin' reward.", ["objectivesText"] = "Obtain the Hex Lord's Fetish from Hex Lord Malacrass in Zul'Aman . Progress: Have ya eliminated Hex Lord Malacrass?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 51809, 69264, 69594, 69595, 69596, 69748 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3805 } }, ["questType"] = "dungeon" },
[29187] = { ["id"] = 29187, ["name"] = "Tuskin' Raiders", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 29187 }, ["series"] = { 29188 }, ["description"] = "'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya. Budd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks. My skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. Bring me back 10 troll tusks, eh mon?", ["objectivesText"] = "Collect 10 Forest Troll Tusks from the trolls in Zul'Aman .", ["rewardGold"] = 188000, ["rewardXP"] = 925, ["rewardItems"] = { 33106 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[29188] = { ["id"] = 29188, ["name"] = "A Troll Among Trolls", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 29188 }, ["series"] = { 29187 }, ["description"] = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon. Zungam, my good-fer-nuthin' cousin, be stuck inside Zul'Aman . He still be alive too - I seen his signal flare just last night! I should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money. Do what ya can to help him out, then leave the collectin' to me!", ["objectivesText"] = "Speak to Zungam in Zul'Aman .", ["rewardGold"] = 188000, ["rewardXP"] = 925, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[29189] = { ["id"] = 29189, ["name"] = "Wicked Webs", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29189 }, ["description"] = "Some of our scouts have not reported back for duty. We fear they have succumbed to the deadly spiders in the vicinity. Hope may not be lost, however. The spiders often wrap up their live prey in cocoons for later consumption. Go search the pillars to the north for cocooned victims. You may yet be able to save some of our brethren.", ["objectivesText"] = "Free 8 victims out of Cinderweb Cocoons .", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29190] = { ["id"] = 29190, ["name"] = "Let's Go Fly a Kite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 1637, ["storyline"] = { 29190 }, ["description"] = "The other day, when some of us were out with the matron, I saw a goblin pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time. I think the goblin's name was Blax Bottlerocket or something. If we can find him, could we get some kites and fly them together? I saw him pushing his cart around the Drag.", ["objectivesText"] = "Purchase a Dragon Kite Two-Pack from Blax Bottlerocket in Orgrimmar's Drag then use it to fly kites with your Orcish Orphan . If your orphan is not present, call for him. Progress: I thought for sure I was going to have to save all my money for like a million years to get a kite!", ["rewardXP"] = 1415, ["rewardItems"] = { 18597, 23002, 23007, 23015, 66073, 69057, 69231, 69233 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29191] = { ["id"] = 29191, ["name"] = "You Scream, I Scream...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 3, ["zoneID"] = 1637, ["storyline"] = { 29191 }, ["description"] = "There's a brand new ice cream shop in Orgrimmar, and it's not just any old ice cream either. This ice cream is made by a crazy goblin mage! You don't think it's going to disappear if I don't finish it in fifteen minutes, do you? I bet it tastes really good. Let's go try it! I heard some of the other kids talking about it, and they were saying the store is called the Cone of Cold and it's in the Orgrimmar Embassy.", ["objectivesText"] = "Purchase ice cream at Cone of Cold and then share it with your orphan. Progress: Ice cream is my favorite.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 18597, 23002, 23007, 23015, 63582, 63583, 63584, 63585, 63586, 66073, 69057, 69231, 69233, 87399, 108439, 157017, 157018, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29192] = { ["id"] = 29192, ["name"] = "The Wardens are Watching", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29192 }, ["description"] = "We must tread carefully, <class>. Fandral's Druids of the Flame practice their fiery magic beyond the pillars to the north. I need you to capture one of those druids alive for questioning. We must seize every opportunity to learn of their plans. One of my wardens will accompany you. Follow her instructions if you wish to survive.", ["objectivesText"] = "Attack a Druid of the Flame to weaken it, then lure it into your Shadow Warden's trap.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 137663, 144339, 199896 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29193] = { ["id"] = 29193, ["name"] = "On a Wing and a Prayer", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 440, ["mapID"] = 114, ["storyline"] = { 29193 }, ["series"] = { 29194, 29225, 29234, 29239, 29432, 30119 }, ["description"] = "Time well spent, mortal. While you struggled in the Plane of Fire, my watchers and I were able to determine when and, most importantly, where our vision was obscured. We discovered that the shroud was placed over the Nexus, far to the north in the realm of the blue dragonflight. I have attuned the Timeless Eye to show you the occurrences that remain hidden to us here. Bring it to Coldarra at once and seek out a place suitable for its activation. Go, child. Time is of the essence...", ["objectivesText"] = "Bring the Timeless Eye to Coldarra.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 44338, 44339, 44340, 44341, 57339, 57340, 57341, 69238 }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 52835, ["x"] = 0.344, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[29195] = { ["id"] = 29195, ["name"] = "A Ritual of Flame", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29195 }, ["series"] = { 29145, 29196, 29197, 29198, 29387, 29388, 29389, 29390 }, ["description"] = "We appear to have everything under control. Our invasion portal to the Firelands will be opened momentarily, and the elementals have not put up much fight. Assist our druids by dispatching the last few of these elementals. Then, once the gate has been opened, we can make our move.", ["objectivesText"] = "Fight the waves of Charred Invaders on Nordune Ridge until the portal is opened. Progress: Continue the fight, <name>. Only a short while longer now.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69854 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52845, ["x"] = 0.271333, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.495714 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29196] = { ["id"] = 29196, ["name"] = "To the Sanctuary!", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29196 }, ["series"] = { 29145, 29195, 29197, 29198, 29387, 29388, 29389, 29390 }, ["description"] = "We should not worry about this \"Druid of the Flame\" for the time being. We must be concerned with the continuance of our operation. Return to Matoclaw at the Sanctuary of Malorne. If Ragnaros was prepared for our arrival, then I anticipate that his forces will launch a counterattack soon.", ["objectivesText"] = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", ["rewardGold"] = 28090, ["rewardXP"] = 550, ["rewardItems"] = { 139734, 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466, 194549, 237812 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52845, ["x"] = 0.271333, ["y"] = 0.600667 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.271333, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29197] = { ["id"] = 29197, ["name"] = "Caught Unawares", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29197 }, ["series"] = { 29145, 29195, 29196, 29198, 29387, 29388, 29389, 29390 }, ["description"] = "Our invasion plan looks to have backfired. Several of our birds have already reported in, speaking of fires breaking out across the vales of central Hyjal. Now, many of our druids are stranded out in the field, unprepared for such a large-scale attack. Thisalee was near Ashen Lake, and several others were out in the Regrowth, to the northeast. Go, <name>! Find them, and make sure that they do not succumb to this backdraft!", ["objectivesText"] = "Help Elderlimb , Thisalee Crow , Tholo Whitehoof and Anren Shadowseeker escape the flames. Progress: There isn't time! Move!", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 137663 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29198] = { ["id"] = 29198, ["name"] = "The Sanctuary Must Not Fall", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29198 }, ["series"] = { 29145, 29195, 29196, 29197, 29387, 29388, 29389, 29390 }, ["description"] = "Malfurion is working on a miracle for us. He believes that, in this time of peril, he can resurrect Malorne to protect the Sanctuary. I have faith in him. In the meantime, we need to hold this perimeter. Stand by, and make sure no harm befalls my fellow arch druid.", ["objectivesText"] = "Stand by Malfurion as he resurrects Malorne. Progress: Please, <name>. Focus on the task at hand.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69213 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52845, ["x"] = 0.271333, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.495714 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29199] = { ["id"] = 29199, ["name"] = "Calling for Reinforcements", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29199 }, ["series"] = { 29200 }, ["description"] = "We suffered heavy losses during the backdraft after our invasion attempt. Our second attempt cannot fail. We need reinforcements before we attempt another invasion. Please, <name>, work with Matoclaw to obtain enough resources to afford reinforcements. Then, we take our second and final stab at the Firelands.", ["objectivesText"] = "Obtain 20 Marks of the World Tree . Progress: The sooner we can break through our invasion portal, the better.", ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.495714 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29200] = { ["id"] = 29200, ["name"] = "Leyara", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29200 }, ["series"] = { 29199 }, ["description"] = "Before we depart, <name>, I have another matter to which you should attend. A Druid of the Flame has been spotted in the ruins to the northwest. I suspect it is the same one that attacked us at the portal several days ago. Now would be an ideal time to see what it is that she truly wants... and if necessary, dispose of her. See to this flame druid, then we can continue on our planned course.", ["objectivesText"] = "Find Leyara , the Druid of the Flame. Progress: Hamuul really shouldn't worry about the affairs of a lone druid. The hour of our attack is at hand!", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69854 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.495714 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29201] = { ["id"] = 29201, ["name"] = "Through the Gates of Hell", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29201 }, ["description"] = "There will be time to mourn for Hamuul later. His is the first of many inevitable casualties in this war.... but our attack cannot wait, nor should the momentum we have gained over the last several days be wasted. The portal atop Nordune Ridge is now open. Our reinforcements are prepared, and they await only my order to pass through the portal. We will meet again on the other side of the portal. Once there, we shall ensure that our foothold is secure.", ["objectivesText"] = "Pass through the portal atop Nordune Ridge and help Malfurion secure a foothold on the Molten Front.", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 69213, 70105, 70106, 70107, 70108 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52845, ["x"] = 0.271333, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.271333, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29202] = { ["id"] = 29202, ["name"] = "The Fate of Runetotem", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29202 }, ["description"] = "I apologize for speaking curtly with you earlier. The loss of Hamuul was shocking to me, and difficult to cope with. They brought in his body while you were away. He is alive, but - as you might imagine - he is very, very badly burned. The scars are deep. He may not live. I have arranged for some of our finest healers to attend to him. If it is not too much to ask, would you speak with Dorda'en Nightweaver ? He and his fellow attendants may need your help.", ["objectivesText"] = "Speak with Dorda'en Nightweaver at the Sanctuary of Malorne in Mount Hyjal.", ["rewardGold"] = 28090, ["rewardXP"] = 550, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29203] = { ["id"] = 29203, ["name"] = "Into the Depths", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29203 }, ["description"] = "Leyara has been spotted in the Igneous Depths. A group of Shadow Wardens has cornered her. Go there immediately. I will join you as soon as I make one necessary preparation.", ["objectivesText"] = "Kill Leyara .", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 69854 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29204] = { ["id"] = 29204, ["name"] = "The Warden's Charge", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29204 }, ["series"] = { 29205 }, ["description"] = "Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise. I've assigned her a large number of our men, but her chances of success would be greatly increased if you join her cause. It's your decision, <name>.", ["objectivesText"] = "If you want to help the Wardens attack the Forlorn Spire, seek out Captain Saynna Stormrunner in northeastern Ashen Fields.", ["rewardGold"] = 23500, ["rewardXP"] = 185, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29205] = { ["id"] = 29205, ["name"] = "The Forlorn Spire", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29205 }, ["series"] = { 29204 }, ["description"] = "Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise. Go there and escort one of her druids to the tower with any forces that she can spare. You'll have quite a fight ahead of you - make sure the druid lives to see the end of it or they'll not be able to seize the tower.", ["objectivesText"] = "Protect one of the druids attempting to take the Forlorn Spire.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29206] = { ["id"] = 29206, ["name"] = "Into the Fire", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29206 }, ["description"] = "Skylord Omnuron and his druids are seeking to push through the Furnace to our northwest. They've been able to fly over the dangers, but they really need someone on the ground to help them secure the territory past the fire... someone like you. If you want to aid the Druids of the Talon, wait for one of Omnuron's Windcallers to start pushing through the fire, stay close to him, and keep him safe from any attackers within the flames.", ["objectivesText"] = "Escort a Windcaller through the Furnace and secure the entrance to the Molten Flow.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 62466, 63841, 63842, 63843 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29208] = { ["id"] = 29208, ["name"] = "An Old Friend", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1977, ["storyline"] = { 29208 }, ["rewardGold"] = 370, ["rewardXP"] = 2090, ["rewardItems"] = { 25583, 25584, 25585, 58165, 69251, 121594, 121595, 121596, 121597, 129986, 129994, 130002, 130013, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29209] = { ["id"] = 29209, ["name"] = "Into the Fiery Depths", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29209 }, ["series"] = { 29210 }, ["description"] = "One of our druids moved ahead into the Igneous Depths in pursuit of a Druid of the Flame. Go to her. Help her.", ["objectivesText"] = "Speak to Theresa Barkskin in the Igneous Depths.", ["rewardGold"] = 23500, ["rewardXP"] = 185, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29210] = { ["id"] = 29210, ["name"] = "Enduring the Heat", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29210 }, ["series"] = { 29209 }, ["description"] = "Shalis has gone with one of our druids to stop a Druid of the Flame that is performing a summoning ritual in the Igneous Depths, below us. They have been tasked with killing the druid, but I need you to stop the ritual. You'll find the entrance to the cavern east of the Magma Springs. Once inside, you'll see 8 blue runes spread throughout the cavern. You can use these runes to protect you from the fiery creatures, but you need to stamp all of them out to end the ritual. You will need to be swift.", ["objectivesText"] = "Find your way to the Igneous Depths, then destroy all 8 of the blue runes within. Progress: You must destroy the runes! Hurry!", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29211] = { ["id"] = 29211, ["name"] = "Solar Core Destruction", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29211 }, ["description"] = "The fight has taken us to Fandral's doorstep. His druids are channeling energies of the Firelands into a vessel called the Solar Core. Should this vessel detonate on Azeroth, none of us will have a home to return to. We need to strike at the Solar Core now, while it is still vulnerable. You can find the infernal device to the northeast.", ["objectivesText"] = "Detonate the Solar Core.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29213] = { ["id"] = 29213, ["name"] = "How's the Hunter Holding Up?", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29213 }, ["series"] = { 29118, 29120, 29121 }, ["description"] = "Tings ain't looking good. Dat panther was under some powerful magic. We better check on dat hunter an' see how he be doin'.", ["objectivesText"] = "Check on Grent Direhammer .", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52371, ["x"] = 0.76, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29214] = { ["id"] = 29214, ["name"] = "The Shadow Wardens", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["mapID"] = 198, ["storyline"] = { 29214 }, ["description"] = "The Shadow Wardens are back in the Regrowth. I know that they take the loss of Fandral from their custody very seriously, so it wouldn't take much prodding to bring them to the Firelands to hunt the Druids of the Flame, and perhaps aid us otherwise in the process. Should you come upon enough marks, you should seek out Captain Saynna Stormrunner at the Sanctuary of Malorne and secure her aid.", ["objectivesText"] = "Obtain 150 Marks of the World Tree . Progress: Yes, <class>?", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 69213 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52844, ["x"] = 0.268, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29215] = { ["id"] = 29215, ["name"] = "The Hunt Begins", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29215 }, ["description"] = "The Shadow Wardens have joined the fight at the Molten Front, on your request. You should find Captain Saynna Stormrunner and see to it that they've found a way to best apply their skills.", ["objectivesText"] = "Speak to Captain Saynna Stormrunner at Malfurion's Breach.", ["rewardGold"] = 70225, ["rewardXP"] = 1095, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29217] = { ["id"] = 29217, ["name"] = "The Captive Scouts", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3805, ["storyline"] = { 29217 }, ["description"] = "After we arrived, I dispatched my scouts to learn more about da Zandalari presence here in Zul'Aman . Many returned with useful information, but four still be missin'. If we do not act quickly, da new warlord's lieutenants will offer dem as sacrifices in honor of da Zandalari emissaries. Find my scouts, <name>, and free dem before da priests offer dem as sacrifices!", ["objectivesText"] = "Free the captive scouts: Hazlek , Bakkalzu , Norkani , and Kasha . They are being held captive by the Amani high priests.", ["rewardGold"] = 137400, ["rewardXP"] = 4790, ["rewardItems"] = { 69747 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3805 } }, ["questType"] = "dungeon" },
[29219] = { ["id"] = 29219, ["name"] = "Bwemba's Spirit", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29219 }, ["description"] = "Dese be troublin' times for us Darkspear. Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost. We tryin' to warn all dat we can. But it might be too late. Another Darkspear gone down to Stranglethorn to warn da people. But it ain't safe to travel alone in Stranglethorn. Help me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes. I gonna bind my spirit wit' ya. When ya get to Stranglethorn, I be able to aid ya.", ["objectivesText"] = "Warn the people of Stranglethorn and find the other Darkspear emissary. Progress: Dis won't be no easy task, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 12185 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 53081, ["x"] = 0.3655, ["y"] = 0.57075 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.57075 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29220] = { ["id"] = 29220, ["name"] = "To Bambala", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29220 }, ["series"] = { 29221 }, ["description"] = "Da first place we check gonna be da place most likely to be attacked first, Bambala. Bambala be dangerously close to da troll city Zul'Gurub... It make for an easy target. Maybe we find da emissary dere. Hopefully it ain't too late.", ["objectivesText"] = "Head to Bambala in Northern Stranglethorn Vale to find the Darkspear emissary.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 53081, ["x"] = 0.3655, ["y"] = 0.57075 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52980, ["x"] = 0.641333, ["y"] = 0.399333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.57075 }, ["mapCandidates"] = { ["npc"] = { 50, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29221] = { ["id"] = 29221, ["name"] = "Serpents and Poison", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29221 }, ["series"] = { 29220 }, ["description"] = "Da warning helped, <name>. We gathered more Headhunters to help defend. But Headhunters... Dey not used to hunting heads on serpents. So we soon be overwhelmed. Dese serpents, dey seem to come from everywhere. An' it probably only gonna get worse. Help us and kill da serpents and have Bwemba use her mojo to cure da ones dat are sick from poison.", ["objectivesText"] = "Kill Jungle Serpents and inspect the poisoned Headhunters to allow Bwemba to heal them.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 42997 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52980, ["x"] = 0.641333, ["y"] = 0.399333 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52980, ["x"] = 0.641333, ["y"] = 0.399333 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.641333, ["y"] = 0.399333 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29222] = { ["id"] = 29222, ["name"] = "Spirits Are With Us", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29222 }, ["description"] = "Dere was something about da way da serpents attacked, <name>. Something unnatural... Even da poison had a hint of some bad mojo. Dere be a shrine near here wit' a bonfire. We can use dat to perform a ritual. Whatever be makin' dese serpents attack, dey probably still watchin' over dem. Da only problem, <name>, is dat I only be here in spirit form. I need you to be my hands. I need you to go to da fire an' prepare it for me. Den I'll handle da rest.", ["objectivesText"] = "Prepare the bonfire in front of the serpent shrine near Bambala for Bwemba 's ritual.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29223] = { ["id"] = 29223, ["name"] = "Nesingwary Will Know", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29223 }, ["series"] = { 29226, 29227 }, ["description"] = "So da Gurubashi be on da rampage an' dey usin' serpents to lead da charge. You know who be good at keepin' da animal population in check? Da hunters at Nesingwary's Expedition. Head over dere and see how dey doin'. See if dey know a good way to get rid of da serpents. If dey don't know, den you gotta at least warn dem dat dese serpents, it ain't all natural.", ["objectivesText"] = "Warn the hunters at Nesingwary's Expedition in Northern Stranglethorn Vale.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52980, ["x"] = 0.641333, ["y"] = 0.399333 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52294, ["x"] = 0.44, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.641333, ["y"] = 0.399333 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29226] = { ["id"] = 29226, ["name"] = "Track the Tracker", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29226 }, ["series"] = { 29223, 29227 }, ["description"] = "We've been fending off serpents for days now, <name>. But the serpents are nothing compared to what else is out in that jungle. We hunters are being hunted. A large panther named Mauti has been dragging my men off into the bush. We sent Grent Direhammer , one of our best hunters, to track this beast down. Direhammer headed off to the east, perhaps you can find them there.", ["objectivesText"] = "Find Grent Direhammer in Northern Stranglethorn Vale.", ["rewardGold"] = 58650, ["rewardXP"] = 4790, ["rewardItems"] = { 94219 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52294, ["x"] = 0.44, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52346, ["x"] = 0.502, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29227] = { ["id"] = 29227, ["name"] = "The Hunter's Revenge", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29227 }, ["series"] = { 29223, 29226 }, ["description"] = "The beast that's been hunting us... I've been hunting it. We call him Mauti. He's a clever one. But he made a grave mistake when he killed my brother. Now that mistake is going to cost him. Ol' Direhammer has got his scent. I've noticed him roaming just above Kurzen's Compound. If we act fast, we can take him down. Are you ready, <name>?", ["objectivesText"] = "Give Grent Direhammer the closure he needs by killing Mauti.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52294, ["x"] = 0.44, ["y"] = 0.23 }, { ["mapID"] = 50, ["npcID"] = 52346, ["x"] = 0.502, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29229] = { ["id"] = 29229, ["name"] = "Follow That Cat", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["storyline"] = { 29229 }, ["series"] = { 29230, 29231, 29232 }, ["description"] = "Well, that explains why Mauti seemed smaller... The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him. Find Direhammer before it's too late!", ["objectivesText"] = "Find where Mauti has taken Grent Direhammer.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29230] = { ["id"] = 29230, ["name"] = "Mauti", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29230 }, ["series"] = { 29229, 29231, 29232 }, ["description"] = "I got da feeling dat somethin' ain't right wit' dat panther, <name>. It ain't natural. I gonna need to perform some rituals over da body. Put Mauti down, an' den let's see what we can find out, <name>.", ["objectivesText"] = "Bring Bwemba to the remains of Mauti.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29231] = { ["id"] = 29231, ["name"] = "How's the Hunter Holding Up?", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29231 }, ["series"] = { 29229, 29230, 29232 }, ["description"] = "Tings ain't looking good. Dat panther was under some powerful magic. We better check on dat hunter an' see how he be doin'.", ["objectivesText"] = "Check on Grent Direhammer .", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52371, ["x"] = 0.76, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29232] = { ["id"] = 29232, ["name"] = "Bury Me With Me Boots...", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29232 }, ["series"] = { 29229, 29230, 29231 }, ["description"] = "Ah... It's you, <name>. Mauti... He's dead? Then my brother has been avenged. I've only one request from ya... This scamp here, he's been pawing at me bare feet. No dwarf should go to the earth with bare feet. Please, bury me with me boots.", ["objectivesText"] = "Collect Grent Direhammer's boots . Progress: Do ya have me boots? Grant a dwarf his last request will ya?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 68937 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52371, ["x"] = 0.76, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52371, ["x"] = 0.76, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29233] = { ["id"] = 29233, ["name"] = "Warn Grom'gol", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29233 }, ["series"] = { 29235 }, ["description"] = "Dis death ain't be in vain, <name>. We figure out dat Kilnara be on da prowl. Tings don't look good. We better check out Grom'gol Base Camp to da west. Maybe we find my contact dere.", ["objectivesText"] = "Make your way to Grom'gol Base Camp.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52996, ["x"] = 0.384, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29234] = { ["id"] = 29234, ["name"] = "Delegation", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29234 }, ["series"] = { 29193, 29194, 29225, 29239, 29432, 30119 }, ["description"] = "I am duty-bound to look into your claims immediately, <race>, which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the World Tree's branch.", ["objectivesText"] = "Recover the Branch of Nordrassil from the Firelands. Progress: Were you able to recover Nordrassil's Bough, <class>?", ["rewardGold"] = 929400, ["rewardXP"] = 7185, ["rewardItems"] = { 5332, 14022, 21536, 46779, 62072, 63194, 69646, 69815, 70994, 70995, 70996, 70997, 70998, 70999, 71000, 71001, 71008, 71015, 71016, 71017, 71084, 71086, 71141, 86570, 86572, 89611, 116154, 124225, 237812 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52995, ["x"] = 0.622, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 53009, ["x"] = 0.465, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 114, 198 }, ["zone"] = { 616 } }, ["questType"] = "raid", ["db2QuestSortName"] = "Engine of Innovation" },
[29235] = { ["id"] = 29235, ["name"] = "Defend Grom'gol", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29235 }, ["series"] = { 29233 }, ["description"] = "I hope you like to fight, <name>. Your troll friend has been through here and warned us that the Gurubashi were on the rampage. I never thought the battle would be this glorious though. Come, join in our fight and let's show these Gurubashi trolls the might of the Horde!", ["objectivesText"] = "Help defend Grom'gol Base Camp for three minutes. Progress: There is no end to these trolls, <name>. I like it that way!", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 52996, ["x"] = 0.384, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52996, ["x"] = 0.384, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29236] = { ["id"] = 29236, ["name"] = "To Hardwrench Hideaway", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29236 }, ["series"] = { 29237, 29238 }, ["description"] = "Bwemba ... Is that you? Your contact was here. He was eager to get to the next location and warn them. And really, who could blame him? I gave him use of a wyvern to reach the goblins of Hardwrench Hideaway, in the Cape of Stranglethorn. I will give you use of one of my wyverns to reach Hardwrench. Talk to me when you are ready to go, <name>.", ["objectivesText"] = "Head to Hardwrench Hideaway in The Cape of Stranglethorn. Progress: We better hury, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 53008, ["x"] = 0.39, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29237] = { ["id"] = 29237, ["name"] = "Voodoo Zombies", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29237 }, ["series"] = { 29236, 29238 }, ["description"] = "Da people... Dey all zombies, voodoo zombies! Dis ain't gonna be pretty, <name>. You gotta kill dem. But once dey killed, dere is a moment where I can save dem. Change dem back into da person dey were before. We gotta act fast. Da zombies don' rest.", ["objectivesText"] = "Rescue 10 Hideaway Survivors. Progress: Dis be a rush job wit da voodoo. But it still be dangerous.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29238] = { ["id"] = 29238, ["name"] = "Bad Supplies", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29238 }, ["series"] = { 29236, 29237 }, ["description"] = "Some of da survivors mentioned food, <name>. We better check da food supplies. I gotta a bad feelin' about dis.", ["objectivesText"] = "Check out the food preparation area in Hardwrench Hideaway.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29241] = { ["id"] = 29241, ["name"] = "Break the Godbreaker", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1977, ["storyline"] = { 29241 }, ["description"] = "< Bloodslayer Zala points at the temple in the distance.> When Jin'do was last ripped from dis world, he survived as a shade, weak and broken, in da spirit world. But Jin'do always had power over da spirits. One by one, he broke dem to his will, and wit' each soul devoured, Jin'do got closer ta' rippin' a hole through to dis world. Ta be here now... Da spirits be wit' us, we must end Jin'do.", ["objectivesText"] = "Kill Jin'do the Godbreaker inside of Zul'Gurub on Heroic difficulty.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29242] = { ["id"] = 29242, ["name"] = "Putting a Price on Priceless", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1977, ["storyline"] = { 29242 }, ["description"] = "Listen, friend. I don't know you, and you don't know me. But as long as we're both here, there's something Revilgaz wanted me to mention. Maybe you're taking a stroll through this troll-infested jungle-ocalypse. Maybe you happen to find a priceless troll artifact or two. Maybe you bring it back to me and I accidentally leave behind a little present for ya'. If you must know, it's for a project. And no, you can't ask what the project is.", ["objectivesText"] = "Investigate the Cache of Madness and find the Mysterious Gurubashi Bijou . Progress: So, did you find a thing? Because my pants are getting pretty heavy from all of this treasure of yours I'm holding onto.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 69647 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29243] = { ["id"] = 29243, ["name"] = "Strike at the Heart", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29243 }, ["series"] = { 29244 }, ["description"] = "One of Ragnaros' Lieutenants has shown itself at Ragnaros' Reach. It is time to strike. Captain Saynna has requested that you be there to help see the fight through. Witherbranch and some others will have joined the battle by the time you arrive. You should make haste to the northwest and find them.", ["objectivesText"] = "Kill the Lieutenant of Flame .", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29244] = { ["id"] = 29244, ["name"] = "A Lieutenant of Flame", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29244 }, ["series"] = { 29243 }, ["description"] = "Captain Saynna has requested your presence at Ragnaros' Reach. A Lieutenant of Flame has shown himself and she thinks you are our greatest chance at striking against him. Make your way there as soon as you're able.", ["objectivesText"] = "Report to Captain Saynna Stormrunner at Ragnaros' Reach.", ["rewardGold"] = 23500, ["rewardXP"] = 185, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29245] = { ["id"] = 29245, ["name"] = "The Mysterious Seed", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29245 }, ["series"] = { 29249, 29254 }, ["description"] = "A small, dried acorn has fallen out of the Flame Druid's robe. Why would a Druid of the Flame be carrying it around? Perhaps someone at Malfurion's Breach would like to see it.", ["objectivesText"] = "Take the Acorn to Avrilla at Malfurion's Breach in the Firelands. Provided item:", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29249] = { ["id"] = 29249, ["name"] = "Planting Season", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29249 }, ["series"] = { 29245, 29254 }, ["description"] = "The acorn seems to be unharmed. < Avrilla shrugs.> No point in beating around the bush. Let's plant it and see what comes out. Luckily for you, we brought some leftover soil with us to help establish our base. You'll find the soil at the graveyard directly east.", ["objectivesText"] = "Plant the Acorn in the Un'Goro Soil at Malfurion's Breach.", ["rewardGold"] = 154900, ["rewardXP"] = 2195, ["rewardItems"] = { 69675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29250] = { ["id"] = 29250, ["name"] = "Making Contact", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 29250 }, ["description"] = "You aren't one of the zombies... A troll? I did see one, just before the outbreak... He warned us, told us to be on our guard... But it was too late. Your troll friend headed to Booty Bay to warn them...", ["objectivesText"] = "Head to Booty Bay and find Bwemba's contact.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 53078, ["x"] = 0.335, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 52767, ["x"] = 0.41, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[29251] = { ["id"] = 29251, ["name"] = "Booty Bay's Interests", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1977, ["mapID"] = 210, ["storyline"] = { 29251 }, ["series"] = { 29252, 29253 }, ["description"] = "Look, <name>. You've helped out plenty so far, but that's not going to be enough. I need these crazy trolls stopped, or at least stopped from getting into Booty Bay. I'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen. At the very least, I want you to find me something that will help keep these trolls out of Booty Bay. You do that and we'll treat you right.", ["objectivesText"] = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay. Progress: Did you find something, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 69774, 133997 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29252] = { ["id"] = 29252, ["name"] = "Booty Bay's Interests", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1977, ["mapID"] = 210, ["storyline"] = { 29252 }, ["series"] = { 29251, 29253 }, ["description"] = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted. Or that it is at least halted at the gates of Booty Bay. I want action and I want results. I want you to get in there and kill. I want you to get in there and find me something that will help keep these trolls out of Booty Bay. You do that and we'll make sure you get paid.", ["objectivesText"] = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay. Progress: Did you find something, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 68833, 69774, 133997 }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 1977 } }, ["questType"] = "standard" },
[29253] = { ["id"] = 29253, ["name"] = "A Shiny Reward", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 29253 }, ["series"] = { 29251, 29252 }, ["description"] = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale. Head to the statue and claim your prize, <class>.", ["objectivesText"] = "Get your reward from a chest in the statue at Janeiro's Point.", ["rewardGold"] = 280900, ["rewardItems"] = { 64457, 69774, 69863, 69864, 69865, 133997 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[29254] = { ["id"] = 29254, ["name"] = "Little Lasher", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29254 }, ["series"] = { 29245, 29249 }, ["description"] = "The little red flower wiggles its tendrils happily. It seems to like you! Perhaps Avrilla would like to see what grew out of the acorn.", ["objectivesText"] = "Bring the Crimson Lasher to Avrilla .", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69213, 69675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29261] = { ["id"] = 29261, ["name"] = "Zul'Aman Voodoo", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3805, ["storyline"] = { 29261 }, ["objectivesText"] = "Progress: The maker of this voodoo pile perished in the process. Perhaps if you could finish it, the spirits would protect you instead....", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3805 } }, ["questType"] = "dungeon" },
[29262] = { ["id"] = 29262, ["name"] = "Zul'Gurub Voodoo", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1977, ["storyline"] = { 29262 }, ["objectivesText"] = "Progress: This potent pile of voodoo witchery emanates strong mojo...", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 52843, 63127, 63128, 64397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1977 } }, ["questType"] = "dungeon" },
[29263] = { ["id"] = 29263, ["name"] = "A Bitter Pill", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29263 }, ["description"] = "As far as I'm concerned, there's no problem that can't be solved with bombs. And if a bomb doesn't solve your problem on the first try... use a bigger bomb. So there's this big worm that's been eating people near the lava pools up north. Search for breath bubbles to find it. Attack it until it prepares to bite, then place this bomb down in front of it. Then sit back and watch the fireworks. Hmm... there was one other thing I wanted to say... oh yeah! Don't get eaten.", ["objectivesText"] = "Find the Subterranean Magma Worm 's breath bubbles, then defeat it by making it swallow the Bitter Pill .", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69759 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29264] = { ["id"] = 29264, ["name"] = "Flamewakers of the Molten Flow", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29264 }, ["description"] = "Of all Ragnaros' minions, the flamewakers appear to be the most devoted. Most of them dwell within this cave, preparing for another attack. Our foothold may be strong, but we will not tolerate any surprise attacks from these worms. No, we will strike first. Tear them apart, <name>.", ["objectivesText"] = "Slay 8 Flamewakers within the Molten Flow.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29267] = { ["id"] = 29267, ["name"] = "Some Good Will Come", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29267 }, ["description"] = "So much violence, so much death. Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it. Will you take a pause from the violence to help care for a panther cub ?", ["rewardItems"] = { 68824, 68833 }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52374, ["x"] = 0.76, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29268] = { ["id"] = 29268, ["name"] = "Some Good Will Come", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 29268 }, ["description"] = "So much violence, so much death. Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it. Will you take a break from the violence and help care for a panther cub ?", ["objectivesText"] = "Care for the panther cub , after all, you did kill it's mother.", ["rewardItems"] = { 39563, 68833 }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 52374, ["x"] = 0.76, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard" },
[29272] = { ["id"] = 29272, ["name"] = "Need... Water... Badly...", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29272 }, ["description"] = "Need... water... badly...", ["objectivesText"] = "Bring Anren Shadowseeker to the entrance of the Molten Front.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69213 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29273] = { ["id"] = 29273, ["name"] = "How Hot", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29273 }, ["description"] = "The fire hawks of Fireplume Peak can withstand incredible temperatures. While you'll often find them circling the skies above, they're also known to swim in molten lava. Isn't that right, Anren? We'd like to know just how hot that lava can get. Fireplume Peak has three large lava pools. Use this to measure the temperature of each.", ["objectivesText"] = "Use Tholo's Thermometer to measure the temperature of the three large lava pools on Fireplume Peak.", ["rewardGold"] = 137400, ["rewardXP"] = 4385, ["rewardItems"] = { 33844, 33857, 41755, 46856, 53438, 53445, 69806, 112885, 112887, 112889, 114727, 114728, 114729, 114730, 116394, 118019, 118020, 118021, 131346, 159000, 159001, 159002, 159003, 159077, 163036, 197110, 201783 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29275] = { ["id"] = 29275, ["name"] = "Fandral's Methods", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29275 }, ["description"] = "The Druids of the Flame... an order of druids that, up until a few weeks ago, Tholo and I had never even heard of. Now, under the leadership of Fandral Staghelm, they threaten our mission's success with their mastery of fire. It would appear that they store some supplies in the Igneous Depths, to the northeast. Perhaps, if we can get some of those supplies, we will have more luck when we take the fight to Fandral.", ["objectivesText"] = "Obtain a Flame Druid Staff , a Flame Druid Spellbook , a Flame Druid Reagent Pouch , and a Flame Druid Idol . Progress: Trust me - whatever information we can gather here will go far to helping us understand the source of Fandral's powers.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69810, 69811, 69812, 69813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29276] = { ["id"] = 29276, ["name"] = "The Flame Spider Queen", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29276 }, ["description"] = "The Widow's Clutch, to the northeast, is named after Beth'tilac, the enormous queen of the flame spiders. Her webs and her poison are a nagging threat to our main offensive force. We believe that if we study the flame spiders here on the Molten Front, we can use that information to find success against Beth'tilac. Use whatever methods you can to gather their venom and their web fluid, then return to my trusted friend Anren.", ["objectivesText"] = "Obtain 8 samples of Flame Venom and 8 samples of Searing Web Fluid . Progress: Be careful with those fluids, <name>. We don't want them spilling anywhere.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 46725, 60854, 69808, 69809, 86565 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29278] = { ["id"] = 29278, ["name"] = "Living Obsidium", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29278 }, ["description"] = "Have you seen those fireballs falling out of the sky? I saw one crash in the fields to the north, and the rock that landed was made of pure Living Obsidium! I can use the material to craft ultra-sturdy heat proof armor and weapons for our troops. Can you bring me a lode? Go to the Magma Springs and touch one of the magnetic stones. Just watch where you're standing when the rain of fire hits, and gather up the rocks before they crumble from the impact.", ["objectivesText"] = "Retrieve 10 Obsidium Meteorites . Progress: How's it going? Found any meteorites yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69807 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29279] = { ["id"] = 29279, ["name"] = "Filling the Moonwell", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["mapID"] = 198, ["storyline"] = { 29279 }, ["description"] = "We've constructed this moonwell, but it serves little purpose until it is filled with the sacred waters of the Well of Eternity. With an active moonwell, we would be able to bless our food stores, and we may also be able to use the blessing to offer you some protection from fire as well. When you've obtained enough marks, speak to Matoclaw at the Sanctuary of Malorne. She'll be able to secure transport of the sacred waters.", ["objectivesText"] = "Obtain 125 Marks of the World Tree . Progress: How can I be of aid, <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 69213, 70112, 70142, 70924, 70925, 70926, 70927 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29280] = { ["id"] = 29280, ["name"] = "Nourishing Waters", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29280 }, ["description"] = "I have dispatched the sacred moonwell waters to Malfurion's Breach, as you requested. Ayla is well trained in tending to them. You should return to her and see the boons she weaves for you there.", ["objectivesText"] = "Speak to Ayla Shadowstorm at Malfurion's Breach.", ["rewardGold"] = 70225, ["rewardXP"] = 1095, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29282] = { ["id"] = 29282, ["name"] = "Well Armed", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["mapID"] = 198, ["storyline"] = { 29282 }, ["description"] = "Ricket should be at Malfurion's Breach with Damek, as you requested. I'm not sure you fully know what you're getting into with those two though. Speaking of which, you should probably go check on them... make sure they haven't managed to blow up the Sentinel Tree itself. As long as you keep them busy with the elementals, the chances of \"accidents\" at the breach should lessen dramatically.", ["objectivesText"] = "Speak to Ricket at Malfurion's Breach.", ["rewardGold"] = 70225, ["rewardXP"] = 1095, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29283] = { ["id"] = 29283, ["name"] = "Calling the Ancients", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["mapID"] = 198, ["storyline"] = { 29283 }, ["description"] = "The ancients await in Hyjal. The Firelands will prove a dangerous place for them considering their... composition, but their strength will be of great use to us if we are to face any of Ragnaros' lieutenants. Gather your marks, and seek out Elderlimb at the Sanctuary of Malorne. If they are to march with us, he would be the one leading them through the portal.", ["objectivesText"] = "Obtain 125 Marks of the World Tree . Progress: Greetings to you, young one.", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 34955, 69213, 71631 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52906, ["x"] = 0.313333, ["y"] = 0.587333 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.313333, ["y"] = 0.587333 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29284] = { ["id"] = 29284, ["name"] = "Aid of the Ancients", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29284 }, ["description"] = "The ancients have seen the value of your wisdom, and have set root at Malfurion's Breach. You should seek out Elderlimb . I am certain he would like to hear from you.", ["objectivesText"] = "Speak to Elderlimb at Malfurion's Breach.", ["rewardGold"] = 42450, ["rewardXP"] = 1095, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29287] = { ["id"] = 29287, ["name"] = "Peaked Interest", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29287 }, ["description"] = "These fire hawks are beings of fire, but they exhibit much of the same behavior that we've seen in birds back home. It makes me wonder from where they originate. Back to the point - I think we might be able to train them. Domesticate them if you will. Use them against our enemies. I'd like you to retrieve one of their eggs from the top of Fireplume Peak. If you can bring it back to me safely, I will see to the rest.", ["objectivesText"] = "Retrieve a Fire Hawk Egg from the top of Fireplume Peak. Progress: Were you able to recover an egg?", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69836, 113542, 122124 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29290] = { ["id"] = 29290, ["name"] = "Fire in the Skies", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29290 }, ["description"] = "Look at that! It's incredible! Born less than two days ago and already full grown. Sadly, I suspect their life cycle is similarly short, so we'll have to take advantage of any time we have. His training went remarkably well. I want you to be the one to take him out and unleash him on the bulk of the enemy forces gathered near Ragnaros' keep. Show no mercy, <race>.", ["objectivesText"] = "Use the Trained Fire Hawk to kill 100 of the Flamewaker Salamanders, 40 of the Cinderweb Spiders, and 3 of the Molten Lords that are amassing in the Firelands. Progress: Some of our most capable forces are poised to strike at Ragnaros himself. If these attacks go well, we may be able to give them the opportunity they need.", ["rewardGold"] = 137400, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29293] = { ["id"] = 29293, ["name"] = "Singed Wings", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29293 }, ["description"] = "Many of our Storm Crows have gone ahead to scout the peak and attempt to retrieve some of the fire hawk eggs, but to very little success I'm afraid. The thermals make it nearly impossible to fly safely, and the fire hawks aren't exactly friendly either. I need you to head over there and rescue any druids that you can. I've got splints, bandages, burn salves, smelling salts... anything you'll need to get them back on their feet, assuming they're still alive. Please hurry and help anyone you can find.", ["objectivesText"] = "Rescue 5 Injured Druids of the Talon on Fireplume Peak. Progress: There must be more of them alive over there... it's just a matter of finding them.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69837, 113542, 122124 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29295] = { ["id"] = 29295, ["name"] = "The Bigger They Are", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29295 }, ["description"] = "You're not going to take on fiery behemoths wearing THAT, are you? If you aren't wearing my obsidium crafted goods, you're going to burn right up! And even if you are, you can never have enough of the good stuff. Look <brother/sister>, I can craft you the best armor that gold can buy, but I need pure, unsmelted Living Obsidium first. The Obsidium Punishers on Fireplume Peak are literally made of the stuff. Go kill them and gather their pieces.", ["objectivesText"] = "Collect 10 Living Obsidium from the Obsidium Punishers on Fireplume Peak. Progress: Did you bring me the goods?", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69860, 141669, 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29296] = { ["id"] = 29296, ["name"] = "Territorial Birds", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29296 }, ["description"] = "The fire hawks are upset by our continued presence. They're getting extremely hostile, and not just in the usual territorial ways. I worry that if we leave them unchecked, they will soon be joining the assault on our tree, and I'm not sure we're capable of handling that. Go across the way to Fireplume Peak and do what you have to to keep them in check. I'm far more concerned with our safety right now than theirs, so be decisive about it.", ["objectivesText"] = "Slay 5 Fire Hawks .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29297] = { ["id"] = 29297, ["name"] = "Bye Bye Burdy", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29297 }, ["description"] = "Staghelm's druids are putting up a fierce fight at Wildflame Point to the northeast. The druids fly above us in fire crow form, then strike when we least expect it. Worst part is, they know exactly how to stay out of our reach! We would be totally helpless, except Damek lent me his trusty harpoon. He says these weapons will fly straight and true even in this super dense air. Take the dwarf's weapon and shoot some birds out of the sky!", ["objectivesText"] = "Kill 3 Druids of the Flame, while in Fire Crow form, with the Burd Sticker .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69832 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29298] = { ["id"] = 29298, ["name"] = "A Smoke-Stained Locket", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 29298 }, ["series"] = { 29302, 29303, 29310, 29311 }, ["description"] = "This locket has a few small leaf-shaped carvings etched into its face, but any other details have been rubbed away with time, or burned away with fire. It appears to be druidic in nature. Most druids pass through Moonglade during their training. If anybody can help you decipher where this locket came from, it would be Rabine Saturna of Nighthaven.", ["objectivesText"] = "Bring the Smoke-Stained Locket to Rabine Saturna at Nighthaven in Moonglade. Progress: Yes, young <race>?", ["rewardXP"] = 2195, ["rewardItems"] = { 69854, 71259 }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 11801, ["x"] = 0.530857, ["y"] = 0.334286 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.530857, ["y"] = 0.334286 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["startItems"] = { 69854 } },
[29299] = { ["id"] = 29299, ["name"] = "Some Like It Hot", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29299 }, ["description"] = "I've been making progress in my research, <name>. Based on what we've witnessed in the local flora, it's quite possible that your Lasher also accepts superheated liquids as a principal source of nutrition. I'd like you to help me with a little experiment. The Emberspit Scorpions that inhabit the Magma Springs to the north spew out burning pools of fire during combat. Take the Lasher and observe his reaction to the scorpions' Ember Pools.", ["objectivesText"] = "Observe the Crimson Lasher drinking from 6 Ember Pools. Ember Pools are created by fighting Emberspit Scorpions.", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 86565, 137663 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29302] = { ["id"] = 29302, ["name"] = "Unlocking the Secrets Within", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 29302 }, ["series"] = { 29298, 29303, 29310, 29311 }, ["description"] = "The initials seem to have worn off of this locket, but I can sense a power within it that suggests only one possible owner: Leyara, the Druid of the Flame. Stand back, and we shall see what surprises this locket contains.", ["objectivesText"] = "Witness the memories stored within the Smoke-Stained Locket .", ["rewardXP"] = 2195, ["rewardItems"] = { 69855 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 11801, ["x"] = 0.530857, ["y"] = 0.334286 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 11801, ["x"] = 0.530857, ["y"] = 0.334286 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.530857, ["y"] = 0.334286 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard" },
[29303] = { ["id"] = 29303, ["name"] = "Tragedy and Family", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 29303 }, ["series"] = { 29298, 29302, 29310, 29311 }, ["description"] = "You were insightful to bring this locket to me, <name>. I am among the few who know where Valstann's body lays. You can find his resting site in a small graveyard, southeast of Astranaar, in Ashenvale. Bring this locket to the site, and it may unlock more memories. Farewell, <name>, and good luck on your journey.", ["objectivesText"] = "Bring the Smoke-Stained Locket to the Night Elf Grave near Astranaar in Ashenvale.", ["rewardXP"] = 2195, ["rewardItems"] = { 69855 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 11801, ["x"] = 0.530857, ["y"] = 0.334286 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.530857, ["y"] = 0.334286 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard" },
[29304] = { ["id"] = 29304, ["name"] = "The Dogs of War", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29304 }, ["description"] = "Our forces are falling beneath an unleashed monstrosity - Charhounds from the molten depths. These dogs fear nothing and will not stop until their lust for blood is satisfied. Our forces are barely holding them back. Go join the defenders in the Ashen Fields or in the Molten Flow. Perhaps you can make a dent in their numbers.", ["objectivesText"] = "Kill 5 Charhounds or Ancient Charhounds .", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29305] = { ["id"] = 29305, ["name"] = "Strike at the Heart", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29305 }, ["description"] = "One of Ragnaros' Lieutenants has shown himself at Ragnaros' Reach, the walled area to our northeast. I hoped to send you as soon as you returned, but I suspect Witherbranch and some of our forces have already joined the fight by now. You should hurry. You should be able to drop down the cliff wall right here and reach them quickly.", ["objectivesText"] = "Kill the Lieutenant of Flame . Progress: Today we cripple their war effort.", ["rewardGold"] = 619600, ["rewardXP"] = 5480, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29310] = { ["id"] = 29310, ["name"] = "The Tipping Point", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29310 }, ["series"] = { 29298, 29302, 29303, 29311 }, ["description"] = "On the day when Leyara attacked Hamuul, she was waiting near some ruins in Hyjal, northwest of the Regrowth. She acted strangely at the time: calm, silent, and staring off into the distance. Perhaps that location is of some importance to her. The locket might react if brought to that location.", ["objectivesText"] = "Bring the Smoke-Stained Locket to the Small Gravestone at Leyara's Sorrow in Hyjal.", ["rewardXP"] = 2195, ["rewardItems"] = { 69855 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29311] = { ["id"] = 29311, ["name"] = "The Rest is History", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29311 }, ["series"] = { 29298, 29302, 29303, 29310 }, ["description"] = "In her memories, Leyara spoke of Malfurion. The tragedies of her past - at least, in her opinion - are largely due to his actions. Malfurion must remember Leyara from before she became a Druid of the Flame. You resolve to bring the locket to him in the Firelands. Hopefully he can answer any remaining questions.", ["objectivesText"] = "Bring the Smoke-Stained Locket to Malfurion in the Molten Front. Provided item:", ["rewardGold"] = 1123600, ["rewardXP"] = 4385, ["rewardItems"] = { 69855, 71259 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29313] = { ["id"] = 29313, ["name"] = "The Secret to Perfect Kimchi", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29313 }, ["description"] = "My family has been making the best kimchi in Darnassus since the city was founded, <name>. The secret is something simple, but it makes all the difference. We bury the jars in the ground until it's ready to serve and my latest batch has just reached that point. You can find the jars buried in earthen mounds all over the city. Would you help me gather them while the contents are just right?", ["objectivesText"] = "Find 8 Buried Kimchi Jars in Darnassus. Progress: Were you able to find the jars?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 69898 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.4505, ["y"] = 0.3865 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29314] = { ["id"] = 29314, ["name"] = "Remembering the Ancestors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29314 }, ["description"] = "The living are not the only ones who require sustenance. One of my duties is to prepare the rice cakes that are left for the ancestors. Normally, my senior apprentice has the honor of taking the cakes to the Temple of the Moon for blessing and then presenting them to the ancestors. Since she is out of the city today, would you mind performing the duty in her place?", ["objectivesText"] = "Collect the Blessed Rice Cakes from the Temple of the Moon. Progress: This is the shrine the trainer mentioned.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69900 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.4505, ["y"] = 0.3865 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29315] = { ["id"] = 29315, ["name"] = "Fungus Among Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29315 }, ["description"] = "Some chefs complain that our beloved Undercity doesn't boast the ingredients to create truly fine fare. Such mewling little cretins. Delicious delights abound! Gather some of the rank, slimy Sewer Caps growing in Undercity's northwest sewer line and return them to me.", ["objectivesText"] = "Obtain 12 Sewer Caps . Deliver the fungus to Eunice Burch in Undercity. Progress: Did you find enough Sewer Caps ?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69899 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.595429, ["y"] = 0.472571 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29316] = { ["id"] = 29316, ["name"] = "Back to Basics", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29316 }, ["description"] = "There are certain things that everyone needs, from the basic household cook to the master chef. One of the city's most important staples is rice flour. Most families keep at least one basket of rice in their houses and the residents of the Craftsmen's Terrace and Tradesmen's Terrace are no different. I often ask my students to help with the task of pounding rice into flour since it's good practice and an endless task. Why don't you give it a try?", ["objectivesText"] = "Help the inhabitants of the Craftsmen's Terrace and Tradesmen's Terrace make rice flour by pounding the contents of Rice Baskets .", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.4505, ["y"] = 0.3865 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29317] = { ["id"] = 29317, ["name"] = "Fish Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29317 }, ["description"] = "There was an... incident... with an orc guard and one of Master Apothecary Faranell 's abominations. Apparently, the Kor'kron Overseer chopped its head clean off and kicked it into the slime. Faranell's apprentices searched for hours but they can't find the thing. Care to try fishing it up? I'm sure the old fellow'd be grateful.", ["objectivesText"] = "Armand Cromwell wants you to fish up a Severed Abomination Head in Undercity for Master Apothecary Faranell . Progress: You haven't by any chance come across a severed abomination head , have you...?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 45992, 67414, 69901 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 2055, ["x"] = 0.512, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.7552, ["y"] = 0.3562 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29318] = { ["id"] = 29318, ["name"] = "Ribs for the Sentinels", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29318 }, ["description"] = "One of my responsibilities is to feed the sentinels of Darnassus while they're on duty. It's a time-consuming task, but one I'm happy to undertake. It's also a great way to practice your skills. Would you mind helping me with today's meal? Simply take these ribs, cook them near a stove or fire, and distribute them to sentinels throughout the city.", ["objectivesText"] = "Use the Uncooked Ribs near a stove or campfire to cook them and then use them to feed 5 Darnassus Sentinels.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69904, 69906 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.4505, ["y"] = 0.3865 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29319] = { ["id"] = 29319, ["name"] = "Tadpole Terror", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29319 }, ["description"] = "Some of our apothecaries took to dumping their more volatile waste chemicals into Stillwater Pond and... well, let's just say that no one wants to know how big mutant flesh-eating toads can grow. Would you consider fishing up some giant flesh-eating tadpoles before it gets to that? Just don't try to handle them with your bare hands.", ["objectivesText"] = "Armand Cromwell in Undercity wants you to bring him 8 Giant Flesh-Eating Tadpoles . Progress: Catch any mutant tadpoles? Don't try to handle them with your bare hands.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69905 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.7552, ["y"] = 0.3562 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29320] = { ["id"] = 29320, ["name"] = "Like Pike?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29320 }, ["description"] = "You've fished in Brightwater Lake, yes? The prize catch there is one of the lake's massive corpse-fed pikes . However, they only bite on a very specific type of bait... corpse worms . Search the graves in the courtyard up top and you should find some.", ["objectivesText"] = "Dig up a Corpse Worm in the Ruins of Lordaeron courtyard and use it as bait to catch a Corpse-Fed Pike . Corpse-Fed Pike can be fished up in Brightwater Lake, northeast of Undercity. Progress: Catch that pike, yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 6256, 34832, 67414, 69907, 69909, 92747 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.7552, ["y"] = 0.3562 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29321] = { ["id"] = 29321, ["name"] = "Happy as a Clam Digger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29321 }, ["description"] = "It seems like everyone I know loves clams, but I can't stand them! They're smelly and slimy, and harvesting them means digging through mud. Give me a fishing pole and some bait any day. Still, I want to surprise my brother with a bucket of fresh clams. I'd reward you if you were willing to gather those clams for me. Just go through the portal to Rut'theran Village and look for the clams in the shallows near the shore.", ["objectivesText"] = "Gather 10 Teldrassil Clams from the shores near Rut'theran Village. Progress: Did you find enough clams?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69910 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.442333, ["y"] = 0.511333 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29322] = { ["id"] = 29322, ["name"] = "Time for Slime", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29322 }, ["description"] = "It takes a special sort of fisherman to reap the bounty of Undercity's burbling slime troughs. Think you can handle gathering some of the squirming, sentient slime mold slithering about down there? You can try to fish them up, but they're wily; you might be better off just diving into the ooze and grabbing them. Remember, they're only useful alive and intact... who'd want to eat a dead slime mold?! Disgusting.", ["objectivesText"] = "Collect 10 Squirming Slime Molds . Deliver them to Armand Cromwell in Undercity. Progress: Difficult to catch, aren't they?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69911 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.7552, ["y"] = 0.3562 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29323] = { ["id"] = 29323, ["name"] = "Stocking Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29323 }, ["description"] = "We've used up most of our food stores in taking care of refugees and feeding those whose homes and livelihoods were destroyed. If we don't replenish our stores, we'll all be in danger next time there's a bad storm or a Horde invasion. Perhaps you'd be willing to help me build up our stock of lake whitefish . You can catch it anywhere in Darnassus, and once it's dried, it'll keep until it's needed.", ["objectivesText"] = "Catch 5 Lake Whitefish by fishing in Darnassus. Progress: If all of our fishermen pitch in, it won't take long to rebuild our supplies.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69912 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.442333, ["y"] = 0.511333 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29324] = { ["id"] = 29324, ["name"] = "The Sister's Pendant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29324 }, ["description"] = "Have you met Sister Aquinne? She and I trained together in Dolanaar, and she recently came to the city to study at the Temple of the Moon. We decided to go for a boat ride, but the clumsy oarsman managed to capsize the craft! When we got back to the shore, Aquinne's moon pendant was missing. The lakes in Darnassus are full of giant catfish who will gobble up anything shiny! I've been catching them nonstop, hoping to find the one with her pendant. I don't suppose you want to help?", ["objectivesText"] = "Retrieve Aquinne's Moon Pendant from the belly of a Giant Catfish . You should be able to catch them anywhere you can fish in Darnassus. Progress: Have you had any luck finding Aquinne's missing pendant? I must've caught fifty of those monsters and I have nothing to show for it!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69913, 69914 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.442333, ["y"] = 0.511333 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29325] = { ["id"] = 29325, ["name"] = "A Slippery Snack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29325 }, ["description"] = "Have you ever eaten octopus meat? It takes some getting used to, but it's my favorite! I even know some people who like to eat the whole thing while it's alive! I don't plan on trying that anytime soon, but I am out of fresh octopi at the moment. Will you help me gather some more? They live in the shallow water off the shore near Rut'theran Village.", ["objectivesText"] = "Gather 6 Baby Octopi from the shallow water near Rut'theran Village. Progress: It's impossible to catch octopi with a fishing line, so you're just going to have to grab them!", ["rewardGold"] = 331700, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69915 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.442333, ["y"] = 0.511333 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29326] = { ["id"] = 29326, ["name"] = "The Nordrassil Summit", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29326 }, ["series"] = { 29327, 29335, 29439, 29440 }, ["description"] = "Hello, <class>! My brothers and sisters of the Earthen Ring have spoken well of your deeds in the wake of the Cataclysm. But much remains to be done if we are to heal this broken world. Walk with me, friend. Preparations for a ceremony are underway, a ritual that I hope will be a turning point in our battle against the Twilight's Hammer. When all is done, you will be able to spread the word about our triumph here.", ["objectivesText"] = "Speak with Thrall under the World Tree in Mount Hyjal and witness the Earthen Ring ceremony.", ["rewardGold"] = 210675, ["rewardXP"] = 3595, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 54313, ["x"] = 0.605333, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 54312, ["x"] = 0.602, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29327] = { ["id"] = 29327, ["name"] = "Elemental Bonds: Doubt", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 29327 }, ["series"] = { 29326, 29335, 29439, 29440 }, ["description"] = "I do know the one you seek... but I do not know if it is wise for you to follow him. He has cast himself into the cyclone. The winds now tear at his body and mind, leaving nothing but shreds of flesh and doubt. Chasing after him would only expose you to the same fate. The wind's edge leaves nothing uncut. You have been warned. Now what will you do?", ["objectivesText"] = "Speak with Cyclonas to secure passage to Thrall . Then, fight the wind elementals that torment him until he is freed. Progress: Stay vigilant, <name>! Do not give up on Go'el.", ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 53524, ["x"] = 0.476, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 53519, ["x"] = 0.342, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[29328] = { ["id"] = 29328, ["name"] = "Elemental Bonds: Desire", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 29328 }, ["series"] = { 29337 }, ["description"] = "Once again, <class>, I cannot do this without your help. I will try to quiet this tempest, but you will need to fight back the unstable elementals that whirl around it. Only then can we free Go'el!", ["objectivesText"] = "Slay the Tides of Longing and Vortexes of Longing near the Abyssal Breach until Thrall is free of their grasp. Progress: My Go'el cannot tread these waters forever, <name>!", ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 53652, ["x"] = 0.698, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 53652, ["x"] = 0.698, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[29329] = { ["id"] = 29329, ["name"] = "Elemental Bonds: Patience", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 29329 }, ["description"] = "With the Stonemother's blessing, I can take us to where Go'el is being held. We must be careful. The Twilight's Hammer has agents all around. You help me hold them off while I attempt to get through to Go'el! Speak with me when you are ready, and I will take you to him.", ["objectivesText"] = "Speak with Aggra when you are ready to help Thrall. Then defeat the Elements of Patience and Corestones of Patience that are holding him captive. Progress: We are nearly there, <name>. Stay by my side a bit longer. We will get through to him yet.", ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 53738, ["x"] = 0.5835, ["y"] = 0.2085 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 53738, ["x"] = 0.5835, ["y"] = 0.2085 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.5835, ["y"] = 0.2085 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[29330] = { ["id"] = 29330, ["name"] = "Elemental Bonds: Fury", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5733, ["storyline"] = { 29330 }, ["series"] = { 29331 }, ["description"] = "The totems, <name>! We need to activate them, or Go'el is lost! Kill the elementals next to each of my totems, located around the edges of this plateau. Once all four totems are activated, we should be able to free the last piece of Go'el's soul!", ["objectivesText"] = "Kill fire elementals next to Aggra 's Air Totem, on the western edge of the plateau, until it activates. Then continue to Aggra 's Water Totem, Aggra 's Earth Totem, and Aggra 's Fire Totem.", ["rewardXP"] = 7185, ["rewardItems"] = { 69777, 137663 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29331] = { ["id"] = 29331, ["name"] = "Elemental Bonds: The Vow", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29331 }, ["series"] = { 29330 }, ["description"] = "Before he passed through the portal to Mount Hyjal, Thrall asked you to follow him. There is something he would like you to witness.", ["objectivesText"] = "Speak with Thrall at Nordrassil in Mount Hyjal.", ["rewardGold"] = 1123600, ["rewardXP"] = 9580, ["rewardItems"] = { 71267, 71268, 71269, 71270 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 54168, ["x"] = 0.602, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29332] = { ["id"] = 29332, ["name"] = "Lily, Oh Lily", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29332 }, ["description"] = "The lilies that grow around Stillwater Pond can be rendered down into a delightful broth. Well... by \"delightful,\" I mean \"won't immediately sicken any orc who drinks it.\" Why don't you go gather some for me, hmmm? Just watch out for the giant flesh-eating tadpoles.", ["objectivesText"] = "Obtain 10 Stillwater Lilies . Deliver the plants to Eunice Burch in Undercity. Progress: Did you find enough Stillwater Lilies ?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69917 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.595429, ["y"] = 0.472571 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29333] = { ["id"] = 29333, ["name"] = "Escargot A Go-Go", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29333 }, ["description"] = "The orc guards are always grumbling about bland and moldering Undercity fare - as if it's OUR fault they can't get by on a diet of mushrooms and old corpses - so I think it's time they learn just the sort of exotic delights we can cook up when we've a mind to. Gather some of the freshwater snails ambling about beneath Brightwater Lake and I'll show them what a true culinary master can create.", ["objectivesText"] = "Collect 8 Brightwater Snails . Deliver them to Eunice Burch in Undercity. Progress: Gather those freshwater snails, yet?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69918 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.595429, ["y"] = 0.472571 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29334] = { ["id"] = 29334, ["name"] = "Roach Coach", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29334 }, ["description"] = "For all the grousing those Kor'kron Overseers do about Undercity food, there's ONE thing they'll eat in spades: My sister Audrey's Thrice-Spiced Crunchy Stew. Its popularity means she's always running low on ingredients. Could you gather some for her at the coach she sells them from? You'll find traps all over the city; just take their contents to Audrey and she'll handle the rest!", ["objectivesText"] = "Obtain 20 Plump Cockroaches. Deliver the insects to Chef Audrey in Undercity. Progress: I call my little traps \"Cockroach Cabins.\" Cockroaches check in, but they don't check out!", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69919 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 53528, ["x"] = 0.62525, ["y"] = 0.3545 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.595429, ["y"] = 0.472571 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29335] = { ["id"] = 29335, ["name"] = "Into Slashing Winds", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29335 }, ["series"] = { 29326, 29327, 29439, 29440 }, ["description"] = "<class>, I refuse to believe my Go'el is lost forever. His spirit has been scattered across the elemental planes. If even a part of him still exists, we can find him, but I will need your help. We will start with the plane of air. Speak to me and we will travel to the Vortex Pinnacle together. We must speak with an elemental, Cyclonas . He's capricious, but he sees everything in the realm of air. If my love is there, Cyclonas will know what's become of him.", ["objectivesText"] = "Speak with Cyclonas on the Bluff of the South Wind in Uldum.", ["rewardXP"] = 2395, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 54312, ["x"] = 0.602, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 53524, ["x"] = 0.476, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 198, 249 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29336] = { ["id"] = 29336, ["name"] = "Into Coaxing Tides", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 29336 }, ["description"] = "Go'el must be in the plane of water... the Abyssal Maw itself! I shudder to imagine what fate awaits him there. Find the elemental, Hydrius , near the Abyssal Breach. He knows of Go'el and is sympathetic to our fight against Ragnaros. If anyone can help you there, it's him. I will meet you beneath the tides of Vashj'ir, <race>...", ["objectivesText"] = "Speak with Hydrius at the Abyssal Breach in the Abyssal Depths of Vashj'ir.", ["rewardXP"] = 2395, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 53519, ["x"] = 0.342, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 53677, ["x"] = 0.695333, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 204, 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[29337] = { ["id"] = 29337, ["name"] = "Into Constant Earth", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 29337 }, ["series"] = { 29328 }, ["description"] = "Time is short! My love lies in Deepholm. I will take us there when you are ready, and we will speak with Therazane the Stonemother.", ["objectivesText"] = "Speak with Therazane at Therazane 's Throne in Deepholm. Aggra can teleport you to Therazane 's Throne from the Abyssal Breach.", ["rewardXP"] = 2395, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 53652, ["x"] = 0.698, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 204, 207 }, ["zone"] = { 5145 } }, ["questType"] = "standard" },
[29338] = { ["id"] = 29338, ["name"] = "Into Unrelenting Flame", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 29338 }, ["description"] = "We must travel now to the Firelands. Within that realm, Go'el's burning spirit could become as terrible as Ragnaros himself! Prepare yourself, for we will be alone in a hostile world. Speak with me when you are ready... and may the ancestors protect us!", ["objectivesText"] = "Speak with Aggra on the Staidridge in Deepholm to secure passage to the Firelands.", ["rewardXP"] = 2395, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 53738, ["x"] = 0.5835, ["y"] = 0.2085 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.5835, ["y"] = 0.2085 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[29339] = { ["id"] = 29339, ["name"] = "Short-Supply Reward", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29339 }, ["rewardItems"] = { 69903, 90818, 103533, 120334, 128803, 140591, 141701, 160054, 184522, 201326, 224573, 259086 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29342] = { ["id"] = 29342, ["name"] = "Cold Water Fishing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29342 }, ["description"] = "The best tastin' fish live in the cold waters o' Dun Morogh, <name>, an' don't let anyone else tell ye otherwise! Me favorite, an' the most popular one in Ironforge, is the arctic char , which only comes from our ancestral lands. I like tae think o' it as Ironforge's gift t' the world! Why don't ye try yer hand at catchin' a few yerself? The best place tae find 'em is down in Helm's Bed Lake, in the eastern end o' Dun Morogh.", ["objectivesText"] = "Catch 5 Arctic Char by fishing in Helm's Bed Lake in Dun Morogh. Progress: Have ye tried to catch those char?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69931 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.479143, ["y"] = 0.078857 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29343] = { ["id"] = 29343, ["name"] = "One fer the Ages", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29343 }, ["description"] = "I'm sure by now ye've heard the tale o' Old Ironjaw, the most famous and elusive fish in the waters o' Ironforge's Forlorn Cavern. Well, in his many years, he's been responsible for the rise o' many young ironjaws . Don't let the name fool ye, <name>, these young'uns are every bit as clever as their dad, but somewhat lackin' in experience. With skill an' patience, ye could probably catch one, an' when ye do, bring it to the museum in Ironforge's Library an' put it on display fer all to see!", ["objectivesText"] = "Catch a Young Ironjaw in Ironforge's Forlorn Cavern and display it in the Library near the Empty Plaque. Progress: Did ye catch one o' Ironjaw's offspring?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69932 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.479143, ["y"] = 0.078857 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29344] = { ["id"] = 29344, ["name"] = "Fish fer Squrky", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29344 }, ["description"] = "Hae I introduced ye tae me pet, Squrky? I'm teachin' him tae fish all proper-like. Fer now, I've been feedin' him minnows fished from the pool in this cavern. Maybe ye'd like tae give it a try? Just cast yer lure in the pool over there and feed Squrky any minnows ye happen tae fish up. He'll love ye ferever!", ["objectivesText"] = "Catch 3 Blind Minnows in the pool in the Forlorn Cavern and feed them to Squrky. Progress: How's Squrky's lunch comin'?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69933 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.479143, ["y"] = 0.078857 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29345] = { ["id"] = 29345, ["name"] = "Pond Predators", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29345 }, ["description"] = "A well-meaning goblin visitor introduced Azshara snakeheads to our waters and now they're overrunning the pond. Please, if you can catch some of these voracious predatory fish before they eat every smallfish and mud snapper in Thunder Bluff, I'd be terribly grateful.", ["objectivesText"] = "Kah Mistrunner in Thunder Bluff wants 8 Azshara Snakehead fish from the Thunder Bluff pond. Progress: Have you caught any Azshara snakeheads , yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 6529, 40199, 67414, 69934 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.5376, ["y"] = 0.4588 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29346] = { ["id"] = 29346, ["name"] = "The Ring's the Thing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29346 }, ["description"] = "One of the Forsaken from the Pools of Vision came to me and said he'd lost his ring to a blind cavefish in the waters there. Or perhaps it was his finger. It was hard to tell; his jaw did not move and his Orcish was no better than mine. In any case, I thought it would be a kind gesture towards our unusual visitors to catch and gut cavefish until the ring - or finger - was found. Would you help?", ["objectivesText"] = "Fish up a Blind Cavefish from the Pools of Vision in Thunder Bluff. Once you catch a cavefish, fillet it and check if it swallowed the ring. Progress: You haven't seen a ring about, have you? I think one of the cavefish might have swallowed it...", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 8350, 67414, 69935, 69956 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 30709, ["x"] = 0.3, ["y"] = 0.210667 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.5376, ["y"] = 0.4588 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29347] = { ["id"] = 29347, ["name"] = "Live Bait", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29347 }, ["description"] = "If ye've ever fished fer crayfish, ye know they respond best to live bait, an' the more bait, the better. Would ye like to test my new bait? Simply smear this on yerself an' hop into Helm's Bed Lake in eastern Dun Morogh. After ye've got the catch, take it to me friend, Cook Ghilm at Gol'Bolar Quarry, west of the lake. He's an expert at cookin' those oversized bugs!", ["objectivesText"] = "Use Grimnur's Bait on yourself, then jump into Helm's Bed Lake in Dun Morogh. Progress: Oh... this might hurt a wee bit.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69940, 133755 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 1355, ["x"] = 0.755, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.479143, ["y"] = 0.078857 }, ["mapCandidates"] = { ["npc"] = { 27, 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29348] = { ["id"] = 29348, ["name"] = "The Race to Restock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29348 }, ["description"] = "Thunder Bluff's fishing pond is being overrun with voracious Azshara snakeheads; there are hardly any smallfish or mud snappers left. We already have fishers trying to kill as many snakeheads as they can, but can you assist us in our restocking efforts? If you could gather some fish from Stonebull Lake and bring them here to Thunder Bluff, I would be very grateful.", ["objectivesText"] = "Kah Mistrunner in Thunder Bluff wants 2 Randy Smallfish and 2 Amorous Mud Snappers from Stonebull Lake in Mulgore. Progress: Did you bring those fish from Stonebull Lake, yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 6256, 6365, 6533, 40199, 67414, 69964, 69967 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.5376, ["y"] = 0.4588 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29349] = { ["id"] = 29349, ["name"] = "Craving Crayfish", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29349 }, ["description"] = "One of the great delicacies of Mulgore is the crayfish that dwell in our lakes and streams. They are particularly popular during weddings or the celebration of a birth. Would you help me catch some of these crafty crustaceans for the cooking pots of Thunder Bluff? You can fish them up from Stonebull Lake, or simply dive in and grab them.", ["objectivesText"] = "Kah Mistrunner in Thunder Bluff wants 10 Stonebull Crayfish from Stonebull Lake in Mulgore. Progress: Crayfish are so tasty. Have you caught many?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 44050, 46109, 67414, 69977 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.5376, ["y"] = 0.4588 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29350] = { ["id"] = 29350, ["name"] = "The Gnomish Bait-o-Matic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29350 }, ["description"] = "One o' the gnomish engineerin' trainers gave me a blueprint fer a fancy lure he says'll help me catch fish faster and keep 'em from gettin' away. The whole thing sounds a mite silly if ye ask me, but I'll try anythin' once. Here are the blueprints. Ye're going to need shiny baubles, which ye can buy from my assistant inside the buildin', a hair trigger ye can buy from an engineerin' supplier in Tinker Town, and a few rat traps from the Deeprun Tram.", ["objectivesText"] = "Use the Bait-o-Matic Blueprint with 5 Shiny Baubles, a Hair Trigger, and 3 Rat Traps to create the Gnomish Bait-o-Matic . Progress: How's that fancy new lure comin' along?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 6529, 39684, 67414, 69978, 69979, 69980 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5161, ["x"] = 0.479143, ["y"] = 0.078857 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.479143, ["y"] = 0.078857 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29351] = { ["id"] = 29351, ["name"] = "A Round for the Guards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29351 }, ["description"] = "The guards who defend Ironforge put their lives on the line against our many enemies, and it's up to us to take care of them. Today, their rations consist of two dwarven favorites, haggis and Ironforge pale ale. Would ye be so kind as to help me distribute them? That way, everyone gets his food in a timely manner and we can move on to other tasks.", ["objectivesText"] = "Distribute the Ironforge Rations to 6 Ironforge Guards.", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 69981 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29352] = { ["id"] = 29352, ["name"] = "A Fowl Shortage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29352 }, ["description"] = "Oh, no, <name>, this is going to be a disaster if we don't find some chicken soon... Ye just cannae make cock-a-leekie soup without the chicken! It's not possible! There's still time to make the soup and broth if ye can find some fresh chicken. Will ye help me? There are usually a few chickens running around outside the front entrance to the city. If ye can get yer hands on, say, six o' them, that should save me soup.", ["objectivesText"] = "Collect 6 Dun Morogh Chickens near the entrance to Ironforge. Progress: The chickens, <name>, do ye have them or not?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 44177, 69982 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29353] = { ["id"] = 29353, ["name"] = "Keepin' the Haggis Flowin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29353 }, ["description"] = "The haggis must flow. Aye, it's a figure o' speech, for haggis'll ne'er flow! Ye dinnae want to know what'll happen if the people o' Ironforge don't get their haggis. I'm working on the next batch, but I'm still missing a couple of ingredients. Sognar Cliffbeard is the meat vendor in the Military Ward, an' he'll sell you the big bag o' sheep innards I need. Ye can buy mild spices from any cooking supplier and ye can find sacks o' oatmeal in any inn or among the supplies in the city.", ["objectivesText"] = "Obtain a Bag o' Sheep Innards , 5 packets of Mild Spices , and 4 Sacks of Oatmeal . Progress: Do ye have those ingredients?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 2678, 69984, 69985 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29354] = { ["id"] = 29354, ["name"] = "Shiny Baubles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29354 }, ["description"] = "One of a fisher's most simple and effective tools is the shiny bauble; affixed to a line, even the most novice angler has a chance at a catch. With all the fishing going on of late, though, Thunder Bluff is in woefully short supply! Might I ask you to collect shiny stones from around the base of the central rise? Bring them to Nahari Cloudchaser so that she might craft more shiny baubles with them.", ["objectivesText"] = "Nahari Cloudchaser in Thunder Bluff wants 20 Shiny Stones from around the central rise's base. Progress: Did you happen to bring me any shiny stones ?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69983 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3028, ["x"] = 0.5376, ["y"] = 0.4588 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 52657, ["x"] = 0.3584, ["y"] = 0.4868 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.5376, ["y"] = 0.4588 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29355] = { ["id"] = 29355, ["name"] = "Can't Get Enough Spice Bread", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29355 }, ["description"] = "It might seem like a basic thing, <name>, but spice bread is a longtime favorite in Ironforge. Some days, I have trouble keeping up! Would ye like to cook some to practice yer skills an' help meet the demand? Ye can buy all the ingredients ye'll need from me brother, Emrul Riknussun, who is downstairs.", ["objectivesText"] = "Make or obtain 10 slices of Spice Bread . Progress: How's that spice bread ?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 2678, 30816, 30817 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29356] = { ["id"] = 29356, ["name"] = "I Need to Cask a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29356 }, ["description"] = "My stocks o' IPA, that's Ironforge Pale Ale for ye novices, are gettin' low. Luckily, the brewery isn't too far away an' they should have a new cask o' Drugan's IPA waitin' fer us. That Drugan's a genius of a brewer, I tell ye. I won't be able to get down to Kharanos meself today, but perhaps ye can dash down there, pick up the new cask an' run it back 'ere? What d'ye say?", ["objectivesText"] = "Pick up the Cask of Drugan's IPA outside the brewery in Kharanos and run it back to Ironforge. Progress: Well, did ye get the cask or not?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 1973, 2459, 2820, 35581, 43499, 132516 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 5159, ["x"] = 0.601, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29357] = { ["id"] = 29357, ["name"] = "Spice Bread Aplenty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29357 }, ["description"] = "Isn't it amazing how something as simple as spice bread is used every day in Darnassus? When I'm not seeing to my other responsibilities, I like to bake spice bread to hone my skills as a cook and practice my technique. Why don't you give it a try? You should be able to get your ingredients here in the shop. No matter how much we make, it never goes to waste. Bring me your loaves when you're done and I'll have someone share them with our friends, the Gilneans.", ["objectivesText"] = "Make or obtain 10 pieces of Spice Bread . Progress: I just love the smell of baking bread, especially spice bread . Don't you?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 2678, 30816, 30817 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4210, ["x"] = 0.4505, ["y"] = 0.3865 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.4505, ["y"] = 0.3865 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29358] = { ["id"] = 29358, ["name"] = "Pining for Nuts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29358 }, ["description"] = "The Shu'halo use pine nuts in so MANY dishes: meat, fish, vegetables, even baked into breads or sprinkled over sweet pastries. The Earth Mother has blessed us in that the very BEST pine nuts come from the trees upon these very mesas. Simply gather pine cones and toast them over a cooking fire to release the nuts within. Would you please be so kind as to gather some? There are hardly ever enough to go around...", ["objectivesText"] = "Obtain 30 Pine Nuts by toasting Mulgore Pine Cones from Thunder Bluff. Deliver the nuts to Aska Mistrunner in Thunder Bluff. Progress: Have you found many of those tasty pine nuts ?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69988, 69990 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29359] = { ["id"] = 29359, ["name"] = "An Old Favorite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 29359 }, ["description"] = "Herring is one of the most sought-after fish in Darnassus, but not just any herring. The Kaldorei herring is native only to the waters surrounding Teldrassil. I try to keep a good supply of it because it's so versatile! I just finished smoking a batch of it, so I need to rebuild my stocks. Would you mind helping me? You can catch Kaldorei herring by fishing in Rut'theran Village.", ["objectivesText"] = "Catch 8 Kaldorei Herring by fishing in Rut'theran Village. Progress: Did you get those herring?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69987 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 4156, ["x"] = 0.442333, ["y"] = 0.511333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.442333, ["y"] = 0.511333 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard" },
[29360] = { ["id"] = 29360, ["name"] = "Would You Like Some Flies With That?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29360 }, ["description"] = "It's not always about making food for the orcs, <class>. This time, it's about making food for what will hopefully be their replacements. We need to start small, we need to catch flies. Flies love rotting meat, and we love rotting meat... as projectile weapons! Check out the Meat Wagons for any extra bits of meat. Where you find the meat, you'll find the flies. Bring me 25 bloated flies, and then I can start on the next stage of our cooking plan.", ["objectivesText"] = "Obtain 25 Bloated Flies from the \"meat\" near the Meat Wagons. Then return to Eunice Burch in Undercity. Progress: I bet some of that \"meat\" is still good.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 69989 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4552, ["x"] = 0.595429, ["y"] = 0.472571 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.595429, ["y"] = 0.472571 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29361] = { ["id"] = 29361, ["name"] = "Moat Monster!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 29361 }, ["description"] = "Sometimes fishing means throwing something back, <class>. We've been overfeeding these frogs for just that occasion. We've fed these frogs bloated spiders, that were fed bloated flies, and now, we are going to feed a real monster. The moat above, in the Ruins of Lordaeron, is home to our very own moat monster. Today is feeding day. But we must train it as well. In this bag, you will find a decoy kit and some bloated frogs . Use the decoy kit, then toss the frogs to the monster when it appears.", ["objectivesText"] = "Use the Alliance Decoy Kit to summon the Moat Monster in the Ruins of Lordaeron. Then use the Bloated Frogs to feed the monster.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 69995, 69998, 69999 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 4573, ["x"] = 0.7552, ["y"] = 0.3562 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.7552, ["y"] = 0.3562 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29362] = { ["id"] = 29362, ["name"] = "\"Magic\" Mushrooms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29362 }, ["description"] = "You know of the Pools of Vision, yes? There is a sort of mushroom that grows there... not the tough, rank fungi that dominates the place, but smaller, more delicate caps that grow beneath them. They are rare and quite delicious, adding a flavor to meat dishes that one might even call magical. ...what? No, really. They just taste good. That's it.", ["objectivesText"] = "Gather 6 \"Magic\" Mushrooms from the Pools of Vision in Thunder Bluff. Deliver them to Aska Mistrunner in Thunder Bluff. Progress: Were you able to gather any mushrooms?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 69994 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29363] = { ["id"] = 29363, ["name"] = "Mulgore Spice Bread", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29363 }, ["description"] = "I am often asked, \"Aska, who is making all this Mulgore spice bread?!\" It is a reasonable question. Our fine and noble bread is traded in countless settlements in the most far-away lands, even by our staunchest foes. IT'S JUST THAT GOOD. And the answer...? It is \"YOU.\" Please take this packet of Mulgore spices and use it to turn bland, boring spice bread into MULGORE spice bread!", ["objectivesText"] = "Use Mulgore Spices with Spice Bread to create 5 Fresh Mulgore Spice Bread (you may make your own Spice Bread or use someone else's). Deliver the bread to Aska Mistrunner in Thunder Bluff. Progress: Have you baked that Mulgore spice bread, yet?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 30816, 69996, 69997 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29364] = { ["id"] = 29364, ["name"] = "Corn Mash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29364 }, ["description"] = "One of Thunder Bluff's most important staples is cornmeal; bowls of corn may be found in nearly every home. With so many of the local mills under constant attack by harpies, gnolls, reckless mining companies and Earth Mother knows what else, I often ask my students to help with the task of grinding corn into cornmeal. Would you care to help?", ["objectivesText"] = "Help the inhabitants of Thunder Bluff make cornmeal by pounding bowls of Corn Kernels .", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29365] = { ["id"] = 29365, ["name"] = "Perfectly Picked Portions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 29365 }, ["description"] = "Even the novice cook knows that a great dish begins with great ingredients. I have standing orders with merchants throughout Thunder Bluff, but I'd like to see how well you do at selecting the very best of what they have to offer. Please make the rounds and gather perfect portions of meat, fish, vegetables and herbs from local merchant stalls.", ["objectivesText"] = "Obtain four \"perfect portions\" from merchant stalls around Thunder Bluff. Deliver the ingredients to Aska Mistrunner in Thunder Bluff. Progress: Have you gathered all the necessary ingredients?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 70000, 70001, 70002, 70003 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3026, ["x"] = 0.492, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[29371] = { ["id"] = 29371, ["name"] = "A Time to Lose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 29371 }, ["description"] = "Well met, <class>. As we attempt to embrace the Wickerman ceremony, it is no surprise that the Horde would attempt to ruin our celebration. Now the prudent course of action may be to rise above the conflict and simply ignore the attacks. I admire those that take that high road, but I cannot help them. But for those that seek to strike back... I can help them. If you are interested, <class>, take this Dousing Agent and use it on the Horde's Wickerman in the Ruins of Lordaeron.", ["objectivesText"] = "Use the Dousing Agent on the Wickerman in the Ruins of Lordaeron. Progress: Have you extinguished the Horde's Wickerman, <class>?", ["rewardXP"] = 710, ["rewardItems"] = { 33176, 33226, 37011, 65360, 68648, 69191, 80585, 90078, 119093, 132120, 211788 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 52064, ["x"] = 0.456, ["y"] = 0.679 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 52064, ["x"] = 0.456, ["y"] = 0.679 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.679 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29372] = { ["id"] = 29372, ["name"] = "Trouble in Podunk", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["storyline"] = { 29372 }, ["description"] = "Outlaws have kidnapped the sheriff!", ["objectivesText"] = "Rescue the sheriff.", ["rewardGold"] = 94000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[29373] = { ["id"] = 29373, ["name"] = "Trouble in Podunk", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4922, ["storyline"] = { 29373 }, ["description"] = "We never paid no heed to Sheriff Blundy, what with his gettin' all up-in-arms at all times 'bout his \"laws\" and his \"mis-de-meanors.\" But them dirty ol' McClintocks, and their cattle-rustlin' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin' and dead-or-alive-wantin', and come this past week they done took the law into their own hands - in the most literal of senses - by haulin' up and hi-jackin' the good Sheriff. As you can see, our humble", ["objectivesText"] = "Rescue the sheriff.", ["rewardGold"] = 94000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[29374] = { ["id"] = 29374, ["name"] = "Stink Bombs Away!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 29374 }, ["description"] = "The foolish Alliance have employed hags to fuel an attack on our city. Well, as my sister once told me, \"Turnabout is fair play.\" We will gladly return the favor. Speak with my sister, and she will provide you with a broomstick flight over Stormwind. While over Stormwind, drop stink bombs on the city and on the people. Make them suffer! We will show those hags in Stormwind who is the most powerful.", ["objectivesText"] = "Speak with Crina Fenlow and take a broomstick flight over Stormwind city. Use the stink bombs to cover the city and its people. Progress: The magic those hags in Stormwind use is no match for our magic, <class>.", ["rewardXP"] = 1060, ["rewardItems"] = { 33226, 69191 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 53763, ["x"] = 0.624, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 53763, ["x"] = 0.624, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29375] = { ["id"] = 29375, ["name"] = "Clean Up in Undercity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 29375 }, ["description"] = "Greetings, <class>! Are you enjoying Hallow's End? It seems that in response to our stink bombing Stormwind, the Alliance has decided to stink bomb our city. Fortunately, we have magics that can handle the stink the Alliance bring us. Use this Arcane Cleanser to remove the stink bombs from the city.", ["objectivesText"] = "Use the Arcane Cleanser to remove stink bombs within the Undercity. Progress: Arcane magic... Works every time.", ["rewardXP"] = 1060, ["rewardItems"] = { 33226, 70727 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 53763, ["x"] = 0.624, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 53763, ["x"] = 0.624, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29376] = { ["id"] = 29376, ["name"] = "A Time to Build Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 29376 }, ["series"] = { 29400, 53122 }, ["description"] = "We burn the effigy of the Wickerman as a symbol of our struggle against those who would oppose us. We wear the ashes of the burnt Wickerman as a symbol of our neverending fight against those who would enslave us. Use the bonfire nearby and ignite the Wickerman. Then take the ashes that lay nearby and spread them across your face. These gestures will serve as a reminder to our enemies that we shall never yield.", ["objectivesText"] = "Use the bonfire in front of the Wickerman to set it ablaze. Use the ashes on the ground near the Wickerman. Progress: This is the night that our enemies fear us the most, <class>.", ["rewardXP"] = 710, ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 15197, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 15197, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29377] = { ["id"] = 29377, ["name"] = "A Time to Break Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 29377 }, ["description"] = "Well met, <class>. As we revel in the Wickerman ceremony, it comes as no surprise that the Alliance would attempt to ruin our celebration. We have an opportunity to make them pay. If you are interested, <class>, take this Dousing Agent and use it on the Alliance's Wickerman in front of Stormwind. Extinguish their flame and revel in their misery, <class>.", ["objectivesText"] = "Use the Dousing Agent on the Wickerman in front of Stormwind. Progress: Have you extinguished the Alliance's Wickerman, <class>?", ["rewardXP"] = 710, ["rewardItems"] = { 33226, 68647 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 15197, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 15197, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[29382] = { ["id"] = 29382, ["name"] = "Thanks, But No Thanks", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29382 }, ["description"] = "A holiday sweater may not be for everyone. The receipt says that you can exchange it for gold at any Smokywood Pastures merchant. All exchanges are final.", ["objectivesText"] = "If you truly dislike your present, you can exchange it for gold by speaking to a Smokywood Pastures merchant. All exchanges are final.", ["rewardGold"] = 619600, ["rewardXP"] = 150, ["rewardItems"] = { 10048, 70923, 70928, 70931, 70932, 206960, 248618 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 70928 } },
[29383] = { ["id"] = 29383, ["name"] = "Thanks, But No Thanks", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29383 }, ["description"] = "A holiday sweater may not be for everyone. The receipt says that you can exchange it for gold at any Smokywood Pastures merchant. All exchanges are final.", ["objectivesText"] = "If you truly dislike your present, you can exchange it for gold by speaking to a Smokywood Pastures merchant. All exchanges are final.", ["rewardGold"] = 619600, ["rewardXP"] = 150, ["rewardItems"] = { 70923, 70931, 70932, 206960, 248618 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 70932 } },
