[29387] = { ["id"] = 29387, ["name"] = "Guardians of Hyjal: Firelands Invasion!", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 198, ["storyline"] = { 29387 }, ["series"] = { 29145, 29195, 29196, 29197, 29198, 29388, 29389, 29390 }, ["description"] = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands. Willing and able-bodied heroes of the Alliance should report to the Sanctuary of Malorne in Mount Hyjal immediately.", ["objectivesText"] = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29388] = { ["id"] = 29388, ["name"] = "Guardians of Hyjal: Firelands Invasion!", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 198, ["storyline"] = { 29388 }, ["series"] = { 29145, 29195, 29196, 29197, 29198, 29387, 29389, 29390 }, ["description"] = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands. Willing and able-bodied champions of the Horde should report to the Sanctuary of Malorne in Mount Hyjal immediately.", ["objectivesText"] = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29389] = { ["id"] = 29389, ["name"] = "Guardians of Hyjal: Firelands Invasion!", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29389 }, ["series"] = { 29145, 29195, 29196, 29197, 29198, 29387, 29388, 29390 }, ["description"] = "Your work has given us the advantage we need to mobilize against the denizens of the Firelands. We are gathering our invasion force just south of our position. We could use your strength again, <race>. Speak with Matoclaw at the Sanctuary of Malorne. She is coordinating the invasion effort.", ["objectivesText"] = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52838, ["x"] = 0.238, ["y"] = 0.495714 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52669, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.495714 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29390] = { ["id"] = 29390, ["name"] = "Guardians of Hyjal: Call of the Ancients", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["storyline"] = { 29390 }, ["series"] = { 29145, 29195, 29196, 29197, 29198, 29387, 29388, 29389 }, ["description"] = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands. Willing and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Lo'gosh, Tortolla, Aviana, and Aessina. New travelers to Mount Hyjal may look for a Warchief's Command to Hyjal on any Horde call board.", ["objectivesText"] = "Assist Lo'gosh, Tortolla, Aviana, and Aessina in Mount Hyjal.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29392] = { ["id"] = 29392, ["name"] = "Missing Heirlooms", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29392 }, ["series"] = { 29398, 29399, 29402, 29403, 29411 }, ["description"] = "The last of my belongings were supposed to be arriving from Theramore today. The ship has arrived, but I haven't heard from the courier. The crate he was transporting had items that've been in my family for generations. Will you go down to Stormwind Harbor and see what's keeping him?", ["objectivesText"] = "Search the cabin of the Hired Courier 's ship in Stormwind Harbor for evidence of what might be delaying him. Progress: The crate that Anson described doesn't appear to be here...", ["rewardXP"] = 150, ["rewardItems"] = { 20492 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 53949, ["x"] = 0.526, ["y"] = 0.5585 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 53950, ["x"] = 0.202, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.5585 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29394] = { ["id"] = 29394, ["name"] = "Brew For Brewfest", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 29394 }, ["objectivesText"] = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", ["rewardGold"] = 234000, ["rewardXP"] = 200, ["rewardItems"] = { 33030, 33031, 33034, 33306, 34017, 34020, 37829, 44235, 117393 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 23558, ["x"] = 0.5196, ["y"] = 0.4284 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23558, ["x"] = 0.5196, ["y"] = 0.4284 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.5196, ["y"] = 0.4284 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[29396] = { ["id"] = 29396, ["name"] = "A New Supplier of Souvenirs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 29396 }, ["description"] = "<sigh> Don't talk to me about last year's stein... I think our shady stein suppliers were somehow involved with that Twilight Hammer cult non-sense that errupted just before the elementals invaded. And that's why we have a new supplier and a better stein! Here's a voucher for one. Talk to Blix near the back of the Brewfest camp. He's pretty strange, even more so now that he's always wearing those goggles. He'll handle the voucher for you, and any other Brewfest transaction.", ["objectivesText"] = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp. Progress: What's happening hot stuff? Got something for me?", ["rewardItems"] = { 33955, 56836 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 24510, ["x"] = 0.425333, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24495, ["x"] = 0.5076, ["y"] = 0.2316 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.425333, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[29397] = { ["id"] = 29397, ["name"] = "A New Supplier of Souvenirs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 3, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 29397 }, ["description"] = "The less said about last year's stein, the better, <name>. I'll tell you this, our previous supplier, they were shady. Turns out they were involved in some cultist activities... We can't work with people who are trying to destroy the world!! So we have a new supplier and a new stein. Take this voucher to Belbi Quikswitch near the back of the Brewfest camp. She'll give you your free Brewfest stein. She'll also handle any and all other Brewfest transactions that come up during the holiday.", ["objectivesText"] = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp. Progress: What's happening hot stuff? Got something for me?", ["rewardItems"] = { 33955, 56836 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24468, ["x"] = 0.5196, ["y"] = 0.4284 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23710, ["x"] = 0.5365, ["y"] = 0.4275 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.5196, ["y"] = 0.4284 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[29398] = { ["id"] = 29398, ["name"] = "Fencing the Goods", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29398 }, ["series"] = { 29392, 29399, 29402, 29403, 29411 }, ["description"] = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished. As you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", ["objectivesText"] = "Follow the spiders to their destination and question the man you find there. Progress: Why are you still pestering me?", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 53950, ["x"] = 0.202, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 8719, ["x"] = 0.612, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29399] = { ["id"] = 29399, ["name"] = "Shopping Around", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29399 }, ["series"] = { 29392, 29398, 29402, 29403, 29411 }, ["description"] = "I told the 'gentleman' that there might be a shop more suited to his needs in the Dwarven District. It's called the Shady Lady and you can find the entrance near the Canals on the western side of the district. Quincy Cutler is your man. He trades in merchandise an honest broker would never touch!", ["objectivesText"] = "Make your way to the Shady Lady in Stormwind's Dwarven District and look for evidence of the crate-thief's visit. Progress: You look like you know something about these missing goods.", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 8719, ["x"] = 0.612, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 54021, ["x"] = 0.641333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29400] = { ["id"] = 29400, ["name"] = "A Season for Celebration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 94, ["storyline"] = { 29400 }, ["series"] = { 29376, 53122 }, ["description"] = "Well met, <class>. Hallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken. Travel to the Ruins of Lordaeron and speak to Darkcaller Yanka . She can tell you more about the Wickerman ceremony.", ["objectivesText"] = "Speak with Darkcaller Yanka in the Ruins of Lordaeron.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 19169, ["x"] = 0.542, ["y"] = 0.508 }, { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19176, ["x"] = 0.402, ["y"] = 0.5615 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 90, ["npcID"] = 19178, ["x"] = 0.648923, ["y"] = 0.442154 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 15197, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 10, 18, 85, 90, 94, 2339 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29401] = { ["id"] = 29401, ["name"] = "Blown Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29401 }, ["description"] = "Please, <mister/miss>, you just gotta help me! My pa brought me a bunch of balloons from the Darkmoon Faire. Best... gift... EVER! They're magical, you know, and never lose their floatiness! There's just one thing... A big ol' gust of wind blew 'em right outta my hands. They're scattered all over Orgrimmar ! I'd chase after 'em myself, but this city's so big I'd get lost for sure. Can you round 'em up for me before they float away? Please?", ["objectivesText"] = "Jaga wants you to collect 5 Windswept Balloons from Orgrimmar . Progress: Did you find all of my balloons, mister?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 71034, 72042, 72045 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 54004, ["x"] = 0.4815, ["y"] = 0.4705 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54004, ["x"] = 0.4815, ["y"] = 0.4705 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.4815, ["y"] = 0.4705 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29402] = { ["id"] = 29402, ["name"] = "Taking Precautions", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29402 }, ["series"] = { 29392, 29398, 29399, 29403, 29411 }, ["description"] = "I'd be wary of anyone identifying himself as the rightful owner of the crate and its contents. He didn't warn you of the danger? Here's a better idea: let's work together to recover the crate and ensure that its contents can't hurt anyone. To protect ourselves, we're going to need a draught made from a few ingredients that can be found around the city. Acquire some strange dust , get vials from an alchemy merchant, and pick some blood nettle from the fields north of the city.", ["objectivesText"] = "Obtain 2 Strange Dust , 5 Crystal Vials , and 5 Blood Nettle . Progress: Did you get all the ingredients?", ["rewardXP"] = 200, ["rewardItems"] = { 3371, 3819, 10940, 44235, 71035 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 54021, ["x"] = 0.641333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 54021, ["x"] = 0.641333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.641333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29403] = { ["id"] = 29403, ["name"] = "The Collector's Agent", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29403 }, ["series"] = { 29392, 29398, 29399, 29402, 29411 }, ["description"] = "According to Quincy, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara. The archmage's faithful servant is to meet with the man who has the crate in the catacombs beneath the Cathedral of Light. You must get there in time to intercept the exchange and retrieve the crate before it is lost to Xylem forever. When you have the crate, meet me at the Golden Keg.", ["objectivesText"] = "Disrupt the meeting between Sanath Lim-yo and the thief in the catacombs beneath the Cathedral of Light.", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 54021, ["x"] = 0.641333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.641333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29411] = { ["id"] = 29411, ["name"] = "What Now?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29411 }, ["series"] = { 29392, 29398, 29399, 29402, 29403 }, ["description"] = "You've finally found the crate that Anson sent you to retrieve. However, it appears the archaeology student's warnings about the nature of the crate's contents were correct. There's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Hudson Barnes , who believes it better to keep the crate's contents locked away?", ["objectivesText"] = "Return the crate to Anson Hastings at the Gilded Rose in Stormwind. -OR- Return the crate to Hudson Barnes at the Golden Keg in Stormwind. Progress: Have you brought the crate as we discussed?", ["rewardXP"] = 150, ["rewardItems"] = { 71057, 71076 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 53949, ["x"] = 0.526, ["y"] = 0.5585 }, { ["mapID"] = 84, ["npcID"] = 54118, ["x"] = 0.65, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.5585 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29412] = { ["id"] = 29412, ["name"] = "Blown Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29412 }, ["description"] = "Please, <mister/miss>, you just gotta help me! Father bought me a bunch of balloons from the Darkmoon Faire. They're magical, you know, and never lose their floatiness! There's just one thing... A gust of wind blew them out of my hands. They're scattered all over Stormwind! I'd chase after them myself, but this city's so big I'd get lost for sure. Can you find them for me before they float away? Please?", ["objectivesText"] = "Vin wants you to collect 5 Windswept Balloons from Stormwind. Progress: Did you find all of my balloons, mister?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 71034, 72042, 72045 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 54117, ["x"] = 0.5855, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 54117, ["x"] = 0.5855, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5855, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29413] = { ["id"] = 29413, ["name"] = "The Creepy Crate", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["storyline"] = { 29413 }, ["description"] = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him. Yet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive. It seems bonded to you and now it's yours.", ["rewardXP"] = 200, ["rewardItems"] = { 71076 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29415] = { ["id"] = 29415, ["name"] = "Missing Heirlooms", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29415 }, ["series"] = { 29416, 29425, 29426, 29427, 29428 }, ["description"] = "I told that courier to take the zeppelin, but no, he had to use the goblin ship! Well, now he's late and my precious family heirlooms are with him. If you're willing to help, would you go down to the docks east of Orgrimmar, board the goblin ship and see what's keeping him?", ["objectivesText"] = "Search the cabin of the Hired Courier 's ship at the docks east of Orgrimmar for evidence of what might be delaying him.", ["rewardXP"] = 150, ["rewardItems"] = { 3371, 10940, 71035 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 54141, ["x"] = 0.620571, ["y"] = 0.492571 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 54142, ["x"] = 0.715, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.620571, ["y"] = 0.492571 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29416] = { ["id"] = 29416, ["name"] = "Fencing the Goods", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 29416 }, ["series"] = { 29415, 29425, 29426, 29427, 29428 }, ["description"] = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished. As you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", ["objectivesText"] = "Follow the spiders to their destination and question the man you find there. Progress: Why are you still pestering me?", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 54142, ["x"] = 0.715, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 44866, ["x"] = 0.539, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[29425] = { ["id"] = 29425, ["name"] = "Shopping Around", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29425 }, ["series"] = { 29415, 29416, 29426, 29427, 29428 }, ["description"] = "Look, I told that shady character that there might be a shop more open to his, uh, wares in the Drag. Droffer's and Son Salvage is the name of the place. Look for Dran Droffers. He oversees the 'salvage' of rare and valuable objects from all over Azeroth.", ["objectivesText"] = "Make your way to Droffers and Son Salvage in Orgrimmar's Drag district and look for evidence of the crate-thief's visit. Progress: You look like you know something about these missing goods.", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 44866, ["x"] = 0.539, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54146, ["x"] = 0.576667, ["y"] = 0.485333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29426] = { ["id"] = 29426, ["name"] = "Taking Precautions", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29426 }, ["series"] = { 29415, 29416, 29425, 29427, 29428 }, ["description"] = "So someone else hired you to retrieve this crate? I don't like the sound of that. That crate's contents belong in the care of the Reliquary. The items it holds are very powerful and very dangerous. We have to find the meeting that Dran set up between the thief and the collector, but first, we'll need to protect ourselves from the effects of handling that crate. Acquire some strange dust , get vials from an alchemy merchant, and pick some blood nettle in the Valley of Wisdom.", ["objectivesText"] = "Obtain 2 Strange Dust , 5 Crystal Vials , and 5 Blood Nettle . Progress: Did you get all the ingredients?", ["rewardXP"] = 200, ["rewardItems"] = { 3371, 10940, 44234, 71035 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 54146, ["x"] = 0.576667, ["y"] = 0.485333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54146, ["x"] = 0.576667, ["y"] = 0.485333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.576667, ["y"] = 0.485333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29427] = { ["id"] = 29427, ["name"] = "The Collector's Agent", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 85, ["mapID"] = 85, ["storyline"] = { 29427 }, ["series"] = { 29415, 29416, 29425, 29426, 29428 }, ["description"] = "According to Dran, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara. The archmage's faithful servant is to meet with the man who has the crate in a secluded corner of the courtyard in the Ruins of Lordaeron. Quickly, take the zeppelin to Tirisfal Glade! You must get there in time to intercept the exchange and retrieve the crate before Xylem gets his hands on it. If you can get the crate, meet me at the Wyvern's Tail in the Valley of Honor.", ["objectivesText"] = "Disrupt the meeting between Sanath Lim-yo and the thief in the Ruins of Lordaeron. Progress: This appears to be the sought-after crate.", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 54146, ["x"] = 0.576667, ["y"] = 0.485333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.576667, ["y"] = 0.485333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[29428] = { ["id"] = 29428, ["name"] = "What Now?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29428 }, ["series"] = { 29415, 29416, 29425, 29426, 29427 }, ["description"] = "You've finally found the crate that Edgar Goodwin sent you to retrieve. However, it appears the Reliquary representative's warnings about the nature of the crate's contents were correct. There's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Delian Sunshade , who believes it better to keep the crate's contents locked away?", ["objectivesText"] = "You may return the crate to either Edgar Goodwin at the Broken Tusk in Orgrimmar's Valley of Strength. -OR- Return the crate to Delian Sunshade at the Wyvern's Tail in Orgrimmar's Valley of Honor. Progress: Have you brought the crate as we discussed?", ["rewardXP"] = 150, ["rewardItems"] = { 35223, 71057, 71076 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54141, ["x"] = 0.620571, ["y"] = 0.492571 }, { ["mapID"] = 85, ["npcID"] = 54170, ["x"] = 0.715, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.620571, ["y"] = 0.492571 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29429] = { ["id"] = 29429, ["name"] = "The Creepy Crate", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["storyline"] = { 29429 }, ["description"] = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him. Yet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive. It seems bonded to you and now it's yours.", ["rewardXP"] = 200, ["rewardItems"] = { 3371, 10940, 71035, 71076 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29430] = { ["id"] = 29430, ["name"] = "A Friend in Need", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 29430 }, ["description"] = "You know, I haven't seen Anson out here yet. Lately, he's been spending all his time drinking himself into a stupor at the Gilded Rose. Something must really be bothering him! Would you mind checking in on him?", ["objectivesText"] = "Visit Anson Hastings at the Gilded Rose in Stormwind's Trade District.", ["rewardGold"] = 77400, ["rewardXP"] = 25, ["rewardItems"] = { 168847, 169908, 169910 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 51934, ["x"] = 0.557333, ["y"] = 0.775667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 53949, ["x"] = 0.526, ["y"] = 0.5585 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.557333, ["y"] = 0.775667 }, ["mapCandidates"] = { ["npc"] = { 37, 84 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[29431] = { ["id"] = 29431, ["name"] = "A Friend in Need", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 3, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 29431 }, ["description"] = "There's something wrong with my friend, Edgar. Normally, he loves the Hallow's End festivities, but he's been sullen and reclusive lately. He spends all his time in the Broken Tusk in Orgrimmar drinking with the orcs. Would you mind stopping by and seeing if there's anything you can do to cheer him up?", ["objectivesText"] = "Speak with Edgar Goodwin at the Broken Tusk in Orgrimmar.", ["rewardGold"] = 77400, ["rewardXP"] = 25, ["rewardItems"] = { 168847, 169908, 169910 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 53763, ["x"] = 0.624, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54141, ["x"] = 0.620571, ["y"] = 0.492571 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18, 85 }, ["zone"] = { 1497 } }, ["questType"] = "standard" },
[29432] = { ["id"] = 29432, ["name"] = "Delegation Tracker", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29432 }, ["series"] = { 29193, 29194, 29225, 29234, 29239, 30119 }, ["description"] = "I am duty-bound to look into your claims immediately, <race>, which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the world tree's branch.", ["objectivesText"] = "Recover the Branch of Nordrassil from the Firelands.", ["rewardGold"] = 282000, ["rewardXP"] = 1110, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "raid" },
[29433] = { ["id"] = 29433, ["name"] = "Test Your Strength", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29433 }, ["description"] = "For some people, it's all fun and games until someone gets hurt. I call those people, weak. To be the strongest, you have to hurt someone or something. You hurt yourself as you push your body to its limits. You hurt those that threaten the well-being of others. If you want to be the strongest, you have to fight. How bad do you want it? I want you to crush those that would offer a challenge to you, then bring me back proof of your triumphs.", ["objectivesText"] = "Kerri Hicks wants you to collect 250 Grisly Trophies . Trophies are obtained as long as you kill creatures that offer experience or honor and you have the Darkmoon Adventurer's Guide with you. Progress: No pain, no gain.", ["rewardItems"] = { 2589, 33385, 33412, 33416, 33429, 33431, 33445, 33447, 33448, 33470, 37091, 37093, 37254, 41599, 43297, 43467, 43508, 43851, 43852, 49655, 49661, 52976, 58488, 62289, 67333, 67539, 68781, 71096, 71634, 132444, 132466, 153041, 223153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29434] = { ["id"] = 29434, ["name"] = "Tonk Commander", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29434 }, ["description"] = "Welcome to our humble little steam tank battle simulator! For one token, you can demonstrate your tactical mastery by navigating the course and destroying the targets.", ["objectivesText"] = "Use your Darkmoon Tonk to destroy 30 Tonk Targets in the time allowed. Progress: Have tonk, will travel!", ["rewardItems"] = { 40110, 71083, 78909, 93724, 122122 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29436] = { ["id"] = 29436, ["name"] = "The Humanoid Cannonball", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29436 }, ["description"] = "For just one Darkmoon Game Token, you can ride the Blastenheimer 5000 Ultra Cannon. But the fun doesn't end there! We've placed a target in the water near the boardwalk. If you can score five points from your landing, you can win some prize tickets! A bullseye gets you five points, a close shot three, and landing at least near it gets you one. Happy landings!", ["objectivesText"] = "Accumulate 5 Cannon Target Points by landing near the target. Progress: Happy landings!", ["rewardItems"] = { 8827, 71083, 78909, 93724, 109076, 168648 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29437] = { ["id"] = 29437, ["name"] = "The Fallen Guardian", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29437 }, ["description"] = "Fandral Staghelm was kept prisoner here in Hyjal. It was the green dragon Alysra - one of my very own! - who was in charge of keeping Fandral secure. We can only conclude that the Twilight's Hammer has gotten to her. You must confront her, <name>. Destroy her if you must - I cannot bear to see it. She was last seen in the Ruins of Lar'donir, west of the World Tree.", ["objectivesText"] = "Confront and slay Alysra at the Ruins of Lar'donir in Mount Hyjal .", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40289, ["x"] = 0.62, ["y"] = 0.248 }, { ["mapID"] = 198, ["npcID"] = 52793, ["x"] = 0.602, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29438] = { ["id"] = 29438, ["name"] = "He Shoots, He Scores!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29438 }, ["description"] = "Think you're a good shot? Quick on the trigger? It'll cost you just a single game token to test your skills. What do you say? How good are you?", ["objectivesText"] = "Score 25 points in 60 seconds. Progress: Shooting static targets isn't always as easy at it seems.", ["rewardItems"] = { 1973, 35275, 44228, 71083, 71086, 71259, 78909, 93724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29439] = { ["id"] = 29439, ["name"] = "The Call of the World-Shaman", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29439 }, ["series"] = { 29326, 29327, 29335, 29440 }, ["description"] = "The Earthen Ring calls to you once more, <name>. As a member of the Alliance, I know that you may have reservations working with the one you call Thrall , the former Warchief of the Horde. But he has specifically requested an Alliance hero to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world. Cast aside your doubts, <class>, and heed the world-shaman's call. You will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree.", ["objectivesText"] = "Speak with Thrall just south of the World Tree in Mount Hyjal.", ["rewardXP"] = 2395, ["rewardItems"] = { 71267, 71268, 71269, 71270 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 45226, ["x"] = 0.745, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 54313, ["x"] = 0.605333, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.745, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 84, 198 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29440] = { ["id"] = 29440, ["name"] = "The Call of the World-Shaman", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29440 }, ["series"] = { 29326, 29327, 29335, 29439 }, ["description"] = "The Earthen Ring calls to you once more, <name>. Thrall has cast aside his mantle as warchief of the Horde, but in his new role he needs the support of his people more than ever. He has requested one of the Horde's finest to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world. You will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree. Heed the call!", ["objectivesText"] = "Speak with Thrall just south of the World Tree in Mount Hyjal.", ["rewardXP"] = 2395, ["rewardItems"] = { 71267, 71268, 71269, 71270 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 54313, ["x"] = 0.605333, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.469714, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 85, 198 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29441] = { ["id"] = 29441, ["name"] = "From the Belly of the Beast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 130, ["storyline"] = { 29441 }, ["rewardGold"] = 619600, ["rewardXP"] = 925, ["rewardItems"] = { 61506, 61507, 61508, 62886, 62887, 62888, 131679 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 130 } }, ["questType"] = "standard" },
[29443] = { ["id"] = 29443, ["name"] = "A Curious Crystal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5956, ["storyline"] = { 29443 }, ["description"] = "Power swirls inside this strange crystal. Perhaps it was once a magical focus, an energy source, or simply a good luck charm. There's no way to know for certain. The Darkmoon Adventurer's Guide indicates that the crystal would be of interest to Professor Thaddeus Paleo at the Darkmoon Faire.", ["objectivesText"] = "Bring the Imbued Crystal to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island. Progress: What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5956 } }, ["questType"] = "standard", ["startItems"] = { 71635 } },
[29444] = { ["id"] = 29444, ["name"] = "An Exotic Egg", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5963, ["storyline"] = { 29444 }, ["description"] = "You're not certain what kind of creature this egg harbors, but it sure doesn't look like the egg of any ordinary animal. The Darkmoon Adventurer's Guide says that an intrepid adventurer might come across any number of strange eggs in his travels. It further notes that the Darkmoon Faire's Zoo Bizarre is always interested in acquiring such specimens. Take the egg to Yebb Neblegear at the Darkmoon Faire.", ["objectivesText"] = "Bring the Monstrous Egg to Yebb Neblegear at the Darkmoon Faire on Darkmoon Island. Progress: What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5963 } }, ["questType"] = "standard", ["startItems"] = { 71636 } },
[29445] = { ["id"] = 29445, ["name"] = "An Intriguing Grimoire", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5844, ["storyline"] = { 29445 }, ["description"] = "This massive spellbook reveals very little of its origins. Its pages are filled with a variety of spells and enchantments, only a few of which are familiar. The Darkmoon Adventurer's Guide says the tome may be of some interest to Sayge , the famous gnoll fortuneteller at the Darkmoon Faire.", ["objectivesText"] = "Bring the Mysterious Grimoire to Sayge at the Darkmoon Faire on Darkmoon Island. Progress: What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 19338, 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5844 } }, ["questType"] = "standard", ["startItems"] = { 71637 } },
[29446] = { ["id"] = 29446, ["name"] = "A Wondrous Weapon", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5844, ["storyline"] = { 29446 }, ["description"] = "An inspection of the weapon reveals expert craftsmanship and intricate inlay work, but this is no ceremonial blade. Faint marks and nicks along the blade attest to its use in combat. The Darkmoon Adventurer's Guide lists several types of rare and valuable weapons, leaving no doubt that Professor Thaddeus Paleo at the Darkmoon Faire would be interested in taking a look at this piece.", ["objectivesText"] = "Bring the Ornate Weapon to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island. Progress: What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5844 } }, ["questType"] = "standard", ["startItems"] = { 71638 } },
[29451] = { ["id"] = 29451, ["name"] = "The Master Strategist", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5956, ["storyline"] = { 29451 }, ["description"] = "This tome of strategy is the masterwork of the famous human general, Anduin Lothar. In his own words, the commander describes the proper deployment of forces and strategies needed to win almost any battle. Professor Thaddeus Paleo of the Darkmoon Faire would probably love to have a look at such a rare book.", ["objectivesText"] = "Take A Treatise on Strategy to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island. Progress: That doesn't look like a common book at all...", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5956 } }, ["questType"] = "standard", ["startItems"] = { 71715 } },
[29452] = { ["id"] = 29452, ["name"] = "Your Time Has Come", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29452 }, ["series"] = { 29129, 29132, 29134, 29135, 29453 }, ["description"] = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.> Young <class>, be still and hear my words. I am called to collect you, to deliver you, to one whose eye none can escape. Find me in Orgrimmar, mortal, for your time has come.", ["objectivesText"] = "Speak to Ziradormi in Orgrimmar.", ["rewardGold"] = 140450, ["rewardXP"] = 2395, ["rewardItems"] = { 65893, 71086, 71141 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 52382, ["x"] = 0.486667, ["y"] = 0.707333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.486667, ["y"] = 0.707333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[29453] = { ["id"] = 29453, ["name"] = "Your Time Has Come", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29453 }, ["series"] = { 29129, 29132, 29134, 29135, 29452 }, ["description"] = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.> Young <class>, be still and hear my words. I am called to collect you, to deliver you, to one whose eye none can escape. Find me in Stormwind, mortal, for your time has come.", ["objectivesText"] = "Speak to Coridormi inside the Mage Quarter's Wizard's Sanctum at Stormwind City.", ["rewardGold"] = 140450, ["rewardXP"] = 2395, ["rewardItems"] = { 18715, 65893, 71086, 71141 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 52408, ["x"] = 0.4885, ["y"] = 0.884 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4885, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29455] = { ["id"] = 29455, ["name"] = "Target: Turtle", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29455 }, ["description"] = "Hey there! Step right up ! Why not show everyone how skilled you are? Just land three rings on the Darkmoon Turtle and you'll get a prize. For one game token you can buy a stack of rings and show the world why we call you the \"Eagle Eyed <class>.\"", ["objectivesText"] = "Land 3 rings on the Darkmoon Turtle. Progress: How's that throwin' arm, champ?", ["rewardItems"] = { 71083, 71950, 78909, 93724, 122123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29456] = { ["id"] = 29456, ["name"] = "A Captured Banner", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 10440, ["storyline"] = { 29456 }, ["description"] = "This tattered banner bears a faded guild crest. This old banner must've seen more than its share of battles. Professor Thaddeus Paleo of the Darkmoon Faire collects banners and other relics of combat and he might be interested in acquiring this one. Show the banner to him next time you visit the Darkmoon Faire.", ["objectivesText"] = "Bring the Banner of the Fallen to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island. Progress: What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10440 } }, ["questType"] = "standard", ["startItems"] = { 71951 } },
[29457] = { ["id"] = 29457, ["name"] = "The Enemy's Insignia", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 10440, ["storyline"] = { 29457 }, ["description"] = "This battered badge carries the insignia of an enemy officer. While worth little more to you than the metal it's made from, this piece would have significant value to a collector of military memorabilia. Professor Thaddeus Paleo of the Darkmoon Faire is famous all over Azeroth for his large collection of military artifacts. Show the badge to him the next time you visit the Darkmoon Faire.", ["objectivesText"] = "Bring the Captured Insignia to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island. Progress: What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10440 } }, ["questType"] = "standard", ["startItems"] = { 71952 } },
[29458] = { ["id"] = 29458, ["name"] = "The Captured Journal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 10440, ["storyline"] = { 29458 }, ["description"] = "This book is covered in battered leather stained with blood and mud. Leafing through the pages, you discover that it is a personal journal of an adventurer with a high opinion of himself and his adventures. Professor Thaddeus Paleo of the Darkmoon Faire might want to see something like this.", ["objectivesText"] = "Bring the Adventurer's Journal to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island. Progress: What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10440 } }, ["questType"] = "standard", ["startItems"] = { 71953 } },
[29463] = { ["id"] = 29463, ["name"] = "It's Hammer Time", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29463 }, ["description"] = "So you want to whack some gnolls? Well you've come to the right place. Your goal is simple, score 30 points in a minute. Use the mallet I give you and get ready to whack. Speak to me when you are ready to start.", ["objectivesText"] = "Score 30 points by whacking Gnolls. Progress: How did you do out there?", ["rewardGold"] = 140450, ["rewardXP"] = 1045, ["rewardItems"] = { 34008, 71083, 78909, 93724, 133576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29464] = { ["id"] = 29464, ["name"] = "Tools of Divination", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5892, ["storyline"] = { 29464 }, ["description"] = "This collection of well-worn runestones has seen much use. The pieces seem old; you can't recognize any of the markings on their surfaces. Perhaps a scholar or a collector would know more about them. Bring them to Professor Thaddeus Paleo next time you're at the Darkmoon Faire.", ["objectivesText"] = "Bring the Soothsayer's Runes to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island. Progress: What do you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 71634, 71635, 71636, 71637, 71638, 71715, 71716, 71951, 71952, 71953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5892 } }, ["questType"] = "standard", ["startItems"] = { 71716 } },
[29477] = { ["id"] = 29477, ["name"] = "Gnomish Engineering", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 29477 }, ["description"] = "A skilled engineer can choose ONE specialization, and I can teach you the ways of gnomish engineering. You look like you know what you're doing, but I'll need some samples of your work. Bring me six mithril tubes , an accurate scope , and two advanced target dummies. Submit these items to an engineering trainer in any of the capital cities and you'll be an official gnomish engineer with access to all the schematics!", ["objectivesText"] = "Bring 6 Mithril Tubes , an Accurate Scope , and 2 Advanced Target Dummies to an engineering trainer in any capital city. Progress: Once I receive your crafted engineering items for my review, you can become a certified gnomish engineer , granting you unlimited access to gnomish engineer schematics.", ["rewardXP"] = 2125, ["rewardItems"] = { 1529, 2319, 2592, 2841, 3575, 3577, 3860, 3864, 4234, 4392, 4407, 10559, 18984, 18986, 30542, 30544, 87250, 87251 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 5174, ["x"] = 0.6844, ["y"] = 0.4436 }, { ["mapID"] = 84, ["npcID"] = 5518, ["x"] = 0.626333, ["y"] = 0.319333 }, { ["mapID"] = 85, ["npcID"] = 11017, ["x"] = 0.566, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 5518, ["x"] = 0.626333, ["y"] = 0.319333 }, { ["mapID"] = 87, ["npcID"] = 7944, ["x"] = 0.6986, ["y"] = 0.5028 }, { ["mapID"] = 85, ["npcID"] = 11017, ["x"] = 0.566, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.6844, ["y"] = 0.4436 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[29481] = { ["id"] = 29481, ["name"] = "Elixir Master", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 85, ["storyline"] = { 29481 }, ["description"] = "Elixirs are all about potency! If you want to become an elixir master , I can teach you. I can't just train anyone, and I require proof that you are devoted before we continue. Several flasks should be sufficient to show your dedication. Remember <name>, you can only learn ONE specialization, so if you complete your elixir training, then potion and transmutation specialization will no longer be available.", ["objectivesText"] = "Bring a variety of flasks to an alchemy trainer in any capital city. Progress: Have you the flasks?", ["rewardItems"] = { 3371, 52329, 52983, 52985, 52987, 52988, 72235, 72237, 72238, 76084, 76085, 76086, 76087, 76088, 76094, 76097, 79010, 79011 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 3347, ["x"] = 0.554333, ["y"] = 0.459333 }, { ["mapID"] = 84, ["npcID"] = 5499, ["x"] = 0.555, ["y"] = 0.855 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 3347, ["x"] = 0.554333, ["y"] = 0.459333 }, { ["mapID"] = 84, ["npcID"] = 5499, ["x"] = 0.555, ["y"] = 0.855 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.554333, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 84, 85 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[29506] = { ["id"] = 29506, ["name"] = "A Fizzy Fusion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29506 }, ["description"] = "I'm sure you've made a lot of potions in your time as an alchemist. How would you like to help with something a bit more light-hearted? I've always wanted to try creating a fruit-flavored version of our popular fizzy drinks. If you're willing to give it a try, you can buy some of the base drink from me and mix it with some moonberry juice. Any innkeeper in Elwynn Forest or Mulgore should be able to sell you enough juice to make your creation.", ["objectivesText"] = "Use the Cocktail Shaker to combine Moonberry Juice and Fizzy Faire Drink to create 5 servings of Moonberry Fizz . Progress: How's that moonberry fizz coming?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 19299, 30817, 39354, 71083, 72043, 72044, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29507] = { ["id"] = 29507, ["name"] = "Fun for the Little Ones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29507 }, ["description"] = "Children are always full of questions about what an archaeologist does and how it works, so I prepared a demonstration for them. I take artifacts and fossils and bury them in the sandbox beside the tent. The children get to dig and make their own discoveries, learn how bones fit together, and see how archaeology can teach them about history. If you have any spare fossils, would you consider donating them to my side project?", ["objectivesText"] = "Bring 15 Fossil Fragments collected with Archaeology to Professor Thaddeus Paleo at the Darkmoon Faire. Progress: How about it? Want to donate some fossil fragments?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 69777, 71083, 87399, 87535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29508] = { ["id"] = 29508, ["name"] = "Baby Needs Two Pair of Shoes", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29508 }, ["description"] = "You may have seen my horse, Baby , over near the wagons. She pulls the cart that hauls some of the animals in our Zoo Bizarre. She's a hard worker and she tears through shoes like you wouldn't believe. It's about time for a new set. I've already bought the raw materials. All you need to do is shape them over an anvil and apply them to Baby 's feet. It's a quick job and worth some tickets, wouldn't you say?", ["objectivesText"] = "Use the Iron Stock to craft 4 Horseshoes , then apply the Horseshoes to Baby at the Darkmoon Faire. Progress: How's old Baby doing?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 71964, 71967, 87216, 190456, 191886 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29509] = { ["id"] = 29509, ["name"] = "Putting the Crunch in the Frog", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29509 }, ["description"] = "The Darkmoon Faire's crunchy frog is famous all over Azeroth! We've just had a fresh batch of frogs delivered. How'd you like to help whip up a few and practice your cooking skills in the process? You can get the flour you'll need to bread the frogs from any trade goods vendor in Elwynn Forest or Mulgore.", ["objectivesText"] = "Prepare 5 Crunchy Frogs by breading your Plump Frogs with Simple Flour and then frying them in the cauldron behind Stamp Thunderhorn . Progress: Do I smell fresh crunchy frog ?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 72056, 72057, 72058, 197792 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29510] = { ["id"] = 29510, ["name"] = "Putting Trash to Good Use", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29510 }, ["description"] = "People don't just come to the faire for fun and fortunes, <name>. Most want something to take home with them, so I help to create the magical trinkets visitors purchase with their prize tickets. For that, I need a steady supply of soothsayer's dust . Take a look around the grounds and you'll see a lot of discarded weapons . Those are just the kinds of items that can be broken down into dust with enchanting skills like yours. Would you like to help?", ["objectivesText"] = "Collect 6 Soothsayer's Dusts by disenchanting Discarded Weapons found around the grounds of the Darkmoon Faire. Progress: Did you manage to get any of that soothsayer's dust ?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 71970, 71979, 72018, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29511] = { ["id"] = 29511, ["name"] = "Talkin' Tonks", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29511 }, ["description"] = "The steam tonks are one of the Darkmoon Faire's most popular amusements. Our visitors love to test their skills for hours and hours, but the tonks take a real beating from all that fun. You look like you know your way around a wrench. Mind helping me fix some of the damaged tonks and return them to working order? I'll compensate you for your time.", ["objectivesText"] = "Repair 5 Damaged Steam Tonks around the grounds of the Darkmoon Faire. Progress: You get those repairs done? Visitors are hard on those tonks and I'll need all of them up and running.", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 72096, 72110, 76061, 89112, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29513] = { ["id"] = 29513, ["name"] = "Spoilin' for Salty Sea Dogs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29513 }, ["description"] = "We've just introduced another exciting new menu item, the salty sea dog. It's so popular, we can barely keep up with the demand! You look like a decent angler and a spry <race>. Would you help me restock my fish supplies? We wouldn't want to disappoint all those faire-goers looking to try a new food, would we?", ["objectivesText"] = "Catch 5 Great Sea Herring in the ocean around Darkmoon Island. Progress: Do you have those fish?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 45189, 45195, 45196, 71083, 73269, 73953, 93732, 124674, 127141, 198225, 198438, 199964 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29514] = { ["id"] = 29514, ["name"] = "Herbs for Healing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29514 }, ["description"] = "The little purple flowers that grow wild around the grounds aren't just pretty. They play a role in everything from treating wounds to seasoning food. You seem to have some talent for harvesting herbs. Would you like to help me rebuild my stocks of darkblossom ?", ["objectivesText"] = "Gather 6 Darkblossoms from around the Darkmoon Faire grounds. Progress: How's that herb collection coming along?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 72046, 95416, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29515] = { ["id"] = 29515, ["name"] = "Writing the Future", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29515 }, ["description"] = "As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures. Most times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice. My stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. You can get the parchment you'll need from any trade goods vendor in Elwynn Forest or Mulgore.", ["objectivesText"] = "Use the Bundle of Exotic Herbs to make Prophetic Ink and then combine the ink with Light Parchment to create Sayge 's Fortunes . Progress: Have you penned any of those fortunes ?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 44235, 71083, 71971, 71972, 71974, 84101, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29516] = { ["id"] = 29516, ["name"] = "Keeping the Faire Sparkling", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29516 }, ["description"] = "The Darkmoon Faire's performers and animals go through more jewelry than I'd ever imagined. Thankfully, the gems are just cut glass, but someone has to craft all of it. If you've some skill as a jewelcrafter, perhaps you'd be willing to help craft some of the sparkling glass gems for our performers. Sometimes you can find odd and amazing bits of glass around the grounds. Those make stunning gems when cut by someone with an eye for this craft.", ["objectivesText"] = "Find Bits of Glass around the grounds of the Darkmoon Faire and craft it into 5 Sparkling 'Gemstones'. Progress: Were you able to craft any replacement gems for the performers' jewelry?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 72050, 72052, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29517] = { ["id"] = 29517, ["name"] = "Eyes on the Prizes", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29517 }, ["description"] = "The games are more popular than ever, and that means we're giving out prizes faster than we ever have before! We're going to need more prizes, and fast. If you've some skill in leatherworking, I can give you a kit. You'll need to buy some of the pieces from any trade goods merchant in Elwynn Forest or Mulgore, but they're inexpensive. Are you willing to help?", ["objectivesText"] = "Use the Darkmoon Craftsman's Kit to make 5 Darkmoon Prizes from Coarse Thread, Shiny Baubles, and Blue Dye. Progress: Have you had a chance to make those prizes?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 71976, 71977, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29518] = { ["id"] = 29518, ["name"] = "Rearm, Reuse, Recycle", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29518 }, ["description"] = "Faire-goers just love the steam tonks! And when the Darkmoon Faire closes, these grounds will be littered with tonk scrap . It'd be a shame to let all that good metal just sit in the dirt. If you help me collect some of the larger scraps, I can use them to reforge broken tonk parts. It's a lot less expensive than buying new metal every time. What do you say?", ["objectivesText"] = "Collect 6 pieces of Tonk Scrap from around the Darkmoon Faire grounds. Progress: Did you manage to find any scrap? The grounds are full of it.", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 71968, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29519] = { ["id"] = 29519, ["name"] = "Tan My Hide", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29519 }, ["description"] = "The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment. You seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.", ["objectivesText"] = "Scrape 4 Staked Skins around the grounds of the Darkmoon Faire. Progress: It's a busy job keeping the Darkmoon Faire running.", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29520] = { ["id"] = 29520, ["name"] = "Banners, Banners Everywhere!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29520 }, ["description"] = "Isn't it wonderful to see Darkmoon banners everywhere? It's my favorite part of setting up, but we have so many old and tattered ones that need to be replaced. If you've some skill with a needle and thread, would you mind making a banner from this kit and putting it up in some loose stones scattered around the grounds of the faire? It's missing a few pieces, but you should be able to get what you need from any trade goods vendor in Elwynn Forest or Mulgore.", ["objectivesText"] = "Use Coarse Thread, Red Dye, and Blue Dye with a Darkmoon Banner Kit to make a Darkmoon Banner , then set it up in a pile of Loose Stones on the grounds of the Darkmoon Faire. Progress: Were you able to find a place for that new banner of yours?", ["rewardXP"] = 200, ["rewardItems"] = { 1645, 2320, 2604, 6260, 6529, 30817, 39354, 71083, 72048, 72049, 190456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[29527] = { ["id"] = 29527, ["name"] = "War on the Ramparts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3562, ["storyline"] = { 29527 }, ["description"] = "Watchkeeper Gargolmar and Vazruden the Herald are in charge of defending these ramparts. If you take them out, their forces will be in complete disarray. Slay them both and bring me proof so the invasion can begin!", ["objectivesText"] = "Slay Watchkeeper Gargolmar, Vazruden the Herald and Vazruden's drake, Nazan. Return Gargolmar's Hand and Nazan's Head to Stone Guard Stok'ton . Progress: This operation depends on your success, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 23881, 23901, 25715, 25716, 25717, 25718 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3562 } }, ["questType"] = "dungeon" },
[29528] = { ["id"] = 29528, ["name"] = "War on the Ramparts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3562, ["storyline"] = { 29528 }, ["description"] = "Hellfire Citadel's entire defensive network relies on the ramparts as a sort of early warning system. You need to take out Watchkeeper Gargolmar and Vazruden the Herald. Without them, taking the ramparts will be simple.", ["objectivesText"] = "Slay Watchkeeper Gargolmar, Vazruden the Herald and Vazruden's drake, Nazan. Return Gargolmar's Hand and Nazan's Head to Advance Scout Chadwick . Progress: Were you successful? We have a lot riding on this operation, <name>.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 23881, 23901, 25715, 25716, 25717, 25718 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3562 } }, ["questType"] = "dungeon" },
[29529] = { ["id"] = 29529, ["name"] = "Demons in the Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3562, ["storyline"] = { 29529 }, ["description"] = "One of our scouts spotted what he thought was an agent of the Burning Legion somewhere in the ramparts. If that is true, then Honor Hold may be in grave danger of a combined assault! If you find this fiend in there, kill it on sight.", ["objectivesText"] = "Slay Omor the Unscarred and bring his hoof to Advance Scout Chadwick . Progress: Did you find any demons in there?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 23886 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3562 } }, ["questType"] = "dungeon" },
[29530] = { ["id"] = 29530, ["name"] = "Demons in the Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3562, ["storyline"] = { 29530 }, ["description"] = "One of our scouts brought back unpleasant news. We've spotted a powerful agent of the Burning Legion in the ramparts! I need you to kill this demon before he has a chance to relay news of our efforts to his superiors.", ["objectivesText"] = "Kill Omor the Unscarred and bring his hoof to Stone Guard Stok'ton . Progress: Were you able to dispose of the foul creature?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 23886 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3562 } }, ["questType"] = "dungeon" },
[29535] = { ["id"] = 29535, ["name"] = "Make Them Bleed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3713, ["storyline"] = { 29535 }, ["description"] = "The Maker serves the purpose of creating more fel orcs by infusing them with demon blood. My superiors believe that we may be able to reverse the process, but we need samples of their blood and The Maker's infusion rod before we can know for sure.", ["objectivesText"] = "Collect 10 Fel Orc Blood Vials and a Fel Infusion Rod for Caza'rez . Progress: You're back! Even better, you're not dead! Well done. Better than anyone else so far.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 23894, 73200 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3713 } }, ["questType"] = "dungeon" },
[29536] = { ["id"] = 29536, ["name"] = "Heart of Rage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3713, ["storyline"] = { 29536 }, ["description"] = "We know that the fel orcs are growing their forces by infusing orcs with demon blood. I need you to venture deep inside these unholy halls and find out how that's happening. We can't risk sending an army into this place until we know exactly what we're dealing with.", ["objectivesText"] = "Fully investigate the Blood Furnace and then report back to Caza'rez .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 25712, 25713, 25714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3713 } }, ["questType"] = "dungeon" },
[29537] = { ["id"] = 29537, ["name"] = "Mind the Gap", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3713, ["storyline"] = { 29537 }, ["description"] = "In all of the Blood Furnace , there is one area where our scryers cannot reach despite their efforts. This 'gap', as they've been calling it, is fairly large, and must be where Magtheridon is being held captive.. You must find the source of the interference and dispose of it.", ["objectivesText"] = "Kill Keli'dan the Breaker and return to Caza'rez .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 25701, 25702, 25710, 25711 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3713 } }, ["questType"] = "dungeon" },
[29538] = { ["id"] = 29538, ["name"] = "Make Them Bleed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3713, ["storyline"] = { 29538 }, ["description"] = "The Maker uses demon blood and a special rod to turn brown and green orcs into red ones. We'd like to see if we can take that blood, mess around with it a bit, and make it turn orcs of all colors into harmless docile lumps. You're going to bring me some samples of their blood so we can see. Don't forget to grab that rod!", ["objectivesText"] = "Collect 10 Fel Orc Blood Vials and a Fel Infusion Rod for Gunny . Progress: You have that blood, darlin'? Might be kind of important if we asked you to get it, you know?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 23894, 73200 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3713 } }, ["questType"] = "dungeon" },
[29539] = { ["id"] = 29539, ["name"] = "Heart of Rage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3713, ["storyline"] = { 29539 }, ["description"] = "As it turns out, the eggheads back at Honor Hold can't see much into this place. Bunch of lying lazy mages, is what they are. Either way, we don't really know exactly what's going on in here. So, you're going in to find out!", ["objectivesText"] = "Fully investigate the Blood Furnace and then report back to Gunny .", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 25712, 25713, 25714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3713 } }, ["questType"] = "dungeon" },
[29540] = { ["id"] = 29540, ["name"] = "The Breaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3713, ["storyline"] = { 29540 }, ["description"] = "So they've got this big ol' demon stashed away in this place, is what they're telling me. And there's an orc that's in charge of keeping him under wraps. Killing an orc is killing an orc, am I right? Doesn't matter what he did or what he's doin', orcs are always ripe for the slaughter!", ["objectivesText"] = "Kill Keli'dan the Breaker and return to Gunny .", ["rewardGold"] = 619600, ["rewardXP"] = 2830, ["rewardItems"] = { 25701, 25702, 25710, 25711, 147469, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3713 } }, ["questType"] = "dungeon" },
[29542] = { ["id"] = 29542, ["name"] = "Invading the Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 29542 }, ["description"] = "With the Legion to one side and the fel orcs to the other, Thrallmar is going to be overrun if we don't do something about it. Head west to the Hellfire Ramparts and speak with Stone Guard Stok'ton . He's in charge of a covert operation to start a Horde invasion on the entire citadel.", ["objectivesText"] = "Speak with Stone Guard Stok'ton in Hellfire Ramparts .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 19256, ["x"] = 0.58, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "dungeon" },
[29543] = { ["id"] = 29543, ["name"] = "Invading the Citadel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 29543 }, ["description"] = "With the Legion to one side and the fel orcs to the other, Honor Hold is going to be overrun in a matter of time if we don't do something about it. Head west to the Hellfire Ramparts and speak with Advance Scout Chadwick . He's in charge of a covert operation to start an Alliance invasion on the entire citadel.", ["objectivesText"] = "Speak with Advance Scout Chadwick in Hellfire Ramparts .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 19309, ["x"] = 0.616, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "dungeon" },
[29563] = { ["id"] = 29563, ["name"] = "Lost in Action", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3717, ["storyline"] = { 29563 }, ["description"] = "You have to help me! We were sent here to investigate the various parts of the reservoir, but my friends haven't come back yet, and it's been a long time. That's why I need you to discover what became of them. Naturalist Bite and Weeder Greenthumb went this way.", ["objectivesText"] = "Discover what happened to Naturalist Bite and Weeder Greenthumb . Then, return to Watcher Jhang . Progress: Have you discovered anything?", ["rewardXP"] = 2830, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3717 } }, ["questType"] = "dungeon" },
[29564] = { ["id"] = 29564, ["name"] = "A Brother Betrayed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3717, ["storyline"] = { 29564 }, ["description"] = "My village was able to escape the naga onslaught at first. We would have all made it to Nagrand had it not been for my brother. He sold our souls for his own freedom. Now he works here as a slave driver, whipping his own brothers until their backs bleed. Make Mennu pay, <race>.", ["objectivesText"] = "Kill Mennu the Betrayer , then return to Nahuud . Progress: Is the traitor dead?", ["rewardGold"] = 561800, ["rewardXP"] = 2830, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3717 } }, ["questType"] = "dungeon" },
[29565] = { ["id"] = 29565, ["name"] = "The Heart of the Matter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3717, ["storyline"] = { 29565 }, ["description"] = "From what Nahuud has told me, two mighty creatures, Rokmar the Crackler and Quagmirran, were among the first enslaved by the naga when they arrived. They helped to subjugate many of the native races of Zangarmarsh. Though it pains me greatly to ask you to do so, you must put them down.", ["objectivesText"] = "Bring The Invader's Claw and The Slave Master's Eye to Watcher Jhang . Progress: Did you slay them?", ["rewardGold"] = 619600, ["rewardXP"] = 2830, ["rewardItems"] = { 25540, 25541, 28029, 65682, 65702, 65720, 65731, 72118, 72119, 131698, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3717 } }, ["questType"] = "dungeon" },
[29566] = { ["id"] = 29566, ["name"] = "Checking Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 29566 }, ["description"] = "These marshes are beautiful, wouldn't you agree? That is, except for the naga forces draining the water away. I sent a small expedition to the Coilfang Reservoir to investigate the naga, and they haven't returned. I'm concerned that something has happened to them. Would you travel to the Slave Pens underneath Serpent Lake and find Watcher Jhang ?", ["objectivesText"] = "Speak with Watcher Jhang in the Slave Pens .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 211279 }, ["starts"] = { { ["mapID"] = 102, ["npcID"] = 17841, ["x"] = 0.784, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "dungeon" },
[29567] = { ["id"] = 29567, ["name"] = "Stalk the Stalker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3716, ["storyline"] = { 29567 }, ["description"] = "The spore giants may be attacking my people today, but the marsh walkers have taken more innocent lives than any creature I've ever seen. They are our ancient enemies. Their brood mother, the Black Stalker, resides deep within this bog. If you were to destroy her and bring me her brain as proof, I would tell tales of your bravery to my grandchildren.", ["objectivesText"] = "Bring the Brain of the Black Stalker to T'shu . Progress: You have returned. Does this mean that The Black Stalker is no more?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 24248, 28108, 28109, 84320, 84321, 84322, 84323, 84324, 84325, 84326, 84327, 84328, 171828, 172089, 237859, 237865, 237871, 237880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3716 } }, ["questType"] = "dungeon" },
[29568] = { ["id"] = 29568, ["name"] = "A Necessary Evil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3716, ["storyline"] = { 29568 }, ["description"] = "Hungarfen and Quagmirran used to jointly rule over the spore giants. With Quagmirran gone, the burden rests solely on Hungarfen 's tendrils. We have no choice but to put the giant down before he can be enslaved and turned into a weapon.", ["objectivesText"] = "Kill Hungarfen , then report back to Naturalist Bite . Progress: Is the deed done, <name>?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3716 } }, ["questType"] = "dungeon" },
[29570] = { ["id"] = 29570, ["name"] = "Rescuing the Expedition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3716, ["storyline"] = { 29570 }, ["description"] = "The last members of my expedition are somewhere in here. We're going to need the knowledge they've gathered and their skills if we're to have any chance at defeating the naga. See if you can find Earthbinder Rayge and Windcaller Claw , and make sure they're ok.", ["objectivesText"] = "Discover what happened to Earthbinder Rayge and Windcaller Claw . Then, return to Watcher Jhang . Progress: Were you able to find either of them? Are they ok?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3716 } }, ["questType"] = "dungeon" },
[29571] = { ["id"] = 29571, ["name"] = "Defending the Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 29571 }, ["description"] = "The Earthen Ring often finds itself working closely with the druids of the Cenarion Circle. Now is one such time. Travel north to the Underbog and speak with Watcher Jhang . She is in charge of an expedition in the Coilfang Reservoir to stop the naga there and save Zangarmarsh.", ["objectivesText"] = "Speak with Watcher Jhang in the Underbog .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18074, ["x"] = 0.605, ["y"] = 0.224 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.224 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "dungeon" },
[29573] = { ["id"] = 29573, ["name"] = "Safety is Job One", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3792, ["storyline"] = { 29573 }, ["description"] = "It's nearly safe for our men to come in here and take what's rightfully ours. The real danger now is Shaffar's personal army that he has crawling all over this place. I need you to take care of his forces for me while I regain my strength.", ["objectivesText"] = "Kill 10 Ethereal Crypt Raiders , 5 Ethereal Sorcerers , 5 Nexus Stalkers , and 5 Ethereal Spellbinders , then return to Artificer Morphalius . Progress: Done already? You humans continue to fascinate me.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 28490, 69210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3792 } }, ["questType"] = "dungeon" },
[29574] = { ["id"] = 29574, ["name"] = "Intriguing Specimens", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3792, ["storyline"] = { 29574 }, ["description"] = "There is a creature not far inside these halls called Pandemonius who is able to twist void energies to sustain and empower itself. A bit further in lies Tavarok, a being that takes those same void energies and converts them into a crystalline structure stronger than any I've ever seen! I absolutely must obtain samples for further study.", ["objectivesText"] = "Bring Pandemonius' Essence and Tavarok's Heart to Mamdy the \"Ologist\". Progress: If you don't have what I'm looking for, stop wasting my time.", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 69210, 72126, 72127 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3792 } }, ["questType"] = "dungeon" },
[29575] = { ["id"] = 29575, ["name"] = "Undercutting the Competition", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3792, ["storyline"] = { 29575 }, ["description"] = "With his ward in place and his forces ready, Nexus-Prince Shaffar has been able to pillage this place for all it's worth without so much as an ounce of trouble. Unsurprisingly, Nexus-Prince Haramad isn't pleased by this, and has placed a hefty bounty on Shaffar's head.", ["objectivesText"] = "Bring Shaffar's Wrappings to Artificer Morphalius . Progress: Were you interested in the bounty on Shaffar's head?", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 28490, 69210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3792 } }, ["questType"] = "dungeon" },
[29582] = { ["id"] = 29582, ["name"] = "Grek's Crazy Night", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 29582 }, ["description"] = "Grek had bad night last night. Shiny mummy man came into Grek 's house and told Grek that he had to go to Mana Tombs in Auchindoun. But Grek still trying to read wanted poster! < Grek 's face lights up.> Grek knows! You go find shiny mummy man and tell him Grek sent you. It perfect plan!", ["objectivesText"] = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["rewardItems"] = { 69210 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 19606, ["x"] = 0.498, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "dungeon" },
[29583] = { ["id"] = 29583, ["name"] = "Eckert the Mad", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 29583 }, ["description"] = "I'm a skilled engineer, a brilliant inventor, the heart of any party, and the best dancer Azeroth has ever seen. Do they call me those things? No. But you have one run-in with an ethereal and all of the sudden everyone and their mother calls you \"the mad\". I saw one right here just yesterday, I swear it! He said if I followed him to the Mana Tombs in Auchindoun there would be vast treasure and ancient knowledge awaiting me!", ["objectivesText"] = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["rewardItems"] = { 28490, 69210 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 21400, ["x"] = 0.574, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "dungeon" },
[29590] = { ["id"] = 29590, ["name"] = "The Dead Watcher", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3790, ["storyline"] = { 29590 }, ["description"] = "A terrifying otherworldly being haunts both the spirit and physical worlds. We call it Shirrak. It can only be harmed in your realm. Please help rid us of this nightmare.", ["objectivesText"] = "Kill Shirrak the Dead Watcher , then return to the Draenei Spirit .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3790 } }, ["questType"] = "dungeon" },
[29591] = { ["id"] = 29591, ["name"] = "Raging Spirits", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3790, ["storyline"] = { 29591 }, ["description"] = "The Auchenai have turned their backs on everything we used to stand for. They've taken to raising the dead as unholy minions! This cannot stand. Put the spirits back to rest, and massacre those responsible for raising them into undeath.", ["objectivesText"] = "Slay 5 Angered Skeletons , 5 Raging Skeletons , and 3 Auchenai Necromancers , then return to the Tormented Soulpriest in Auchenai Crypts . Progress: Don't speak to me again until the deed is done.", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3790 } }, ["questType"] = "dungeon" },
[29593] = { ["id"] = 29593, ["name"] = "Hitting Them Where It Hurts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3562, ["storyline"] = { 29593 }, ["description"] = "The fel orcs have stockpiled many of their supplies here. Stealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, <class>?", ["objectivesText"] = "Steal 3 piles of Hellfire Supplies , then return to Stone Guard Stok'ton in Hellfire Ramparts . Progress: How many piles were you able to take?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 72160 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3562 } }, ["questType"] = "dungeon" },
[29594] = { ["id"] = 29594, ["name"] = "Hitting Them Where It Hurts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3562, ["storyline"] = { 29594 }, ["description"] = "The fel orcs have stockpiled many of their supplies here. Stealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, <class>?", ["objectivesText"] = "Steal 3 piles of Hellfire Supplies , then return to Advance Scout Chadwick in Hellfire Ramparts . Progress: How many piles were you able to take?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 72160 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3562 } }, ["questType"] = "dungeon" },
[29595] = { ["id"] = 29595, ["name"] = "Everything Will Be Alright", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 29595 }, ["series"] = { 29596 }, ["description"] = "You've had quite an adventure, <name>. And before you've even set foot inside of the Auchenai Crypts . I am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts. What I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.", ["objectivesText"] = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and speak with the Draenei Spirit .", ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 19698, ["x"] = 0.35, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "dungeon" },
[29596] = { ["id"] = 29596, ["name"] = "The End of the Exarch", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3790, ["storyline"] = { 29596 }, ["series"] = { 29595 }, ["description"] = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped. You must slay him for the benefit of us all, dead and alive.", ["objectivesText"] = "Kill Exarch Maladaar and return to the Draenei Spirit inside the Auchenai Crypts .", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 29337, 29339, 29340, 29341 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3790 } }, ["questType"] = "dungeon" },
[29598] = { ["id"] = 29598, ["name"] = "Taretha's Diversion", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 2367, ["storyline"] = { 29598 }, ["series"] = { 10282, 29599 }, ["description"] = "It was Taretha who created the original diversion at Durnholde, allowing Thrall to escape. Now the Infinite have captured Taretha. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges.", ["objectivesText"] = "Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion . Speak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze. Progress: Who are you?", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 25853 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2367 } }, ["questType"] = "dungeon" },
[29601] = { ["id"] = 29601, ["name"] = "The Darkmoon Field Guide", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["storyline"] = { 29601 }, ["description"] = "Do you have a copy of the Darkmoon Field Guide, friend? It's a most useful book to carry with you. It can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you've found your five hundredth brass button or that rare treasure the Darkmoon Faire's collectors crave.", ["rewardItems"] = { 19182, 71634 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29605] = { ["id"] = 29605, ["name"] = "Brother Against Brother", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3791, ["storyline"] = { 29605 }, ["description"] = "The Sethekk departed Skettis when Auchindoun exploded. My brother, Syth, was one of their leaders and told us we had to go into the ruins and face our god. In time, Syth had me cast out of the Halls for doubting them, but he refused to let me take our sister Lakka . Will you help me rescue her?", ["objectivesText"] = "Free Lakka from captivity. Return to Isfar inside the Sethekk Halls when you've completed the rescue. Progress: Did you find her, <name>? Was she still being held within the halls?", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 29333, 29334, 29335, 29336, 62210, 62211, 62212, 62213, 131655 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3791 } }, ["questType"] = "dungeon" },
[29606] = { ["id"] = 29606, ["name"] = "Terokk's Legacy", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3791, ["storyline"] = { 29606 }, ["description"] = "Terokk, hero of the Arakkoa, mysteriously vanished one day, leaving only his mask and spear behind. Darkweaver Syth still holds his mask and Talon King Ikiss guards his spear. It would mean a great deal to my people if these items were returned to us.", ["objectivesText"] = "Bring Terokk's Mask and Terokk's Quill to Isfar inside the Sethekk Halls . Progress: The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 25464, 27632, 27633, 29329, 29330, 29332 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3791 } }, ["questType"] = "dungeon" },
[29607] = { ["id"] = 29607, ["name"] = "Eyes of Desire", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3791, ["storyline"] = { 29607 }, ["description"] = "I have a buyer who is interested in the eyes of the Cobalt Serpents that have taken up residence here. If you were to bring me some of these rare gems, I would cut you a portion of the profits. Do we have a deal?", ["objectivesText"] = "Dealer Vijad inside the Sethekk Halls wants you to bring him 3 Cobalt Eyes . Progress: Did you bring the eyes?", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 72480 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3791 } }, ["questType"] = "dungeon" },
[29608] = { ["id"] = 29608, ["name"] = "Allies in Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3537, ["mapID"] = 117, ["storyline"] = { 29608 }, ["description"] = "Welcome to Northrend, <name>. I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there. Ride the gryphon to Dalaran and once you land, make your way to our inn there, A Hero's Welcome. Find Isirami Fairwind and speak with her immediately. She can help you bind your hearthstone to the city so you can use the Silver Enclave's portal to travel back to Stormwind quickly.", ["objectivesText"] = "Accept a gryphon ride to Dalaran and speak with Isirami Fairwind at A Hero's Welcome.", ["rewardXP"] = 175, ["rewardItems"] = { 86570 }, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 23736, ["x"] = 0.598, ["y"] = 0.632 }, { ["mapID"] = 114, ["npcID"] = 26879, ["x"] = 0.588, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 114, 117 }, ["zone"] = { 3537 } }, ["questType"] = "standard" },
[29609] = { ["id"] = 29609, ["name"] = "Friends in Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 495, ["mapID"] = 114, ["storyline"] = { 29609 }, ["description"] = "Welcome to Northrend. I have been asked to arrange travel for you to Dalaran so that you can meet our friends in the city. Speak with me and accept a ride to Dalaran . Once you land, make your way to The Filthy Animal. Make contact with Uda the Beast immediately. She can help you bind your hearthstone to the city so you can use the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.", ["objectivesText"] = "Accept a ride to Dalaran from the flight master and speak with Uda the Beast at The Filthy Animal.", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 25288, ["x"] = 0.404, ["y"] = 0.515 }, { ["mapID"] = 117, ["npcID"] = 27344, ["x"] = 0.79, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 114, 117 }, ["zone"] = { 495 } }, ["questType"] = "standard" },
[29613] = { ["id"] = 29613, ["name"] = "A Proper Fate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3715, ["storyline"] = { 29613 }, ["description"] = "Warlord Kalithresh is in charge of the entire Steamvault operation. I need you to kill him, <name>. The naga have left us with no option but violence. Show him no mercy.", ["objectivesText"] = "Kill Warlord Kalithresh and return to Watcher Jhang inside the Steamvault .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3715 } }, ["questType"] = "dungeon" },
[29614] = { ["id"] = 29614, ["name"] = "Containment is Key", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3715, ["storyline"] = { 29614 }, ["description"] = "The naga are working with leper gnomes to spread a horrific disease across Zangarmarsh. It's already spread throughout the Steamvault . Clear out anything that's been contaminated and bring me the central gear from Mekgineer Steamrigger, quickly!", ["objectivesText"] = "Kill 3 Bog Overlords , 6 Coilfang Lepers , and obtain an Irradiated Gear from Mekgineer Steamrigger, then return to Naturalist Bite inside the Steamvault . Progress: Be as thorough as possible. The fate of Zangarmarsh depends on it.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 72574 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3715 } }, ["questType"] = "dungeon" },
[29615] = { ["id"] = 29615, ["name"] = "Windcaller Claw and the Water Thief", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3715, ["storyline"] = { 29615 }, ["description"] = "The Steamvault is the heart of the naga's efforts to pump the water out of Zangarmarsh, and Hydromancer Thespia personally oversees those efforts. Taking her out would seriously hinder their operation.", ["objectivesText"] = "Kill Hydromancer Thespia and return to Windcaller Claw inside the Steamvault . Progress: Did you dispatch of the water thief?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3715 } }, ["questType"] = "dungeon" },
[29616] = { ["id"] = 29616, ["name"] = "Storming the Steamvault", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 29616 }, ["description"] = "We have not as of yet been able to stop the naga in the Steamvault , where most of their pumping infrastructure is located. Thankfully, the expedition I sent there is hard at work trying to change that fact. Will you travel to the Steamvault and offer Watcher Jhang and her crew your aid?", ["objectivesText"] = "Speak with Watcher Jhang in the Steamvault .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 102, ["npcID"] = 17841, ["x"] = 0.784, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "dungeon" },
[29640] = { ["id"] = 29640, ["name"] = "Find Spy To'gun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3789, ["storyline"] = { 29640 }, ["series"] = { 29641 }, ["description"] = "The Shadow Council has already killed most of our spies, but To'gun was foolish enough to escape only to go back in! You must find him. He may be reckless, but we need to find out what he knows.", ["objectivesText"] = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3789 } }, ["questType"] = "dungeon" },
[29641] = { ["id"] = 29641, ["name"] = "The Soul Devices", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3789, ["storyline"] = { 29641 }, ["series"] = { 29640 }, ["description"] = "They've been torturing me, trying to get me to tell them everything that I know. They fed the others to Hellmaw, and I was to be next. But I told them nothing! They're using special devices to make their summoning more powerful. You must steal these devices!", ["objectivesText"] = "Steal 5 Soul Devices and deliver them to Spy Grik'tha inside the Shadow Labyrinth of Auchindoun. Progress: Were you able to find To'gun?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 27480, 28167, 28170, 28171, 28174 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3789 } }, ["questType"] = "dungeon" },
[29642] = { ["id"] = 29642, ["name"] = "Trouble at Auchindoun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 29642 }, ["description"] = "I have spies within Auchindoun and they have been sending me disturbing reports. That place has been nothing but trouble ever since it exploded a couple of years ago. Something in there has gone horribly wrong - again - and the Shadow Council is now on a war footing. Though the reports were lacking on details, their preparations appear to be directed inward. You must make your way to the Shadow Labyrinth . My field commander, Mahfuun, will fill you in on what needs to be done.", ["objectivesText"] = "Report to Field Commander Mahfuun inside the Shadow Labyrinth at Auchindoun in Terokkar Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18893, ["x"] = 0.505, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon" },
[29643] = { ["id"] = 29643, ["name"] = "The Codex of Blood", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3789, ["storyline"] = { 29643 }, ["series"] = { 29644 }, ["description"] = "Two years ago the Shadow Council summoned forth a being that shattered Auchindoun in its wake. Read the Codex of Blood to find out what happened. Be warned, Grandmaster Vorpil guards it with his life.", ["objectivesText"] = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3789 } }, ["questType"] = "dungeon" },
[29644] = { ["id"] = 29644, ["name"] = "Into the Heart of the Labyrinth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3789, ["storyline"] = { 29644 }, ["series"] = { 29643 }, ["description"] = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago. Known only as Murmur , it threatens to overrun the Shadow Council and break free into the outside world!", ["objectivesText"] = "Destroy Murmur and inform Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun. Progress: Has the chaotic being been banished from our world?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 28176, 28177, 28178, 28179 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3789 } }, ["questType"] = "dungeon" },
[29645] = { ["id"] = 29645, ["name"] = "Ambassador Hellmaw", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3789, ["storyline"] = { 29645 }, ["description"] = "When the Cabal found our spies, they fed them to Ambassador Hellmaw one by one. Our men deserve justice. Slay the ritualists binding him, then dispose of Hellmaw. It is a most deserving fate.", ["objectivesText"] = "Kill 12 Cabal Ritualists and Ambassador Hellmaw , then return to Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3789 } }, ["questType"] = "dungeon" },
[29649] = { ["id"] = 29649, ["name"] = "How to Save a Life", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29649 }, ["description"] = "Gunny is dying from a powerful curse, <name>. Grand Warlock Nethekurse augments his power with a pair of mystical braziers. If you bring me an ember from that brazier, perhaps it can counteract the dark magic?", ["objectivesText"] = "Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember . Progress: Did you bring the ember? We don't have much time!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 23726, 23735, 25788, 25789, 25790, 25791, 25792 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29650] = { ["id"] = 29650, ["name"] = "Fel Ember", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29650 }, ["description"] = "Caza'rez is dying a coward's death. Grand Warlock Netherkurse placed a terrible curse upon him. Perhaps if you were to bring me one of the embers from his braziers, we could use it to counteract the magic before it's too late?", ["objectivesText"] = "Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember . Progress: Did you bring the ember? Caza'rez deserves a warrior's death.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 23726, 23735, 25788, 25789, 25790, 25791, 25792 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29651] = { ["id"] = 29651, ["name"] = "Honor the Dying", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29651 }, ["description"] = "Their elite warriors are ruthless... so... powerful. < Caza'rez spits up blood.> You have to kill them... or we will never defeat Kargath...", ["objectivesText"] = "Caza'rez inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires , 2 Shattered Hand Centurions , and 2 Shattered Hand Champions . Progress: Are they dead, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29652] = { ["id"] = 29652, ["name"] = "One Last Favor", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29652 }, ["description"] = "Ol' Gunny doesn't have much longer... Do me one last favor, and kill the biggest, meanest fel orcs ye can find. For old times' sake, aye?", ["objectivesText"] = "Gunny inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires , 2 Shattered Hand Centurions , and 2 Shattered Hand Champions . Progress: Did ye kill 'em?", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["rewardItems"] = { 59650, 59651, 59652 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29653] = { ["id"] = 29653, ["name"] = "The Will of the Warchief", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29653 }, ["description"] = "Kargath was once one of the Horde's greatest heroes. He now wears the false mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he once was, rather than the monster he's become.", ["objectivesText"] = "Bring Warchief Kargath's Fist to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel. Progress: Have you proof of Kargath Bladefist's defeat?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 23723, 25808, 25809, 25810, 25811 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29654] = { ["id"] = 29654, ["name"] = "Turning the Tide", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29654 }, ["description"] = "There is only one true way to end the fel orc threat to Honor Hold and the Alliance. Their Warchief must be slain. Bring me his namesake weapon, so that we can always remember his death.", ["objectivesText"] = "Bring Warchief Kargath's Fist to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel. Progress: Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", ["rewardGold"] = 280900, ["rewardXP"] = 5530, ["rewardItems"] = { 23723, 25803, 25804, 25805, 25806, 140245, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29655] = { ["id"] = 29655, ["name"] = "A Very Special Cloth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29655 }, ["description"] = "Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever encountered. He is ruthless, cunning, and extremely powerful. Take him down and bring me his warcloth so that we may fashion it into a banner and show them the fury of the Horde!", ["objectivesText"] = "Kill Warbringer O'mrogg and bring his warcloth to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel. Progress: Did you bring me the cloth?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 72597 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29656] = { ["id"] = 29656, ["name"] = "O'mrogg's Warcloth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3714, ["storyline"] = { 29656 }, ["description"] = "Stormwind wants to see proof of our successes in the war effort. Rather than showing him body bags, I thought we'd present him the warcloth of O'mrogg, Kargath's fiercest warrior. Think you can handle him?", ["objectivesText"] = "Kill Warbringer O'mrogg and bring his warcloth to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel. Progress: Did you bring me the cloth?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 72597 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3714 } }, ["questType"] = "dungeon" },
[29657] = { ["id"] = 29657, ["name"] = "With Great Power, Comes Great Responsibility", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3849, ["mapID"] = 111, ["storyline"] = { 29657 }, ["series"] = { 29658 }, ["description"] = "<A voice like the sound of light bells rings in your head.> The Mechanar employs my race's technology to create manacells, objects which provide great amounts of power. I need you to eliminate Mechano-Lord Capacitus so that Kael'thas' forces cannot harvest that power.", ["objectivesText"] = "A'dal has asked you to slay Mechano-Lord Capacitus in the Mechanar of Tempest Keep.", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3849 } }, ["questType"] = "dungeon" },
[29658] = { ["id"] = 29658, ["name"] = "The Calculator", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 29658 }, ["series"] = { 29657 }, ["description"] = "<A gentle wind caresses your face.> One more task yet remains. Pathaleon the Calculator oversees many of his master's operations. He is personally responsible for much of the recent torment that has plagued this world. I ask that you eliminate him.", ["objectivesText"] = "A'dal has asked you to slay Pathaleon the Calculator in the Mechanar of Tempest Keep.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon" },
[29659] = { ["id"] = 29659, ["name"] = "Lost Treasure", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 29659 }, ["description"] = "I sense that one of my kind's artifacts has been taken and stashed away in the Cache of the Legion. We cannot give them time to discover its power. If you would kill the Gatewatchers and retrieve it for me, I would be most grateful.", ["objectivesText"] = "Retrieve the Blinding Fury for A'dal from the Cache of the Legion in the Mechanar of Tempest Keep. Progress: You've obtained it, I assume?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 39336, 39380, 39433, 39454, 72663 }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon" },
[29660] = { ["id"] = 29660, ["name"] = "Saving the Botanica", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3847, ["mapID"] = 111, ["storyline"] = { 29660 }, ["series"] = { 29667, 29669 }, ["description"] = "Kael'thas' forces in the Botanica were unsuccessful in handling the numerous creatures contained within. We must take action to right their wrongs. The first step is to eliminate their forces so that they cannot cause further problems.", ["objectivesText"] = "A'dal wants you to kill Commander Sarannis , High Botanist Freywinn , and Thorngrin the Tender inside the Botanica of Tempest Keep.", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3847 } }, ["questType"] = "dungeon" },
[29667] = { ["id"] = 29667, ["name"] = "Culling the Herd", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3847, ["mapID"] = 111, ["storyline"] = { 29667 }, ["series"] = { 29660, 29669 }, ["description"] = "It seems that Kael'thas' forces have twisted the Botanica 's specimens beyond saving. I do not want to see them unleashed upon Outland as so many others have. There is one, Laj, who I would like to examine. He is different somehow. Perhaps we can learn from him.", ["objectivesText"] = "A'dal has asked you to kill 6 Mutate Fleshlashers , 6 Mutate Fear-shriekers , 6 Mutate Horrors , and to obtain a Rapidly Evolving Frond from Laj in the Botanica of Tempest Keep. Progress: I see you have obtained the frond. Very good.", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["rewardItems"] = { 72706 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3847 } }, ["questType"] = "dungeon" },
[29669] = { ["id"] = 29669, ["name"] = "A Most Somber Task", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 29669 }, ["series"] = { 29660, 29667 }, ["description"] = "I must now ask you to complete a most somber task. Warp Splinter used to act as guardian to all of the Botanica . He is now impure, and must be taken down.", ["objectivesText"] = "A'dal has asked you to slay Warp Splinter in the Botanica of Tempest Keep.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon" },
[29674] = { ["id"] = 29674, ["name"] = "Unbound Darkness", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3848, ["mapID"] = 111, ["storyline"] = { 29674 }, ["series"] = { 29675, 29681 }, ["description"] = "<The sound of chimes enters your head, but it is distressed.> We imprisoned the most dangerous beings we came across in our travels. Zereketh is a powerful void lord. If he escapes into Netherstorm, he will feed off of the abundant void energy.", ["objectivesText"] = "A'dal has asked you to slay Zereketh the Unbound in the Arcatraz of Tempest Keep.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3848 } }, ["questType"] = "dungeon" },
[29675] = { ["id"] = 29675, ["name"] = "Hey There Dalliah", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3848, ["mapID"] = 111, ["storyline"] = { 29675 }, ["series"] = { 29674, 29681 }, ["description"] = "Two powerful agents of the Burning Legion, Wrath-Scryer Soccothrates and Dalliah the Doomsayer , have begun rallying the demons on board together into a small army. You cannot let their forces grow any larger, or the Arcatraz may soon become yet another Legion stronghold.", ["objectivesText"] = "A'dal has asked you to kill Wrath-Scryer Soccothrates and Dalliah the Doomsayer in the Arcatraz of Tempest Keep.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3848 } }, ["questType"] = "dungeon" },
[29681] = { ["id"] = 29681, ["name"] = "Maximum Security Breakout", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 29681 }, ["series"] = { 29674, 29675 }, ["description"] = "Harbinger Skyriss is the heart of the problem in the Arcatraz . He corrupted Warden Mellichar and made him release many of the prisoners. It is only a matter of time before the Harbinger himself is let loose. <name>, you cannot let a servant of the Old Gods live!", ["objectivesText"] = "A'dal has asked you to slay Harbinger Skyriss in the Arcatraz of Tempest Keep.", ["rewardGold"] = 58650, ["rewardXP"] = 3440, ["rewardItems"] = { 31747, 31748, 31749 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon" },
[29682] = { ["id"] = 29682, ["name"] = "Magisters' Terrace", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 29682 }, ["series"] = { 11481 }, ["description"] = "We recently sent in an expeditionary force to the Magisters' Terrace to stop the Legion forces there. However, we haven't heard from them since, and I fear the worst. Will you go there and try to find Exarch Larethor ? He's in charge of the expedition.", ["objectivesText"] = "Captain Theris Dawnhearth wants you to find Exarch Larethor inside the Magisters' Terrace .", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["rewardItems"] = { 3316, 3354, 3365, 3370, 3389, 251103, 251104, 251108, 251115, 251118, 260312 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 24967, ["x"] = 0.474, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "dungeon" },
[29684] = { ["id"] = 29684, ["name"] = "Severed Communications", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4131, ["storyline"] = { 29684 }, ["series"] = { 11482, 11490, 29685 }, ["description"] = "We've had a contact embedded in Magisters' Terrace gathering intelligence for us for some time now, but we've lost contact with him. The information he was collecting is vital to our mission.", ["objectivesText"] = "Exarch Larethor inside the Magisters' Terrace wants you to find Tyrith , a blood elf spy.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4131 } }, ["questType"] = "dungeon" },
[29685] = { ["id"] = 29685, ["name"] = "Hard to Kill", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4131, ["storyline"] = { 29685 }, ["series"] = { 11482, 11490, 29684 }, ["description"] = "As you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends. Kael'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.", ["objectivesText"] = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace . You are to take Kael's head and report back to Larethor inside the Magisters' Terrace . Progress: Well, <class>, I must admit, I wasn't sure I'd see you again.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 34157, 35487, 35488 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4131 } }, ["questType"] = "dungeon" },
[29686] = { ["id"] = 29686, ["name"] = "A Radical Notion", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4131, ["storyline"] = { 29686 }, ["description"] = "We cannot afford to lose this war. I'd like to empower our sentries so that brave men and women don't have to die. The Legion has gotten a hold of a powerful elemental being. Its essence could be just what we need.", ["objectivesText"] = "Exarch Larethor in the Magisters' Terrace wants you to kill Vexallus and obtain its essence. Progress: Were you able to get your hands on its essence?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 73084 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4131 } }, ["questType"] = "dungeon" },
[29687] = { ["id"] = 29687, ["name"] = "Twisted Associations", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4131, ["storyline"] = { 29687 }, ["description"] = "The Legion and Kael'thas' forces are becoming increasingly intertwined. This concerns me very deeply. From what we can gather Selin Fireheart and Priestess Delrissa work closely together to unite the two armies. You need to stop them.", ["objectivesText"] = "Exarch Larethor in the Magisters' Terrace wants you to kill Selin Fireheart and Priestess Delrissa .", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4131 } }, ["questType"] = "dungeon" },
[29688] = { ["id"] = 29688, ["name"] = "Advancing the Campaign", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 29688 }, ["description"] = "I mostly listen, <class>. I listen so that the Warchief doesn't have to. I've heard of the status of our campaign against the Hellfire Citadel. It is time to take the Shattered Halls , seat of power for the fel orcs. Go speak with Stone Guard Stok'ton , he's in charge there.", ["objectivesText"] = "Shadow Hunter Ty'jin has asked you to speak with Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 16575, ["x"] = 0.55, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "dungeon" },
[29689] = { ["id"] = 29689, ["name"] = "Advancing the Campaign", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 29689 }, ["description"] = "The time has come to lay the final blow against the fel orcs. Advance Scout Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make haste, their forces could strike against Honor Hold at any moment!", ["objectivesText"] = "Force Commander Danath Trollbane has asked you to speak with Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 16819, ["x"] = 0.566, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "dungeon" },
[29691] = { ["id"] = 29691, ["name"] = "Bring Me A Shrubbery!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3716, ["storyline"] = { 29691 }, ["description"] = "My people use sanguine hibiscus for a number of purposes. It grows naturally only in the Underbog , and many of the bog's denizens have taken a liking to it. If you could bring me some, I would be very grateful.", ["objectivesText"] = "Collect 5 Sanguine Hibiscus and return them to T'shu in the Underbog . Progress: Were you able to gather any hibiscus?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 24246 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3716 } }, ["questType"] = "dungeon" },
[29692] = { ["id"] = 29692, ["name"] = "Bring Me Another Shrubbery!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 3716, ["storyline"] = { 29692 }, ["objectivesText"] = "Progress: We can still use more sanguine hibiscus . We're always struggling to find more. Bring them to me in bunches of five and I will be most grateful.", ["rewardItems"] = { 24246 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3716 } }, ["questType"] = "dungeon" },
