[29760] = { ["id"] = 29760, ["name"] = "Pit Fighter", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 3, ["zoneID"] = 5861, ["storyline"] = { 29760 }, ["description"] = "There must be more to being a master pit fighter than this... Perhaps Korgol Crushskull who runs the Darkmoon Deathmatch at the Faire will know.", ["objectivesText"] = "Speak with Korgol Crushskull at the Darkmoon Faire. Provided item:", ["rewardXP"] = 25, ["rewardItems"] = { 5816, 74034, 74035 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "pvp", ["startItems"] = { 74034 } },
