[29763] = { ["id"] = 29763, ["name"] = "Stealing Their Thunder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 206, ["storyline"] = { 29763 }, ["description"] = "The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple. There's one they esteem though, goes by the name of Ingvar. Bring him down and you'll deal a mighty blow to their spirit.", ["objectivesText"] = "Defender Mordun has asked you to acquire the head of Ingvar the Plunderer. Progress: Good to see you're well, <name>. We've had about as many casualties as we can handle.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 33330, 38218, 38219, 38220, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 206 } }, ["questType"] = "dungeon" },
[29764] = { ["id"] = 29764, ["name"] = "Disarmament", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 206, ["storyline"] = { 29764 }, ["description"] = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly. I need you to pilfer some o' them weapons before they're used on us!", ["objectivesText"] = "Defender Mordun wants you to steal 5 Vrykul Weapons . Progress: You pinch a load a' them vrykul axes?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 43513, 44374, 44375, 44376, 44377, 44400, 44401, 44402, 44403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 206 } }, ["questType"] = "dungeon" },
[29801] = { ["id"] = 29801, ["name"] = "Proving Your Worth", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5892, ["storyline"] = { 29801 }, ["series"] = { 29802, 29847, 29934, 30092, 30093, 30106 }, ["description"] = "Hello, <name>! You've earned a reputation among the flight as having - shall we say - 'nimble fingers.' We need someone of your skills for a matter of utmost delicacy. Before I reveal more, we need to know you're the right <man/woman> for the job. When the course of battle takes you to the Eye of Eternity, I need you to pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring . Are you up to the task?", ["objectivesText"] = "Pickpocket a cryptomancer's decoder ring from Hagara the Stormbinder at the Eye of Eternity within the Dragon Soul raid encounter. Progress: Have you completed our task? These artifacts are crafted such that they dissolve if their bearer is killed, so only a skilled thief can acquire them.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 2892, 6947, 45766, 45769, 64493, 74246, 74748, 74749, 77945, 77946, 77947, 77948, 77949, 77950, 77951, 77952, 77954, 78339 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5892 } }, ["questType"] = "standard" },
[29802] = { ["id"] = 29802, ["name"] = "A Hidden Message", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5892, ["mapID"] = 241, ["storyline"] = { 29802 }, ["series"] = { 29801, 29847, 29934, 30092, 30093, 30106 }, ["description"] = "Corastrasza , currently stationed at the Vermillion Redoubt in the Twilight Highlands, has intercepted a coded message of grave importance. I'll let her explain the full situation, but we need your expertise to unravel the cipher! Take your decoder ring to an ethereal thaumaturge in your capital city - he should know how to charge it. Acquire the encoded cipher from Corastrasza and use the ring to decode it for her. Hurry! Time is ticking...", ["objectivesText"] = "Charge your Cryptomancer's Decoder Ring and use it to decode the Corastrasza 's Singed Cipher . Progress: I was hoping Lord Afrasastrasz would find us a competent <class>. What have you got for us, <name>? Do you have a means of decrypting the message?", ["rewardGold"] = 137400, ["rewardXP"] = 4790, ["rewardItems"] = { 74256, 74748, 74749, 74750, 74752, 77945, 77946, 77947, 77948, 77949, 77950 }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 55488, ["x"] = 0.29, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 5892 } }, ["questType"] = "standard" },
[29803] = { ["id"] = 29803, ["name"] = "Ears of the Lich King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 206, ["storyline"] = { 29803 }, ["description"] = "Prince Keleseth acts as Arthas' eyes and ears in the Fjord. I don't like that one bit! Go and give him a round o' pain. You'll be doing the world a favor by doing so.", ["objectivesText"] = "Defender Mordun inside Utgarde Keep wants you to slay Prince Keleseth .", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 39676, 39678, 39679, 39680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 206 } }, ["questType"] = "dungeon" },
[29807] = { ["id"] = 29807, ["name"] = "Death to the Traitor King", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4277, ["storyline"] = { 29807 }, ["description"] = "Anub'arak, the traitor king, makes his home in the once proud Kingdom of Azjol-Nerub . He has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who have pledged themselves to serving the Lich King. Bring an end to his reign.", ["objectivesText"] = "Reclaimer A'zak in Azjol-Nerub has tasked you with defeating Anub'arak. You are to return to A'zak with Anub'arak's Broken Husk . Progress: Is it done, <class>? Has the traitor king finally met his end?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 43411, 44358, 44359, 44360, 44361 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4277 } }, ["questType"] = "dungeon" },
[29808] = { ["id"] = 29808, ["name"] = "Don't Forget the Eggs!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4277, ["storyline"] = { 29808 }, ["description"] = "Throughout Azjol-Nerub , the scourged nerubians carefully nurture eggs that will soon hatch, providing them nerubian young to slaughter and raise. The eggs have been tainted with foul magics. Our only recourse is to dispose of them.", ["objectivesText"] = "Reclaimer A'zak in Azjol-Nerub wants you to destroy 6 Nerubian Scourge Eggs .", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 44362, 44363, 44364, 44365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4277 } }, ["questType"] = "dungeon" },
[29811] = { ["id"] = 29811, ["name"] = "The Gatewatcher's Talisman", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4277, ["storyline"] = { 29811 }, ["description"] = "Krik'thir, guardian of the gates to Azjol-Nerub , was not a traitor. He fell in the War of the Spider defending our home from the Scourge. As per his station, he was in possession of the key to the hidden empire. I'd like you to retrieve it so it may be returned to its people.", ["objectivesText"] = "Reclaimer A'zak in Azjol-Nerub wants you to retrieve the Gatewatcher's Talisman from Krik'thir the Gatewatcher. Progress: Has Krik'thir's spirit been released from the curse of undeath? What of the talisman?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 74616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4277 } }, ["questType"] = "dungeon" },
[29820] = { ["id"] = 29820, ["name"] = "Into the Nexus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["storyline"] = { 29820 }, ["description"] = "I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days. Would you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.", ["objectivesText"] = "Archmage Berinand has asked you to speak with Warmage Kaitlyn in the Nexus.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[29825] = { ["id"] = 29825, ["name"] = "Pupil No More", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4494, ["storyline"] = { 29825 }, ["series"] = { 13187, 29826 }, ["description"] = "I once called Elder Nadox my teacher. That changed forever when I was forced to watch him mercilessly slaughter my friends and family as a servant of the damned. Find him within the depths and make him pay for his crimes, <race>.", ["objectivesText"] = "Seer Ixit in Ahn'Kahet has tasked you with the assassination of Elder Nadox . Progress: Is the mighty Nadox dead for good?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4494 } }, ["questType"] = "dungeon" },
[29826] = { ["id"] = 29826, ["name"] = "Reclaiming Ahn'Kahet", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4494, ["storyline"] = { 29826 }, ["series"] = { 13187, 29825 }, ["description"] = "Prince Taldaram and his army of Scourge use the same wards we once used to hide our empire to keep themselves safe from the native denizens of the icy depths. Deactivate the wards and slaughter the Scourge guarding them. My forces will help the natives slaughter the rest.", ["objectivesText"] = "Seer Ixit in Ahn'Kahet wants you to kill 3 Eyes of Taldaram , a Bonegrinder , and Prince Taldaram . Progress: Much work remains to be done in Ahn'Kahet, even long after the Scourge are defeated.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4494 } }, ["questType"] = "dungeon" },
[29828] = { ["id"] = 29828, ["name"] = "What the Scourge Dred", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4196, ["storyline"] = { 29828 }, ["description"] = "One of the fleeing Drakkari trolls told me of a great raptor king, Dred, that was immune to the plague. If you could find King Dred and bring me one of his teeth, perhaps I could fashion it into a weapon.", ["objectivesText"] = "Kurzel inside Drak'Tharon Keep wants you to slay King Dred and bring her his tooth. Progress: Does the great beast exist?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 74755 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4196 } }, ["questType"] = "dungeon" },
[29829] = { ["id"] = 29829, ["name"] = "Discretion is Key", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4395, ["storyline"] = { 29829 }, ["series"] = { 29830 }, ["description"] = "Listen to me, <race>. It's just been brought to my attention that there's been an incident at the Violet Hold . It would appear that the blues are launching a full scale invasion of Dalaran! I need you to get to the prison and speak with Lieutenant Sinclari at once. She'll give you the details. That is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear? Very well. Now, go!", ["objectivesText"] = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Lieutenant Sinclari .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["rewardItems"] = { 42482, 65672, 65694, 65712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "dungeon" },
[29830] = { ["id"] = 29830, ["name"] = "Containment", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4415, ["storyline"] = { 29830 }, ["series"] = { 29829 }, ["description"] = "My forces are in absolute shambles, and Malygos' assailants just keep coming. I fear that the worst has yet to come. You must engage them until their leader, Cyanigosa , comes. Only her death will stop the invasion and save Dalaran. Speak to me again when you are ready.", ["objectivesText"] = "Lieutenant Sinclari in the Violet Hold wants you to put an end to the blue dragon invasion force. You are to speak to her again once Cyanigosa is slain. Progress: Is it over? Were you able to withstand the assault?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 44342, 44343, 44344, 44345, 147477, 159081, 159082, 159083, 159084, 159085, 159086, 159087, 159088, 237812, 237891, 237894 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4415 } }, ["questType"] = "dungeon" },
[29833] = { ["id"] = 29833, ["name"] = "Unfinished Business", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 29833 }, ["description"] = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done. The greater part of Akali's blood has empowered another, and it is in him that the true danger lies. Quickly, <name>, make your way to Gundrak and speak with Tol'mar . He will be able to direct you further in this cause.", ["objectivesText"] = "Har'koa wants you to speak with Tol'mar in Gundrak .", ["rewardGold"] = 309800, ["rewardXP"] = 1385, ["rewardItems"] = { 18366, 18367, 18368, 18369, 27498, 27499, 27500, 27501, 27502, 27503, 86570 }, ["starts"] = { { ["mapID"] = 121, ["npcID"] = 28401, ["x"] = 0.6185, ["y"] = 0.6395 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.6185, ["y"] = 0.6395 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "dungeon" },
[29834] = { ["id"] = 29834, ["name"] = "Gal'darah Must Pay", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4416, ["storyline"] = { 29834 }, ["description"] = "It musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible... My job be to observe only. But dis cannot stand! Gal'darah and his followers must pay! Avenge Akali's death, mon. It be da right thing ta do.", ["objectivesText"] = "Tol'mar wants you to slay Slad'ran , Moorabi , and Gal'darah in Gundrak . Progress: Has Akali's death been avenged, <race>?", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["rewardItems"] = { 43164, 43165, 43167, 43168 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4416 } }, ["questType"] = "dungeon" },
[29835] = { ["id"] = 29835, ["name"] = "Gal'darah Must Pay", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4416, ["storyline"] = { 29835 }, ["description"] = "Da mighty Akali has been slain, <race>. My role in life be to record, not fight. But dis cannot stand! Gal'darah and his followers must pay! Avenge Akali's death, mon. It be da right thing ta do.", ["objectivesText"] = "Chronicler Bah'Kini wants you to slay Slad'ran , Moorabi , and Gal'darah in Gundrak .", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["rewardItems"] = { 43164, 43165, 43167, 43168 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4416 } }, ["questType"] = "dungeon" },
[29836] = { ["id"] = 29836, ["name"] = "Just Checkin'", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 29836 }, ["description"] = "There have been fearsome sounds echoing from Gundrak . They have been increasing in volume and frequency of late. My long-time student is currently recording events from inside Gundrak . Perhaps you could find the time to check in on her for me?", ["objectivesText"] = "To'kini wants you to speak to Bah'kini in Gundrak .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 86570 }, ["starts"] = { { ["mapID"] = 121, ["npcID"] = 28527, ["x"] = 0.598, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "dungeon" },
[29840] = { ["id"] = 29840, ["name"] = "For Posterity", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4416, ["storyline"] = { 29840 }, ["description"] = "Gundrak looks doomed. You know dis to be true. If you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end. Perhaps one day we be bringin' dem back to der former glory.", ["objectivesText"] = "Chronicler Bah'Kini in Gundrak wants you to collect 6 Drakkari History Tablets . Progress: You find da Drakkari history tablets , mon?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 43140, 43177, 43178, 43179, 43180 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4416 } }, ["questType"] = "dungeon" },
[29844] = { ["id"] = 29844, ["name"] = "For Posterity", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4416, ["storyline"] = { 29844 }, ["description"] = "Da land of da ice trolls is a shadow of its former glory. If you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end. Perhaps one day we be givin' dis land back to a new line of frost trolls.", ["objectivesText"] = "Tol'mar in Gundrak wants you to collect 6 Drakkari History Tablets . Progress: You find da Drakkari history tablets , mon?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 43140, 43177, 43178, 43179, 43180 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4416 } }, ["questType"] = "dungeon" },
[29847] = { ["id"] = 29847, ["name"] = "To Catch a Thief", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 29847 }, ["series"] = { 29801, 29802, 29934, 30092, 30093, 30106 }, ["description"] = "Just beyond this cave lies Ravenholdt Manor. You need to get inside without being seen! < Mostrasz places an enchantment on you.> There - now I'll be able to keep an eye on you and communicate as you venture into the compound. Now sneak into that manor, locate the egg, and don't get caught...", ["objectivesText"] = "Infiltrate Ravenholdt Manor and locate the missing black dragon egg.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 17124, 77945, 77946, 77947, 77948, 77949, 77950 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 56375, ["x"] = 0.678, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 267 } }, ["questType"] = "standard" },
[29848] = { ["id"] = 29848, ["name"] = "The Forlorn Watcher", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4264, ["storyline"] = { 29848 }, ["description"] = "I would gladly give my life for the Makers or their creations. However, since Loken's betrayal it seems all of Ulduar has turned on the world. One in particular, the Maiden of Grief, seems to reel in agony at her new orders. Please lay her to rest and bring me one of her tears.", ["objectivesText"] = "Kaldir Ironbane in the Halls of Stone has asked you to put the Maiden of Grief to rest and to obtain a Crystal Tear of Grief . Progress: I wish there were another way, but it seems death is the maiden's only salvation now.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 74830 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4264 } }, ["questType"] = "dungeon" },
[29850] = { ["id"] = 29850, ["name"] = "Corrupt Constructs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4264, ["storyline"] = { 29850 }, ["description"] = "The iron dwarves are busy at work carving out massive stone constructs that I fear will soon be used as powerful weapons. You must defeat their overseer, Krystallus , and the dark rune giants already walking the halls before it is too late!", ["objectivesText"] = "Kaldir Ironbane in the Halls of Stone has asked you to kill 3 Dark Rune Giants and Krystallus .", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4264 } }, ["questType"] = "dungeon" },
[29851] = { ["id"] = 29851, ["name"] = "Champion of the Tournament", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 29851 }, ["description"] = "With this tournament we grow ever closer to our final confrontation with the Lich King. <name>, fight with valor and honor. Every fighter here has gathered for the common good. Together, we will stop Arthas!", ["objectivesText"] = "Highlord Tirion Fordring has tasked you with the completion of the Trial of the Champion .", ["rewardXP"] = 6880, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[29860] = { ["id"] = 29860, ["name"] = "Diametrically Opposed", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4272, ["storyline"] = { 29860 }, ["description"] = "I shall speak plainly to you, little <race>. My people have not been the same since our ties with Thorim were severed. Volkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.", ["objectivesText"] = "Stormherald Eljrrin in the Halls of Lightning wants you to defeat Volkhan .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 43193, 43194, 43195, 43197, 43198 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4272 } }, ["questType"] = "dungeon" },
[29861] = { ["id"] = 29861, ["name"] = "Whatever it Takes!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4272, ["storyline"] = { 29861 }, ["series"] = { 13047, 29863 }, ["description"] = "One way or another, Loken shall fall. The honor and glory of his defeat shall be yours. Return to me with his lying tongue, and earn my unending gratitude.", ["objectivesText"] = "Stormherald Eljrinn in the Halls of Lightning wants you to defeat Loken. You are then to return to Stormherald Eljrinn with Loken's Tongue . Progress: Has justice been brought to Loken?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 42844, 43151, 43207, 43208, 43209 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4272 } }, ["questType"] = "dungeon" },
[29862] = { ["id"] = 29862, ["name"] = "Clearing the Way", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 4272, ["storyline"] = { 29862 }, ["description"] = "Loken's forces prepare for war. What they are not ready for is to be attacked themselves. Now is the moment to strike. Take out General Bjarngrim and his army, lest they mount an offensive on all life on Azeroth!", ["objectivesText"] = "Stormherald Eljrrin in the Halls of Lightning wants you to kill 3 Stormforged Menders , 3 Stormforged Tacticians , and General Bjarngrim . Progress: Have you vanquished their forces?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 26009, 26023, 26035, 112595, 112596, 112597, 112598, 131273 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4272 } }, ["questType"] = "dungeon" },
[29864] = { ["id"] = 29864, ["name"] = "Working at the Source", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1196, ["storyline"] = { 29864 }, ["description"] = "We are hard at work ensuring that we minimize our losses to the Scourge war machine. The vrykul here are undermining that mission by willingly joining the Lich King's ranks. Please, brave champion, you must defeat their spiritual leader, Svala, before she leads her people into the eternal shadow!", ["objectivesText"] = "Argent Confessor Paletress wants you to slay Svala Sorrowgrave . Progress: I have faith in you, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 44151 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1196 } }, ["questType"] = "dungeon" },
[29934] = { ["id"] = 29934, ["name"] = "To Ravenholdt", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 29934 }, ["series"] = { 29801, 29802, 29847, 30092, 30093, 30106 }, ["description"] = "If the egg is in Ravenholdt Manor, we can't risk torching it in an all-out assault. I'll need someone slippery to get in there and find out for sure. That's you, <name>. Mostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!", ["objectivesText"] = "Speak to Mostrasz at the Vermillion Redoubt and fly to Ravenholdt Manor together. Progress: So, are you ready to do some spying?", ["rewardGold"] = 77400, ["rewardXP"] = 1200, ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950, 237812 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 55488, ["x"] = 0.29, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 56375, ["x"] = 0.678, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 25, 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard" },
[30092] = { ["id"] = 30092, ["name"] = "Our Man in Gilneas", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 30092 }, ["series"] = { 29801, 29802, 29847, 29934, 30093, 30106 }, ["description"] = "If you wish to join my cause and slaughter the black dragons in hiding, prove yourself by taking down Hiram Creed. He's amassing an army in Gilneas. We haven't been able to slip past his defenders, but we've got a man on the scene keeping an eye on him. Zazzo Twinklefingers , a very crafty arcane mage, is waiting for us to contact him just outside of the ruins of the Gilnean capital. Find him and he'll direct you to the target.", ["objectivesText"] = "Seek out Zazzo Twinklefingers near the ruins of Gilneas City in Gilneas.", ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 25, 42 }, ["zone"] = { 267 } }, ["questType"] = "standard" },
[30093] = { ["id"] = 30093, ["name"] = "Assassinate Creed", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4706, ["mapID"] = 42, ["storyline"] = { 30093 }, ["series"] = { 29801, 29802, 29847, 29934, 30092, 30106 }, ["description"] = "The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, has infected the lot of those dogs with his own draconic blood. Even the Forsaken are having trouble routing him out. Only a surgical assassination can end this! The bridge behind me is relatively unguarded. Slip in through merchant's square and head south - you'll find Creed in the middle of the military district. I'll keep an eye on you and pull you out if there's any trouble. ...There WILL be trouble!", ["objectivesText"] = "Stealth into the ruins of Gilneas City and slay Hiram Creed within the military district. Progress: Hiram Creed. Among the black dragons, he is known as \"Creetharus.\"", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 8827, 22826, 42960, 43378, 45769, 55822, 64493, 77945, 77946, 77947, 77948, 77949, 77950, 85500 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 4706 } }, ["questType"] = "standard" },
[30094] = { ["id"] = 30094, ["name"] = "The End Time", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 30094 }, ["description"] = "Nozdormu , the bronze Aspect, has asked for help from the champions of the Horde. You are on his short list. I can share few other details. It is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself. He awaits you at the End Time , in the distant future. I can help you to travel there, if you so choose.", ["objectivesText"] = "Speak with Nozdormu at the End Time .", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["rewardItems"] = { 72876, 246936, 249400, 251821, 254267, 254579 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 52382, ["x"] = 0.486667, ["y"] = 0.707333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.486667, ["y"] = 0.707333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon" },
[30095] = { ["id"] = 30095, ["name"] = "The End Time", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 30095 }, ["series"] = { 30096, 30098, 30099, 30100, 30101 }, ["description"] = "Nozdormu , the bronze Aspect, has asked for help from the champions of the Alliance. You are on his short list. I can share few other details. It is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself. He awaits you at the End Time , in the distant future. I can help you to travel there, if you so choose.", ["objectivesText"] = "Speak with Nozdormu at the End Time .", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["rewardItems"] = { 246936, 249400, 251821, 254267, 254579 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 52408, ["x"] = 0.4885, ["y"] = 0.884 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4885, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon" },
[30096] = { ["id"] = 30096, ["name"] = "Murozond", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5789, ["storyline"] = { 30096 }, ["series"] = { 30095, 30098, 30099, 30100, 30101 }, ["description"] = "If we are to destroy Deathwing, we will need the power of the Dragon Soul. To obtain the Dragon Soul, I would have to take you back to the Sundering, ten thousand years in the past... but that time passage is blocked to me. The creature that blocks us from accessing this time passage is named Murozond . He must be slain, here, in this twisted future, before we can continue our plot to unmake Deathwing. This is why you were brought here, <name>.", ["objectivesText"] = "Slay Murozond . Progress: This is a future of Azeroth, yes... but not an inevitable one. This future is what my fellow aspects are trying to avoid.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 72873, 72874, 72875, 76152 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5789 } }, ["questType"] = "dungeon" },
[30097] = { ["id"] = 30097, ["name"] = "Archival Purposes", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5789, ["storyline"] = { 30097 }, ["description"] = "From what I understand, you intend to avoid this future. If this is true, then we must archive data from this timestrand before it is lost to us. We believe that the most interesting and valuable elements of this future are the powerful \"echoes\" that roam the dragonshrines. Take this vessel with you as you silence these echoes. A portion of their energies will be archived within the bronze dragonflight's depository.", ["objectivesText"] = "Slay two of the Echoes within the End Time , then allow Alurmi's Vessel to archive their information. Progress: Nozdormu is acting with haste. This is something that Nozdormu does not usually do. Normally I would be more thorough with my archival. However, given the circumstances, we are forced to pick and choose what we record... and to employ the help of mercenaries like you.", ["rewardGold"] = 137400, ["rewardXP"] = 4790, ["rewardItems"] = { 72852, 72871, 72872, 77939, 77940, 77941, 77942, 77955, 92726 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5789 } }, ["questType"] = "dungeon" },
[30098] = { ["id"] = 30098, ["name"] = "The Well of Eternity", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5789, ["storyline"] = { 30098 }, ["series"] = { 30095, 30096, 30099, 30100, 30101 }, ["description"] = "We must move quickly, before any remaining Infinite agents intervene. Time is precious. I will now take you from your distant future into your distant past... the War of the Ancients. Our goal is the Dragon Soul, an artifact of immense power... enough power to break Deathwing, and end his reign over your present.", ["objectivesText"] = "Speak with Nozdormu at the Well of Eternity .", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5789 } }, ["questType"] = "dungeon" },
[30099] = { ["id"] = 30099, ["name"] = "In Unending Numbers", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5788, ["storyline"] = { 30099 }, ["series"] = { 30095, 30096, 30098, 30100, 30101 }, ["description"] = "Between us and the Dragon Soul lies a legion of demons. They will have to be dispatched before we proceed. If my timing is correct - and it usually is - a young night elf named Illidan Stormrage should be crossing our path shortly. He will undoubtedly be of some use when it comes to demon hunting. Help Illidan disable the demons' portals, then slay their leader, Peroth'arn .", ["objectivesText"] = "Disable the three demon portals, then slay Peroth'arn . Progress: You should temporarily lay aside any prejudices you may carry against Illidan. Remember, you are ten thousand years in your past, and he must not be punished for any future crimes.", ["rewardGold"] = 137400, ["rewardXP"] = 4790, ["rewardItems"] = { 72876 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5788 } }, ["questType"] = "dungeon" },
[30100] = { ["id"] = 30100, ["name"] = "The Vainglorious", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5788, ["storyline"] = { 30100 }, ["series"] = { 30095, 30096, 30098, 30099, 30101 }, ["description"] = "Queen Azshara and her royal guard lie ahead of us. We cannot afford the possibility of any interference with our plan. So we will take the fight to her, before she has a chance to meddle. It is quite unlikely that you will kill Queen Azshara today; very few coherent timelines exist along that branch. Consider it a victory if you are simply able to occupy her attention, however temporarily.", ["objectivesText"] = "Dispatch of Queen Azshara . Progress: Azshara and her fawners have long prepared for this day. She will not take our interference lightly.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5788 } }, ["questType"] = "dungeon" },
[30101] = { ["id"] = 30101, ["name"] = "The Path to the Dragon Soul", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5788, ["storyline"] = { 30101 }, ["series"] = { 30095, 30096, 30098, 30099, 30100 }, ["description"] = "I cannot simply fly up and grab the Dragon Soul. The old gods protect it. To make matters worse, their shield is strengthened by the swirling, arcane energies that emanate from the Well of Eternity , and those energies are being focused by the great demon Mannoroth . Distract Mannoroth , and the link between the Dragon Soul and the Well will be broken. Without the Well's power, the old gods' ward will be weakened, and the Dragon Soul will be vulnerable. And then I will take it.", ["objectivesText"] = "Slay Mannoroth . Progress: What?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 72876, 72877, 72878, 72879 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5788 } }, ["questType"] = "dungeon" },
[30102] = { ["id"] = 30102, ["name"] = "The Hour of Twilight", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5844, ["storyline"] = { 30102 }, ["series"] = { 30103 }, ["description"] = "There's no need to stand around here forever. Have you forgotten? We can CONTROL TIME. Especially since you got rid of that Murozond fellow, back in the future. That Dragon Soul that you just liberated? Thrall already has it, back in your present day. And he's going to need your help. You ready to go?", ["objectivesText"] = "Speak with Thrall at the Hour of Twilight .", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5844 } }, ["questType"] = "dungeon" },
[30103] = { ["id"] = 30103, ["name"] = "To Wyrmrest!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5844, ["storyline"] = { 30103 }, ["series"] = { 30102 }, ["description"] = "The Dragon Soul... a weapon with enough power to defeat Deathwing. Thanks to you, it is now safely in our hands. Come! The aspects await us. We must bring the Dragon Soul to Wyrmrest Temple, in the center of Dragonblight.", ["objectivesText"] = "Escort Thrall safely to Wyrmrest Temple. Progress: Come, <name>. We do not have much further to travel.", ["rewardGold"] = 232300, ["rewardXP"] = 4790, ["rewardItems"] = { 72858, 72887, 72888 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5844 } }, ["questType"] = "dungeon" },
[30104] = { ["id"] = 30104, ["name"] = "Documenting the Timeways", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 5789, ["storyline"] = { 30104 }, ["description"] = "You... <name>, was it? You assisted with our archival in the past. Well, technically it was the future, but I believe you understand. Time is highly relative. I require more information for our archive. While you and Nozdormu don't intend to overwrite this timestrand, as you did in the End Time, we can still benefit from more data. I require information on Captain Varo'then, one of Azshara's pretty little handmaidens, and... hmm... oh, how about that big felguard, just down those stairs?", ["objectivesText"] = "Slay a Legion Demon, a Royal Handmaiden, and Captain Varo'then, then allow Alurmi's Vessel to archive their information.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 72880, 72881, 72882, 72883, 77955 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5789 } }, ["questType"] = "dungeon" },
[30105] = { ["id"] = 30105, ["name"] = "The Twilight Prophet", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 5844, ["storyline"] = { 30105 }, ["description"] = "The missive reads as follows: \"The Hour of Twilight is upon us. The world-shaman Thrall approaches Wyrmrest with the Dragon Soul in hand, feebly whimpering one final threat to destroy our glorious master.\" \"Stop Thrall , and we win our war. I will be watching you from nearby.\" ~ The Twilight Prophet", ["objectivesText"] = "Find and unmask the Twilight Prophet. Progress: I have my suspicions about this Twilight Prophet.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 72884, 72886, 76153, 77957 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5844 } }, ["questType"] = "dungeon", ["startItems"] = { 77957 } },
[30106] = { ["id"] = 30106, ["name"] = "The Deed is Done", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4706, ["mapID"] = 42, ["storyline"] = { 30106 }, ["series"] = { 29801, 29802, 29847, 29934, 30092, 30093 }, ["description"] = "Prince Wrathion will be pleased to hear that you've succeeded. You should report back to him at Ravenholdt Manor. The Prince has been known to be extremely generous to those who help him.", ["objectivesText"] = "Report your success to Prince Wrathion at Ravenholdt Manor in Hillsbrad Foothills.", ["rewardGold"] = 140450, ["rewardXP"] = 2395, ["rewardItems"] = { 53272, 53274, 53305, 72822, 72860, 77945, 77946, 77947, 77948, 77949, 77950, 131406 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 25, 42 }, ["zone"] = { 4706 } }, ["questType"] = "standard" },
[30107] = { ["id"] = 30107, ["name"] = "Cluster Clutch", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 30107 }, ["description"] = "The daggers I have given you are lifeless shells. They can do great things, once they are given a means to contain the power I have in mind. I need for you to acquire Shadowy Gems for me. The facets of these unusual stones are like windows into the infinite. They are often used by minions of the Twilight's Hammer to control the most powerful of elementals. A great battle is raging around Wyrmrest Temple. Collect Elementium Gem Clusters from Deathwing's minions and bring the gems to me.", ["objectivesText"] = "Collect 333 Shadowy Gems by looting Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter. Progress: How many gems have you collected? Are my father's minions as twisted as he?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950, 77951, 77952 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 267 } }, ["questType"] = "standard" },
[30108] = { ["id"] = 30108, ["name"] = "Our Man in Karazhan", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 30108 }, ["series"] = { 30109, 30113 }, ["description"] = "Your next target is the Black Dragon Nalice, who is engaged in some sort of arcane debauchery beneath the ruined tower of Karazhan. Your primary mission is to destroy her, but if you can bring me back a vial of her blood, I'll be able to use it to augment the power of the daggers I've given you. Your accomplice Zazzo has already been dispatched to the scene and awaits you there. He'll have more details.", ["objectivesText"] = "Report to Zazzo Twinklefingers in the ruins just southeast of Karazhan.", ["rewardGold"] = 29325, ["rewardXP"] = 2395, ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 25, 42 }, ["zone"] = { 267 } }, ["questType"] = "standard" },
[30109] = { ["id"] = 30109, ["name"] = "Blood of the Betrayer", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 30109 }, ["series"] = { 30108, 30113 }, ["description"] = "I've pinpointed Nalice to the Master's Cellar, an extended basement you'll find in the ruins up ahead. Dragon cultists are everywhere, and Nalice has set up some strange arcane storage devices throughout the area. Perhaps you can use those to your advantage? Sneak past the cultists, obliterate Nalice, and grab a vial of her blood for Wrathion. I'll keep my eyes on you and pull you out if you get into any trouble. But I'm NOT coming in there with you!", ["objectivesText"] = "Sneak into the Master's Cellar in the ruins around Karazhan, defeat Nalice, and acquire a Vial of Black Dragonsblood . Progress: Nalice. Dead?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950, 77954, 109217 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Day of the Dead" },
[30110] = { ["id"] = 30110, ["name"] = "LFGDungeons - Cataclysm - Raid Finder - 1st", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 30110 }, ["rewardGold"] = 549600, ["rewardXP"] = 9580, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30112] = { ["id"] = 30112, ["name"] = "A Score to Settle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 3, ["zoneID"] = 206, ["storyline"] = { 30112 }, ["description"] = "Utgarde's forces are organizing under the advisory of Prince Keleseth , a san'layn ambassador of the Scourge. We cannot allow the vrykul to benefit from his counsel any further. Silence him.", ["objectivesText"] = "Dark Ranger Marrah wants you to slay Prince Keleseth inside Utgarde Keep . Progress: Is it done, <name>?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 39676, 39678, 39679, 39680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 206 } }, ["questType"] = "dungeon" },
[30113] = { ["id"] = 30113, ["name"] = "Victory in the Depths", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4706, ["mapID"] = 42, ["storyline"] = { 30113 }, ["series"] = { 30108, 30109 }, ["description"] = "<Zazzo performs an enchantment on the vial of blood, then quickly hands it back to you, as though it's toxic.> Done! You'll want to get this back to Wrathion as soon as possible, along with those two daggers of yours. I don't know what he plans to do with this stuff. Between you and me, sometimes that little dragon kid creeps me out. Good luck!", ["objectivesText"] = "Take the Vial of Preserved Dragonsblood , along with your daggers Fear and Vengeance , to Wrathion at Ravenholdt Manor in Hillsbrad Foothills. Progress: Ah, you've returned! I no longer sense Nalice's presence. Is she dead? Or has she somehow eluded us both?", ["rewardGold"] = 154900, ["rewardXP"] = 2395, ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950, 78339 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 57770, ["x"] = 0.525, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 25, 42 }, ["zone"] = { 4706 } }, ["questType"] = "standard" },
[30116] = { ["id"] = 30116, ["name"] = "Sharpening Your Fangs", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 30116 }, ["description"] = "Do you understand why I have you assassinate the dragons, yet spare the mortals? It isn't their fault. They must seek out their own destiny, free from the meddling of my kind. We are nearing the end of our mission, and it is time for you to seek out your own destiny as well. I can continue to augment your weapons, but collecting shadowy gems won't be enough. My work will require entire clusters. Gather them from my father's minions...", ["objectivesText"] = "Collect 60 Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter. Progress: How many clusters have you acquired? The tenacity of your race continues to inspire me!", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950, 77952, 78352 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 267 } }, ["questType"] = "standard" },
[30118] = { ["id"] = 30118, ["name"] = "Patricide", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 30118 }, ["description"] = "Your next target has claimed the lives of all of my other assassins. I need you to kill my father himself. You must destroy Deathwing. We are out of time. His madness has already corrupted all the others of my kind, and his darkness will consume the world if he is not stopped. If you by some miracle succeed, and can retrieve for me a piece of him - perhaps a fragment of the armor he uses to disguise his true chaotic nature - the reward I give you will be without equal.", ["objectivesText"] = "Destroy Deathwing and retrieve a Fragment of Deathwing's Jaw . Progress: What of my father?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 77945, 77946, 77947, 77948, 77949, 77950, 78352 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 57777, ["x"] = 0.714, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 58038, ["x"] = 0.705, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 267 } }, ["questType"] = "standard" },
[30119] = { ["id"] = 30119, ["name"] = "Well of Eternity RP Tracker", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 30119 }, ["series"] = { 29193, 29194, 29225, 29234, 29239, 29432 }, ["description"] = "I am duty-bound to look into your claims immediately, <race>, which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the world tree's branch.", ["objectivesText"] = "Recover the Branch of Nordrassil from the Firelands.", ["rewardGold"] = 282000, ["rewardXP"] = 1110, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "raid" },
[30120] = { ["id"] = 30120, ["name"] = "Cleansing Drak'Tharon", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 3, ["zoneID"] = 4196, ["storyline"] = { 30120 }, ["description"] = "'Ey, mon, you be here! Dis is good, mon! Drak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon! Once ya be reachin' its top, ya must summon me, and I'll perform the ritual. Alas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", ["objectivesText"] = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 35797, 36758, 38303, 40755, 40756, 40757, 40758 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4196 } }, ["questType"] = "dungeon" },
[30177] = { ["id"] = 30177, ["name"] = "Daily Heroic Random (1st) (Cataclysm)", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 3, ["storyline"] = { 30177 }, ["rewardGold"] = 282000, ["rewardXP"] = 1480, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
